Derecho a la libertad (Art. 50 CNA). Por esta disposición ningún niño o adolescente será
detenido o privado de su libertad salvo por mandato judicial o flagrante infracción.
Derecho a la identidad (Art. 6 o CNA). Este derecho no comprende sólo el nombre, sino
la nacionalidad, el conocerá los padres, llevar sus apellidos y al desarrollo integral de su
personalidad. La Constitución peruana protege el derecho a la identidad (Art. 2° inciso 1).
Derecho a la Inscripción (Art. 7°CNA). Por la inscripción se garantiza el derecho a la fecha
cierta del nacimiento y el derecho al nombre, y el otorgamiento gratuito de la primera
partida. Al regular este derecho, el CNA hace referencia al certificado de nacimiento vivo,
en el cual debe constar la identificación dactilar de la madre como la huella pelmatoscó-
pica del niño(a), sirviendo ello para acreditar el entroncamiento entre hijo y madre, dado
que las huellas del niño coinciden con la de la madre durante los primeros años de vida.
(Art. 23o CC).
Derecho a vivir en una familia. Principalmente se garantiza el derecho del niño a vivir con
su familia, y en su defecto en un ambiente familiar adecuado, con ello no se excluyen los
hogares como las aldeas S.O.S. u otros. Además se garantiza el derecho de los niños y ado
lescentes a no ser separados de su familia sino por circunstancias especiales previamente
establecidas.
Derecho aque los padres cumplan con los cuidados necesarios para su desarrollo integral
(Art. 8 o CNA)
Derecho a la educación, cultura, deporte y recreación. (Art. 14o CNA).
Derecho a la no discriminación. (Art. 14o CNA).
Derecho a la educación de la niña embarazada. (Art. 14o CNA).
Derecho a la educación básica. (Art. 15° CNA). En esta disposición se precisan los conteni
dos de la educación básica, el de los niñosy los adolescentes, laque debe comprender en
tre otros: el desarrollo de sus capacidades, enseñar el respeto por los derechos humanos
y libertades, difusión de los derechos del niño, el respeto a los padres, la preparación para
una vida responsable, con espíritu de solidaridad, amistad entre los pueblos y grupos ét
nicos, el desarrollo de pensamiento crítico, la orientación sexual.
Derecho a ser respetado por sus educadores (Art. 16o CNA).
Derecho a ser matriculado en el sistema regular de enseñanza.
Derecho a la protección por los directores de los centros educativos. (Art. 18o CNA) Por
este derecho constituye un deber de los directores de los centros educativos el comuni
car a la autoridad los casos de maltrato, acoso y violencia sexual, la reiterada repitencia
y deserción escolar, las reiteradas faltas injustificadas, el consumo de sustancias tóxicas,
