21. R é g im e n d e v i s i t a s
Los padres que no ejerzan la Patria Potestad tienen derecho a visitar a sus hijos, para lo cual
deberán acreditar con prueba suficiente el cumplí miento o la imposibilidad del cumplimiento
de la obligación alimentaria. Si alguno de los padres hubiera fallecido, se encontrará fuera del
lugar de domicilio o se desconociera su paradero, podrán solicitar el régimen de visitas los
parientes hasta el cuarto grado de consanguinidad de dicho padre.
Extensión: El Régi men de Visitas decretado por el] uez podrá extenderse a los parientes hasta el
cuarto grado de consanguinidady segundo de afinidad, esto es, a los abuelos, tíos, primos, tíos
políticos, cuñados, etc, cuando el Interés Superior del Niñoy del adolescente así lo justifique.
• De los alimentos
Se considera alimentos lo necesario para el sustento, habitación, vestido, educación, instruc
ción y capacitación para el trabajo, asistencia médica y psicológica y recreación del niño o del
adolescente. También los gastos del embarazo de la madre desde la concepción hasta la etapa
de postparto.
Obligados a prestar alimentos: Es obligación de los padres prestar alimentos a sus hijos por
ausencia de los padres o desconocimiento de su paradero, prestan alimentos en el orden de
prelación siguiente:
Los hermanos mayores de edad (i°)
Los abuelos (20)
Los parientes colaterales hasta el tercer grado (30); y.
Otros responsables del niño o adolescente (40)
Reglas del proceso de alimentos: Para la demanda de alimentos ya no es exigible contar con
un abogado, se presenta por escrito a través de la Mesa de Partes física o de manera virtual em
pleando la Mesa de Partes Electrónica. Alternativamente, la demanda puede ser presentada
por medio de formularios físicos o electrónicos.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 637 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
La parte demandante deberá especificar si la parte demandada es un trabajador dependien
te o independiente, mencionando el nombre del lugar donde la parte demandada trabaja o
ejerce sus labores. La no consignación de esta información no determina, en ningún caso, la
inadmisibilidad o la improcedencia de la demanda.
Los procesos de alimentos serán de competencia exclusiva de los jueces de Paz Letrados en
todos los casos (hijos reconocidos o no), siendo competentes para conocer los procesos de
fijación, aumento, reducción, extinción o prorrateo de alimentos, sin perjuicio de la cuantía de
la pensión, la edad o la prueba sobre el vínculo familiar, salvo que la pretensión alim entaria se
proponga accesoriamente a otras pretensiones. (Art. 96 CNA)
En los casos de filiación judicial de paternidad extramatrimonial cuya competencia es de los
juzgado de Paz Letrado, podrá acumularse como pretensión accesoria, la fijación de una pen
sión alimentaria.
Será también competente el juez de Paz, a elección del demandante, respecto de demandas
en donde el entroncamiento esté acreditado de manera indubitable. Cuando el entrón ca
imiento fam iliar no esté acreditado de manera indubitable el juez de Paz puede promover una
conciliación si ambas partes se allanan a su competencia.
Es competente para conocer estos procesos en segundo grado el juez de Familia, en los casos
que hayan sido de conocimiento del juez de Paz Letrado y este últim o en los casos que hayan
sido conocidos por el juez de Paz.
En el proceso de alimentos el juez tiene la facultad, de oficio, de acceder en línea a los sistemas
de información automatizados (planilla electrónica) del MINTRA o a los sistemas de infor
mación automatizados de la SUNAT y extraer en tiempo real la información sobre el centro
de trabajo del demandado, su remuneración, gratificaciones, vacaciones y cualquier suma de
libre disponibilidad que provenga de la relación laboral de este y, de ser el caso, obtener in
formación sobre la actividad comercial o profesional independiente y sobre la renta mensual
que perciba por estas, así como las declaraciones juradas de renta anual que hubiera realizado
por estas actividades. Asimismo, puede acceder en línea al sistema automatizado de la Super
intendencia de Banca, Seguros y Administradoras Privadas de Fondos de Pensiones y extrae
en tiempo real la información bancada y financiera del demandado. De igual forma, puede
accederá información de la SUNARP sobre los bienes muebles e inmuebles activos e inactivos
del demandado y del RENIEC sobre el número total de hijos menores de edad que tuviera el
obligado a la prestación alimentaria. Ley N°32006 (Pub. 24.04.2024).
Se dispone que, una vez obtenida la sentencia firme que ampara la demanda de alimentos,
el juez ordenará al demandado abrir una cuenta de ahorros a favor del demandante en cual
quier institución del sistema financiero. Esta cuenta sólo servirá para el pago y cobro de la
pensión alim enticia,y estará exonerada de cualquier impuesto. En aquellos lugares donde no
existan entidades financieras, el pago y la entrega de la pensión alimenticia se harán en efec
tivo, dejándose constancia en acta que se anexará al proceso.
En caso de que el obligado, luego de haber sido notificado para la ejecución de sentencia fir
me, no cumple con el pago de la pensión alimenticia, el juez, de oficioy bajo responsabilidad,
previa liquidación correspondiente, el requerimiento del cumplim iento del pagoy el consen
tim iento expreso del representante procesal del menor alimentista; remitirá copias certifica
