Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 638 of 1506 --

das de las piezas procesales pertinentes al fiscal provincial penal de turno, a fin deque proceda
con arreglo a sus atribuciones de conformidad con el literal d) del numeral i del artículo 446
del Nuevo Código Procesal Penal. Este acto constituye el trám ite de interposición de denuncia
penal por incumplimiento de pensión alimenticia. (Art. 566-AC.PC.)
El demandado en un proceso de alimentos podrá accionar, ante el mismo juzgado que co
noció del proceso, el cese de la obligación alimentaria si comprueba a través de una prueba
genética u otra de validez científica, con igual o mayor grado de certeza, que no es el padre del
menor. (Art. 415 C.C.)
Si durante la audiencia única del proceso de alimentos, el demandado aceptara la paternidad,
el juez tendrá por reconocido al hijo. Para dicho efecto, enviará a la municipalidad respectiva
la copia certificada de la pieza judicial que corresponda, ordenado la inscripción del recono
cimiento en la partida de nacimiento del menor, sin perjuicio de la continuación del proceso.
Asimismo, se dispone que si el demandado no asiste a la referida audiencia, pese a haber
sido emplazado válidamente, el juez procederá a sentenciar en el mismo acto atendiendo a la
prueba actuada. (Art. 171 del CNA).
• De la tutela
Tutela:
Derechos y deberes del tutor: Son derechos y deberes del tutor los prescritos en el Código
de Niñosy Adolescentesy en la legislación vigente.
Impugnación de los actos del tutor: El adolescente puede recurrir ante el Juez contra los
actos de su tutor, así como pedir la remoción del mismo.
Juez competente: El Juez especializado es competente para nombrar tu to ry es el respon
sable de supervisar periódicamente el cumplimiento de su labor.
• Del acogimiento familiar
Medida de protección provisional fam iliar (en sede administrativa) incorporada en nuestra
legislación a través del Decreto Legislativo 1297- Decreto Legislativo para la protección de ni
ñas, niñosy adolescentes sin cuidados parentales o en riesgo de perderlos (Pub. El Peruano
30.12.2016).
Definición: El acogimiento fam iliares una medida de protección temporal que se aplica a los
niños, niñas y adolescentes que se encuentran en situación de desprotección fam iliar con la
finalidad de ser integrados a su familia extensa, a un tercero o una familia profesionalizada
previamente evaluada o seleccionada.
El artículo 62 del Decreto Legislativo N° 1297 precisa que la medida de protección provisional
para niñas o niños menores de 03 años de edad será preferentemente el de acogimiento fa
miliar. El acogimiento fam iliar tiene un plazo máximo de 18 meses. Transcurrido ese plazo, el
artículo 63 establece que la autoridad competente puede promover la reintegración fam iliar
y retorno del niño, niña o adolescente a su familia o se puede promover la declaración judicial
de desprotección y la adopción de una medida de protección de carácter permanente.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 639 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Tipos de acogimiento familiar: Tenemos.-
a) Acogimiento en familia extensa: Se aplica con aquella fam ilia extensa (familiares con los
que no convive) que ha sido evaluada favorablemente por la Unidad de Protección Espe
cial (UPE) para asumirel cuidado y protección de la niña, niño o adolescente. Es acompa
ñada por profesionales de la UPEde manera permanente.
b) Acogimiento Familiar con Tercero: El acogimiento fam iliar con tercero, se aplica con una
persona o fam ilia que no forma parte de la familia extensa de la niña, niño o adolescente,
que previamente ha sido seleccionada, y declarada idónea paraserfam ilia acogedora. Es
acompañada y apoyada profesional mente, de manera permanente.
En estos casos, se da preferencia a la persona o familia que haya tenido vínculo afectivo
con la niña, niño o adolescente con anterioridad.
c) Acogimiento familiar profesionalizado: El acogimiento fam iliar profesionalizado es el
que se brinda a niñas, niños o adolescentes con características especiales, por una perso
na o fam ilia especialmente calificada, a condición de una subvención económica para los
gastos de manutención de la niña, niño o adolescente, que incorpora su atención profe
sionalizada, bajo supervisión de la autoridad competente.
Requisitos para constituirse en familia acogedora: La persona o las personas que deseen
constituirse en fam ilia acogedora deben cumplir con los siguientes requisitos:
a) Contar con mayoría de edad.
b) Acceder de forma voluntaria a ser familia acogedora. Los cónyuges o convivientes, deben
presentar la solicitud de acogimiento fam iliar en forma conjunta, tratándose de una fa
milia monoparental, podrá presentar el acogedor o acogedora. Asimismo, se recibe la
opinión de las hijas o hijos de la familia, en función a su edad, y grado de madurez, así
como de los miembros que residan en la unidad familiar.
c) Disfrutar de un estado de salud, física y psíquica, que no dificulte el normal cuidado de
la niña, niño o adolescente, debidamente comprobado por la autoridad competente a
través de informes debidamente sustentados.
d) Haber recibido capacitación y evaluación favorable.
e) Haber sido recomendada como idónea en el plan de trabajo individual por el equipo in
terdisciplinario a cargo.
f) Disponer de recursos necesarios para asumir los gastos de alimentación, salud, vivienda,
educación y otros derivados del acogimiento, salvo que se trate de un acogimiento fam i
liar retribuido.
g) Aceptar ser acompañados y evaluados en la implementación del plan de trabajo individual.
Exclusiones: No puede otorgarse acogimiento familiar a la persona o fam ilia que:
a) Registren denuncias, antecedentes penales o judiciales por la comisión de delitos en
agravio de las niñas, niños o adolescentes o delitos que conlleven a la suspensión o pérdi
da de la patria potestad.
b) Hayan sido sancionados con suspensión o pérdida de la patria potestad o hayan sido re
movidos de la tutela o acogimiento de hecho por mal desempeño.
