e) Registren incumplimiento en sus obligaciones en materia alimentaria.
f) Registren incumplimiento en el régimen de visitas a sus hijas o hijos menores de edad.
• Del Consejo de Familia
Habrá Consejo de Familia para velar por la persona e intereses del niño o del adolescente que
no tenga padre ni madre o que se encuentre incapacitado lo dispone el artículo 619o del Có
digo Civil.
El adolescente participara en las reuniones del Consejo de Familia con derecho a voz y voto. El
niño será escuchado con las restricciones propias de su edad.
Composición del Consejo de Familia: El consejo se compone de las personas que haya desig
nado por testamento o en escritura pública el últim o de los padres que tuvo al hijo bajo su
patria potestad o su cúratela; y, en su defecto, por las personas designadas por el últim o de los
abuelos o abuelas que hubiera tenido al menor o incapaz bajo su tutela o cúratela.
A falta de las personas mencionadas, forman el consejo los abuelos y abuelas, tíos y tías, her-
manosy hermanas del menor o del incapaz.
Los hijos del mayor incapaz, que no sean sus curadores, son miembros natos del consejo que
se forme para él.
Facultades del Consejo de Familia:
1. - Nombrar tutores dativos o curadores dativos generales y especiales, conforme a este Có
digo.
2. - Adm itir o no la excusa o la renuncia de los tutores y curadores dativos que nombre.
3. - Declarar la incapacidad de los tutores y curadores dativos que nombre, y removerlos a su
juicio.
4. - Provocar la remoción judicial de los tutores y curadores legítimos, de los testamentarios o
escriturarios y de los nombrados por el juez.
5. - Decidir, en vista del inventario, la parte de rentas o productos que deberá invertirse en los
alimentos del m enorodel incapaz, en su caso, y en la administración desús bienes, si los
padres no la hubieran fijado.
6 . - Aceptar la donación, la herencia o el legado sujeto a cargas, dejado al menor o, en su caso,
al incapaz.
