• De la licencia para enajenar u obligar bienes
Quienes administran bienes de niños o de adolescentes necesitan autorización judicial para
gravarlos o enajenarlos por causas justificadas de necesidad o utilidad de conformidad con el
Código Civil.
El administrador presentara al juez, conjuntamente con la demanda, las pruebas que acrediten la
necesidad o utilidad del contrato. Asimismo indicara los bienes que pretende enajenar o gravar.
• De las autorizaciones
Notarial: para el viaje de niños o adolescentes fuera del país solos o acompañados por uno de
sus padres, es obligatoria la autorización de ambos padres con certificación notarial.
En caso de fallecimiento de uno de los padres o de estar reconocido el hijo por uno solo de
ellos, bastara el consentimiento del padre sobreviviente o del que efectuó el reconocimiento,
debiendo constaren el permiso notarial habertenido a la vista la partida de defunción o la de
nacimiento correspondiente.
En caso de que el niño, niña o adolescente requiera atención médica en el extranjero a causa
de alguna enfermedad compleja o rara sin tratamiento o con tratamiento insuficiente en el
Perú, puede ser autorizado por uno de los padres.
En caso de que el niño, niña o adolescente requiera autorización para realizar un viaje por
estudios al extranjero, puede ser autorizado solo por el padre o la madre en dos supuestos:
por participación en un programa de intercambio estudiantil o a razón de la obtención de una
beca completa de estudios.
En caso de que el niño, niña o adolescente requiera autorización para viajar en representa
ción del país a olimpiadas académicas o competencias deportivas en el extranjero, se deben
presentar los documentos que acrediten la representación o la invitación a la competencia o
evento internacional validado por el sector académico o deportivo autorizando la representa
ción, así como el tiempo de duración y el lugar en el cual se desarrollará.
De existir disentimiento de uno de los padres, este será tratado por la vía judicial correspondiente.
En caso de que el viaje se realice dentro del país bastara la autorización de uno de los padres.
Judicial: es competencia del juez especializado, autorizar el viaje de niños o adolescentes
dentro del país cuando falten ambos padres, y fuera del país por ausencia o disentim iento de
uno de ellos para lo cual el responsable presentara los documentos justifícatenos de la peti
ción. (Resolución Administrativa N°000096-2022-CE-PJ)
