En caso de disentimiento de uno de los padres o de existir oposición al viaje, se abrirá el inci
dente a pruebay en el término de dos días resolverá el juez, previa opinión fiscal. La oposición
que formule alguno de los padres inscribirá en el libro de Oposición de Viaje de los Juzgados
Especializados, el que caduca al año.
Autorización especial de viaje de menores: Cuando uno de los padres se encuentre inscrito
en el Registro de Deudores Alimentarios Morosos (REDAM) creado por la Ley 28970, o haya
sido condenado con sentencia firm e por delito doloso cometido en agravio de sus hijos o en
perjuicio de los mismos, sin que se le haya inhabilitado para el ejercicio de la patria potestad,
el responsable presentará ante el juzgado correspondiente esta situación a fin de que el juez
decida en el plazo máximo de dos días la salida del niño o adolescente sin abrir incidente a
prueba ni solicitar la opinión del fiscal, salvo casos excepcionales.
El supuesto anteriornoseráaplicablecuando el deudoralim entario moroso haya cancelado la
deuda total de la asistencia alimentaria.
• Del matrimonio de adolescentes
A través de las modificaciones introducidas por la Ley N° 31945 (Pub. 25.11.2023), se prohíbe
el matrimonio entre menores de edad y se confirma que a los 18 años de edad se adquiere
capacidad de ejercicio plenay deroga las disposiciones que señalaban que-excepcionalmen-
te- adquirían plena capacidad de ejercicio, los mayores de 14 años y menores de 18 años que
hayan contraído matrimonio, o quienes ejerciten la paternidad.
22. Responsabilidad penal de adolescentes
El Código de Responsabilidad Penal del Adolescente (CRPA) aprobado por Decreto Legislativo
N°1348 publicado en el diario oficial El Peruano con fecha 07.01.2017,y reglamentado por D.S.
N° 004-2018-JUS, supone una reforma integral del Sistema de Justicia Juvenil, bajo los pará
metros dé la doctrina de protección integral establecida en la Convención sobre los Derechos
del Niño, priorizando el respeto de principios, garantías y derechos tanto de los adolescentes
en conflicto con la Ley Penal, como para las víctimas.
22.1. El proceso de responsabilidad penal adolescente
lurisdicción y competencia.- El CRPA crea juzgados con competencias especiales para el pro
ceso a adolescentes. Estos responden a la estructura del Nuevo Código Procesal Penal.
Así, los Juzgados de Investigación Preparatoria del Adolescente se encargarán de la investigación
y la etapa intermedia, mientras que el juicio oral estará a cargo de las instancias de Juzgamiento
del Adolescente. Las impugnaciones serán revisadas por las Salas Penales de las Cortes Superio
res de Justicia. Las casaciones y los recursos de queja, por la Sala Penal de la Corte Suprema.
Sujetos procesales.-
El Ministerio Público: Es el titu la r del ejercicio de la acción para perseguir los hechos que re
vistan carácter de infracción. Actúa de oficio, a instancia de la víctima, por acción popularo por
noticia policial. El Fiscal conduce desde su inicio la investigación de la infracción que se le im
pute a un adolescente. Con tal propósito, la Policía Nacional del Perú está obligada a cumplir
los mandatos del Ministerio Público en el ámbito de sufunción.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 643 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
La Policía Especializada: Es un órgano especializado dependiente de la Policía Nacional del
Perú - PNR que interviene exclusivamente en aquellas causas en las que el imputado es un
adolescente. Debe estar capacitada para el tratamiento de adolescentes, en base a los princi
pios de la protección integral de derechosy el enfoque de género.
Adolescentes: Comprende a las o los adolescentes entre los 14 años hasta antes de cumplir
los 18 años de edad, quienes están sujetos a responsabilidad penal y son pasibles de medidas
socioeducativas señaladas en el CRPA luego de un proceso judicial. En consecuencia, el sujeto
activo del sistema penal juvenil en nuestro país, será el adolescente infractor de la ley penal,
comprendido en este grupo etáreo.
Se encuentra exonerado de responsabilidad el adolescente que tenga anomalía psíquica, gra
ve alteración de la conciencia o que sufra alteraciones en la percepción que afectan gravemen
te su concepto de la realidad, que no posea la facultad de comprender el carácter delictuoso
de su acto o para determinarse según esta comprensión.
Defensa Técnica: El Ministerio de Justicia y Derechos Humanos provee la defensa gratuita
especializada a todos los adolescentes que, por sus escasos recursos no puedan designar un
abogado defensor de su elección, o cuando resulte indispensable el nombramiento de un
abogado defensor de oficio para garantizar la legalidad de una diligenciay el debido proceso.
La Víctima - El Agraviado: Se considera agraviado a toda persona que resulte directamen
te ofendido por la infracción o perjudicado por las consecuencias del mismo. Tratándose de
menores de edad, incapaces absolutos, personas jurídicas o del Estado, su representación
corresponde a quienes el Código Procesal Penal u otra norma que la sustituya lo designe. La
afectación de bienes jurídicos colectivos se regula de acuerdo a la legislación sobre la materia.
Órganos Auxiliares: El proceso de responsabilidad penal del adolescente cuenta con cuerpos
técnicos auxiliares especializados en adolescentes, a fin de brindar un enfoque interdiscipli
nario que permita asistiry orientar profesional y exclusivamente tanto a los jueces como a los
fiscales y defensores, debiendo estar integrado por médicos, psicólogos, educadores y traba
jadores sociales. Durante el proceso, intervienen los siguientes equipos: a. El Equipo Técnico
Interdisciplinario del Ministerio Público, b. El Equipo Técnico Interdisciplinario del Poder Judi
cial, que asiste a los Jueces competentes en materia de Responsabilidad penal de Adolescen
tes, c. El Equipo Técnico Interdiscipl i nario del Centro Juvenil.
22.2. Medidas de coerción procesal aplicables al adolescente
Si el adolescente procesado se ausenta o no quiere ira las audiencias pese a estar notificado, el
juez puede imponerle medidas de coerción procesal para obligarlo a que vaya.
La detención, que puede ser policial, mediante arresto ciudadano o resolución judicial por fla
grancia delictiva. Estos arrestos no pueden durar más de 24 horas.
La Suspensión preventiva de derechos como el impedimento de salida del país o de realizar de
terminadas labores, ordenar el impedimento de aproximarse a ciertos lugares, prohibición de
aproximarse al agraviado o víctima u otras personas, según la necesidad del caso en concreto.
La internación preventiva, cuando exista peligro de fuga y convicción de que el adolescente co
metió una infracción sancionable con internación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 644 of 1506 --

UBILEX
La comparecencia, el juez de investigación dicta mandato de comparecencia simple si el Fiscal
no solicita internación preventiva al térm ino del plazo previsto en el presente Código. Tam
bién lo hará cuando, de mediar requerimiento Fiscal, no concurran los presupuestos mate
riales para el dictado de la internación preventiva en caso que sea atendible para los fines del
proceso de responsabilidad penal del adolescente.
La internación dom iciliaria, consiste en cum plir la internación fuera del centro juvenil, per
m itiéndole su permanencia en el ám bito fam iliar bajo el control establecido del CRPA, el
procedimiento y ejecución de esta medida se rige de acuerdo a lo dispuesto para la de
tención dom iciliaria en el Código Procesal Penal u otra norma que la sustituya, en lo que
corresponda.
2 2 .3 .Desarrollo del proceso
En general, se sigue la misma estructura del Código Procesal Penal de 2004: una primera eta
pa de investigación, una intermedia donde se debate la acusación o lasuspensión del proceso
por falta de pruebas y, finalmente, el juicio oral. También se regula un proceso de terminación
anticipada: acuerdo donde el procesado asume su responsabilidad ante el fiscal.
22.4. Salidas alternativas del proceso
Son aquellas instituciones de resolución de conflictos, que buscan que las partes alcancen
acuerdos evitando las consecuencias negativas que puede originar el proceso judicial para el
adolescente. Deben ser incentivadasy propiciadas en todas las instancias del proceso.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 645 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Remisión: Consiste en promover la abstención del ejercicio de la acción penal o la separación
del proceso del adolescente que ha cometido una infracción que no reviste mayor gravedad,
procurando brindarle orientación especializada, dirigida a lograr su rehabilitación y reinser-
ción social por medio de la aplicación de programas de orientación con enfoque restaurativo,
cuya duración no excede de i 2 meses.
Acuerdo Reparatorio: Consiste en el reconocimiento del adolescente del daño ocasionado por
la infracción a lavíctim ayel compromiso para repararlo o la prestación di recta de un servicio por
parte del adolescente en favor de la víctima, con el fin de resarcir el daño. Se puede aplicar en
tanto la infracción afecte el patrimonio de lavíctimay la misma no afecte su integridad o su vida.
Mecanismo Restaurativo: Es una intervención especializada, cuya aplicación está a cargo de
un mediadory, excepcionalmente, por un conciliador extrajudicial acreditado o por un tercero
especializado y autorizado por la autoridad fiscal o judicial competente, que permite el diálo
go entre las partes. Siendo su finalidad lograr un acuerdo entre las partes sobre la reparación
del daño a la víctima, procurando que el adolescente comprenda las consecuencias de sus
actos y repare el daño ocasionado integralmente en forma directa, indirecta o simbólica a la
víctima, promoviendo el restablecimiento de las relaciones con la comunidad.
El mecanismo restaurativo se presta principalmente a través del servicio de mediación penal
juvenil a cargo de la Dirección de Conciliación y Mecanismos Alternativos del MINJUSDH.
El acuerdo al que se arribe mediante el mecanismo restaurativo sirve para la remisión, el
acuerdo reparatorio, la terminación anticipada, la sentencia, el cumplim iento del programa
de orientación, la ejecución de medidas socioeducativasy otros supuestos permitiros en la ley.
22.5. Medidas socioeducativas
Comprobada la participación del adolescente en un hecho penal y declarada su responsabili
dad, el Juez del juicio, puede imponer al adolescente las medidas socioeducativas señaladas
en el CRPAya sea en forma alternativa, indistinta o conjuntamente y en tanto permitan su
ejecución simultánea, debiendo el informe interdisciplinario indicar cuál es la que mejor se
adecúa al adolescente conforme a su interés superiory su fase de desarrollo.
Las medidas socioeducativas deben contener una función pedagógica positiva y formativa,
con la finalidad de facilitar la resocialización y reintegración a la sociedad. En la elección y
determinación de la medida socioeducativa se debe priorizar la que pueda tener un mayor
impacto educativo sobre los derechos de los adolescentes y la que contribuya de mejor mane
ra a su reintegración.
Tipos de medidas socioeducativas: El adolescente que comete un hecho tipificado como deli
to o falta, de acuerdo a la legislación penal, solo puede ser sometido a las siguientes medidas
socioeducativas:
I. Medidas no privativas de libertad:
a. Amonestación
La Amonestación consiste en la llamada de atención que hace el Juez, oralmente, al ado
lescente, exhortándolo a cumplir con las normas de convivencia social.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 646 of 1506 --

UBILEX
La amonestación puede alcanzar a los padres, tutores o responsables del (la) adolescente,
cuando corresponda. En tales casos, el juez extiende la llamada de atención oralmente,
comprometiéndolos a que ejerzan mayor control sobre la conducta del (la) adolescentey
advirtiéndoles de las consecuencias jurídicas de reiterarse la infracción.
La amonestación debe ser clara y directa, de manera que el adolescente y los responsa
bles de su conducta comprendan la ilicitud de los hechos cometidos.
La ejecución de la amonestación queda condicionada al cumplim iento de las medidas
accesorias, las que pueden ser dictadas por un plazo no mayor de 06 meses.
b. Libertad asistida
La libertad asistida consiste en otorgar la libertad al adolescente, obligándose éste a cum
plir programas educativosy recibirorientación, con la asistencia de especialistas y perso
nas con conocimientos o aptitudes en el tratam iento del (la) adolescente. Esta medida se
aplica por un plazo mínimo deseisy máximo de doce meses.
Esta medida se ejecuta en entidades públicas o privadas que desarrollen programas
educativos o de orientación para adolescentes. La Gerencia de Operaciones de Centros
juveniles del Poder judicial, o la que haga sus veces, se encarga de la supervisión de los
programas educativos o de orientación y de administrar el registro de las entidades que
brindan dichos servicios a nivel nacional.
Las entidades donde se ejecuta la medida socioeducativa, o la institución a cargo de los
Centros juveniles, deben informar al juez sobre la evolución del (la) adolescente infractor
cada tres meses o cuando se le requiera.
c. Prestación de servicios a la comunidad
La prestación de servicios a la comunidad consiste en la realización de tareas gratuitas, de
interés social, en entidades asistenciales, de salud, educación que desarrollen programas
educativos o de orientación u otras instituciones similares, ya sean públicas o privadas,
autorizadas para tal fin por la institución a cargo de los Centros juveniles.
Los servicios son asignados, en lo posible, conforme a las aptitudes del (la) adolescente, de
biendo cumplirse en jornadas de seis horas semanales, entre los días sábados, domingos o
feriados, sin perjudicar su salud, su asistencia regular a un centro educativo o de trabajo.
La prestación deservicios a la comunidad tiene una duración no menor de ocho ni mayor
de trein tay seis jornadas.
El adolescente puede ser autorizado para prestar estos servicios en los días hábiles se
manales, computándose la jornada correspondiente. Para tal efecto, el juez toma en con
sideración las circunstancias particulares del (la) adolescente. Las unidades receptoras
deben informar al juez sobre la evolución del (la) adolescente infractor cada dos meses o
cuando se le requiera o cuando exista un incumplimiento injustificado.
d. Libertad restringida
La libertad restringida es una medida socioeducativa en medio libre, que consiste en la
asistenciay participación diariay obligatoria del adolescente a programas de intervención
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 647 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
diferenciados, sin discriminación de género, de enfoque formativo - educativo, que orientan
y controlan sus actividades, cuya duración es no menor de 06 meses ni mayor de un oí año.
La libertad restringida se ejecuta en los Servicios de Orientación al Adolescente o en insti
tuciones públicas o privadas con fines asistenciales o sociales, estas últimas a través de la
las instituciones de los Centro Juveniles informan sobre la evaluación, seguimiento y re
sultados de los programas de intervención diferenciados cada 03 meses al Juez o el Fiscal.
MEDIDAS ACCESORIAS: Estas medidas se pueden aplicar de manera simultánea a las medi
das socioeducativas no privativas de libertad, donde el juez interpondrá que se cumpla ciertas
características especificadas en el artículo 157.2 CRPA:
1. Fijar un lugar de residencia determinado o cambiar de lugar de residencia al actual;
2. No frecuentar a determinadas personas;
3. No frecuentar bares, discotecas o determinados centros de diversión, espectáculos u
otros lugares señalados por el Juez;
4 . No ausentarse del lugar de residencia sin autorización judicial previa;
5. Matricularse en una institución educativa (pública o privada) o en otra cuyo objeto sea la
generación de un oficio o profesión;
6 . Desempeñar una actividad laboral o formativa laboral; siempre que sea posible su ejecu
ción y se adecúe a la legislación sobre la materia;
7. No consumir o ingerir bebidas alcohólicas o drogas;
8 . Internar al adolescente en un centro de salud, público o privado, para un tratam iento
desadictivo;
9. Participar en programas educativos o de orientación; y, otras que el Juez considere ade
cuada y fundamente en la sentencia condenatoria.
II. Internación en un centro juvenil
Presupuestos de la internación: La internación es una medida socioeducativa privativa de li
bertad de carácter excepcional y se aplica como últim o recurso, siempre que se cumpla cual
quiera de los siguientes presupuestos:
1. Cuando se trate de hechos tipificados como delitos dolosos y sean sancionados en el Có
digo Penal o Leyes especiales, con pena privativa de libertad no menor de 06 años, siem
pre que se haya puesto deliberadamente en grave riesgo la vida o la integridad física o
psicológica de las personas;
2. Cuando el adolescente infractor haya incumplido injustificada y reiteradamente las me
didas socioeducativas distintas a la de internación; o,
3. La reiteración en la perpetración de otros hechos delictivos, cuya pena sea mayor a 06
años de pena privativa de libertad en el Código Penal o leyes especiales, en un lapso que
no exceda de dos años.
La internación no puede aplicarse cuando el hecho punible se encuentre tipificado como delito
doloso y sancionado en el Código Penal o Leyes especiales, con penas distintas a la privativa de
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 647

-- 648 of 1506 --

UBILEX
libertad. En ningún caso la duración de la medida socioeducativa de internación puede ser ma
yor a la pena abstracta establecida en el tipo penal doloso del Código Penal o Leyes especiales.
La internación es cumplida en Centros juveniles exclusivos para adolescentes, preferentemen
te en el más próximo al entorno fa m i Ii a r y social del infractor. Los adolescentes son ubicados
según su edad, sexo, la gravedad de la infracción y el informe preliminar del Equipo Técnico
Interdisciplinario del Centro Juvenil.
Duración de la internación: La duración de la internación es de uno oí hasta seis 06 años
como máximo, cuando se cumpla cualquiera de los presupuestos señalados. No obstante, la
medida socioeducativa de internación es no menor de 04 ni mayor de 06 años, cuando el ado
lescente tenga entre i6 y menos de 18 años de edady se trate de los siguientes delitos26:
1. Parricidio.
2. Homicidio calificado.
3. Homicidio calificado por la condición de la víctima.
4. Feminicidio.
5. Lesiones graves (segundo y tercer párrafo).
6 . Lesiones graves cuando la víctima es menor de edad, de la tercera edad o persona con
discapacidad.
7. Lesiones graves por violencia contra la m ujery su entorno familiar.
8 . Instigación o participación en pandillaje pernicioso.
9. Secuestro.
10. Trata de personas.
11. Formas agravadas de la trata de personas.
12. Violación sexual.
13. Violación de persona en estado de inconsciencia o en la imposibilidad de resistir.
14. Violación de persona en incapacidad de resistencia.
15. Violación sexual de menor de edad.
16. Robo agravado.
17. Extorsión.
18. Promoción o favorecimiento al Tráfico Ilícito de Drogasy otros.
19. Tráfico Ilícito de Insumos Químicos y Productos Fiscalizados.
20. Comercialización y cultivo de amapola y marihuana y su siembra compulsiva.
21. Formas agravadas de tráfico de drogas.
Asimismo, cuando el adolescente sea integrante de una organización criminal, actúe por en
cargo de ella o se encuentre vinculado a la misma, conforme a las consideraciones de la Ley N°
30077, Ley contra el Crimen Organizado, así como conforme a lo dispuesto en los artículos 317
y 317-B del Código Penal.
26 Cuando se trate de delitos, la medida socioeducativa de internación es no menor de 01 ni mayor de 04 años,
para los adolescentes entre I 4y 18 años de edad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 649 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Cuando se trate de los delitos antes mencionados y el adolescente tenga entre catorce (14) y
menos de dieciséis años (16), la medida socioeducativa de internación es no menor de 03 ni
mayor de 05 años.
Excepcionalmente, cuando se trate del delito de sicariato (108-C) o violación sexual de menor
de edad seguida de muerte o lesión grave (173-A), así como de los delitos regulados mediante
Decreto Ley N° 25475, la medida de internación puede durar de seis (06) a ocho (08) años, si
el adolescente tiene entre catorce (14) y menos de dieciséis (16) añosy de ocho (08) a diez (10)
años, si el adolescente tiene entre 16 y menos de 18 años de edad.
Variación de la internación: Cumplida la tercera parte del plazo de la internación impuesto
y con el informe favorable del Equipo Técnico Interdisciplinario del Centro Juvenil, el Juez, de
oficio o a pedido de parte, previa audiencia, puede variar la medida socioeducativa de interna
ción considerando el respeto al principio educativo, del interés superior del adolescente y que
se hayan cumplido los fines de la medida socioeducativa.
Las medidas socioeducativas impuestas al adolescente cesan por cumplimiento de la duración
impuesta en la sentencia por disposición del Juez mediante resolución motivada, ordenándose
se borre los datos del adolescente del registro de adolescentes infractores del poder judicial.
Concurrencia de medidas socioeducativas: Durante la ejecución de medidas socioeducati
vas, se atenderán los siguientes supuestos de concurrencia:
1. En caso que concurra una medida privativa de libertad con una medida no privativa de li
bertad, el juez que impuso la internación resuelve la ejecución simultánea, sucesiva o la
absorción de la segunda en la primera, previo informe del equipo técnico interdisciplinario.
2. En caso que concurran dos medidas no privativas de libertad, el juez que impuso la pri
mera sentencia resuelve la ejecución simultánea, sucesiva o la absorción de la medida de
menor en la de mayor intensidad, previo informe del equipo técnico interdisciplinario.
3. En caso que concurran dos medidas privativas de libertad, el juez que impuso la primera
internación resuelve sobre la absorción de la medida de menor en la de mayor duración,
previo informe del equipo técnico interdisciplinario.
4. En caso que concurra una medida no privativa de libertad con una medida de internación,
el juez que impuso la internación resuelve sobre la absorción de la primera en la segunda,
previo informe del equipo técnico interdisciplinario.
23. Delitos contra la familia: Bigamia. Omisión a la asistencia familiar. Sustracción de
menores (tratamiento cuando es internacional)
1. Bigamia
Descripción normativa:
Artículo 139 CP.- El casado que contrae matrimonio será reprimido con pena privativa de libertad no
menor de uno ni mayor de cuatro años.
Si, respecto a su estado civil, induce a error a la persona con quien contrae el nuevo matrimonio la pena
será privativa de libertad no menor de dos ni mayor de cinco años.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 650 of 1506 --

UBILEX
Bien jurídico protegido: La familia. Protegiéndose tanto el m atrim onio como institución so
cial que se caracteriza por su unidad expresada en forma monogámica. Así como el grupo
reducido de personas que forman parte: la madre, el padrey los hijos, con exclusión de miem
bros ajenos a la familia.
Tipicidad Objetiva
El sujeto activo es la persona casada (tipo especial propio), siendo posible que ambos contra
yentes cometan bigamia. El sujeto pasivo es la colectividad y los afectados, como el cónyuge
del matrimonio anterior o primigenio, así como de la persona soltera, viuda o divorciada que
contrae nupcias, sin saber el estado civil de casado del sujeto activo.
La conducta típica consiste en que la persona casada -mediante matrimonio valido en terri
torio nacional o extranjero- contrae nupcias con persona distinta a la de su anterior o primer
matrimonio. La nulidad del matrimonio anterior o primigenio excluye el tipo.
No cuenta el matrimonio religioso, atipicidad.
Es un delito especial propio, el sujeto activo siempre será una persona unida en matrimonio
eficaz.
Tipicidad subjetiva
Es el dolo.
Antijuridicidad: Se entiende por antijuridicidad del comportamiento, lo opuesto al ordena
miento jurídico; y cuando arremete contra el bien jurídico familia, en este caso se constata la
acción típica bigamia que se califica luego como antijurídica (injusto).
Consumación: Este delito se consuma cuando la persona casada contrae nuevas nupcias, se
admite tentativa.
2. Omisión a la asistencia familiar
Descripción normativa:
Aí 1 . 149 CR El que omite cumplir su obligación de prestar los alimentos que establece una resolución
judicial será reprimido con pena privativa de libertad no mayor de tres años, o con prestación de servicio
comunitario de veinte a cincuentldós jornadas, sin perjuicio de cumplir el mandato judicial.
Si el agente ha simulado otra obligación de alimentos en connivencia con otra persona o renuncia o
abandona maliciosamente su trabajo la pena será no menor de uno ni mayor de cuatro años.
Si resulta lesión grave o muerte y éstas pudieron ser previstas, la pena será no menor de dos ni mayor de cua
tro años en caso de lesión grave, y no menor de tres ni mayor de seis años en caso de muerte.
Bien jurídico protegido: La familia, específicamente la asistencia familiar, es decir los alimen
tos, pues “se trata de un interés tutelado por razones de humanidad".
Tipicidad Objetiva
Sujeto activo, es el agente que no cumple, siendo su deber jurídico cumplir la prestación eco
nómica, previamente establecida por resolución judicial en sede civil.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 651 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Sujeto pasivo, es la persona quién sufre las consecuencias del ilícito penal de omisión a la
asistencia familiar.
Conducta típica, el comportamiento del sujeto activo consiste en om itir el cumplim iento de
la prestación de alimentos establecida en una resolución judicial, siendo un delito de omisión
propia, donde la norma de mandato consiste en una obligación que pesa sobre el sujeto acti
vo de cumplir con sus deberes legales de asistencia.
Es así que, conociendo su deber jurídico, se le requiere mediante resolución judicial para que
cumpla con la obligación del pago alimentario y no obstante ello persiste en su incum pli
miento, por lo que se penaliza su conducta omisiva ante la resistencia a la autoridad judicial,
en aplicación al artículo trescientos sesentay ocho del Código Penal.
En este injusto penal, no es permitido el pago parcial del deber jurídico que corresponde al
pago alimentario por parte del agente, para que quede sin efecto, dicho pago debe ser total,
de lo contrario procede la acción penal por omisión al deber impuesto no cumplido; "como
señala TAPIA VIVES “Si se permite el pago parcial o tardío de la obligación alimentaria, se debi
litaría en gran medida la pretensión de prevención general positiva inminente que se intenta
conseguir a través de la pena".
Agravantes
Si el agente ha simulado otra obligación de alimentos en connivencia con otra persona o
renuncia o abandona maliciosamente su trabajo.
Si resulta lesión graveo m uertey éstas pudieron ser previstas, pero prevista por el agente.
Genéricamente, la penalidad aumenta si el sujeto activo es reincidente o habitual.
Tipicidadsubjetiva: Es el dolo. En caso de que el agente se encuentre sin capacidad económi
ca, se excluirá el tipo subjetivo.
Antijuridicidad: Se entiende por antijuridicidad del comportamiento, lo opuesto al ordena
miento jurídico; y cuando arremete contra el bien jurídico familia, específicamente la asisten
cia familiar. Si el sujeto trata de conservar su subsistencia, estamos ante un estado de necesi
dad justificante.
Requisito de procedibilidad: Notificación de la obligación alimentaria decidida en sede ju
risdiccional.
Delito permanente: El delito de Omisión a la Asistencia Familiar dura mientras persista el
deberá la asistencia fa m iliary por ello se dice que es un delito permanente, sólo deja de serlo
si se cumple en forma total el deber jurídico impuesto.
Delito de peligro: La responsabilidad penal conlleva la idea de peligro, la resolución judicial
impuesta en sede civil, reestablece el equilibrio, obligando el cumplim iento del derecho ali
mentario, y de esta manera el daño ocasionado al bien jurídico que es la familia, es reparado
median te la asistencia fam iliar por los conceptos de alimentos, salud, vivienda, educación,
recreación y con ello el peligro contra la fa m iliay su seguridad jurídica se reestablece.
La responsabilidad penal conlleva la idea de peligro, la resolución judicial impuesta en sede
civil, reestablece el equilibrio, obligando el cumplimiento del derecho alimentario, y de esta
manera el daño ocasionado al bien jurídico que es la familia, es reparado median te la asisten-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 65

-- 652 of 1506 --

da familiar por los conceptos de alimentos, salud, vivienda, educación, recreación y con ello el
peligro contra la fa m iliay su seguridad jurídica se reestablece.
Consumación: Este delito se consuma cuando el agente omite prestar alimentos, estando de
bidamente notificado, pues el ilícito penal se verifica con el incumplimiento al requerimiento
judicial debido a que se ha mantenido en el tiempo la realización típica, ya que el mero co
nocimiento de la resolución judicial que ordena una pensión alim enticiay su omisión a esta,
invocado por Salinas Siccha27, solo resulta ser la acción que instaura el estado antijurídico.
3. Sustracción de menores
Descripción normativa:
® Artículo i 47 CP.- El que, mediando relación parenial, sustrae a un menor de edad o rehúsa entregarlo
a quien ejerce la patria potestad, será reprimido con pena privativa de libertad no mayor de dos años.
La misma pena se aplicará al padre o la madre u otros ascendientes, aún cuando aquellos no hayan
sido excluidos judicialmente de la patria potestad.
Bien jurídico protegido: Luis Bramont Arias, señala que la “libertad" es el bien jurídico a cau
telar; sin embargo, Luis Reyna, considera que el verdadero bien jurídico es la “patria potestad”,
considerado aquel derecho como el vínculo de guarda, cuidado y responsabilidad que une al
progenitor con su hijo.
Igualmente se señala su doble dimensión como derecho-debery que cualquiera de estos ám
bitos si es vulnerado, es pasible de provocar una denuncia penal.
Tipicidadobjetiva: El sujeto activo es el pariente. Incluyéndose a los padres privados del ejer
cicio de la patria potestad. También, es autor el padre, la madrey los ascendientes no privados
de ejercer la patria potestad. El sujeto pasivo es el que ejerce la patria potestad (padres y todo
aquel que ejerza la patria potestad legalmente) y el menor de edad.
La conducta típica consiste en sustraer por un periodo relevante al menor de edad (Ti po de ac
ción) o rehúsa entregarlo a quien ejerce la patria potestad legalmente sobre el menor de edad
(tipo de omisión propia), pero debiendo existir previamente un reclamo del sujeto pasivo, y
sabiendo de esto el agente. En este últim o supuesto, el menor de edad está legalmente con el
sujeto activo, pues esto es antes de rehusarse a entregarlo; mientras que en la sustracción no
se aprecia esto.
El artículo 147 del CP señala dos “actos” configuradores del tipo penal: “la sustracción” y el “re-
husamiento de entrega”.
Con el acto de sustracción, podemos entender todo acto cometido por un progenitor, con
ducente a “apartar”, “alejar”, “separada un menor de edad respecto del otro progenitor.
Cuando se analiza el acto de “sustraer” se podría provocar inclusive acciones en el ámbito
internacional (sustracción internacional de menores) con lo cual la tutela judicial efectiva
para el agente pasivo se torna en un vía crucis imposible de ser solucionado.
27 SALINAS SICCHA, Ramiro. Derecho penal. Parte especial, segunda edición (Lima: Grljley, 2007), pp. 410-411.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 653 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Con el rehusamiento de entrega, podemos entender aquellas manifestaciones en las cua
les un progenitor se resiste a variar “su" situación de tenencia efectiva sobre su hijo.
La acción de “rehusar” en este sentido podría ofrecer mayores problemas para su deter
minación, si consideramos que esta negación de acción positiva puede ser manifestada
sólo oralmente (“no te entrego”) o vía acción inmediata (variación de dom icilio del agente
activo). Acciones intimidatorias que no necesariamente configuran una mayor gravosi-
dad a la situación y que puede ser solucionado inclusive a nivel policial o fiscal, a través de
acciones disuasivas.
Tipo subjetivo: Existe el dolo, aunque nuestro sistema penal a nivel jurisprudencia no ha con
siderado el elemento del “dolo” en los imputados.
Complicidad: El segundo párrafo del artículo 147° CP, señala que los ascendientes del proge
nitor calificado como agente activo, pueden ser catalogados como cómplices de este delito, al
tener el térm ino “otros ascendientes".
Antijuridicidad: Se entiende por antijuridicidad del comportamiento, lo opuesto al ordena
miento jurídico (antijuridicidad formal); y cuando arremete contra el bien jurídico derechos
y deberes inherentes a la patria potestad y la seguridad del menor de edad (antijuridicidad
material).
Consumación: Este delito se consuma, en el caso de la sustracción con el desplazamiento del
menor. Se admite la tentativa.
En cuanto al rehusamiento se consuma con la omisión. No se admite la tentativa.
Sustracción de menor (Ámbito Internacional)
Cuando uno de los padres decide cambiar unilateralmente el lugar de residencia del hijo re
iteramos comete el delito de sustracción de menor y cuando tal residencia se ubica en otro
país, procede la aplicación de la Convención internacional sobre los Efectos Civiles de la Sus
tracción de Menores. En tales casos, puede ocurrir que el padre o madre que lleva al niño fuera
de país cuente con una autorización temporal u trasgreda tal autorización y decida quedarse
más tiempo, o ilimitadamente, en otros casos sin contar con autorización, se lleva al niño (a) y
lo retiene sin justificar motivo alguno.
Tales circunstancias han sido materia de regulación en la Convención de las Naciones Unidas
sobre los Derechos del N iñoy con anterioridad a ella por la Convención sobre Sustracción In
ternacional de Menores.
El Perú ha ratificado la Convención sobre los aspectos civiles de la sustracción Internacional
de menores (Convención de la Haya), que entró en vigor en nuestro país el oí de agosto del
2001. Así el Perú puede ser el país que solicita la restitución o el país al cual se le solicita la
restitución.
La finalidad de la Convención de sustracción:
a. Garantizar la restitución inmediata de los menores trasladados o retenidos de manera
ilícita en cualquier Estado contratante; y
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 65

-- 654 of 1506 --

UBILEX
b. Velar porque los derechos de custodia y de visita vigentes en uno de los Estados contra
tantes se respeten en los demás Estados contratantes.
De la aplicación de la Convención de sustracción y sus principios:
En la aplicación de la convención se tienen los siguientes principios:
a. - El Principio del Interés superiordel niño (a).
b. - La celeridad.
c. - La inmediación.
d. - La concentración de actos procesales.
e. - La contradicción.
f. - La participación del niño.
Excepciones a la Restitución: La Convención de sustracción dispone la restitución salvo que
se demuestre que el menor ha quedado integrado en su nuevo ambiente. Así lo dispone el
segundo párrafo del artículo 12o. También se protege el Interés Superior del Niño cuando se
indica en el artículo 13.b) como excepciones a la restitución que: “Existe un grave riesgo de que
la restitución del menor lo exponga a un peligro grave físico o psíquico o de cualquier otra
manera ponga al menor en una situación intolerable”.
En cuanto a la opinión del niño (a) es de resaltar lo establecido por el segundo párrafo del
artículo 13 en tanto permite que se acate la opinión del niño cuando se opone a la restitución.
Sobre los plazos: Uno de los aspectos más importantes de este convenio es el del cum plim ien
to de los plazos, el cual resulta de preocupación en tanto de no resolverse con inmediatez la
finalidad de la restitución no podrá cumplirse.
