Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 655 of 1506 --

TEMA 4
TEMAS DE L
ESPECIALIDAD COMERCI
i. DERECHO SOCIETARIO
1. Reglas aplicables a todas las sociedades
Las Reglas Generales aplicables a las Sociedades en el Peni, se regulan en el Libro primero de
la Ley N °26887-Ley General de Sociedades-, en adelante la Ley (LGS). Estas reglas correspon
den a los preceptos fundamentales que poseen en su naturaleza las sociedades en común. En
el Perú, los tipos de sociedades que se pueden constituir son los siguientes:
1. Sociedad Anónima.
2. Sociedad Colectiva.
3. Sociedad en Comandita.
4. Sociedad Comercial de Responsabilidad Limitada.
5. Sociedades Civiles.
i) Naturaleza jurídica de la sociedad:
En Derecho Societario, uno de los temas que sigue siendo discutido por los especialistas,
es el relacionado con la naturaleza jurídica del acto constitutivo por medio del cual se crea
una sociedad, existiendo diversas posiciones al respecto.
Por un lado, la corriente contractualista considera que el contrato es el vínculo jurídico
que une a los socios fundadores de la sociedad originariamente, tal contrato es uno «sui
generis». Por otro lado, la corriente institucionalista considera que la sociedad nace por
un acto jurídico no contractual, es decir, por imperio de la ley es que se le reconoce como
sujeto de derecho, uno de los fundamentos por los que esta teoría niega la calidad de
contrato al acto constitutivo de una sociedad es que la modificación del pacto social re
quiere una mayoría calificada a diferencia de un contrato que requiere un acuerdo uná
nime entre los intervinientes. Finalmente, la teoría mixta, recoge lo mejor de las teorías
anteriores.
No obstante, nuestra Ley no adopta alguna de las teorías antes mencionadas, sino que
señala en su artículo primero que aquellos que constituyen una sociedad convienen en
aportar bienes o servicios para el ejercicio en común de actividades económicas.
ii) Modalidades de constitución:
El artículo tercero de la Ley señala que, la sociedad colectiva, la sociedad en comandita,
la sociedad comercial de responsabilidad limitada y las sociedades civiles, solo pueden
constituirse simultáneamente en solo un acto. Mientras que, la sociedad anónima es
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 656 of 1506 --

la única que permite dos modalidades distintas de constitución, de un lado la constitu
ción simultánea en un solo acto por los socios fundadores o en forma sucesiva mediante
oferta a terceros contenida en el programa de fundación otorgado por los fundadores.
Adviértase que en este artículo se alude a la «oferta a terceros» que no necesariamente es
equivalente a la llamada oferta pública,ya que, tratándose de este últim o caso, según el
artículo 56o, 2do párrafo de la Ley, cuando la oferta a terceros tenga la condición legal de
oferta pública le es aplicable la legislación especial que regula la materia, que no es otra
que la Ley del Mercado de Valores y sus normas reglamentarias y complementarias.
iii) Pluralidad de socios:
La Ley en su artículo 4 ° ha establecido como regla general que para constituir una so
ciedad se requiere cuando menos de dos socios, que pueden ser personas naturales o
jurídicas, eliminándose como consecuencia de ello, el requisito de tres socios que exigía
la anterior ley para la constitución de sociedades anónimas. Caso especial ocurre con los
cónyuges que se encuentran bajo el régimen de una sociedad de gananciales, debido a
que en dicho régimen es la sociedad de gananciales la que adquiere de titularidad de las
acciones o participaciones de la sociedad y es considerada como una sola socia, sin em
bargo, es posible que los conyugues sean considerados socios de manera personal si los
aportes de estos se tratan de bienes propios según la R eso lu ció n N ° 2 0 6 4 - 2 0 1 7 -S U N A R P -
TR-L, la cual agrega que los integrantes de una sociedad conyugal que busquen ser reco
nocidos como dos accionistas distintos al momento de constituir una sociedad, deberán
proveer pruebas o títulos idóneos que permitan acreditar dicha circunstancia, con el ob
jetivo de enervar los alcances de la presunción ju ris ta n tu m contenida en el inciso 1 del
artículo 311 del Código Civil: “Los bienes se presumen sociales, salvo prueba en contrario”.
La ley establece que para todos los modelos societarios bastarán 2 socios. Si se pierde esta
pluralidady no se reconstituye en un plazo de seis meses se disuelve de pleno derecho al
término de ese plazo, constituyendo ésta una causal de disolución recogida en el inciso
sexto del artículo 407o. Al respecto, la R eso lu ció n N ° 2 0 0 6 -2 0 1 1 -S U N A R P -T R -L señala que
la restitución de la pluralidad de socios puede realizarse por transferencia de acciones o
por aumento de capital. Asimismo, la R esolución N ° 3 8 i-2 0 ii-S U N A R P -T R -A agrega que,
una vez transcurrido los 6 meses para la reconstitución de la pluralidad de socios, resulta
rá improcedente cualquier inscripción de un nuevo accionista, toda vez que la sociedad,
si bien aún no se ha extinguido, se ha disuelto de pleno derecho.
En el s e g u n d o p á rra fo d e l a r t íc u lo 4 0 LG S, la n o r m a e s t a b le c e q u e no se h a c e e x ig ib le la
p lu r a lid a d d e s o c io s c u a n d o el ú n ic o s o c io es el E s ta d o o en o tro s c a s o s s e ñ a la d o s e x p re
s a m e n t e p o r la Ley.
