Tema 4: Temas de la especialidad comercial
Por último, en el párrafo final del artículo 5o se consagra el derecho de cualquier socio a
demandar el otorgamiento de la escritura pública de constitución, cuando el pacto social
no se hubiese elevado a dicha condición, lo cual se podrá lograr a través del proceso su-
marísimo.
iv) Personalidad jurídica:
El artículo 6 o de la Ley señala que la sociedad adquiere personalidad jurídica desde su ins
cripción en el registro y la mantiene hasta que se inscribe su extinción. Al respecto, el Tri
bunal Registral, percibe el concepto de persona jurídica como una creación del derecho,
cuyos elementos son la organización, la finalidady el reconocimiento formal. Porun lado,
la organización y la finalidad serán realidades preexistentes que el Derecho acepta por ser
valiosos para la comunidad. Por otro lado, el reconocimiento formal es la exigencia que el
ordenamiento jurídico ha previsto para que la persona jurídica adquiera autonomía dis
tinta desús integrantes y que se traduce en el cumplim iento de la inscripción registral. En
tal sentido, la capacidad de sertitularde derechosy obligaciones permiteque lasociedad
responda (y no los socios) por las deudas que aquella haya contraído en el ejercicio de las
actividades económicas elegidas (R eso lu ció n N ° 2 8 4 - 2 0 i 8 -S U N A R P -T R -T ).
Es importante destacar que la Ley, en la sección cuarta del Libro IV, en forma sistemática,
regula la extinción de las sociedades como la fase final del proceso de disolución y liqui
dación de sociedades. La R esolución N ° 3111-2018-S U N A R P -TR -L prescribe que la extin
ción implica la pérdida de la persona jurídica, es decir, la sociedad dejó de ser sujeto de
derechosy obligaciones, por consiguiente, no puede ser requerida para el cumplim iento
de las obligaciones que hubiera quedado pendientes. En tal sentido, el Tribunal Registral
establece como criterio que, en la partida registral de la sociedad extinguida, ya no po
drán extenderse inscripciones, por lo que deberá cerrarse la partida registral y darse de
baja la denominación o razón social del índice.
S o b re e ste t e m a es im p o r t a n t e s e ñ a la r la e s p e c ia l s itu a c ió n q u e se d e r iv a d e u n a s e n t e n c ia
f ir m e q u e d e c la r e la n u lid a d d e l p a c to s o c ia l, u n a v e z q u e h a q u e d a d o in s c r it a la e s c ritu ra
p ú b lic a d e c o n s tit u c ió n p o r c u a le s q u ie r a d e la s c a u s a le s p r e c is a d a s en el a r t íc u lo 33o LGS.
Si bien conforme al artículo 36o LGS, la sentencia firm e que declara la nulidad, debida
mente inscrita en el registro, disuelve de pleno derecho la sociedad, esta mantiene su per
sonalidad jurídica sólo para los fines de liquidación, con el fin de proteger a los terceros
de buena fe que hubieren contratado con la sociedad.
Respecto a los actos anteriores celebrados en nombre de la sociedad antes de su inscrip
ción en el Registro, el artículo 70 de la Ley supedita la validez de estos al cumplim iento de
dos condiciones: que se inscriba la sociedad en el registro y a que sean ratificados por la
sociedad dentro de los tres meses siguientes, estableciéndose que, si se omite o retarda
el cumplim iento de estos requisitos, quienes hayan celebrado actos en nombre de la so
ciedad responden personal, ilim itaday solidariamente frente a aquellos con quien hayan
contratado y frente a terceros.
S in p e r ju ic io d e lo a n t e s m e n c io n a d o , el a r t íc u lo 71 d e la Ley, s e ñ a la e n s u s e g u n d o p á rra fo
q u e , a f a lt a d e p r o n u n c ia m ie n t o d e la s o c ie d a d en el c it a d o p la z o d e tre s m e s e s a q u e se
