UBILEX
refiere el artículo 7o, se presume que los actos y contratos celebrados por los fundadores
han sido ratificados.
iv) Convenios:
La Ley en su artículo 8 o reconoce plena validez a los convenios suscritos entre socios o
entre estos y terceros, a partir del momento que les sean debidamente comunicados a la
sociedad, siendo por tanto exigibles en todo cuanto le sea concerniente. Señala también
que, si hubiera contradicción entre alguna estipulación de dichos convenios y el pacto
social o el Estatuto, prevalecerán estos últimos, sin perjuicio de la relación que pudiera
establecer el convenio entre quienes lo celebraron. Estas disposiciones constituyen una
importante innovación de la Ley por cuanto hacen obligatorias los llamados convenios
parasociales o extrasocietarios, adoptándose con ello la misma posición que las moder
nas legislaciones europeas. Ahora bien, la falta de comunicación de los convenios a la
sociedad no implica que estos son inválidos, sino que, dada su naturaleza contractual, son
válidosy exigibles entre los intervinientes más nooponibles por o ante la sociedad.
Respecto específicamente a las acciones de las sociedades anónimas, debe señalarse que
en el artículo 101o de la Ley se establece que las limitaciones a la libre transmisibilidad
de las acciones son obligatorias para la sociedad cuando estén contempladas en el pacto
social, en el Estatuto o se originen en convenios entre accionistas y terceros, que hayan
sido notificados a la sociedad. Tales limitaciones se deberán inscribir en la matrícula de
acciones y en los respectivos certificados. Ahora bien, tal prohibición no podrá exceder de
diez años prorrogables antes del vencimiento por periodos no mayores.
F in a lm e n t e , en el t e m a d e lo s c o n v e n io s , es im p o r t a n t e s e ñ a la r q u e , t r a t á n d o s e d e s o c ie
d a d e s a n ó n im a s a b ie r t a s , p o r d is p o s ic ió n e s p e c íf ic a d e l a r t íc u lo 2 5 4 o d e la Ley, e n e sta s
