g a n lim it a c io n e s , r e s t r ic c io n e s o p r e fe r e n c ia s v in c u la d a s a la n e g o c ia c ió n o lib r e t r a n s m i
s ib ilid a d d e la s a c c io n e s , a u n c u a n d o se n o t if iq u e n o se in s c r ib a n en la s o c ie d a d , s ie n d o
e s ta u n a e x c e p c ió n a la re g la .
v) Denominación o razón social:
La sociedad tiene una denominación o una razón social, según corresponda a su forma
societaria, así las sociedades capitalistas como la sociedad anónima contarán con de
nominación social, mientras que las sociedades personalistas contarán con razón social
como la sociedad colectiva o sociedad civil.
En la Ley, se ha ampliado la protección del nombre tanto de la denominación social como
de la razón social. La Ley anterior era muy restrictiva en este sentido, por cuanto sólo otor
gaba protección a un nombre igual. Con la actual Ley no se puede adoptar un nombre
igual, salvo que se demuestre legitimidad para ello, ni tampoco una denominación com
pleta o abreviada o razón social que contenga nombres de organismos o instituciones pú
blicas o signos distintivos protegidos por derechos de propiedad industrial o elementos
protegidos por derecho de autor salvo que se demuestre estar legitimado para ello. En la
misma línea, el Tribunal Registral en la R esolución N ° 2 6 4 -2 0 1 8 -S U N A R P -T R -L establece
que uno de los atributos de la personalidad es contar con un signo distintivo que sirva
58 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 659 of 1506 --

Tema 4. Temas de la especialidad comercial
para diferenciar a cada persona de las demás, así, en el caso de las personas jurídicas, el
signo distintivo podrá ser una razón social o una denominación social.
Asimismo, con el a rtic u ló lo 0 de la Ley, se ratifica el derecho a reservar la preferencia regis
tra! de la denominación o razón social a inscribir, recogiéndose con ello lo ya vigente por
mandato de Ley N° 26364. Es decir, mediante un trámite registral se impide que terceros
obtengan la inscripción del nombre o los nombres que se han escogido para incorporar
los como denominación o razón social de una sociedad, operando este derecho tanto
para las sociedades que recién se constituyan como para las que opten por cambiar o mo-
dificarsu pacto social o Estatuto, alcanzando esta protección a la denominación completa
o abreviada de la sociedad. Lo que se trata con dicha norma es que, quienes hayan elegido
una denominación o razón social podrán reservarla por 30 días, período dentro del cual
deberán realizarse los actos necesarios para solicitar la inscripción definitiva utilizando
el nombre que han reservado. Para este fin, el índice Nacional de Reserva de Preferencia
Registral de Nombre, Denominación o Razón Social se encuentra integrado en el índice
Nacional de Registro de Personas jurídicas.
La reso lu ció n N ° 2173-2016 -S U N A R P -T R -L considera necesario atendera la finalidad que
cumple el nombre en la persona jurídica, evitándose en todo momento evitar que este
induzca a error o confusión sobre el tipo de persona jurídica a constituir. Asimismo, el
Tribunal Registral, en la Resolución N° 353-201 o -S UÑARP-TR-T establece los criterios a
evaluar para determinar la posibilidad de que la denominación o razón social pueda in
ducir a error o confusión sobre el tipo de persona jurídica de la sociedad.
vi) Objeto social:
El artículo 11o de Ley establece como regla general que la sociedad circunscribe sus ac
tividades a los negocios, operaciones o actividades lícitas indicadas en su objeto social,
entendiéndose incluidos los actos relacionados con el mismo, que coadyuven a la realiza
ción de sus fines, aunque no estén expresamente indicados en el pacto social o en el Esta
tuto. La sociedad no puede tener por objeto el desarrollo de actividades que la ley atribuye
con carácter exclusivo a otras entidades o personas. La relevancia del objeto social ha sido
establecida por el Tribunal Registral en distintas oportunidades, quien ha indicado que
este debe servir como instrumento que permita salvaguardar el principio de seguridad
del tráfico, la protección al tercero de buena fe y la defensa del interés del socio singular
a no ver frustrado el contenido del objeto social (R eso lu ció n N ° 2 9 4 5 -2 0 2 1 -S U N A R P -T R ).
den lo relacionado a los actos que coadyuven a la realización del objeto social, la R eso lu
ción N ° 3 3 9 -2 0 1 9 -S U N A R P -T R -A señala que, al comprender una gran variedad de actos,
no se requiere que estén expresamente indicados. En tal sentido, al momento de registrar
el estatuto social, el Registrador no podrá calificar si dicho acto coadyuva o no a los fines
societarios.
El artículo 120 LGS, referido a los alcances de la representación, se ocupa de los actos cono
cidos como Ultra Vires, destacando la protección que imprime la ley al tercero de buena
fe que contrata con la sociedad. En efecto, si los representantes de una sociedad celebran
determinados actos o contratos dentro de los límites de las facultades que le han sido
conferidas, pero comprometiéndola en negocios u operaciones no comprendidos dentro
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 660 of 1506 --

UBILEX
de su objeto social, aquellos deben ser cumplidos por la sociedad. Al respecto, la Casación
N° 1788-2003 recalca la importancia de la buena fe de los terceros contratantes, toda vez
que, si no hubiera mediado buena fe, la sociedad quedaría eximida de responsabilidad.
Por otro lado, el artículo 13 de la Ley señala que aquellos que no están autorizados para
ejercer la representación de la sociedad no la obligan con sus actos, aunque los celebren
en nombre de ella. La responsabilidad civil o penal por tales actos recae exclusivamente
sobre sus autores.
Sobre el nombramiento u otorgamiento de poderes a los administradores, liquidadores
o a cualquier otro representante de la sociedad, el artículo 14o de la Ley prescribe que
surten efecto desde su aceptación expresa o tácita, siendo tácita cuando las referidas per
sonas empiecen a desempeñar la función o a ejercer los poderes conferidos. Asimismo,
tras la modificación legislativa del año 2017, el gerente general, por su solo nombramien
to y salvo estipulación en contrario, goza de todas las facultades de representación ante
personas naturales y/o jurídicas privadas y/o públicas para el inicio y realización de todo
procedimiento, gestión y/o trám ite a que se refiere la Ley del Procedimiento Administra
tivo General. Igualmente, goza de facultades de disposición y gravamen respecto de los
bienes y derechos de la sociedad, pudiendo celebrar todo tipo de contrato civil, bancario,
mercantil y/o societario previsto en las leyes de la materia, firm a ry realizar todo tipo de
operaciones sobre títulos valores sin reserva ni limitación alguna y en general realizar y
suscribir todos los documentos públicos y/o privados requeridos para el cumplim iento
del objeto de la sociedad. No obstante, la sociedad podrá imponer limitaciones y restric
ciones a estas facultades, debiendo estar expresamente inscritas en la partida electrónica
de la sociedad para ser oponibles a terceros.
Es decir, actualmente el artículo 14 de la Ley otorga amplias facultades al gerente gene
ral por lo que es recomendable evaluar eventuales limitaciones a sus poderes, las cuales
deben constar inscritas en la partida electrónica de la sociedad, caso contrario no serán
oponibles a terceros.
vi i) Duración de la sociedad:
Según el artículo 19o LGS, la duración de la sociedad puede ser por plazo determinado o
indeterminado, y salvo sea prorrogado con anterioridad, vencido el plazo determinado, la
sociedad se disuelve de pleno derecho. Ahora bien, el acuerdo de prórroga debe adoptar
se antes del vencimiento del plazo de duración e incluso inscribirse en el Registro, lo cual
constituye una novedad legislativa. Por el contrario, vencido el plazo, la sociedad queda
incursa en la causal de disolución prevista en el inciso 1) del artículo 407o de la Ley, la mis-
maque opera de pleno derecho.
vííi) Domicilio:
Respecto al domicilio, se establece en el artículo 20o LGS que la sociedad tiene por dom i
cilio el señalado en el Estatuto, donde desarrolla alguna de sus actividades principales o
donde instala su administración. En caso de discordancia entre el dom icilio de la socie
dad que aparece en el registro, y el que efectivamente se ha fijado, se puede considerar
cualquiera de ellos.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 661 of 1506 --

Tema 4: Temas de la especialidad comercial
También se establece que la sociedad constituida en el Perú, tiene su dom icilio en territo
rio peruano salvo cuando su objeto social se desarrolle en el extranjero y fije sudom icilio
fuera del país.
ix) Aportes:
Cada socio está obligado frente a la sociedad por lo que se haya comprometido a aportar
al capital. Contra el socio moroso la sociedad puede exigir el cumplim iento de la obliga
ción mediante el proceso ejecutivo o excluir a dicho socio por el proceso sumarísimo, se
gún el artículo 22 de la Ley. El aporte transfiere en propiedad a la sociedad el bien aporta
do, salvo que se estipule que se hace a otro título, en cuyo caso, la sociedad adquiere sólo
el derecho transferido a su favor por el socio aportante. Al respecto, el Tribunal Registral
establece en la R esolución N ° 3 2 6 8 -2 0 1 9-SU N A RP-TR-L que el aporte es el instrumento
fundamental por el cual se facilitan recursos a la sociedad y se produce la integración del
capital social. Por ende, constituye un requisito esencial la posibilidad de que sea valo
rado económicamente.
Cabe destacar que, con respecto a la sociedad anónima, sólo puede ser objeto de aporte
los bienes o derechos susceptibles de valoración económica. De esta manera, la Reso
lució n N ° i 6 5 4 ''2 0 1 2 -S U N A R P -T R -L indica que la sociedad anónima se forma gracias al
aporte que efectúan los socios con la finalidad de desarrol lar una actividad económica en
búsqueda de obtener a cambio un lucro o ganancia, toda vez que nos encontramos frente
a una sociedad de capitales.
Aportes no dinerarios
Los aportes en dinero se desembolsan en la oportunidad y condiciones estipuladas
en el pacto social.
Aportes no dinerarios
En el caso de la entrega de bienes inmuebles aportados a la sociedad se reputa efec
tuada al otorgarse la escritura pública en la que conste el aporte, mientras que, la
entrega de bienes muebles aportados a la sociedad debe quedar completada a más
tardar al otorgarse la escritura pública de constitución o de aumento de capital, se
gún sea el caso.
Por otro lado, si el pacto social admite que el socio aportante entregue como aporte títu
los valores o documentos de crédito a su cargo, el aporte no se considera efectuado hasta
que el respectivo título o documento sea íntegramente pagado. Asimismo, el pacto social
permite que el aporte esté representado por títulos valores o documentos de crédito en
los que el obligado principal no es el socio aportante, el aporte se entenderá cumplido
con la transferencia de los respectivos títulos o documentos, con el endoso de los respec
tivos títulos valores o documentos y sin perjuicio de la responsabilidad solidaria prevista
en la ley.
Ahora bien, el artículo 27o LGS de la Ley se generaliza como regla de los aportes no di
nerarios, la necesidad de contar con un informe de valorización en el que se describan
los bienes y derechos materia del aporte, los criterios aplicables para su valuación y sus
respectivos valores. Asimismo, el artículo 36 del Reglamento del Registro de Sociedades
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 662 of 1506 --

UBILEX
establece que este informe deberá contener la información suficiente que permita la in
dividualización de los bienes o derechos aportados.
Por otro lado, el artículo 76o LCS de la Ley contempla la obligación del directorio de revi
sar la valorización de los aportes no dinerarios dentro del plazo de sesenta días contado
desde la constitución de la sociedad o del pago del aumento de capital. Vencido dicho
el plazo, dentro de los treinta días siguientes, cualquier accionista podrá solicitar que se
compruebe judicialmente, por el proceso abreviado, la valorización mediante operación
pericial y deberá constituir garantía suficiente para sufragar los gastos del peritaje.
Hasta que la revisión se realice por el directorio y transcurra el plazo para su comproba
ción no se emitirán las acciones que correspondan a las aportaciones materia de la revi
sión. Si se demuestra que el valor de los bienes aportados es inferior en veinte por ciento
o más a la cifra en que se recibió el aporte, el socio aportante deberá optar entre: (i) la
anulación de las acciones equivalentes a la diferencia, (ii) su separación del pacto social o
(i i i) el pago en dinero de la diferencia. En cualquiera de los dos primeros casos, la socie
dad reduce su capital en la proporción correspondiente si en el plazo de treinta días las
acciones no fueren suscritas nuevamente y pagadas en dinero.
x) Patrimonio social:
En el a r t íc u lo 3 1 o LG S e s t a b le c e q u e el p a t r im o n io s o c ia l r e s p o n d e p o r la s o b lig a c io n e s d e
la s o c ie d a d s in p e r ju ic io d e la r e s p o n s a b ilid a d p e r s o n a l d e lo s s o c io s en a q u e lla s fo r m a s
s o c ie t a r ia s q u e a s í lo c o n t e m p la n .
Cabe mencionarqueel patrimonio social no es lo mismo que capital social y viceversa, así
la diferencia principal entre ambos es que el patrimonio social está en constante cambio,
en cambio el capital social es solo una cifra de valor inmutables, a menos que se realice
un aumento o disminución en el pacto social.
xi) Acciones:
La acción es un Título Valor que representa una parte alícuota del capital social y además
es el medio de configurar la condición de accionistas, todas tienen el mismo valor nomi
nal y dan derecho a un voto, salvo excepciones.
Naturaleza jurídica.- La acción tiene la naturaleza de los Bienes muebles (status incorporado
a documento).
La acción como parte del capital social: La Acción como parte del Capital Social conlleva
a que debe existir Igualdad de su valor Nominal; asimismo que la Acción supone la efec
tiva aportación patrimonial al fondo social.
Generación de acciones: Fases:
Creación: Pueden crearse al constituirse la sociedad (acto constitutivo) o mediante
acuerdo de lajunta general (al aumentarel capital social), siendo necesario paraello
modificar el estatuto.
Emisión: Las acciones sólo se emiten una vez que han sido suscritas y pagadas en
por lo menos el veinticinco por ciento de su valor nominal, salvo el caso de aportes
en especie que están sujetos a revisión.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 663 of 1506 --

Tema 4: Temas de la especialidad comercial
C o lo cació n d e A cciones:
Acciones colocadas a la p a r- Cuando hay equivalencia entre el Valor Nominal y Valor de
Aportación.
Acciones colocadas con p rim a .-Cuando se coloca al valor nominal más un plus. Se presenta
cuando el patrimonio neto es mayor que el capital social y al colocara la par se desvalori
zan las acciones antiguas. El destino de la prima es incrementa la reserva legal. Se puede
repartir como dividendo, cuando la reserva legal más la prima supere a la quinta parte del
capital social.
Acciones colocadas bajo la par- Se presenta cuando el valor de aportación es menor que el
valor nominal. Se presenta en los casos que patrimonio neto sea menor que el capital
social. La acción se cotiza menos que el valor nominal. Se considerará pérdida de colo
cación. A pesar de la diferencia negativa entre valor de aportación y el valor nominal se
considera íntegramente pagada. Por ejemplo, en las operaciones Underwritinges normal
que lo que perciba la sociedad sea igual al valor nominal menos las comisiones y tasa de
descuento.
Indivisibilidad de la acción:
Por la naturaleza de la acción esta representa una parte del capital social; y por el carácter
del acto jurídico generador el contrato social no se puede modificar unilateralmente. En
caso de copropiedad por la que la titularidad pertenece a varios propietarios, la legitima
ción corresponde a uno de ellos para ejercicio de derechos que debe representarlo, pero
todos responden solidariamente por obligaciones.
La acción como conjunto de derechos y obligaciones
La acción cumple la función de incorporar el status desocio (derechos y obligaciones).
Derechos corporativos.
Derechos económico patrimonial (derechos materiales): participaren el reparto de utilidades;
suscripción preferente de nuevas acciones; transmisión de sus acciones; entre otros.
Derechos de carácter político (derechos instrumentales): Derecho de asistir a las Juntas Gene
rales; derecho de votar en las Juntas Generales; derechos de información y Fiscalización;
derecho de impugnar acuerdos.
La acción como título valor:
Los títulos valoresy la acción- La acción es un título valor que incorpora derechos de carác
ter corporativo; son substancial mente títulos de participación social y lacirculabilidad del
título es de la naturaleza de la acción.
La Acción como Título Nominativo.- La acción es un título emitido en serie o en masa que
para su trasmisión es necesaria la intervención del deudor o emisor del título, pues ade
más de la cesión o del endoso requiere su inscripción en Matrícula del emisor.
Matrícula de las Acciones.- Las acciones deberán figuran en libro-registro llevado por la socie
dad, en ella se inscribirán la creación, emisión, sucesivas transferencias, constitución de dere
chos reales u otros gravámenes sobre ellos
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 664 of 1506 --

UBILEX
| H H | C o m u n ic ac ió n a la S o c ie d a d .- Para trasmisión de acciones se requiere notificación a sociedad,
^ con la finalidad de ser anotada en Matrícula acciones: El transmitente pondrá transferencia en
conocimiento de sociedad, acompañada del título; podrá transmitirse con inserción de cons-
tancia de cesión o endoso en el título entregando a sociedad.
C e rtific a d o d e A ccion es.- En el certificado están materializado los derechos que contiene la
acción. La existencia del título de la acción implica que sucesión en calidad de socio irá ligada
a trasmisión del documento.
A n o ta c io n e s en c u e n ta .- Cuando cantidades de títulos-acciones que acuden al mercado de
valores dificultan el tráfico, ha sido necesaria que se representen por simples anotaciones en
cuentas llevadas por computadoras según técnicas de la informática. Características: La trans
misión por transferencia contable, la inscripción de la transmisión los mismos efectos que la
tradición de los títulos; oponible a terceros desde el momento en que se haya inscrito; el terce
ro que adquiere acciones al que según registro contable, aparezca legitimada para transm itir
las “no estará sujeto a reivindicación".
Transferencias. Limitacionesy prohibiciones
Principio General.- Las acciones son por esencia libremente transmisibles.
Limitaciones.- El principio de la libre transmisión de las acciones puede ser lim itado por dis
ponerlo así el estatuto social, el pacto social o por acuerdos particulares entre los accionistas
o entre estos y terceros.
Cláusulas Limitativas: Las cláusulas limitativas más conocidas son:
Cláusula de Tanteo.- Son las que conceden a todos o a parte de los accionistas un derecho
de adquisición preferente sobre las acciones que otro accionista desee trasmitir.
Cláusulas de Consentimiento.- Son las que subordinan frente a la sociedad la eficacia de
su trasmisión al hecho de que esta autorice.
P ro h ib icio n es T e m p o ra le s d e tra n s fe re n c ia d e acciones
Es válida la prohibición temporal de transferir, gravar o afectar acciones.
Puede ser establecido porel Estatuto, mediante sindicación deacciones, o por acuerdo de
la junta general (en cuyo caso los efectos solo alcanzara los que aprobaron tal propuesta).
La prohibición debe ser por plazo determinado o determinable no mayor de diez años, pu-
diendo prorrogar el plazo que dure la misma hasta por periodos no mayores a los diez años.
Los términos y condiciones de prohibición temporal deben ser anotados en Matrícula de
acciones y en los certificados de acciones.
Usufructo de acciones: El usufructo es el derecho de usar y gozar de un bien ajeno, pero sin
tener la propiedad ni disponerde dicho bien.
Características:
El nudo propietario conserva todos los derechos de socio, excepto los económicos.
El usufructuario tiene derecho a participar en las ganancias sociales durante el periodo
del usufructo y que se repartan dentro del mismo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 665 of 1506 --

Tema 4: Temas de la especialidad comercial
Corresponden al nudo propietario los dividendos que se repartan con cargo a reservas
constituidas antes del periodo del usufructo y los dividendos correspondientes a ejerci
cios anteriores, aunque se repartan durante el mismo.
Corresponden al nudo propietario los que se repartan fuera del periodo del usufructo,
aunque se hayan devengado dentro de ejercicios anteriores.
El derecho de voto en las juntas generales y el de suscripción preferente de acciones co
rresponden al nudo propietario.
Cuando hay una ampliación del capital con beneficios obtenidos durante el plazo del
usufructo las acciones le corresponden en pleno dom inio al nudo propietario, salvo pacto
en contrario como señala nuestro ordenamiento legal.
Embargo de acciones: Es la Inmovilización jurídica de un bien del deudor, a fin que el acree
dor pueda hacer efectivo su crédito, una vez que sea reconocido por sentencia firme.
Características:
a) La acción como título valor, es una cosa en sí, el embargo afecta la cosa en sí, no sus frutos.
b) El embargo de acciones no apareja la retención de los dividendos, salvo orden judicial.
c) El propietario conserva el ejercicio de los derechos de accionista.
d) Embargo en forma de depósito, el depositario está obligado a facilitar al accionista el
ejercicio de sus derechos.
Clases de acciones:
Se presenta cuando los derechos que distinguen a un grupo de acciones permiten que puedan
separarse en series o clases distintas, por ejemplo, puede crearse una clase de acciones a la que
denominaremos Clase A, la cual cuente con derechos económicos y políticos (voto) y otra, a
la que denominaremos Clase B, la cual cuente con derechos económicos pero sin derecho a
voto, acciones que contarán con una preferencia al momento de participar en el reparto de
utilidadesy en el patrimonio neto resultante de la liquidación.
Acciones Ordinarias: Son aquellas que atribuyen a titulares un régimen normal de derechos
y obligaciones integrantes de condición de socio. Es punto de partida para definir a acciones
privilegiadas ya que conceden particulares ventajas o privilegios con relación a derechos de
acciones ordinarias.
Acciones privilegiadas: Son lasque conceden particulares ventajas o privilegios con relación a
los derechos de las acciones ordinarias. Las ventajas pueden incidirsobreel dividendo o sobre
el patrimonio social.
Adquisición por la sociedad de sus propias acciones
a) Adquisición con cargo al capital social.- La sociedad puede adquirirsus propias acciones
con cargo al capital únicamente para amortizarlas, previo acuerdo de reducción del capi
tal adoptado conforme a ley. Cuando la adquisición de las acciones se realice por monto
mayoral valor nominal, la diferencia sólo podrá ser pagada con cargo a beneficios y reser
vas libres de la sociedad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 666 of 1506 --

UBILEX
I b) A d q u is ic ió n sin re e m b o ls o d e l v a lo r n o m in a l.- La sociedad puede adquirir sus propias
acciones para amortizarlas sin reducir el capital y sin reembolso del valor nominal al ac
cionista, entregándole a cambio títulos de participación. Se requiere acuerdo de junta
general para incrementar proporcionalmente el valor nominal de las demás acciones. Los
títulos de participación son nominativosy transferibles (participa en utilidades).
c) Adquisición cuyo reembolso se hace con cargo a beneficios y reservas libres.- La socie
dad puede adquirir sus propias acciones con cargo a beneficios y reservas libres. El re
embolso de las acciones se pagará con el excedente del patrimonio sobre el capital. Se
efectuará en los casos siguientes:
Para am ortizar (anular acciones) sin reducir el capital. Incrementando el valor nominal
de las acciones restantes hasta que el capital social quede dividido entre ellas en alí
cuotas de igual valor;
Para am ortizarlas sin reducir el capital entregando a cambio títulos de participación.
Incrementando valor nominal de acciones;
Sin amortizar, para evitar un daño grave, debiendo venderse en un plazo no mayor de 2
años;
Sin amortizar, previo acuerdo de ju n ta general para mantenerlas en cartera por un perío
do no mayor de 2 años y en un monto no mayoral 10% del capital suscrito,
d) Control indirecto de las acciones (Art.105 LCS)
Manifestación del control Indirecto de Acciones.'' La operación más usada es entregar sus propias
acciones a su filial o filiales, configurando como nota característica la participación reciproca
de acciones.
Las Participaciones Recíprocas
Participaciones recíprocas directas.- Dos sociedades participan recíprocamente en sus respecti
vos capitales sociales: La sociedad “A" participa en el capital de la sociedad "B”, y ésta participa
en el capital de “A”.
Participaciones recíprocas indirectas.- Las participaciones recíprocas pueden constituirse a través
de filiales (por vía indirecta): “A” controla a “B”, ésta a “C”, ésta a “D” y esta últim a participa en A ’.
xii) Órganos de la sociedad
J U N T A G E N E R A L D E A C C IO N IS T A S
Concepto.- La Junta General de Accionistas es el órgano supremo de la sociedad, es decir, no
tiene órgano superior en su línea.
Función.- Los accionistas constituidos en junta general debidamente convocada,y con el quo
rum correspondiente, deciden por la mayoría que establece esta ley los asuntos propios de su
competencia.
Naturaleza Jurídica de la junta.- Es el órgano de la sociedad donde se forma la voluntad social.
Naturaleza Jurídica del acuerdo.- Es un negocio jurídico (efectos jurídicos) colectivo (m ulti
plicidad de voluntades), unilateral (expresión de voluntad de la sociedad) y unitario (emana
de órgano colegiado).
i 66 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 667 of 1506 --

Tema 4: Temas de la especialidad comercial
Limitaciones.- Los acuerdos no deben ser contrarios a la ley, al estatuto o al interés social, asi
mismo, no pueden vulnerar los derechos individuales del accionista, ni los requisitos formales
para su convocatoria, instalación y acuerdos.
Efectos.- Todos los accionistas, incluso los disidentes y los que no hubieren participado en la
reunión, están sometidos a los acuerdos adoptados por la junta general. La excepción, cuando
se incurra en causales que otorga el derecho de separación.
Convocatoria a junta general (Art. 113 LCS)
Organo competente (Art. 113 LCS).- El Directorio o en su caso la administración de la socie
dad, por ejemplo el gerente general en la S.A.C., convoca a junta general; en determinados ca
sos lo convoca el juez. Ahora bien, al referirnos al Directorio nos referimos a este como órgano
colegiado, el cual deberá adoptar el acuerdo por mayoría, y no a un directoren específico, tal
como lo señala la Resolución N°1984-2017-SUNARP-TR-L.
Momento de convocatoria (Art. 113 LCS).-Se convoca a junta general cuando lo ordena la ley,
lo establece el estatuto, lo acuerda el directorio por considerarlo necesario al interés social o lo
solicite un número de accionistas que represente cuando menos el veinte por ciento (20%) de
las acciones suscritas con derecho a voto.
Requisitos de la Convocatoria (Art. 116 LCS)
a) Convocatoria Regular o Común.- El aviso de convocatoria de la junta general obligatoria
anual y de las demás juntas previstas en el estatuto debe ser publicado con una anticipa
ción no menor de diez días al de la fecha fijada para su celebración.
b) Convocatoria Excepcional.- En los demás casos, salvo aquellos en que la ley o el estatuto
fijen plazos mayores, la anticipación de la publicación será no menor de tres días.
c) Finalidad.- Otorgar la posibilidad de que todos los accionistas puedan tom ar conoci
miento de ella.
d) Contenido.- El aviso de convocatoria debe especificar:
Lugar, día y hora de celebración de la junta general. Puede constar asimismo en el
aviso el lugar, día y hora en que, si así procediera, se reunirá la junta general en se
gunda convocatoria. Dicha segunda reunión debe celebrarse no menos de tres ni
más de diez días después de la primera.
Los asuntos a tratar. La agenda u “orden del día" debe ser clara y precisa para la pre
paración de la discusión. La junta general no puede tratar asuntos distintos a los se
ñalados en el aviso de convocatoria, salvo en los casos permitidos por la Ley. Ejemplo
: los asuntos que tienen aprobación unánime de todos los accionistas reunidos en
juntas universales. Para evitar confusiones, el Tribunal Registral insta que la convo
catoria sea claray precisa, debido a que ello será determinante para dar información
a los socios respecto a los asuntos que se tratarán en la junta, con lo que podrán
decidir si asistir o no, según la importancia que tenga para los convocados, además
de servir para prepararse para las discusiones según lo señala en la Resolución N°
456-2013-SUNARP-TR-L
