a) Legitimidad.- Cuando soliciten uno o más accionistas que representen no menos del
20% de las acciones suscritas con derecho a voto la celebración de la junta general.
b) Formalidades.- Solicitud vía notarial, indicando los asuntos que los solicitantes propon
gan tratar.
c) Trámite.-. La ju n t a g e n e r a l d e b e s e r c o n v o c a d a p a ra c e le b r a r s e d e n t r o d e u n p la z o d e 15
d ía s d e la f e c h a d e p u b lic a c ió n d e la c o n v o c a t o r ia .
Si la solicitud antes mencionada fuese denegada o transcurriesen más de 15 días de presen
tada sin efectuarse la convocatoria, el o los accionistas, acreditando que reúnen el porcentaje
exigido de acciones, pueden solicitar al notarioy/o al juez de dom icilio de la sociedad que or
dene la convocatoria, que señale lugar, día y hora de la reunión, su objeto, quién la preside, con
citación del órgano encargado, y, en caso de hacerse por vía judicial, el juez señala al notario
que da fe de los acuerdos
Convocatoria judicial ( A r t s .iiy y ii9 LGS)
a) Casos:
Cuando la solicitud a Convocatoria hecha por los accionistas que representen no me
nos del 20% de las acciones suscritas con derecho a voto fuese denegada o trans
curriesen más de quince días de presentada sin efectuarse la convocatoria, el o los
accionistas, acreditando que reúnen el porcentaje exigido de acciones, podrán soli
citar al juez de la sede de la sociedad que ordene la convocatoria por el proceso no
contencioso.
Si la junta obligatoria anual o cualquier otra ordenada por el estatuto no se convoca
dentro del plazo y para sus fines, o en ellas no se trata los asuntos que corresponde,
será convocada, a pedido del titu la r de una sola acción suscrita con derecho a voto,
por el juez del domicilio social, por el proceso no contencioso.
b) Trámite:
Si el Juez ampara la solicitud, ordena la convocatoria, señala lugar, día y hora de la
reunión, su objeto, quien la presidiráy el notario que dará fe de los acuerdos.
Segunda convocatoria (Art. 118 LGS)
Si la junta general debidamente convocada no se celebra en primera convocatoria y no se
hubiese previsto en el aviso la fecha para una segunda convocatoria, esta debe ser anun
ciada con los mismos requisitos de publicidad que la primera, y con la indicación que se
trata de segunda convocatoria, dentro de los diez días siguientes a la fecha de la junta no
celebrada y, por lo menos, con tres días de antelación a la fecha de la segunda reunión.
Puede constar en el aviso de la primera convocatoria para la eventualidad que no se ob
tenga quorum para la celebración de la junta en esta convocatoria, el lugar, día y hora
en que se reunirá la junta general en segunda convocatoria. En este caso, dicha segunda
reunión debe celebrarse no menos de tres ni más de diez días después de la primera.
Derecho de Información del Accionista (Art. 130 LGS).- Desde el día de la publicación de la
convocatoria, los documentos, mociones que son intenciones de acuerdosy diseños o memo-
