Tema 4: Temas de la especialidad comercial
rías descriptivas, relacionados con el objeto de la junta general, deben estar a disposición de
los accionistas en las oficinas de la sociedad o en el lugar de celebración de la junta general,
durante el horario de oficina de la sociedad.
Informes a d ic io n a le s .- Los accionistas pueden solicitar con anterioridad a la junta general o
durante el curso de la misma los informes o aclaraciones que estimen necesarios acerca de
los asuntos comprendidos en la convocatoria. El directorio o el gerente general, de ser el caso,
están obligados a proporcionárselos, salvo en los casos en que juzgue que la difusión de los
datos solicitados perjudique el interés social. Esta excepción no procede cuando la solicitud
sea formulada por accionistas presentes en la junta que representen al menos el veinticinco
por ciento de las acciones suscritas con derecho a voto.
Clases
]unta Obligatoria Anual (Art.114 Lgs)
a) Definición: Es aquellaque debe pronunciarse sobre asuntos que ha sido tradicionalmen-
te su exclusiva competencia: Análisis y pronunciamiento sobre la gestión social y los re
sultados económicos del ejercicio anterior.
b) Periodo: La junta obligatoria anual se reúne obligatoriamente cuando menos una vez
al año dentro de los tres meses siguientes a la terminación del ejercicio económico. De
acuerdo al artículo 116 de la Ley, la anticipación para la convocatoria en este tipo de junta
deberá ser de 10 días, asilo reitera la Resolución No4 2 4 -2 0 T4 -SUNARP-TR-L.
c) Objeto: Esta junta tiene por objeto:
Pronunciarse sobre la gestión social y los resultados económicos del ejercicio ante
rior expresados en los estados financieros del ejercicio anterior.
Resolver sobre la aplicación de las utilidades, si las hubiere;
Elegir cuando corresponda a los miembros del directorio y fijar su retribución;
Designar o delegar en el directorio la designación de los auditores externos, cuando
corresponda; y,
Resolver sobre los demás asuntos que le sean propios, conforme al estatuto y sobre
cualquier otro consignado en la convocatoria.
junta Universal (Art.120 LGS)
a) Definición.'' Es la reunión que se celebra con la asistencia o representación de accionistas
titulares del 100% de las acciones suscritas con derecho a voto, los cuales acuerdan por
unanimidad la realización de la ju n ta y de los temas a tratar sin necesidad de convocato
ria previa. Este tipo de junta constituye una excepción en el deber de la sociedad de “con
vocar debidamente" de manera previa a los accionistas, toda vez que no será necesario
anticipar los puntos a tratar (Resolución No267-2 0 i 7-SUNARP-TR-T).
b) Requisitos.- La junta general se entiende co nvocada y vá Ii da m e nte constituida para tra
tar sobre cualquier asunto y tomar los acuerdos correspondientes, siempre que reúnan
los siguientes requisitos:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 670 of 1506 --

UBILEX
Se encuentren presentes accionistas que representen la totalidad de las acciones
suscritas con derecho a voto,
Acepten por unanimidad la celebración de la ju n ta ,y
Acepten por unanimidad los asuntos que en ella se proponga tratar.
Basta la oposición del titu la r de i acción para que no se pueda realizar.
Junta general de accionistas (Art. 115 LCS).-
Asimismo, es de competencia de la junta General de Accionistas:
a) Removerá los miembros del directorioy designar a sus reemplazantes;
b) Modificar el estatuto;
c) Aumentar o reducir el capital social;
d) Emitir obligaciones;
e) Acordar la enajenación, en un solo acto, de activos cuyo valor contable exceda el cincuen
ta por ciento del capital de la sociedad;
f) Disponer investigacionesy auditorias especiales;
g) Acordar la transformación, fusión, escisión, reorganización y disolución de la sociedad,
así como resolver sobre su liquidación; y,
h) Resolveren los casos en que la ley o el estatuto dispongan su intervención y en cualquier
otro que requiera el interés social.
Juntas Especiales (Art. 132 LGS)
a) Cuando existan diversas clases de acciones, los acuerdos de la junta general que afecten
los derechos particulares de cualquiera de ellas deben ser aprobados en sesión separada
por la junta especial de accionistas de la clase afectada.
b) Es muy sencilla la creación de clases distintas de acciones, pues basta que para ello una
modificación de estatutos, pero no es igualmente fácil el acuerdo de eliminación de una
clase de acciones, donde se requiere una doble aprobación: la aprobación de la junta ge
neral de accionistas de lasociedad como la de la junta o juntas especiales de los accionis
tas tenedores de la clase o clases interesadas.
c) La junta especial se regirá por las disposiciones de la junta general, en tanto le sean apli
cables, inclusive en cuanto al quorum y la mayoría calificada cuando se trate de los casos
de modificación estatutaria.
Derecho de concurrencia a junta (Art. 121 LGS)
a) Pueden asistirá la junta general y ejercer sus derechos los titulares de acciones con dere
cho a voto que figuren inscritas a su nombre en la matrícula de acciones, con una antici
pación no menor de dos días al de la celebración de la junta general.
b) Los directores y el gerente general que no sean accionistas pueden asistir a la junta ge
neral con voz pero sin voto. Por su contacto rutinario con la gestión de la sociedad es de
suma utilidad para que la junta pueda discutir sobre los temas de la agenda. Tiene dere
cho a que se deje constancia en acta sus intervenciones.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 671 of 1506 --

Tema 4: Temas de la especialidad comercial
c) El estatuto, la propia junta general o el directorio pueden disponer la asistencia, con voz
pero sin voto, de funcionarios, profesionalesy técnicos al servicio de la sociedad o de otras
personas que tengan interés en la buena marcha de los asuntos sociales. Esto permite
contar con la información (necesaria para adoptar un acuerdo técnico) de personas que
se hallan vinculados a la sociedad o a temas especializados.
d) El artículo 325 de la LCS dispone que el representante de los obligacionistas puede asistir
con voz pero no con voto.
Lista de asistentes (Art.123 LCS)
a) Antes de la instalación de la junta general, se form ula la lista de asistentes expresando el
carácter o representación de cada uno y el número de acciones propias o ajenas con que
concurre, agrupándolas por clases si las hubiere.
b) Al final de la lista se determina el número de acciones representadas y su porcentaje res
pecto del total de las mismas con indicación del porcentaje de cada una de sus clases, si
las hubiere.
c) Estos datos sirven para establecer quienes estuvieron presentes en la junta y determinar
si se contó con el quorum necesario para su instalación. Asimismo, sirve para determinar
la legitimidad en caso de impugnación de acuerdos o ejercer el derecho de separación.
Representación (Art.122 LCS)
a) Facultad: Todo accionista con derecho a participaren las juntas generales puede hacerse
representar por otra persona. El estatuto puede lim itar esta facultad, reservando la re
presentación a favor de otro accionista, o de un director o gerente. Se busca evitar que
tengan acceso a las deliberaciones del órgano supremo de la sociedad a personas ajenas
a la administración o al accionariado de la misma.
b) Formalidad.- La representación debe constar porescritoy con carácter especial para cada
junta general, salvo que se trate de poderes otorgados por escritura pública, donde no
será necesario elaborar un poder adicional para cada junta.
c) Registro.- Los poderes deben ser registrados ante la sociedad con una anticipación no
menor de veinticuatro horas a la hora fijada para la celebración de la junta general. El
plazo tiene como finalidad permitir a los administradores poder revisar la legitim idad de
los poderes con una anticipación razonable.
d) Revocabilidad.- La representación ante la junta general es revocable, debiéndose comu
nicara la sociedad para su validez.
e) Revocabilidad tácita.- La asistencia personal del representado a la junta general produ
cirá la revocación del poder conferido tratándose del poder especial y dejará en suspenso,
para esa ocasión, el otorgado por escritura pública.
f) Excepción a la Revocabilidad.- La revocabilidad tácita no será de aplicación en ios casos
de poderes irrevocables, pactos expresos u otros casos permitidos por la ley.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 671

-- 672 of 1506 --

QUORUM
Aspectos Generales (Art. 124 LGS)
a) Concepto.- Quorum es la cantidad de acciones representadas en junta, la cual debe cum
plir determinados mínimos para que esta pueda instalarse y sesionar válidamente.
b) Cómputo.- El quorum se com putay establece al inicio de la junta. Para el cómputo debe
calcularse tomando en cuenta las acciones suscritas con derecho a voto, con exclusión de
las acciones en cartera, las que no tienen derecho a voto, las de morosos por dividendos
pasivos, aquellas adquiridas por la misma sociedad, y las que controla la sociedad. Se
computa la proporción de acciones con derecho a voto. El cómputo se efectúa al inicio,
por lo que el retiro posterior de un grupo de accionistas no variará el quorum computado.
Pero podría afectar la validez del acuerdo si no se cuenta con la mayoría requerida. Com
probado el quorum el presidente la declara instalada. Las acciones de los accionistas que
ingresan a la junta después de instalada, no se computan para establecer el quorum pero
respecto de ellas se puede ejercer el derecho de voto.
Con respecto a la persona encargada de form ular la constancia sobre el quorum, el Re
glamento de Inscripción del Registro de Personas jurídicas establece en su artículo 61
que deberá ser quien presidió la sesión, por el órgano con facultad legal o estatutaria de
convocatoria para la sesión de que se trate, o por el encargado de ejecutarla en caso de
convocatoriajudicial.
c) Acciones no computadas para quorum calificado.- En las juntas generales convocadas
para tratar asuntos que, conforme a ley o al estatuto, requieren concurrencias distintas,
cuando un accionista así lo señale expresamentey deje constancia al momento de form u
larse la lista de asistentes, sus acciones no serán computadas para establecer el quorum
requerido para tratar alguno o algunos de los asuntos a que requieran quorum calificado.
Este mecanismo protege a los socios minoritarios de una situación abusiva que algunas
veces impusieron las mayorías, que consistía en convocar juntas con agendas complejas,
que contemplaban el tratamiento de temas de interés para todos los accionistas, para
cuya discusión y aprobación no se necesita ni quorum ni mayorías calificadas (aplicación
de utilidades) y otros temas que si requerían quorum y mayorías calificadas para su dis
cusión y aprobación (aumento de capital con nuevos aportes). Ahora se encuentra per
m itido que un grupo minoritario asista a la junta para discutir asuntos sobre los que sí
tiene interés, no prestándose para el cómputo del quorum calificado necesario para la
adopción, por ejemplo, del acuerdo de aumento de capital.
Clases de quorum:
Quorum simple (Art. 125 LGS)
Salvo lo previsto en el artículo siguiente, la junta general queda válidamente constituida
en primera convocatoria cuando se encuentre representado, cuando menos, el cincuenta
por ciento de las acciones suscritas con derecho a voto.
En segunda convocatoria, será suficiente la concurrencia de cualquier número de acciones
suscritas con derecho a voto. Este número permite que la junta como órgano deliberante,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 673 of 1506 --

Tema 4: Temas de la especialidad comercial
no se vea obstruido por la posible inactividad o negligencia de un grupo de accionistas,
por más representativo que sea.
En todo caso podrá llevarse a cabo la Junta, aun cuando las acciones representadas en ella
pertenezcan a un solo titular. Sostener lo contrario, sería perm itir que en sociedades en las
que un accionista concentre casi la totalidad del capital, la junta no pueda funcionar.
Quorum c a lific a d o (Art.126 LGS)
Para que la junta general adopte válidamente los acuerdos detallados a continuación, es
necesaria en primera convocatoria, cuando menos, la concurrencia de dos tercios de las
acciones suscritas con derecho a voto (6 6 .6 6 6 6 6 %).
• Modificar el estatuto.
• Aumentar o reducir el capital social.
• Emitirobligaciones.
• Acordar la enajenación, en un solo acto, de activos cuyo valorcontable exceda el cin
cuenta por ciento del capital de la sociedad.
• Acordar la transformación, fusión, escisión, reorganización y disolución de la socie
dad, así como resolversobre su liquidación.
En segunda convocatoria basta la concurrencia de al menos tres quintas partes de las ac
ciones suscritas con derecho a voto (60%).
Acuerdos (Art.127 LGS)
Mayoría simple: los acuerdos se adoptan con el voto favorable de la mayoría absoluta de
las acciones suscritas con derecho a voto representadas en la junta.
Mayoría calificada: cuando se trata de los asuntos donde es necesario contar con quo
rum calificado, se requiere que el acuerdo se adopte por un número de acciones que re
presente, cuando menos, la mayoría absoluta de las acciones suscritas con derecho a voto
(independientemente de las representadas en junta).
ACTAS
Formalidades (Arts. 134,136 y 138 LGS)
a) La junta general y los acuerdos adoptados en ella constan en un acta que expresa un resu
men de lo acontecido en la reunión.
b) Las actas pueden asentarse en un libro especialmente abierto a dicho efecto, en hojas
sueltas o en cualquier otra forma que permita la ley.
c) Cuando consten en libros o documentos, ellos serán legalizados conforme a ley.
d) Excepcionalmente, cuando por cualquier circunstancia no se pueda asentar el acta en la
forma establecida por ley, ella se extenderá y firmará portodos los accionistas concurren
tes en un documento especial, el que se adherirá o transcribirá al libro o a las hojas sueltas
no bien éstos se encuentren disponibles, o en cualquier otra forma que permita la ley. El
documento especial deberá ser entregado al gerente general quien será responsable de
cum plir con lo antes prescrito en el más breve plazo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 674 of 1506 --

UBILEX
e) Por acuerdo del di recto rio o a sol icitud presentada no menos de cuarenta y ocho horas
antes de celebrarse la junta general, por accionistas que representen cuando menos el
veinte por ciento de las acciones suscritas con derecho a voto, la junta se llevará a cabo en
presencia de notario, quien certificará la autenticidad de los acuerdos adoptados por la
junta.
f) Correspondeal gerente general ladesignación del notarioy en casodeque lasolicitudsea
formulada por los accionistas éstos correrán con los gastos respectivos.
Contenido (Art. 135 LGS)
En el acta de cada junta debe constar:
a) Lugar, fechay hora en que se realizó;
b) La indicación de si se celebra en primera, segunda o tercera convocatoria;
c) El nombre de los accionistas presentes o de quienes los representen;
d) El número y clase de acciones de las que son titulares;
e) El nombre de quienes actuaron como presidente y secretario;
f) La indicación de las fechasy los periódicos en que se publicaron los avisos de la convocatoria;
g) La forma y resultado de las votaciones y los acuerdos adoptados.
h) Cualquier accionista concurrente o su representante y las personas con derecho a asistir a
la junta general están facultados para solicitar que quede constancia en el acta del senti
do desús intervencionesy de los votos que hayan emitido.
Aprobación (Art. 135 LGS)
El acta, incluido un resumen de las intervenciones referidas en el párrafo anterior, será
redactada por el secretario dentro de los cinco días siguientes a la celebración de la junta
general.
Cuando el acta es aprobada en la misma junta, ella debe contener constancia de dicha
aprobación y ser firmada, cuando menos, por el presidente, el secretario y un accionista
designado al efecto.
Cuando el acta no se aprueba en la misma junta, se designará a no menos de dos accio
nistas para que, conjuntamente con el presidentey el secretario, la revisen y aprueben.
El acta debe quedar aprobada y firmada dentro de los diez días siguientes a la celebración
de la junta y puesta a disposición de los accionistas concurrentes o sus representantes, quie
nes podrán dejar constancia de sus observaciones o desacuerdos mediante carta notarial.
Tratándose de juntas generales universales es obligatoria lasuscripción del acta portodos
los accionistas concurrentes aellas, salvo que hayan firmado la lista de asistentesy en ella
estuviesen consignados el número de acciones del que son titularesy los diversos asuntos
objeto de la convocatoria. En este caso, basta que sea firmada por el presidente, el secreta-
rioy un accionista designado al efectoy la lista de asistentes se considera parte integrante
e inseparable del acta.
Cualquier accionista concurrente a la junta general tiene derecho a firm ar el acta.
