Tema 4: Temas de la especialidad comercial
Validez (Art 135 LGS)
El acta tiene fuerza legal desde su aprobación.
Copia certificada del acta (Art 137 LGS)
a) Cualquier accionista, aunque no hubiese asistido a la junta general, tiene derecho de ob
tener, a su propio costo, copia certificada del acta correspondiente o de la parte específica
que señale.
b) El gerente general de la sociedad está obligado a extenderla, bajo su firm a y responsabi
lidad, en un plazo no mayor de cinco días contados a partir de la fecha de recepción de la
respectiva solicitud.
c) En caso de incumplimiento, el interesado puede recurrir al Juez del dom icilio por la vía
del proceso no contencioso a fin que la sociedad exhiba el acta respectiva y el secretario
del Juzgado expida la copia certificada correspondiente para su entrega al solicitante. Los
costos y costas del proceso son de cargo de la sociedad.
Lugar y celebración de la Junta
a) Lugar de Celebración.- La junta general se celebra en el lugar del dom icilio social, salvo
que el estatuto prevea la posibilidad de realizarla en lugar distinto. No se refiere a la sede
social ya que puede llevarse a cabo en cualquier local del lugar del dom icilio y no preci
samente en el local social. Así debe constar en la convocatoria. Sin perjuicio de lo antes
mencionado, es posible que los órganos de las sociedades realicen sesiones no presencia
les, con la misma validez que las sesiones presenciales, a través de medios electrónicos
u otros de naturaleza similar, de conformidad con lo establecido en su estatuto, garanti
zando la identificación, comunicación, participación, el ejercicio de los derechos de voz
y voto de sus miembros y el correcto desarrollo de la sesión, siendo su cumplim iento de
responsabilidad del que conforme al estatuto y la ley le corresponda convocarla o presi
dirla. Esta disposición no es aplicable cuando exista una prohibición legal o estatutaria.
Las sesiones no presenciales podrán ser convocadas por medios electrónicos u otros de
naturaleza similar que permitan la obtención de la constancia de recepción. El ejercicio
del derecho de voto no presencial, en sesiones presenciales o no presenciales, se podrá
realizar a través de firm a digital, medios electrónicos u otros de naturaleza similar, o por
medio escrito con firm a legalizada e insertada en el libro de actas correspondiente (Art.
2 1-A, modificado por la Ley N °31194, LGS).
Ahora bien, por la pandemia del Covid-19 la Ley N° 31194 estableció en su segunda dis
posición complementaria que, durante la vigencia del régimen de excepción, donde se
suspende el ejercicio de derechos constitucionales que impiden la realización de sesiones
presenciales, los órganos de las sociedades podrán realizar sesiones no presenciales, aun
cuando su estatuto no establezca la posibilidad de realizar sesiones no presenciales.
b) Presidencia y Secretaría de la Junta.- Salvo disposición diversa del estatuto, la junta ge
neral es presidida por el presidente del directorio. El gerente general de la sociedad ac
túa como secretario. En ausencia o impedimento de éstos, desempeñan tales funciones
aquellos concurrentes que la propia junta designe.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 676 of 1506 --

UBILEX
c) Aplazamiento de la Junta.-A solicitud de accionistas que representen al menos el vein
ticinco por ciento de las acciones suscritas con derecho a voto la junta general se aplazará
por una sola vez, por no menos de tres ni más de cinco días y sin necesidad de nueva
convocatoria, para deliberary votar los asuntos sobre los que no se consideren suficiente
mente informados. Cualquiera que sea el número de reuniones en que eventualmente se
divida una junta, se la considera como una sola, y se levantará un acta única.
d) Suspensión del derecho de voto.- El derecho de voto no puede ser ejercido porquien ten
ga, por cuenta propia o de tercero, interés en conflicto con el de la sociedad. En este caso,
las acciones respecto de las cuales no puede ejercitarse el derecho de voto son computa-
bles para establecer el quorum de la junta general pero no computables para establecer
las mayorías en las votaciones. El acuerdo adoptado sin observar lo dispuesto en el primer
párrafo de este artículo es im pugnabley los accionistas que votaron no obstante a dicha
prohibición responden solidariamente por los daños y perjuicios cuando no se hubiera
logrado la mayoría sin su voto.
Impugnación de acuerdos
Acuerdos impugnables judicialmente:
a) Acuerdos de la junta general cuyo contenido sea contrario a la ley.
b) Acuerdos de la junta general cuyo contenido se oponga al estatuto o al pacto social.
c) Acuerdos de la junta general cuyo contenido lesione, en beneficio directo o indirecto de
uno o varios accionistas, los intereses de la sociedad.
d) Los acuerdos que incurran en causal de anulabilidad prevista en la Ley o en el Código Civil,
también serán impugnables en los plazosy formas que señala la ley.
Impugnación Improcedente
a) No procede la impugnación cuando el acuerdo haya sido revocado, o sustituido por otro
adoptado conforme a ley, al pacto social o al estatuto.
b) El juez mandará tener por concluido el proceso y dispondrá el archivo de los autos, cual
quiera que sea su estado, si la sociedad acredita que el acuerdo ha sido revocado o susti
tuido conforme a lo prescrito en el párrafo precedente.
c) En los casos antes previstos no se perjudica el derecho adquirido por el tercero de buena fe.
Legitimación activa de la impugnación.- La impugnación puede ser interpuesta por los si
guientes accionistas:
a) Accionistas que en la junta general hubiesen hecho constaren acta su oposición al acuer
do,
b) Accionistas ausentes,
c) Accionistas que hayan sido ilegítimamente privados de em itir su voto, y
d) Titulares de acciones sin derecho a voto, sólo respecto de acuerdos que afecten los dere
chos especiales de dichas acciones.
Caducidad de la impugnación.- La impugnación caduca:
a) A los dos meses de la fecha de adopción del acuerdo si el accionista concurrió a la junta;
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 677 of 1506 --

Tema 4: Temas de la especialidad comercial
b) A los tres meses si el accionista no concurrió; y
c) Tratándose de acuerdos inscribibles, dentro del mes siguiente a la inscripción.
Proceso de impugnación y Juez Competente
a) La impugnación se tram ita por el proceso abreviado.
b) Las que se sustenten en defectos de convocatoria o falta de quorum se tram itan por el
proceso sumarísimo.
c) Es competente para conocer la impugnación de los acuerdos adoptados por la junta ge
neral el juez del dom icilio de la sociedad.
Condición del impugnante
a) El accionista que impugne judicialmente cualquier acuerdo de la junta general deberá
mantener la condición de tal durante el proceso, a cuyo efecto se hará la anotación res
pectiva en la matrícula de acciones.
b) La transferencia voluntaria, parcial o total, de las acciones de propiedad del accionista
demandante extinguirá, respecto de él, el proceso de impugnación.
Suspensión del acuerdo
a) El juez, a pedido de accionistas que representen más del 20% del capital suscrito, podrá
dictar medida cautelar de suspensión del acuerdo impugnado.
b) El juez debe disponer que los solicitantes presten contracautela para resarcir los daños y
perjuicios que pueda causar la suspensión.
Acumulación de pretensiones de Impugnación
a) Todas las acciones que tengan por objeto la impugnación de un mismo acuerdo se sus
tanciarán y decidirán en un mismo proceso.
b) No puede acumularse a la pretensión de impugnación, la de indemnización por daños
y perjuicios o cualquier otra que deba tramitarse en el proceso de conocimiento, ni se
admitirá la reconvención que por este concepto formule la sociedad, quedando sin em
bargo a salvo el derecho de las partes a iniciar procesos separados.
Medida cautelar
a) A solicitud de parte, el Juez puede dictar medida cautelar, disponiendo la anotación de la
demanda en el Registro.
b) La suspensión definitiva del acuerdo impugnado se inscribirá cuando quede firme la re
solución que así lo disponga.
c) A solicitud de la sociedad las anotaciones antes referidas se cancelarán cuando la demanda
en que se funden sea desestimada por sentencia firme, o cuando el demandante se haya
desistido, conciliado, transado o cuando se haya producido el abandono del proceso.
Ejecución de la sentencia
a) La sentencia que declare fundada la impugnación producirá efectos frente a lasociedady
todos los accionistas,
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 678 of 1506 --

UBILEX
b) No afectará los derechos adquiridos por terceros de buena fe a consecuencia del acuerdo
impugnado.
c) La sentencia firme que declare la nulidad de un acuerdo inscrito debe inscribirse en el
Registro.
Sanción para el demandante de mala fe
Cuando la impugnación se hubiere promovido con mala fe o con notoria falta de fundamento
el juez impondrá al demandante, en beneficio de la sociedad afectada por la impugnación,
una penalidad de acuerdo con la gravedad del asunto, así como la indemnización por daños y
perjuicios que corresponda.
Acción de nulidad de acuerdo
Causales (Art.150 LGS): Procede acción de nulidad para invalidar los acuerdos de lajunta con
trarios a normas imperativas o que incurran en causales de nulidad previstas en esta ley o en
el Código Civil.
Legitimación (Art.150 LGS): Cualquier persona que tenga legítimo interés puede interponer
acción de nulidad contra los acuerdos mencionados en el párrafo anterior, la que se sustancia
rá en el proceso de conocimiento.
Caducidad (Art.150 LGS): La acción de nulidad prevista en este artículo caduca al año de la
adopción del acuerdo respectivo.
DIRECTORIO
Concepto (Arts. 152 y 153 LGS).- El directorio es el órgano colegiado que está a cargo de la
administración de la sociedad.. Tiene el carácter de órgano por que expresa la voluntad de la
persona jurídica. Es órgano colegiado porque se encuentra conformado por una pluralidad de
miembros, en número no menor de 3, sus decisiones se adoptan, no a título personal sino por
el directorio como órgano. Ahora bien, las sociedades anónimas cerradas, pueden prescindir
de este órgano según lo establece el artículo 247 de la Ley, asumiendo tales funciones el ge
rente general.
Características del cargo
Cargo Personal (Art. 159 LGS).- El cargo de director (sea titular, suplente o alterno) es perso
nal, es decir, debe ser desempeñado personalmente por quien ha sido elegido, salvo que el
estatuto autorice la representación.
Recae en persona natural (Art. 160 LGS).- El cargo de director recae sólo en personas natura
les, es decir, no es posible que el cargo sea desempeñado por personas jurídicas a diferencia de
la gerencia general, pues puede traer eventuales incompatibilidades entre la responsabilidad
personal del directory la actuación indirecta de la persona jurídica en el ejercicio del cargo.
No requiere ser accionista (Art. 160 LGS).- Consagrando la disociación entre la titularidad del
capital invertido y el control de la sociedad, no se requiere ser accionista para ser director, ía
administración debe estar en manos de quienes resulten profesionalmente capacitados; salvo
que el estatuto disponga lo contrario.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 679 of 1506 --

Tema 4: Temas de la especialidad comercial
Cargo retribuido (Alt. 166 LGS).- Enfatizando su carácter netamente profesional y laboral, el
cargo de director es retribuido. Si el estatuto no prevé el monto de la retribución, corresponde
determinarlo a la junta obligatoria anual. En el caso que, además de su retribución, el director
tenga derecho a la participación de utilidades, esta solo puede ser detraída de las utilidades
líquidas y, en su caso, después de la detracción de la reserva legal correspondiente al ejercicio.
Cada director tiene el derecho a ser informado por la gerencia de todo lo relacionado con la
marcha de la sociedad.
Diligencia en el ejercicio del cargo (Art. 171 LGS).- Los directores deben desempeñar el cargo
con la diligencia de un ordenado comerciantey de un representante leal. Este deberse refiere
a las funciones de gestión y representación con la finalidad de llevar a cabo el objeto social.
Están obligados a guardar reserva respecto de los negocios de la sociedady de la información
social a que tengan acceso, salvaguardando la divulgación de información privilegiada. Esta
obligación dura aun después de cesaren sus funciones.
Vacancia del cargo de director (Art. 157 LGS).- El cargo de di rector vaca porfallecimiento, renun
cia, remoción o por incurrir el directoren alguna de las causales de impedimento señaladas por
la ley o el estatuto. Es importante señalar lo establecido por el Tribunal Registral sobre los casos
en los que, a raíz de una vacancia, el número de miembros del directorio llegue a ser menor al
mínimo establecido por ley (3 miembros). En dichos supuestos, el directorio podrá seguir en fun
ciones siempre que cuenten con el número mínimo para sesionar, toda vez que ladisposición del
número mínimo de miembros está referida al establecimiento del número de directores para la
elección de estos en el estatuto, mas no a circunstancias posteriores a esta, derivadas o ajenas al
funcionamiento de la sociedad (Resolución N °1804-2019-SUNARP-TR-L).
Duración del directorio (Art. 1 63 LGS)
a) Basados en el régimen de temporalidad del Directorio, el estatuto puede señalar que la
duración del directorio por períodos determinados sea no mayor de tres años ni menorde
uno. Si el estatuto no señala plazo de duración se entiende que es por un año.
b) El directorio se renueva totalmente al término de su período, incluyendo a aquellos direc
tores que fueron designados para completar períodos. Los directores pueden ser reelegi
dos, salvo disposición contraria del estatuto.
c) El período del directorio termina al resolver la junta general elegir al nuevo directorio,
pero el directorio continúa en funciones, aunque hubiese concluido su período, mientras
no se produzca nueva elección.
Remoción (Art. 154 LGS)
a) Los directores pueden ser removidos en cualquier momento, bien sea por la junta general
o por la junta especial que los eligió, aun cuando su designación hubiese sido una de las
condiciones del pacto social.
b) La junta general solo podrá remover a los directores por ella elegidos, mientras que la
junta especial podrá hacer lo propio con los directores correspondientes a la respectiva
clase de acciones.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 680 of 1506 --

UBILEX
Facultades
La resolución N° 99i-2020-SUNARP-TR-L menciona que en la Ley no existe una disposición
expresa que señale en detalle cuáles son las facultades que corresponde al directorio. No obs
tante, puede deducirse que éste se encarga de elaborar la política y lineamientos a los que se
encontrará sujeta la empresa, contando además con facultades necesarias para la adminis
tración de la sociedad, salvo aquellos asuntos reservados por la Ley o el estatuto a la junta
general. En tal sentido, las facultades más relevantes serán:
a) De Gestión y representación (Art. 172 LGS)
b) Derecho a la información (Art. 173 LGS)
c) De Delegación (Art. 174 LGS). El Tribunal Registral considera que esta facultad tiene la fi
nalidad de agilizary dotar de eficiencia a la realización de actos que conlleven a la conse
cución del objeto social y con ello a la satisfacción de intereses de la sociedad. Asimismo,
cabe aclarar que la norma no permite delegar la facultad de decidir sobre los asuntos que
corresponden al directorio, sino delegar la facultad de ejecutar solo determinados actos
(Resolución N°99i''2020-SUNARP-TR-L)
Deberes
a) Proporcionar información fidedigna (Art. 175 LGS),
b) Convocar a junta para informar pérdidas o insolvencia (Art. 176 LGS),
c) Acceder a las prestaciones, garantías y créditos de la sociedad en condiciones del merca
do (Art. 179 LGS)
d) Cautelar el interés social (Arts. 173 y 180 LGS)
Sesiones no presenciales (Art. 169 LGS).- El estatuto puede prever la realización de sesiones
no presenciales, a través de medios escritos, electrónicos, o de otra naturaleza que permitan la
comunicación y garanticen la autenticidad del acuerdo. Cualquier director puede oponerse a
que se utilice este procedimiento y exigir la realización de una sesión presencial.
Responsabilidad de los directores
Alcances de la responsabilidad (Art. 177 LGS)
a) Los directores responden, personal ilim itada y solidariamente, ante la sociedad, los ac
cionistas y los terceros por los daños y perjuicios (efectos) que causen por los acuerdos o
actos contrarios a la ley, al estatuto, a los acuerdos de la junta general de accionistas o por
los realizados con dolo, abuso de facultades o negligencia grave (causales).
b) Asimismo, los directores son solidariamente responsables con los directores que los ha
yan precedido por las irregularidades que éstos hubieran cometido si, conociéndolas, no
las denunciaren por escrito a la junta general.
Exención de responsabilidad (Art. 178 LGS)
No es responsable el director que, habiendo participado en el acuerdo o habiendo tomado co
nocimiento de él, haya manifestado su disconformidad en el momento del acuerdo o cuando
lo conoció, siempre que haya cuidado que tal disconformidad se consigne en acta o haya he
cho constar su desacuerdo por carta notarial.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 681 of 1506 --

Tema 4: I emas de la especialidad com ercia
Pretensión social de responsabilidad (Art.181 LGS)
a) La Pretensión social de responsabilidad tiene como carácter esencial que su ejercicio co
rresponde únicay exclusivamente a la sociedady tiene por objeto lograr el resarcimiento
de los dañosy perjuicios causados por los directores a la sociedad.
b) Los bienes que se obtengan en virtud de la demanda entablada por los accionistas son
percibidos por la sociedad, y los accionistas tienen derecho a que se les reembolse los
gastos del proceso.
c) Personas Legitimadas.
La Propia sociedad.- La pretensión social de responsabilidad contra cualquier direc
tor se promueve en virtud de acuerdo de la junta general, aun cuando la sociedad
esté en liquidación. El acuerdo puede ser adoptado, aunque no haya sido materia de
la convocatoria.
Los accionistas que representan por lo menos un tercio del capital social pueden
ejercer directamente la pretensión social de responsabilidad contra los directores,
siempre que se satisfaga los requisitos siguientes:
• Que la demanda comprenda las responsabilidades a favor de la sociedady no el
interés particular de los demandantes;
• Que, en su caso, los actores no hayan aprobado la resolución tomada por la junta
general sobre no haber lugar a proceder contra los directores.
Cualquier accionista puede entablar directamente pretensión social de responsa
bilidad contra los directores, si transcurridos tres meses desde que la junta general
resolvió la iniciación de la pretensión no se hubiese interpuesto la demanda. Es apli
cable a este caso que se satisfaga los requisitos siguientes:
• Que la demanda comprenda las responsabilidades a favor de la sociedady noel
interés particular de los demandantes;
• Que, en su caso, los actores no hayan aprobado la resolución tomada por la junta
general sobre no haber lugar a proceder contra los directores.
Los acreedores de la sociedad sólo pueden dirigirse contra los directores cuando su
pretensión tienda a reconstituir el patrimonio neto, no haya sido ejercitada por la
sociedad o sus accionistas y, además, se trate de acto que amenace gravemente la
garantía de los créditos
Pretensión individual de responsabilidad (Art.182 LGS)
a) Concepto: La Pretensión individual de responsabilidad corresponde a los accionistas o
cualquier tercero por los daños y perjuicios ocasionados por actos de los directores que
lesionen directamente los intereses de aquellos.
b) Alcances: No se considera lesión directa la que se refiere a daños causados a la sociedad,
aunque ello entrañe como consecuencia daño al accionista.
c) Legitimados: Los socios y terceros que tengan legítimo interés.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 682 of 1506 --

UBILEX
Caducidad de responsabilidad (Art.184 LCS).- La responsabilidad civil de los directores ca
duca a los dos años de la fecha de adopción del acuerdo o de la de realización del acto que
originó el daño, sin perjuicio de la responsabilidad penal.
GERENCIA
Concepto (Art.185 LCS).-Mientras el Directorio se ocupa de delinear las políticas generales de
administración, la gerencia realiza los actos de ejecución y gestión cotidiana de la sociedad, o
sea, la ejecución de los actos que exige la correcta conducción de los negocios.
Designación (Arts.i8 s y 193 LCS)
Órgano encargado de la Designación (Art.185 LCS)
La sociedad cuenta con uno o más gerentes designados por el Directorio, salvo que el es
tatuto reserve esa facultad a la Junta General de Accionistas. Al respecto, la resolución N°
632-2021-SUNARP-TR''L siguiendo el criterio establecido en el XCIII Pleno Registral, señala
que el nombramiento de un gerente general efectuado por un órgano no competente, es sus
ceptible de ser ratificado por el órgano competente.
Cuando se designe un solo gerente éste será el gerente general y cuando se designe más
de un gerente, debe indicarse en cuál o cuáles de ellos recae el título de gerente general.
Las atribucionesy responsabilidades que establece la ley se refieren al Gerente General.
A falta de tal indicación se considera gerente general al designado en primer lugar.
Designación de una persona jurídica (Art.193 LCS)
Cuando se designe gerente a una persona jurídica esta debe nombrar a una persona natural
que la represente al efecto, la que estará sujeta a las mismas responsabilidades de las perso
nas naturales designadas como gerentes, sin perjuicio de las que correspondan a los directo
res y gerentes de la entidad gerente y a ésta.
Duración del cargo (Art.186 LCS).
La duración del cargo de gerente es por tiempo indefinido, salvo disposición en contrario del
estatuto o que la designación se haga por un plazo determinado. Siguiendo la misma línea,
en la resolución N° 562-2020-SUNARP-TR-T, el Tribunal Registral menciona que el cargo de
gerente solo terminaría por renuncia o por remoción dispuesta por ¡a junta general o por el
Directorio, según corresponda.
Remoción { A r t i8y LCS)
Órgano facultado a su remoción.- El gerente puede ser removido en cualquier momento por
el Directorio o por la junta general, cualquiera que sea el órgano del que haya emanado su
nombramiento. Ahora bien, la Resolución N° 632-2021-SUNARP-TR-L señala que es posible
que el estatuto delegue la facultad de nombrar al gerente a la junta general, pero dicha deci
sión no impedirá al Directorio removerlo de sus fundones.
Carácter revocable del cargo.- De lo anterior mencionado se desprende que es nula la dis
posición del estatuto o el acuerdo de la junta general o del directorio que establezca la irre-
vocabilidad del cargo de gerente o que imponga para su remoción una mayoría superior a la
mayoría absoluta.
BALOTARiO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 683 of 1506 --

Tema 4: Temas de la especialidad comercial
Atribuciones (Art.188 LGS).- Las atribuciones del gerente se establecerán en el estatuto, al ser
nombrado o por acto posterior. Se presume, salvo disposición distinta del estatuto o acuerdo
expreso de la junta general o del directorio, que el gerente general goza de las siguientes atri
buciones:
a) Celebrary ejecutar los actos y contratos ordinarios correspondientes al objeto social;
b) Representar a la sociedad, con las facultades generalesy especiales previstas en el Código
Procesal Civil;
c) Asistir, con voz pero sin voto, a las sesiones del directorio, salvo que este acuerde sesionar
de manera reservada;
d) Asistir, con voz pero sin voto, a las sesiones de la junta general, salvo que esta decida en
contrario;
e) Expedir constancias y certificaciones respecto del contenido de los libros y registros de la
sociedad; y,
f) Actuar como secretario de las juntas generalesy del Directorio.
Deberes (Art. 190 LGS)
El gerente es particularmente responsable por-,
a) La existencia, regularidad y veracidad de los sistemas de contabilidad, los libros que la
ley ordena llevara lasociedady los demás libros y registros que debe llevar un ordenado
comerciante;
b) El establecimiento y mantenimiento de una estructura de control interno diseñada para
proveer una seguridad razonable de que los activos de la sociedad estén protegidos con
tra uso no autorizado y que todas las operaciones son efectuadas de acuerdo con autori
zaciones establecidas y son registradas apropiadamente;
c) La veracidad de las informaciones que proporcione al directorio y la junta general;
d) El ocultamiento de las irregularidades que observe en las actividades de la sociedad;
e) La conservación de los fondos sociales a nombre de la sociedad;
f) El empleo de los recursos sociales en negocios distintos del objeto de la sociedad;
g) La veracidad de las constanciasy certificaciones que expida respecto del contenido de los
libros y registros de la sociedad;
h) Dar cumplim iento en la forma y oportunidades al derecho de información de los accio
nistas; y,
i) El cumplim iento de la ley, el estatuto y los acuerdos de la junta general y del directorio.
Responsabilidad
Alcances (Art. 190 LGS).- El gerente responde ante la sociedad, los accionistas y terceros, por
los daños y perjuicios que ocasione por el incumplimiento de sus obligaciones, dolo, abuso
de facultades y negligencia grave. La sociedad, los accionistas y terceros pueden accionar las
pretensiones sociales, y estos últimos la individual de responsabilidad, aplicando las disposi
ciones establecidas para los directores.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 684 of 1506 --

UBILEX
Responsabilidad solidaría con directores (Art. 191 LGS).- El gerente es responsable, solida
riamente con los miembros del directorio, cuando participe en actos que den lugar a respon
sabilidad de estos o cuando, conociendo la existencia de esos actos, no informe sobre ellos al
directorio o a la junta general.
N ulid ad de absolución antelada de responsabilidad (Art. 194 LGS).- Es nula toda norma es
tatutaria o acuerdo de junta general o del directorio tendientes a absolver en forma antelada
de responsabilidad al gerente.
Efectos inm ediatos del acuerdo de responsabilidad (Art. 1 95 LGS).- El acuerdo para iniciar
pretensión de responsabilidad contra el gerente, adoptado por la junta general o el directorio,
importa la automática remoción de éste, quien no podrá volver a ser nombrado para el cargo ni
para cualquier otra función en la sociedad sino en el caso de declararse infundada la demanda
o de desistí rse la sociedad de la pretensión entablada.
C a d u cid a d de re sp o n sab ilid a d (Art. 1 97 LG S).- La responsabilidad civil del gerente cadu
ca a los dos años del acto realizado u o m itid o por este, sin perjuicio de la responsabilidad
penal.
xiii) Modificación de estatutos .
Órgano competente (Art. 198 LGS).- La modificación del estatuto se acuerda por junta gene
ral.
Requisitos form ales (Art. 198 LGS).- Para cualquier modificación del estatuto se requiere:
1. Expresaren la convocatoria de la junta general, con claridady precisión, los asuntos cuya
modificación se someterá a la junta.
2. Que el acuerdo se adopte mediante quorum y mayoría calificada (artículos 126 y 127), de
jando a salvo lo relativo a la junta universal (artículo 120), es decir:
• Para que la junta general adopte válidamente acuerdos relacionados con la m odifi
cación de estatutos, es necesaria en primera convocatoria, cuando menos, la concu
rrencia de dos tercios de las acciones suscritas con derecho a voto. En segunda convo
catoria basta la concurrencia de al menos tres quintas partes de las acciones suscritas
con derecho a voto. Los acuerdos se adoptan con el voto favorable de un número de
acciones que represente, cuando menos, la mayoría absoluta de las acciones suscri
tas con derecho a voto.
• La junta general se entiende convocada y válidamente constituida para tratar sobre
cualquier asunto y tomar los acuerdos correspondientes, siempre que se encuentren
presentes accionistas que representen la totalidad de las acciones suscritas con dere
cho a voto y acepten por unanimidad la celebración de la junta y los asuntos que en
ella se proponga tratar.
3. Con los mismos requisitos, la junta general puede acordar delegar en el directorio o la
gerencia la facultad de modificar determinados artículos en térm inosy circunstancias ex
presamente señaladas.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 685 of 1506 --

Tema 4: Temas de la especialidad comercial
Alcances y limitaciones ( A r t i 99 LGS)
Ninguna modificación del estatuto puede imponer a los accionistas nuevas obligaciones
de carácter económico, salvo para aquellos que hayan dejado constancia expresa de su
aceptación en la junta general o que lo hagan posteriormente de manera indubitable.
La junta general puede acordar, aunque el estatuto no lo haya previsto, la creación de
diversas clases de acciones o la conversión de acciones ordinarias en preferenciales.
Derecho de separación (Alt. 200 LGS)
Causales.- La adopción de los acuerdos que se indican a continuación, concede el derecho a
separarse de la sociedad:
a) El cambio del objeto social;
b) El traslado del dom icilio al extranjero;
c) La creación de limitaciones a la transmisibilidad de las acciones o la modificación de las
existentes; y,
d) En los demás casos que lo establezca la ley o el estatuto.
Es nulo todo pacto que excluya el derecho de separación o haga más gravoso su ejercicio.
Legitim ación Activa.- Sólo pueden ejercer el derecho de separación los accionistas que en la
junta hubiesen hecho constar en acta su oposición al acuerdo, los ausentes, los que hayan sido
ilegítimamente privados de e m itirsu voto y los titulares de acciones sin derecho a voto.
Aquellos acuerdos que den lugar al derecho de separación deben ser publicados por la socie
dad, por una sola vez, dentro de los diez días siguientes a su adopción, salvo aq uel los casos en
que la ley señale otro requisito de publicación. El derecho de separación se ejerce mediante
carta notarial entregada a la sociedad hasta el décimo día siguiente a la fecha de publicación
del aviso antes mencionada.
xiv. Aum ento y reducción de capital
El capital es una cifra invariable, sin embargo, puede ser objeto de modificaciones, así la Re
solución N°i6oi-202i-SUNARP-TR, señala que dichas modificaciones pueden consistir en un
aumento o en una reducción del capital. Por un lado, el aumento de capital incrementará la ci
fra que está consignada en el estatuto como capital así como en la partida registral respectiva,
mientras que, la reducción conlleva a una disminución del patrimonio social por la salida de
bienes del activo que se entregan a los accionistas a título de devolución de aportes, o bien la
disminución o eliminación de las pérdidas sufridas en las operaciones sociales que, en últim a
instancia, son soportadas por los accionistas.
Aum ento de capital (Art. 201 LGS):
El aumento de capital se acuerda por Junta General cumpliendo los requisitos establecidos
para la modificación del estatuto, consta en escritura pública y se inscribe en el Registro. Al
respecto, el Tribunal Registral señala que el aumento de capital es una operación de natura
leza económica dirigida a proporcionar nuevos recursos a la sociedad, con la finalidad que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 686 of 1506 --

UBILEX
i pueda seguir realizando sus actividades, alcanzar sus fines y constituir una garantía frente a
terceros (R esolución N°254-202i-SUNARP-TR-L).
Según el artículo 202 de la Ley, el aumento de capital puede originarse en:
1. Nuevos aportes;
2. La capitalización de créditos contra la sociedad, incluyendo la conversión de obligaciones
en acciones;
3. La capitalización de utilidades, reservas, beneficios, primas de capital, excedentes de re
valuación; y,
4. Los demás casos previstos en la ley.
El aumento de capital determina la creación de nuevas acciones o el incremento del valor no
minal de las existentes.
Para el aumento de capital por nuevos aportes o por la capitalización de créditos contra la
sociedad es requisito previo que la totalidad de las acciones suscritas, cualquiera sea la clase a
la que pertenezcan, estén totalmente pagadas. No será exigióle este requisito cuando existan
dividendos pasivos a cargo de accionistas morosos contra quienes esté en proceso la sociedad
y en los otros casos que prevé esta ley.
En el aumento de capital por nuevos aportes, los accionistas tienen derecho preferencial para
suscribir, a prorrata de su participación accionaria, las acciones que se creen, derecho denom i
nado "de suscripción preferente”, este derecho patrimonial ha sido desarrollado por la Reso
lución N ° 3 2 2 4 -2 0 2 1 -S U N A R P -T R , la cual señala que el derecho de suscripción preferente se
otorga a efectos de que los accionistas mantengan su proporción de participación en el capital
social y sigan gozando de los beneficios económicos y políticos en la sociedad; manteniendo
portanto, su participación en las utilidadesy en el voto. Asimismo, se indica que es un derecho
renunciable, lo que implica que para que este se haga efectivo se tendrá que manifestar para
cada junta general en la que se efectúe el aumento. Por último, se señala que es un derecho
transferí ble, toda vez que el accionista que no pueda o no tenga interés en suscribir las accio
nes, podrá mitigar la disminución del valor patrimonial de su cuota mediante la transmisión
del derecho de suscripción preferente. Asimismo, en la Resolución N° 6 8 y-2 0 2 0 -SUNARP-
TR-L, el Tribunal Registral manifiesta que, cuando se realice un aumento de capital por capi
talización de créditos contra la sociedad, también se reconocerá el derecho de los accionistas
de realizar aportes por un monto que permita a todos los accionistas ejercer su derecho de
suscripción preferente para mantener la proporción que tienen en el capital, de acuerdo al
segundo párrafo del artículo 213 de la Ley.
El aumento de capital por excedentes de revaluación de los activos supone que la sociedad
cuente con plusvalía oculta en el balance y que provengan del aumento de los valores que
pueden haberse acumulado en el tiempo con respecto a los activos revaluados. Estos benefi
cios extraordinarios podrán ser capitalizados, lo que conllevará un aumento en el capital se
gún lo señala la Resolución N °i2 9 3 -2 0 2 0 -S U N A R P -T R -L .
Reducción de capital (Art. 215 LGS):
La reducción del capital se acuerda por junta General, cumpliendo los requisitos establecidos
para la modificación del estatuto, consta en escritura pública y se inscribe en el Registro. Al
86 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 687 of 1506 --

Tema 4: Temas de la especialidad com ercial
respecto, la R eso lu ció n N ° 4 8 i - 2 0 2 0 -S U N A R P -T R -T señala que la reducción de capital supone
una afectación a la sociedad, a sus accionistas y a los acreedores y terceros en general, por lo
que, la Ley determina una serie de requisitos y formalidades con la finalidad de salvaguardar
el derecho de los acreedores, así como el porcentaje de participación de los socios en el capi
tal. De esta manera, el objetivo primordial de la disminución de capital responde a dos pará
metros fundamentales. Por una parte, salvaguardar los derechos de los acreedores y terceros,
que pueden ser vulnerados por la disminución de la garantía que es capital. Por otra parte, la
reducción de capital debe afectaren estricta proporción a todos los accionistas.
La reducción del capital determina la amortización de acciones emitidas o la disminución del
valor nominal de ellas.
Se realiza mediante:
i. La entrega a sus titulares del valor nominal amortizado;
z. La entrega a sus titulares del importe correspondiente a su participación en el patrimonio
neto de la sociedad;
3 . La condonación de dividendos pasivos;
4. El restablecimiento del equilibrio entre el capital social y el patrimonio neto disminuidos
por consecuencia de pérdidas; u,
5. Otros medios específicamente establecidos al acordar la reducción del capital.
Tal como lo menciona el Tribunal Registral, los dos primeros numerales implican una devo
lución de aportes a los socios, mientras que el tercero importa una exención de deudas a los
socios. Asimismo, el cuarto numeral no representa ni devolución ni exención de deudas. Por
último, el últim o numeral dependerá de lo que disponga la junta general, para determinar si
la reducción de capital equivale o no una devolución de aportes o exención de deudas a los
socios (R esolución N°6iy-2020-SUNARP-TR-L).
La reducción del capital tendrá carácter obligatorio cuando las pérdidas hayan dism inuido el
capital en más del cincuenta por ciento y hubiese transcurrido un ejercicio sin haber sido su
perado, salvo cuando se cuente con reservas legales o de libre disposición, se realicen nuevos
aportes o los accionistas asuman la pérdida, en cuantía que compense el desmedro.
Form alidades (Art. 217 LGS)
El acuerdo de reducción del capital debe expresar la cifra en que se reduce el capital, la forma
cómo se realiza, los recursos con cargo a los cuales se efectúay el procedimiento mediante el
cual se lleva a cabo.
La reducción debe afectar a todos los accionistas a prorrata de su participación en el capital
sin modificar su porcentaje accionario o por sorteo que se debe aplicar por igual a todos los
accionistas. Cuando se acuerde una afectación distinta, el la debe ser decidida por unanimidad
de las acciones suscritas con derecho a voto. El acuerdo de reducción debe publicarse por tres
veces con intervalos de cinco días. Sin perjuicio de lo antes mencionado, el Tribunal Registral
contempla algunas excepciones en la R eso lu ció n N °6 i7 -2 0 2 0 -S U N A R P -T R -L , tal como el su
puesto donde exime de dicho requisito cuando se reduce y se aumenta el capital de manera
simultánea, toda vez que con el aumento de capital se está protegiendo a los acreedores que
pudieran verse perjudicados por la reducción de capital.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 688 of 1506 --

UBILEX
Derecho de oposición (A rt 219 LGS)
El acreedor de la sociedad, aun cuando su crédito esté sujeto a condición o a plazo, tiene dere
cho de oponerse a la ejecución del acuerdo de reducción del capital si su crédito no se encuen
tra adecuadamente garantizado. El ejercicio del derecho de oposición caduca en el plazo de
treinta días de la fecha de la últim a publicación de los avisos de reducción de capital.
La oposición se tram ita por el proceso sumarísimo, suspendiéndose la ejecución del acuerdo
hasta que la sociedad pague los créditos o los garantice a satisfacción del juez, quien procede
a dictar la medida cautelar correspondiente.
xv. Beneficios y pérdidas
Para la distribución de beneficios, el artículo 39° LGS comienza consagrando el principio de la
proporcionalidad en función a los aportes al capital social cosa que no hacía el artículo 20o de
la anterior ley, dejando a salvo que por el pacto social o por el estatuto se fijen otras proporcio
nes o formas distintas de distribución.
Respecto a las pérdidas, si no hay pacto expreso, las pérdidas serán asumidas en la misma pro
porción que los beneficios, y solo se puede exceptuar de la responsabilidad por las pérdidas a
los socios que aportan servicios. Están prohibidos los pactos leoninos que excluyan a algunos
socios de la percepción de utilidades o que exoneren a algunos socios de la asunción de las
pérdidas, exceptuándose comoya hemos mencionado, a los socios que aportan servicios, si el
pacto social o el Estatuto así lo establece.
xvi. Plazos y caducidad
Todos los plazos de la Ley se han convertido en plazos de caducidad, convirtiendo al Derecho
Societario en un Derecho dinámico por excelencia, claro y muy bien delimitado. Por consi
guiente, sus normas no se condicen con la institución de la prescripción que tiene elementos
como la suspensión, la interrupción y la necesidad de ser invocada. Por el contrario, la caduci
dad anula el derechoy la situación queda terminada de manera claray definitiva.
xvii. Arbitraje
El artículo 48o de la Ley señala que el Estatuto o pacto social puede contener en una de sus
cláusulas, un convenio arbitral, en virtud del cual las diferencias que se produzcan entre la
sociedady sus socios aunque hubiesen dejado de serlo, representantes o administradores con
ocasión a los derechos u obligaciones relacionadas al cumplim iento de los estatutos o la vali
dez de los acuerdos, entre otros, quedarán sometidas a dicha jurisdicción.
2. Reglas de la sociedad anónima
2.1. Definición de sociedad anónima
La sociedad anónima es una sociedad de capitales, con responsabilidad limitada, en la que el
capital social se encuentra representado por acciones, y en la que la propiedad de las acciones
está separada de la gestión de la sociedad.
Nace para una finalidad determinada. Los accionistas no tienen derecho sobre los bienes ad
quiridos, pero si sobre el capital y utilidades de la sociedad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 689 of 1506 --

2.2. Caracteres esenciales
a) Es una sociedad capitalista.'' constituida ¡n tu itu pecuniae, en la que en principio apenas
juegan ni interesan las condiciones personales de los socios, sino la participación que
cada uno tenga en el capital social, que habrá de integrarse precisamente por las aporta
ciones de aquéllos.
b) Es una sociedad por acciones.- en la que el capital deberá estar necesariamente dividido
en partes alícuotas denominadas acciones, que confieren a su titu la r la condición de so
cio.
c) Es una sociedad de responsabilidad lim ita d a.- en el sentido de que el socio se obliga a
aportar a la sociedad el importe de las acciones que haya suscrito, respondiendo frente
a ella del incum plimiento de esa obligación, pero sin responsabilidad personal alguna
por las deudas sociales, por lo que los acreedores sociales no pueden, dirigir sus acciones
contra los socios para la satisfacción de sus créditos.
2.3. Constitución de la sociedad anónima
La sociedad anónima se constituye simultáneamente en un solo acto por los socios fundado
res, al momento de otorgarse la escritura pública que contiene el pacto social y el estatuto, en
cuyo acto suscriben íntegramente las acciones; o en forma sucesiva mediante oferta a terceros
contenida en el programa de fundación otorgado por los fundadores.
El pacto social contiene obligatoriamente:
1. Los datos de identificación de los fundadores. Si es persona natural, su nombre, dom i
cilio, estado civil y el nombre del cónyuge en caso de ser casado; si es persona jurídica,
su denominación o razón social, el lugar de su constitución, su domicilio, el nombre de
quien la representay el comprobante que acredita la representación.
2 . La manifestación expresa de la voluntad de los accionistas de constituir una sociedad
anónima.
3. El monto del capital y las acciones en que se divide.
4. La forma como se paga el capital suscrito y el aporte de cada accionista en dinero o en
otros bienes o derechos, con el informe de valorización correspondiente en estos casos.
5. El nom bram ientoy los datos de identificación de los primeros administradores.
6 . El estatuto que regirá el funcionamiento de la sociedad.
2.4. Los fundadores
En la constitución simultánea son fundadores aquellos que otorguen la escritura pública de
constitución y suscriban todas las acciones. En la constitución por oferta a terceros son funda
dores quienes suscriben el programa de fundación. También son fundadores las personas por
cuya cuenta se hubiese actuado en la forma indicada en este artículo.
En la etapa previa a la constitución los fundadores que actúan a nombre de la sociedad o a
nombre propio, pero en interés y por cuenta de ésta, son solidariamente responsables frente a
aquellos con quienes hayan contratado. Los fundadores quedan liberados de dicha responsa-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 68

-- 690 of 1506 --

UBILEX
biI¡dad desde que las obligaciones asumidas son ratificadas por la sociedad dentro del plazo
de tres meses. A falta de pronunciamiento de la sociedad dentro del citado plazo, se presume
que los actos y contratos celebrados por los fundadores han sido ratificados.
Adicionalmente los fundadores son solidariamente responsables frente a la sociedad, a los
demás socios y a terceros por:
i. La suscripción integral del capital y por el desembolso del aporte mínimo exigido para la
constitución.
z. La existencia de los aportes no di nerarios, conforme a su naturaleza, características y valor
de aportación consignados en el informe de valorización correspondiente.
3. La veracidad de las comunicaciones hechas por ellos al público para la constitución de la
sociedad.
Independientemente de su calidad de accionistas, los fundadores pueden reservarse dere
chos especiales de diverso contenido económico, los que deben constar en el estatuto. Cuan
do se trate de participación en las utilidades o de cualquier derecho sobre éstas, los beneficios
no pueden exceder, en conjunto, de la décima parte de la utilidad distribuible anual que apa
rezca de los estados financieros de los primeros cinco años, en un período máximo de diez
años contados a partir del ejercicio siguiente a la constitución de la sociedad.
La responsabilidad de los fundadores caduca a los dos años contados a partir de la fecha de
inscripción de la sociedad en el Registro, de la denegatoria definitiva de ella o del aviso en que
comunican a los suscriptores la extinción del proceso de constitución de la sociedad.
2.5. Denominación
La sociedad anónima puede adoptar cualquier denominación, pero debe figurar necesaria
mente la indicación “sociedad anónima” o las siglas “S.A.” Cuando se trate de sociedades cuyas
actividades sólo pueden desarrollarse, de acuerdo con la ley, por sociedades anónimas, el uso
de la indicación o de las siglas es facultativo.
2.6. El capital social
En lasociedadanónimael capital está representado poracciones nominativasy se integra por
aportes de los accionistas, quienes no responden personalmente de las deudas sociales. No se
admite el aporte de servicios en la sociedad anónima.
Para que se constituya la sociedad es necesario que tenga su capital suscrito total mente y cada
acción suscrita y pagada por lo menos en una cuarta parte. Igual regla aplica para los aumen
tos de capital que se acuerden.
2.7. Las acciones
Representan partes alícuotas del capital, todas tienen el mismo valor nominal y dan derecho
a un voto, con la excepción de la elección de directores y las demás contempladas en la ley.
Las acciones se crean en el pacto social o posteriormente por acuerdo de la junta general. Es
nula la creación de acciones que concedan el derecho a recibir un rendimiento sin que existan
utilidades distribuibles.
.1.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 691 of 1506 --

Tema 4: Temas de la especialidad com ercial
Puede concederse a determinadas acciones el derecho a un rendimiento máximo, mínimo o
fijo, acumulable o no, siempre sujeto a la existencia de utilidades distribuidles.
El importe a pagarse por las acciones se establece en la escritura pública de constitución o por
la junta general que acuerde el aumento de capital. Pueden existir diversas clases de acciones.
La diferencia puede consistir en los derechos que corresponden a sus titulares, en las obliga
ciones a su cargo o en ambas cosas a la vez. Todas las acciones de una clase gozarán de los
mismos derechos y tendrán a su cargo las mismas obligaciones.
La creación de clases de acciones puede darse en el pacto social o por acuerdo de la junta
general. Las acciones son indivisibles. Los copropietarios de acciones deben designar a una
sola persona para el ejercicio de los derechos de socio y responden solidariamente frente a la
sociedad de cuantas obligaciones deriven de la calidad de accionistas.
La sociedad considera propietario de la acción a quien aparezca como tal en la matrícula de
acciones. Puede crearse una o más clases de acciones sin derecho a voto. Las acciones sin dere
cho a voto no se computan para determinar el quorum de las juntas generales.
En el pacto social o por acuerdo de aumento de capital, la sociedad puede crear acciones, con
o sin derecho a voto, las que se mantienen en cartera. Las acciones en cartera no podrán repre
sentar más del veinte por ciento del número total de las acciones emitidas. Las acciones emi
tidas, cualquiera que sea su clase, se representan por certificados, por anotaciones en cuenta
o en cualquier otra forma que permita la ley.
2.8. Emisión de obligaciones
La sociedad puede em itir series numeradas de obligaciones que reconozcan o creen una deu
da a favor de sus titulares. Una misma emisión de obligaciones puede realizarse en una o más
etapas o en una o más series, si así lo acuerda la junta de accionistas o de socios, según el caso.
El importe total de las obligaciones, a la fecha de emisión no podrá ser superior al patrimonio
neto de la sociedad, con las siguientes excepciones:
i. Que se haya otorgado garantía específica.
z. Que la operación se realice para solventar el precio de bienes cuya adquisición o construc
ción hubiese contratado de antemano la sociedad.
3 . En los casos especiales que la ley lo permita.
Las condiciones de cada emisión, así como la capacidad de la sociedad para formalizarlas, en
cuanto no estén reguladas por la ley, serán las que disponga el estatuto y las que acuerde la
junta de accionistas o de socios, según el caso.
Son condiciones necesarias la constitución de un sindicato de obligacionistas y la designa
ción por la sociedad de una empresa bancaria, financiera o sociedad agente de bolsa que, con
el nombre de representante de los obligacionistas, concurra al otorgamiento del contrato de
emisión en nombre de los futuros obligacionistas.
La emisión de obligaciones se hará constar en escritura pública, con intervención del represen
tante de los obligacionistas.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 691

-- 692 of 1506 --

UBILEX
La colocación de las obligaciones puede iniciarse a partir de la fecha de la escritura pública
de emisión. Si existen garantías inscribibles sólo puede iniciarse después de la inscripción de
estas. Las obligaciones pueden representarse por títulos, certificados, anotaciones en cuenta
o en cualquier otra forma que permita la ley.
Los títulos o certificados representativos de obligaciones y los cupones correspondientes a
sus intereses, en su caso, pueden ser nominativos o al portador, tienen mérito ejecutivo y son
transferibles con sujeción a las estipulaciones contenidas en la escritura pública de emisión.
Las obligaciones representadas por medio de anotaciones en cuenta se rigen por las leyes de
la materia.
El sindicato de obligacionistas se constituye por el otorgamiento de la escritura pública de
emisión. Los adquirentes de las obligaciones se incorporan al sindicato por la suscripción de
las mismas.
La sociedad emisora debe satisfacer el importe de las obligaciones en los plazos convenidos,
con las primas y ventajas que se hubiesen estipulado en la escritura pública de emisión.
2.9. El estado de situación financiera y otras principales
El estado de situación financiera (antes balance general) es un cuadro o representación gráfica
y corporativa de los saldos de las diferentes cuentas del activo y del pasivo, q ue resume toda la
contabilidad del ejercicio y determina la existencia de pérdidas o ganancias. Ofrece una ima
gen de la situación de la empresa en un momento determinado. Para ello, los datos contables
se agrupan en diversas cuentas organizadas en dos columnas (activo y pasivo). Las cuentas
contenidas en la columna del activo representan el valor de los bienes y derechos del empre
sario. Por su parte, las cuentas agrupadas en la columna del pasivo muestran la procedencia
de los recursos que aparecen en la columna del activo, es decir, cuáles son los fondos propiosy
cuáles son los fondos ajenos o deudas con acreedores.
Mientras la columna del activo indica la estructura patrimonial de la empresa, la columna
del pasivo es fundamental para determinar su estructura financiera. El análisis del pasivo del
balance indica el nivel de endeudamiento del empresario.
La ley impone al empresario la redacción de cuentas anuales como medio de establecer pe
riódicamente los beneficios o pérdidas experimentados en el ejercicio de la actividad empre
sarial.
La contabilidad debe perm itir obtener una representación lo más exacta y veraz de la realidad
de la empresa, tanto por lo que se refiere al activo y al pasivo y a la situación financiera como a
las ganancias o pérdidas obtenidas en el ejercicio.
Los principales estados financieros que se someten a consideración de la junta general son el
estado de situación financiera, el estado de resultados,y la memoria.
2.10. Estado de resultados
El estado de resultados comprende los ingresos y los gastos del ejercicio y, por diferencias, el
resultado del mismo. Este documento ofrece una visión dinámica del ejercicio, indicando el
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 693 of 1506 --

Tema 4: Temas de la especialidad com ercial
empleo de los recursos empresariales y cuáles han sido las causas de la existencia de benefi
cios o pérdidas. En la contabilidad de partida doble, cada operación se registra dos veces tanto
en el “debe” como en el "haber”. Esta duplicidad presenta siempre una igualdad entre las sumas
que figuran en el “debey el “haber”, lo que permite la comprobación de los registros.
2.11. Reglas de otras modalidades de sociedad anónima
La sociedad anónima cerrada y la sociedad anónima abierta
Sociedad Anónim a Cerrada
a) Las sociedades cerradas o llamadas frecuentemente familiares son entes con muy escaso
número de accionistas, en las que predomina el "intuito personae” frente al “in tu ito pecunie”.
Sus acciones no son libremente trasmisibles (salvo pacto en contrario).
b) La Ley General de Sociedades ha diseñado un régimen especial facultativo para este tipo
de sociedades, no obstante exige no tener más de veinte accionistas ni acciones inscritas
en el Registro Público del Mercado de Valores (Art. 234 de la Ley).
c) La ley simplifica los requisitos formales para la convocatoria a Junta General de Accionis
tas ya que pueden realizarse juntas no presenciales; las funciones del Directorio pueden
ser asumidas por el Gerente General, siendo facultativa la existencia de dicho órgano y
existe la posibilidad de la exclusión de accionistas si el pacto social o el estatuto lo esta
blecen. Además, los deberes de publicidad se simplifican, dada la naturaleza de este tipo
de sociedad. Así por ejemplo, en este tipo de sociedades la convocatoria a junta general
se realiza mediante esquelas u otra forma que permita tener constancia de su recepción
por los accionistas destinatarios.
d) La característica fundamental de este tipo de sociedades anónimas, es el derecho de ad
quisición preferente con el que cuentan sus accionistas, toda vez que, según lo establecido
en el artículo 237 de la Ley, el accionista que se proponga transferir total o parcialmente sus
acciones a otro accionista o a terceros debe comunicarlo a la sociedad mediante carta di rígi
da al gerente general, quien lo pondrá en conocimiento de los demás accionistas dentro de
los diez días siguientes, para que dentro del plazo de treinta días puedan ejercer el derecho
de adquisición preferente a prorrata de su participación en el capital. El accionista podrá
transferir a terceros no accionistas las acciones en las condiciones comunicadas a la socie
dad cuando hayan transcurrido sesenta días de haber puesto en conocimiento de esta su
propósito de transferir, sin que la sociedady/o los demás accionistas hubieran comunicado
su voluntad de compra, en caso no se cumpla con dichas formalidades la transferencia que
se realice sería ineficaz. Sin perjuicio de lo antes mencionado, el estatuto podrá establecer
otros pactos, plazosy condiciones para la transmisión de las accionesy su valuación, inclusi
ve suprimiendo el derecho de-preferencia para la adquisición de acciones.
e) En lo que respecta los casos de separación que concede la ley, tiene derecho a separarse
de la sociedad anónima cerrada, el socio que no haya votado a favor de la modificación
del régimen relativo a las limitaciones a la transmisibilidad de las acciones o al derecho
de adquisición preferente.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 694 of 1506 --

UBILEX
f) Si bien la Ley permite que los accionistas puedan hacerse representar por otra persona,
en los supuestos de una sociedad anónima cerrada, el artículo 243 de la ley establece que
el accionista solo podrá hacerse representaren las juntas por medio de otro accionista, su
cónyuge o ascendiente o descendiente en primer grado, salvo que el estatuto contemple
una extensión en la representación a otras personas (R eso lu ció n N ° 3 0 4 -2 0 1 8 -S U N A R P -
TR -A ). En la misma línea, el Reglamento del Registro de Sociedades establece en su artí
culo 75 que, en el acta o lista de asistentes de la junta general de la sociedad anónima ce
rrada utilizada para inscribir un acuerdo, se indique la relación de parentesco que vincula
al representante con el accionista representad o, en su defecto, se presente una constancia
del gerente general indicando las circunstancias señaladas.
Sociedad A nónim a Abierta
a) Las sociedades abiertas, se caracterizan por tener acciones que se trasmiten frecuente
mente en el mercado de valores, son sustancialmente bursátiles, sus socios se encuentran
dispersos, o dispersados, desatendidos de la sociedad y atentos a su cartera de valores,
estos no poseen la tradicional “affectiosocietatis", excepto el grupo que la controla. El con
trol de estas sociedades se obtiene por diversos medios ejecutivos. Son arquetipo de la
gran empresa capitalista.
b) La Ley General de Sociedades ha delineado un régimen especial obligatorio para este tipo
de sociedades (Arts.249 y siguientes de la Ley General de Sociedades). De esta manera,
quienes adopten este régimen deberán cum plir con haber hecho una oferta pública de
acciones, tener más de setecientos cincuenta accionistas o contar con más del treinta por
ciento de su capital distribuido entre ciento setentaicinco accionistas. Ahora bien, es po
sible que la Sociedad Anónima Abierta, se constituya como tal o que los accionistas deci
dan transformar o adaptar la preexistente a este régimen.
c) Las características centrales de este régimen son: 1) La inscripción de sus acciones en el
Registro Público del Mercado de Valores; 2) El control y supervisión por parte de la CO-
NASEV; 3) la invalidez de las estipulaciones que limiten la libre transmisibilidad de las
acciones; 4) la invalidez de pactar un derecho de preferencia a los accionistas o a la so
ciedad; 5) La obligación de tener auditoría externa anual; 6) El derecho de información se
podrá ejercer fuera de la junta; entre otros. Con respecto la anticipación con la que deben
estar inscritas las acciones para asistir a la junta general y ejercer el derecho a voto, el
artículo 256 de la Ley señala que debe ser de diez días.
3. Otras formas societarias
3.1. La sociedad colectiva
En la sociedad colectiva los socios responden en forma solidaria e ilim itada por las obligacio
nes sociales. Todo pacto en contrario no produce efecto contra terceros. Esta forma societaria
realiza sus actividades bajo una razón social que se integra con el nombre de todos los socios
o de algunos o alguno de ellos, agregándose la expresión “Sociedad Colectiva" o las siglas "S.C.”
La persona que, sin ser socio, permite que su nombre aparezca en la razón social, responde
como si lo fuera. La sociedad colectiva tiene plazo fijo de duración. La prórroga requiere con
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 695 of 1506 --

Tema 4: Temas de la especialidad comercial
sentimiento unánime de los socios y se realiza luego de haber cumplido con la publicación del
acuerdo. Salvo estipulación diferente, los acuerdos de la sociedad se adoptan por mayoría de
votos, computados por personas. Si se pacta que la mayoría se computa por capitales, el pacto
social debe establecer el voto que corresponde a l o a los socios industriales. En todo caso en
que un socio tenga más de la mitad de los votos, se necesitará además el voto de otro socio.
Salvo régimen distinto previsto en el pacto social, la administración de la sociedad correspon-
de, separada e individualmente a cada uno de los socios. Ningún socio puede transm itir su
participación en la sociedad sin el consentimiento de los demás. Las participaciones de los so
cios constan en la escritura pública de constitución social. Igual formalidad es necesaria para
la transmisión de las participaciones.
3.2. Las sociedades en comandita
En las sociedades en comandita, los socios colectivos responden solidaria e ilim itadamente
por las obligaciones sociales, en tanto que los socios comanditarios responden sólo hasta la
parte del capital que se hayan comprometido a aportar. El acto constitutivo debe indicar quié
nes son los socios colectivosy quiénes los comanditarios. La sociedad en comandita realiza sus
actividades bajo una razón social que se integra con el nombre de todos los socios colectivos,
o de algunos o alguno de ellos, agregándose, según corresponda, las expresiones "Sociedad
en Comandita” o “Sociedad en Comandita por Acciones”, o sus respectivas siglas “S. en C.”, o
"S. en C. por A.” El socio comanditario que consienta que su nombre figure en la razón social
responde frente a terceros por las obligaciones sociales como si fuera colectivo. La sociedad en
comandita puede ser simple o por acciones. A la sociedad en comandita simple se aplican las
disposiciones relativas a la sociedad colectiva, siempre que sean compatibles con lo indicado
en el artículo 281° de la Ley General de Sociedades. A la sociedad en comandita por acciones se
aplican las disposiciones relativas a la sociedad anónima, siempre que sean compatibles con
lo indicado en el artículo 282o de la Ley.
3.3. Las sociedades comerciales de responsabilidad limitada
En la Sociedad Comercial de Responsabilidad Limitadael capital está dividido en participaciones
¡guales, acumulables e indivisibles, que no pueden ser incorporadas en títulos valores, ni deno
minarse acciones. Los socios no pueden exceder de veinte y no responden personalmente por las
obligaciones sociales. La Sociedad Comercial de Responsabilidad Limitada tiene una denomina
ción, pudiendo útil izar además un nombre abreviado, al que en todo caso debe añadir la indica
ción "Sociedad Comercial de Responsabilidad Limitada” o su abreviatura “S.R.L." El capital social
está integrado por las aportaciones de los socios. Al constituirse la sociedad, al capital debe estar
pagado en no menos del veinticinco por ciento de cada participación, y depositado en entidad
bancada o financiera del sistema financiero nacional a nombre de la sociedad. La voluntad de los
socios que representen la mayoría del capital social regirá la vida de la sociedad.
3.4. Las sociedades civiles
La Sociedad Civil se constituye para un fin común de carácter económico que se realiza me
diante el ejercicio personal de una profesión, oficio, pericia, práctica u otro tipo de actividades
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 696 of 1506 --

UBILEX
personales por alguno, algunos o todos los socios. La sociedad civil puede ser ordinaria o de
responsabilidad limitada. En la primera los socios responden personalmentey en forma sub
sidiaria, con beneficio de excusión, por las obligaciones socialesy lo hacen, salvo pacto distin
to, en proporción a sus aportes. En la segunda, los socios, que no pueden exceder de treinta,
no responden personalmente por las deudas sociales. La sociedad civil ordinariay la sociedad
civil de responsabilidad limitada desenvuelven sus actividades bajo una razón social que se
integra con el nombre de uno o más socios y con la indicación “Sociedad Civil” o su expresión
abreviada “S. Civil", o “Sociedad Civil de Responsabilidad Limitada” o su expresión abreviada "S.
Civil de R. L.". El capital social de la sociedad civil debe estar íntegramente pagado al tiem po de
la celebración del pacto social. La junta de socios es el órgano supremo de la sociedad y ejerce
como tal los derechos y las facultades de decisión y disposición que legalmente le correspon
den, salvo aquellos que, en virtud del pacto social, hayan sido encargados a los administrado
res. Los acuerdos se adoptan por mayoría de votos computada conforme al pacto social y, a
falta de estipulación, por capitales y no por personas.
4. Reorganización de sociedades: transformación, fusión, escisión. Disolución, liquida
ción y extinción de sociedades
4.1 Transformación (Art. 333 LGS)
Las sociedades reguladas por la Ley General de Sociedades pueden transformarse en cual
quier otra clase de sociedad o persona jurídica contemplada en las leyes de nuestro país.
Cuando la ley no lo impida, cualquier persona jurídica constituida en el Perú puede transfor
marse en alguna de las sociedades reguladas por la Ley.
La transformación no entraña cambio de la personalidad jurídica, lo que evita que los accio
nistas tengan que disolver la sociedady constituir otra nueva, toda vez que la transformación
importa un cambio de forma jurídica, con los mismos socios y el mismo patrimonio, así lo
señala la Resolución N °570-2018-SUNARP-TR-L.
Cam bio en la responsabilidad de los socios (Art. 334 LGS).- Los socios q ue en vi rtud de la
nueva forma societaria adoptada asumen responsabilidad ilim itada por las deudas socia
les, responden en la misma forma por las deudas contraídas antes de la transformación.
La transformación a una sociedad en que la responsabilidad de los socios es limitada, no
afecta la responsabilidad ¡limitada que corresponde a estos por las deudas sociales con
traídas antes de la transformación, salvo en el caso de aquellas deudas cuyo acreedor la
acepte expresamente.
Requisitos (Art. 336 LGS).- La transformación se acuerda con los requisitos establecidos
por la ley y el estatuto de la sociedad o de la persona jurídica para la modificación de
su pacto social y estatuto. Ahora bien, el artículo 117 del Reglamento del Registro de So
ciedades señala que la escritura pública de transformación debe comprender todos los
requisitos exigidos para la nueva forma societaria adoptada. Así, en la Resolución N °
1827-201 o-SUN ARP-TR-L, se menciona que la transformación de la sociedad supone la
aprobación de un nuevo estatuto adecuado a la nueva forma que se adopta, con variacio
nes que pueden repercutiren las distintas relaciones entre los socios, entre la sociedady
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 697 of 1506 --

Tema 4: Temas de la especialidad comercial
los terceros, en la responsabilidad de los socios, en la administración social, entre otros
cambios estructurales.
Publicación del acuerdo (Art.337 LGS).- El acuerdo de transformación se publica por tres
veces, con cinco días de intervalo entre cada aviso.
Balance de Transform ación (Art. 339 LGS).- La sociedad está obligada a form ular un ba
lance de transformación al día anteriora la fecha de la escritura pública correspondiente.
No se requiere insertar el balance de transformación en la escritura pública, pero la socie
dad debe ponerlo a disposición de los socios y de los terceros interesados, en el dom icilio
social, en un plazo no mayor de treinta días contados a partir de la fecha de la referida
escritura pública.
Fecha de vigencia (Art. 341 LGS).- La transformación entraen vigencia al día siguiente de
la fecha de la escritura pública respectiva. La eficacia de esta disposición está supeditada
a la inscripción de la transformación en el Registro.
4.2. Fusión
Por la fusión dos o más sociedades se reúnen para formar una sola cumpliendo los requisitos
prescritos por la Ley. Puede adoptar alguna de las siguientes formas:
a) La fu sió n p o r in c o rp o ra ció n : Donde dos o más sociedades se fusionan para constituir una
nueva sociedad incorporante, lo cual origina la extinción de la personalidad jurídica de las
sociedades incorporadas y la transmisión en bloque, y a título universal de sus patrim o
nios a la nueva sociedad; o,
b) La fu sió n p o r ab so rció n : Donde una o más sociedades son absorbidas por otra sociedad
ya existente, lo que origina la extinción de la personalidad jurídica de la sociedad o so
ciedades absorbidas. La sociedad absorbente asume, a título universal, y en bloque, los
patrimonios de las absorbidas.
En ambos casos los socios o accionistas de las sociedades que se extinguen por la fusión reci
ben acciones o participaciones como accionistas o socios de la nueva sociedad o de la socie
dad absorbente, en su caso.
Requisitos del acuerdo de fusión (Art. 345 LGS).- La fusión se acuerda con los requisitos
establecidos por la ley y el estatuto de las sociedades participantes para la modificación
de su pacto social y estatuto.
No se requiere acordar la disolución y no se liquida la sociedad o sociedades que se extin
guen por la fusión.
Aprobación del proyecto de fusión (Art. 346 LGS).- El directorio de cada una de las socie
dades que participan en la fusión aprueba, con el voto favorable de la mayoría absoluta
de sus miembros, el texto del proyecto de fusión.
En el caso de sociedades que no tengan directorio el proyecto de fusión se aprueba por la ma
yoría absoluta de las personas encargadas de la administración de la sociedad.
Al respecto), el Tribunal Registral define al proyecto de fusión como el documento necesario
que, suscrito por los administradores de las sociedades participantes que recoge las condicio
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 698 of 1506 --

nes básicas en que se programa actuar la fusión, resultado de las negociaciones y acuerdos
adoptados por los representantes de las sociedades. Sin embargo, solo después de la apro
bación del proyecto de fusión y su posterior adopción, las sociedades quedarán legalmente
obligadas a la efectiva realización de la fusión (Resolución N° 286-2018-SUNARP-TR-A).
Acuerdo de fusión (Art.351 LGS).- La junta general o asamblea de cada una de las socie
dades participantes aprueba el proyecto de fusión con las modificaciones que expresa
mente se acuerden y fija una fecha común de entrada en vigencia de la fusión.
Fecha de entrada en vigencia (Art. 353 LGS).- La fusión entra en vigencia en la fecha fi
jada en los acuerdos de fusión. En esa fecha cesan las operaciones y los derechos y obli
gaciones de las sociedades que se extinguen, los que son asumidos por la sociedad ab
sorbente o incorporante. De esta manera, el Tribunal Registral considera que la Ley ha
otorgado amplia libertad a las sociedades intervinientes para fijar la fecha de entrega en
vigencia. No obstante, como se verá a continuación, la inscripción será un requisito para
el perfeccionamiento de la fusión, lo que otorga efectos frente a terceros (Resolución N°
1708-2013-SUNARP-TR-L).
Sin perjuicio de su inmediata entrada en vigencia, la fusión está supeditada a la inscripción de
la escritura pública en el Registro, en la partida correspondiente a las sociedades participantes.
La inscripción de la fusión produce la extinción de las sociedades absorbidas o incorporadas,
según sea el caso. Por su solo mérito se inscriben también en los respectivos registros, cuando
corresponda, la transferencia de los bienes, derechosy obligaciones individuales que integran
los patrimonios transferidos.
Publicación de los acuerdos (Art. 355 LGS).- Cada uno de los acuerdos de fusión se publi
ca por tres veces, con cinco días de intervalo entre cada aviso. Los avisos podrán publicarse
en forma independiente o conjunta por las sociedades participantes.
Contenido de la escritura pública (Art. 358 LGS).- La escritura pública de fusión se otorga
una vez vencido el plazo de treinta días contado a partir de la fecha de publicación del
últim o aviso. La escritura pública de fusión contiene:
1. Los acuerdos de las juntas generales o asambleas de las sociedades participantes.
2. El pacto social y estatuto de la nueva sociedad o las modificaciones del pacto social y
del estatuto de la sociedad absorbente.
3. La fecha de entrada en vigencia de la fusión.
4. La constancia de la publicación de los avisos de la publicación de los acuerdos.
5. Los demás pactos que las sociedades participantes estimen pertinente.
Cam bio en la responsabilidad de los socios.- Es aplicable a la fusión cuando origine
cambio en la responsabilidad de los socios o accionistas de alguna de las sociedades par
ticipantes lo dispuesto en el artículo 334 de la Ley, es decir si se asume responsabilidad
ilim itada por las deudas sociales, los socios responden en la misma forma por las deudas
contraídas antes de la fusión. Por o tro lado, si tras la fusión la responsabilidades limitada,
no afecta la responsabilidad ilim itada que corresponde a los socios por las deudas socia
les contraídas antes de la fusión, salvo que el acreedor lo acepte expresamente.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 699 of 1506 --

Tema 4: Temas de la especialidad comercial
4.3. Escisión
Por la escisión una sociedad fracciona su patrimonio en dos o más bloques para transferirlos
íntegramente a otras sociedades o pudiendo conservar uno de ellos, así, la escisión puede ser
de dos formas: (i) La división de la totalidad del patrimonio de una sociedad en dos o más
bloques patrimoniales, que son transferidos a nuevas sociedades o absorbidos por sociedades
ya existentes o ambas cosas a la vez., lo que produce la extinción de la sociedad escindida; o
(ii) La segregación de uno o más bloques patrimoniales de una sociedad que no se extinguey
que los transfiere a una o más sociedades nuevas, o son absorbidos por sociedades existentes
o ambas cosas a la vez. La sociedad escindida ajusta su capital en el monto correspondiente.
En ambos casos los socios o accionistas de las sociedades escindidas reciben acciones o parti
cipaciones como accionistas o socios de las nuevas sociedades o sociedades absorbentes, en
su caso.
La escisión entraen vigencia en la fecha fijada en el acuerdo en que se aprueba el proyecto de
escisión. A partir de esa fecha las sociedades beneficiarías asumen automáticamente las ope
raciones, derechosy obligaciones de los bloques patrimoniales escindidosy cesan con respec
to a ellos las operaciones, derechosy obligaciones de la o las sociedades escindidas, ya sea que
se extingan o no. Sin perjuicio de su inmediata entrada en vigencia, la escisión está supeditada
a la inscripción de la escritura pública en el Registroy en las partidas correspondientes a todas
las sociedades participantes. La inscripción de la escisión produce la extinción de la sociedad
escindida, cuando éste sea el caso. Por su solo mérito se inscriben también en sus respectivos
Registros, cuando corresponda, el traspaso de los bienes, derechosy obligaciones individuales
que integran los bloques patrimoniales transferidos.
4.4. Reorganización simple
Se considera reorganización el acto por el cual una sociedad segrega uno o más bloques pa
trimoniales y los aporta a una o más sociedades nuevas o existentes, recibiendo a cambio y
conservando en su activo las acciones o participaciones correspondientes a dichos aportes.
4.5. Disolución y liquidación de sociedades
Disolución: La disolución es el inicio del proceso de extinción de la persona jurídica, la que
mantendrá su capacidad para los actos y contratos que sean necesarios celebrar a efectos de la
liquidación (Resolución N °8 i5 -2 0 19-SUNARP-TR-T).
Causales de disolución: La sociedad se disuelve por las siguientes causas:
1. Vencimiento del plazo de duración, que opera de pleno derecho, salvo si previamen
te se aprueba e inscribe la prórroga en el Registro.
2. Conclusión de su objeto, no realización de su objeto durante un período prolongado
o imposibilidad manifiesta de realizarlo.
3. Continuada inactividad de la junta general.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 69

-- 700 of 1506 --

UBILEX
4 - Pérdidas que reduzcan el patrimonio neto a cantidad inferior a la tercera parte del
capital pagado, salvo que sean resarcidas o que el capital pagado sea aumentado o
reducido en cuantía suficiente.
5. Acuerdo de la junta de acreedores, adoptado de conformidad con la ley de la mate
ria, o quiebra.
6 . Falta de pluralidad de socios, si en el térm ino de seis meses dicha pluralidad no es
reconstituida.
7. Resolución adoptada por la Corte Suprema a petición del poder ejecutivo.
8 . Acuerdo de la junta general, sin mediar causa legal o estatutaria.
9. Cualquier otra causa establecida en la ley o prevista en el pacto social, en el estatuto
o en convenio de los socios registrado ante la sociedad.
Convocatoria y acuerdo de disolución (Art. 409 LGS).- En los casos previstos utsupra, el
directorio, o cuando éste no exista cualquiersocio, administrador o gerente, convoca para
que en un plazo máximo de treinta días se realice una junta general, a fin de adoptar el
acuerdo de disolución o las medidas que correspondan.
Cualquier socio, director, o gerente puede requerir al directorio para que convoque a la
junta general si, a su juicio, existe alguna de las causales de disolución establecidas en la
ley.
Si la junta general no se reúne o si reunida no adopta el acuerdo de disolución o las medi
das que correspondan, cualquier socio, administrador, director o el gerente puede solici
tar al juez del domicilio social la disolución de la sociedad. Por otro lado, la junta general
se reserva el derecho de disolver la sociedad por solo acuerdo sin necesidad de mediar
explicación de por medio, siempre que se cumpla con el quorum y mayorías establecidas
legal o estatutariamente (Resolución N °4 2 0 -2 0 2 i-S U N A R P -T R -L ).
Publicidad e inscripción del acuerdo de disolución (Art. 412 LGS).-EI acuerdo de disolu
ción debe publicarse dentro de los diez días de adoptado, por tres veces consecutivas.
La solicitud de inscripción se presenta al Registro dentro de los diez días de efectuada la
últim a publicación, bastando para ello copia certificada notarial del acta que decide la
disolución. En consecuencia, será improcedente toda solicitud de inscripción que se rea
lice previa a la publicación del acuerdo de disolución (Resolución N °4 2 0 -2 0 2 i-S U N A R P -
TR-L).
Liquidación: El artículo 413 de la Ley dispone que, una vez disuelta la sociedad, se inicia el
proceso de liquidación. La sociedad disuelta conserva su personalidad jurídica mientras dura
el proceso de liquidación y hasta que se inscriba la extinción en el Registro. Durante la liquida
ción, la sociedad debe añadir a su razón social o denominación la expresión “en liquidación” en
todos sus documentos y correspondencia. Desde el acuerdo de disolución cesa la representa
ción de los directores, administradores, gerentes y representantes en general, asumiendo los
liquidadores las funciones que les corresponden conforme a ley, al estatuto, al pacto social, a
los convenios entre accionistas inscritos ante la sociedady a los acuerdos de la junta general.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 701 of 1506 --

Tema 4: Temas de la especialidad com ercial
Por consiguiente, durante la liquidación, la junta general no podrá nombrar apoderados para
realizar otros actos según lo señala la Resolución N °8i 5-2019-SUNARP-TR-T.
Sin embargo, si fueran requeridas para ello por los liquidadores, las referidas personas están
obligadas a proporcionar las informaciones y documentación que sean necesarias para facili
tar las operaciones de liquidación.
Durante la liquidación se aplican las disposiciones relativas a las juntas generales, pudiendo
los socios o accionistas adoptar los acuerdos que estimen convenientes.
Los liquidadores (Art.414 LGS).- La junta general, los socios o, en su caso el juez designa
a los liquidadores y, en su caso, a sus respectivos suplentes al declarar la disolución, salvo
que el estatuto, el pacto social o los convenios entre accionistas inscritos ante la sociedad
hubiesen hecho la designación oque la ley disponga otra cosa. El número de liquidadores
debe ser impar, por lo que podrá elegirse solo uno. En dicho supuesto, el Tribunal Registral
ha establecido que, ante su renunciay posterior inscripción de la misma, deberá también
inscribirse el nombramiento de su reemplazante de manera conjunta, siendo ineficaz
cualquier acto distinto (Resolución N° 2145-2019-SUNARP-TR-L).
Los socios que representen la décima parte del capital social tienen derecho a designar un
representante que vigile las operaciones de liquidación.
Insolvencia o quiebra de la sociedad en liquidación (Art. 417 LGS).- Si durante la liquida
ción se extingue el patrimonio de la sociedad y quedan acreedores pendientes de ser paga
dos, los liquidadores deben convocar a la junta general para informarla de la situación sin
perjuicio de solicitar la declaración judicial de quiebra, con arreglo a la ley de la materia, es
decir, la Ley General del Sistema Concursal. Sobre el tema, el Tribunal Registral ha reconoci
do el derecho de las empresas de aumentar o reducir el capital social con el objetivo de evi
tar la liquidación y eventual declaración de quiebra (Resolución N°5i6-20iy-SUNARP-TR).
La Ley no señala de manera expresa que la declaración judicial de quiebra suponga la
extinción de la sociedad. No obstante, el Tribunal Registral ha manifestado que, una vez
obtenida la declaración judicial de extinción del patrimonio, la inscripción de la misma
supone la extinción de la sociedad, en razón del cumplim iento de la finalidad de la di
solución, cual es la liquidación y extinción del patrimonio de la sociedad (Resolución N°
582-2013-SUNARP-TR-L).
Balance final de liquidación (Art. 419).- Los liquidadores deben presentar a la junta ge
neral la memoria de liquidación, la propuesta de distribución del patrimonio neto en
tre los socios, el balance final de liquidación, el estado de ganancias y pérdidas y demás
cuentas que correspondan, con la auditoria que hubiese decidido la junta general o con
laque disponga la ley.
Aprobado, expresa o tácitamente, el balance final de liquidación se publica por una sola
vez, y se procede a la distribución entre los socios del haber social remanente.
Distribución del haber social (Art. 420).- La distribución del haber social se practica con
arreglo a las normas establecidas por la ley, el estatuto, el pacto social y los convenios en
tre accionistas inscritos ante la sociedad. En defecto de éstas, la distribución se realiza en
proporción a la participación de cada socio en el capital social.
