Extinción de la sociedad: Se produce cuando se ha cumplido con distri bui r el habersocialy se
inscribe en registros. La solicitud se presenta mediante recurso firmado por el o los liquidado
res, indicando la forma cómo se ha dividido el haber social, la distribución del remanente y las
consignaciones efectuadas. Al inscribir la extinción se debe indicar el nombre y dom icilio de la
persona encargada de la custodia de los librosy documentos de la sociedad.
5. Empresa individual de responsabilidad lim itada
Es una persona jurídica de derecho privado, constituida por voluntad unipersonal, con patri
monio propio distinto al de su titular, que se constituye para el desarrollo exclusivo de activi
dades económicas de Pequeña Empresa, al amparo de los Decretos Leyes N° 21435, Ley de la
Pequeña Empresa de Propiedad Privada, y Decreto Ley N° 21621, Ley que norma la Empresa
Individual de Responsabilidad Limitada. El patrimonio de la Empresa está constituido inicial
mente por los bienes que aporta quien la constituye. El valor asignado a este patrimonio ini
cial constituye el capital de la Empresa. La responsabilidad de la Empresa está lim itada a su
patrimonio.
El titu lar de la empresa no responde personalmente por las obligaciones de ésta, salvo si la
empresa no estaba debidamente representada, hubiere efectuado retiros que no responden a
beneficios debidamente comprobados, o habiéndose producido la pérdida del 50% o más del
capital el titu lar no actuó de acuerdo a ley o no efectúe la reducción de capital correspondien
te. Solo las personas naturales pueden constituir o ser titulares de Empresas Individuales de
Responsabilidad Limitada. Cada persona natural podrá ser titu la r de una o más Empresas In
dividuales de Responsabilidad Limitada. La Empresa tendrá una denominación que permita
individualizarla, seguida de las palabras "Empresa Individual de Responsabilidad Limitada", o
las siglas “E.I.R.L.” Cualquiera que sea su objeto es de duración indeterm inaday tiene carácter
mercantil. En todo lo que no está previsto en la Escritura de Constitución de la Empresa o en
los actos que la modifiquen, se aplicarán las disposiciones que establece el Decreto Ley N°
21621 y sus modificatorias, no pudiendo estipularse contra estas normas. La Empresa debe
ser constituida en el Perú y tener su domicilio en territorio peruano quedando sometida a la
jurisdicción de los tribunales del Perú.
La Empresa se constituirá por escritura pública otorgada en forma personal por quien la cons
tituye y deberá ser inscrita en Registros. La inscripción es la form alidad que otorga personali
dad jurídica a la Empresa, considerándose el momento de la inscripción como el inicio de las
operaciones.
En la escritura pública de constitución de la Empresa se expresará:
a) El nombre, nacionalidad, estado civil, nombre del cónyuge si fuera casado, y dom icilio del
otorgante.
b) La voluntad del otorgante de constituir la Empresay de efectuar sus aportes.
c) La denominación y domicilio de la Empresa.
d) Que la empresa circunscriba sus actividades a aquellos negocios u operaciones lícitas
cuya descripción detallada constituye su objeto social. Se entiende que están incluidos
en el objeto social, todos los actos relacionados con éstey que coadyuven a la realización
