Tema 4: Temas de la especialidad comercial
de sus fines empresariales, aunque no estén expresamente indicados en el pacto social o
en su estatuto. La empresa no puede tener por objeto desarrollar actividades que la ley
atribuye con carácter exclusivo a otras entidades o personas.
e) El valor del patrimonio aportado, los bienes que lo constituyen y su valorización.
f) El capital de la Empresa.
g) El régimen de los órganos de la Empresa.
h) El nombramiento del primer gerente o gerentes.
i) Las otras condiciones lícitas que se establezcan. La constitución de la Empresa y los actos
que la modifiquen deben constaren escritura pública debiendo inscribirse en el Registro
Mercantil dentro del plazo de treinta días de la fecha de otorgamiento de la respectiva
escritura.
6. Teoría general de los títu lo s valores
6.1. Desarrollo de la teoría general
La historia del derecho cambiario tiene como inicio Italia medieval cuya concepción prim i
genia de la naturaleza de obligación cambiaría fue la consensual, o sea como un contrato de
cambio trayecticio; el título tenía función probatoria de contrato literal de cambio trayecticio,
era sólo un medio para dar ejecución. Con el criterio predominante de esta concepción, es el
alemán Savigny quien aportó la idea de la “incorporación al documento”. A partir de este apor
te aparecieron diversas escuelas, entre las que se encuentran las siguientes:
Escuela Comercialista Alemana: Entre los principales exponentes tenemos: Liebe (1848)
introduce los principios de formalidad, literalidad y abstracción; Einet concibió a la incorpo
ración al título como acto unilateral, demoliendo teorías contractuales, buscando dotar de
confianza en la promesa, consagrando el Derecho Autónomo; Kuntze (1857) consideró que la
obligación cambiaría nace desde el momento que la "cambial” es redactada pues tiene como
fuente de declaración unilateral de voluntad. Finalmente Bruner (1840-1915) form ula la pri
mera definición de Título Valor: “Es el documento de Derecho Privado, cuya realización está subor
dinada a la posesión del Documento”.
Escuela Comercialista Italiana: Vivante (1855-1944) define al títu lo de crédito como docu
mento necesario para ejercitar el derecho literal y autónomo expresado en el mismo; consi
dera que es Literalidad porque la existencia se fija de acuerdo al tenor del documento, Au
tónomo, porque el poseedor de buena fe ejercita un derecho propio separado de relaciones
existentes con anteriores poseedores, finalmente, entiende que es necesario porque para
ejercer cualquier derecho debe exhibir el documento (Legitimación). El Mérito fundam en
tal de Vivante es haber incluido a los títulos nominativos entre la categoría de los títulos de
crédito.
Bolaffio (1948-1940) Cuestiona la Teoría Unificadora de Vivante, ya que considera que los tí
tulos nominativos no tienen la circulación libre, regulary perfecta, el emitente puede impedir
la transmisión y la Transferencia es una cesión de créditos y necesita anotarse la transferencia
en los registros del emitente.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 704 of 1506 --

UBILEX
Mossa (1886-1957) revela el carácter constitutivo del título valory que el valor no existe sin el
documento. Messineo (1885-1974) reafirmó el carácter constitutivo del título de crédito expre
sando que es un documento social mente destinado a la circulación. Decemo (1885) señala que
la característica primaria de estos títulos es la documentabilidad, Asquini (1889-1972) agrega
el destino circulatorio del título de crédito; Ascarelli (1903-1959) individualiza el presupuesto
del título de crédito expresando que es un documento socialmente destinado a la circulación;
finalmente Ferri (1908) considera que el título valor tiene como carácter tipológico la destina
ción a circular pero subordinado a la voluntad; aunque las críticas a Ferri no se dejaron esperar
pues los títulos valores pueden entrar en circulación sin la voluntad de su creador y existe la
inoponíbilidad a los terceros poseedores de buena fe.
Antecedentes Legislativos: El Código de Comercio de 1902 diferenció a los efectos de Comer
cio (letras, cheque, pagaré); los valores mobiliarios (acciones, bonos) y los títulos de tradición
(Conocimiento de Embarque, Certificado de Depósito, Warrant); la ley 16587 introdujo el sis
tema unitario, estableciendo reglas generales aplicables a todos los títulos valores, pero cir
cunscribiendo inicialmente solo a la letra, cheque, vale y pagaré. Finalmente, la ley 27287 no
solo establece reglas generales aplicables a todos los títulos valores, sino que regula toda la
gama de títulos valores que circulaban en ese momento en el país, como la letra de cambio, el
cheque, el pagaré, los Valores Mobiliarios (acciones, bonos) y los títulos de tradición (Conoci
miento de Embarque, Certificado de Depósito, Warrant).
Denominación: Se dice que el término “Títulos Valores” abarca a los títulos representativos
de mercaderías, títulos representativos de participación y títulos representativos de crédito.
Ahora bien, con la aparición de los valores desmaterializados, se ha reformulado su denomi
nación, siendo denominado por algunos autores como “Valores Negociables”, cuyas especies
serían los valores materializados o títulos valoresy los valores desmaterializados o valores re
presentados en cuenta.
Son una serie de documentos que siendo distintos por su contenido y por su forma, habiendo
nacido en diversas épocas, y estando dotados de caracteres diferentes, ofrecen, sin embargo,
la nota común de incorporar una promesa unilateral de realizar determinada prestación a fa
vor de quien resulte legítimo tenedor del documento. Los títulos también cumplen principal
mente la función, también común, de servirá la mejor circulación de los bienes, constituyen
do por ello un instrumento del tráfico mercantil que corre pareja importancia con el contrato.1
Los valores materializados que representen o incorporen derechos patrimoniales, tendrán la
calidad y los efectos de Título Valor, cuando estén destinados a la circulación, siempre que
reúnan los requisitos formales esenciales que, por imperio de la ley, les corresponda según su
naturaleza. Las cláusulas que restrinjan o limiten su circulación o el hecho de no haber circu
lado no afectan su calidad de título valor.
Si le faltare alguno de los requisitos esenciales que le corresponda, el documento no tendrá
carácter de título valor, quedando a salvo los efectos del acto jurídico a los que hubiere dado
origen su emisión o transferencia. Por consiguiente, ante cualquier controversia que pueda
suscitarse, los órganos jurisdiccionales deberán examinar detenidamente las letras de cam-
1 URÍA, op. cit., p. 833.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 705 of 1506 --

Tema 4: Temas de la especialidad com ercial
bio, con el objetivo de determinar si éstas cumplen o no con las formalidades que la ley exige
desde su emisión (C o n s id e ra n d o s 0, Cas. N ° 5 2 8 9 -2 0 1 9 L im a).
El valor patrimonial de los títulos valores expresado en una suma de dinero, constituye requi
sito esencial, por lo que debe señalarse la respectiva unidad o signo monetario.
En caso de diferencia del importe del título valor, expresado sea en letras o en números o me
diante codificación, prevalecerá la suma menor; sin perjuicio que el interesado pueda hacerse
valer sus mayores derechos frente al obligado, por la vía causal.
En caso de diferencia en la referencia de la unidad monetaria, se entenderá que su impor
te corresponde a la moneda nacional, si uno de los importes estuviere expresado en dicha
moneda. En caso contrario, el documento no surtirá efectos cambiarios. Los importes que no
consignen la unidad monetaria, se entenderán que corresponden a la moneda nacional.
En los títulos valores, además de la firm a autógrafa, pueden usarse medios gráficos, mecáni
cos o electrónicos de seguridad, para su emisión, aceptación o transferencia.
Toda persona que firm e un título valor deberá consignar su nombre y documento oficial de
identidad. Tratándose de personas jurídicas, además se consignará el nombre y documento
oficial de identidad de sus representantes que intervienen en el título. Siguiendo la línea de lo
establecido en el numeral 2 del artículo 1 de la ley, de comprobarse que los títulos valores no
han sido firmados por la persona que dice ser la giradora, esto es, de tratarse de firmas falsifi
cadas, estos no podrán ser calificados como títulos valores, debido a que nos encontraríamos
frente a un supuesto de documentos adulterados (Considerando y°, Cas. N° 5289-2019 Lima).
Los que emitan, giren, acepten, endosen o garanticen títulos valores, quedan obligados so
lidariamente frente al tenedor, salvo cláusula o disposición legal expresa en contrario. Éste
puede accionar contra dichos obligados, individual o conjuntamente, sin tener que observar
el orden en el que hubieren intervenido.
Los títulos valores confieren a su legítimo tenedor, el derecho exclusivo a disponer o, de ser el
caso, gravar o afectar los bienes que en ellos se mencionan; sin perjuicio de las excepciones
que señale la ley.
Concepto: El artículo 1 de la Ley N° 27287, alude a "valores materializados que representen o
incorporen derechos patrimoniales” evidenciando el abandono a la concepción típicamente
cartular,ya que pueden también existir títulos valores “desmaterializados”2.
Valores materializados: La definición clásica lo hizo Vivante expresando que el título de cré
dito es un documento necesario para ejercitar el derecho literal y autónomo expresado en el mismo3.
Broseta Pont dice que en la doctrina inglesa se destaca que el título valor (negotiable instru-
ment) contiene “una promesa de pago, exigióle por cualquier poseedor de buena fe, al que
no podrán oponerse excepciones personales derivadas del anterior poseedor”. En la doctrina
española el profesor Carrigues lo define diciendo que “título valores un documento sobre un
2 BEAUMONT CALLIRCOS, Ricardo y CASTELLARES ACU I LAR, Rolando. Obra citada, p. 43-
3 VIVANTE, César. Tratado de Derecho Mercantil. Volumen III, Editorial Reus. Madridi936. pp. 136-137.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 706 of 1506 --

UBILEX
derecho privado, cuyo ejercicio y cuya transmisión están condicionados a la posesión del do
cumento4.
Para la Ley de Títulos Valores los valores materializados (títulos valores en sentido estricto)
son documentos de carácter formal que representan o contienen (incorporen) derechos patri
moniales y q ue están destinados a la circulación.
Características del título valor:
Derechos Patrimoniales Incorporados.- Partiendo que el título valor es un documento que
incorpora derechos patrimoniales, se debe mencionar que tipo de derechos son materia de
esta incorporación, estos pueden ser: Derechos de Créditos (letra, cheque, pagaré, bonos);
Derechos de participación (acciones, certificados de participación de Fondos Mutuos), o Dere
chos Reales sobre mercancía (Conocimiento de Embarque, Warrant).
Destino Circulatorio.- La esenciadel título valores que pueda circular, mas no en realidad que
circule. La virtualidad de la circulación nace de la promesa unilateral que hace el librador del
documento de que la obligación contenida será pagada a quien al final de circulación resulta
titu lar del crédito.
Documento Formal.- El título valor debe contener los requisitos de forma presente por la ley
de lo contrario destruye su eficacia.
Resulta importante resaltar que los títulos valores incompletos (que suponen la ausencia de
los requisitos formales esenciales que debe contener todo título para ser considerado como
tal), impiden el ejercicio de la acción cambiaría: cuando circula puede hacerlo incompleto, es
decir, bastará con la firm a del suscriptor, pero debe estar completo al momento de presentarlo
para el pago. Por ende, este tipo de títulos dejan en forma deliberada, total o parcialmente,
espacios en blanco para ser llenados por el tenedor legítimo, de acuerdo con las instrucciones
dadas a este últim o (Sentencia N° 04087-2011-PA/TC).
Responsabilidad solidaria: Los que emitan, giren, acepten, endosen o garanticen títulos va
lores, quedan obligados solidariamente frente al tenedor, salvo cláusula o disposición legal
expresa en contrario. Este puede accionar contra dichos obligados, individual o conjuntamen
te, sin tener que observar el orden en el que hubieren intervenido. El mismo derecho corres
ponde a todo obligado de un título valor que lo haya pagado, contra los obligados anteriores a
él. El tenedor puede ejercitar acumulativamente las acciones directas y de regreso; y, de darse
el caso, la de ulterior regreso.
6.2. Circulación de los títulos valores
Los títulos valores al portador:
Concepto de título al portador (Art. 22o LTV).- Título valor al portador es aquél que con au
torización de la ley, se expide a favor de persona indeterminada, pero determinable, tiene la
cláusula "al portador” y que se negocia con la mera entrega del mismo, por ello, a su legítimo
poseedor le otorga la calidad de titu lar de los derechos que representa.
4 BROSETA PONT, Manuel. Manual de Derecho Mercantil. Editorial Tecnos. Madrid 1983. p. 542.
6 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 707 of 1506 --

Tema 4: Temas de la especialidad comercial
Forma de trasmisión (Art. 22o LTV).- Para su transmisión no se requiere de más formalidad
que susimple tradición o entrega. La tradición material representa su ley de circulación. Sigue
las mismas normas que las cosas muebles. Toda adquisición de la posesión del título legitima
para el ejercicio del derecho. La tradición confiere la investidura para ese ejercicio (Carrigues).
La indicación del nombre de persona determinada en un título valor al portador no altera la
naturaleza de éste; ni genera obligaciones para aquélla, salvo que se trate de una intervención
para asumir alguna obligación.
Los títulos valores a la orden:
Concepto (Art. 26o LTV).-Se considera como título valor a la orden al que designa como titu la r
a una persona determinada o a otra, que aquella o los sucesivos poseedores legítimos del do
cumento designen. El título a la orden es nominativo, pero por medio de una cláusula de en
doso que ha de estamparse en el mismo título puede ser sustituida por la persona designada
en él, sin necesidad de notificarlo al deudor, emitente o aceptante del título (Sánchez Calero).
La ley, definiendo al Título valor a la orden, dice que es el emitido con la cláusula “a la orden”,
con indicación del nombre de persona determinada, quien es su legítimo titular. La cláusula“a
la orden” puede ser om itida en los casos de títulos valores que sólo se emitan de este modo y
en los casos expresamente autorizados por la ley.
Forma de transmisión (Art. 26o LTV).- En estos títulos la transmisión de su propiedad y de la
titularidad del derecho incorporado, se obtiene mediante un doble requisito. Primero, la cláu
sula de endoso, que es la declaración escrita por el tenedor en el dorso del título y que contiene
su voluntad de trasmitirlo. Segundo, la tradición o entrega del documento a la persona en
cuyo favor se ha redactado la cláusula (Broseta Pont). La ley dice que se transmite por endoso
y consiguiente entrega del título, salvo pacto de truncamiento.
Los títulos valores nominativos:
Concepto (Art. 29o LTV).- El título valor nominativo es aquél emitido en favor o a nombre de
persona determinada, quien es su titular. Sánchez Calero dice que es aquel que designa como
titu la ra una persona determinada y que no puede transm itirlo sin que se notifique al deudor,
siendo necesario, en algunos casos, que este colabore en cierta manera (como el emisor de las
acciones cuando registra la transferencia en la matrícula respectiva)
Transferencia del título nominativo (Art. 29o LTV).- Este ti po de título se transmite por cesión
de derechos. Para que la transferencia del título valor nominativo surta efecto frente a terceros
y frente al emisor, la cesión deberá ser comunicada al emisor para su anotación en la respecti
va matrícula, sin perjuicio de las limitaciones o condiciones para su transferencia que consten
en el texto del título. Estos títulos carecen de la cláusula "a la orden” y si se consigna no lo
convierte en título valor endosable. En caso de tratarse de valor con representación por anota
ción en cuenta, la cesión debe ser inscrita en la Institución de Compensación y Liquidación de
Valores correspondiente; sin perjuicio de las limitaciones o condiciones para su transferencia
que consten en el registro respectivo.
Constancia de la transmisión (Art. 30oLTV).- La cesión de los títulos valores nominativos pue
de constar en el mismo documento o en documento aparte, salvo disposición contractual o
legal distinta o condición especial que conste en el texto del mismo título. La cesión del título
