valor puede constar como cláusula si mi lar al endosoen el mismo documento o puedeconstar
en documento aparte y deberá indicarse la siguiente información: nombre del cesionario (re
quisito esencial, por lo que su omisión conlleva la ineficacia de la cesión); naturaleza y, en su
caso, las condiciones de la transferencia (a falta de indicación se presumirá que el cesionario
adquiere la propiedad plena del título); fecha de la cesión (a falta de indicación se presumirá
que la cesión se efectuó en la fecha de comunicación de ella al emisor) y nombre, número del
documento oficial de identidady firm a del cedente (requisito esencial, por lo que su omisión
conlleva la ineficacia de la cesión. En este caso, el emisor u obligado principal tiene la facultad
de requerir la entrega del título transferido, así como exigir la certificación de la autenticidad
de la firm a del cedente, hechayasea por intermediario autorizado o por fedatario de ley.
Registro y anotación de la transferencia del título nominativo (Art. 31o LTV).- El emisor
deberá anotar la transferencia en la respectiva matrícula, en mérito al documento en el que
conste la transferencia (en el mismo título o en documento aparte), con la firm a del cedente
y demás informaciones y formalidades señaladas en la ley. La Institución de Compensación y
Liquidación de Valores deberá anotar la transferencia en el registro, en mérito al documento
en el que conste la transferencia, con la firm a del cedente e informaciones y formalidades es
tablecidas la ley.
Endoso de los títulos valores a la orden:
Concepto (Art. 34° LTV).-el endoso es la forma típica de transmisión de los títulos valores a la
orden y debe constaren el reverso del título respectivo o en hoja adherida a él.
Requisitos (Art.34° LTV).- El endoso debe reunir los siguientes requisitos:
a) Nombre de! endosatario. Si se omite este requisito se entenderá que se trata de un endoso
en blanco.
b) Clase del endoso. Si se omite este requisito se presumirá que el título valor ha sido transmi
tido en propiedad, sin que valga prueba en contrario respecto a tercero de buena fe.
c) Fecha del endoso.■La omisión de la fecha del endoso hace presumir que ha sido efectuado
con posterioridad a la fecha que tuviera el endoso anterior.
d) Nombre, el número del documento oficial de identidady firm a del endosante. El nombre, el núme
ro del documento oficial de identidady la firm a del endosante son requisitos esenciales
del endoso, por lo que su inobservancia conlleva la ineficacia del endoso. El error en la
consignación del número del documento oficial de identidad no afectará la validez del
endoso.
Carácter incondicional del Endoso (Art. 35° LTV).-El endoso no puede sujetarse a modalidad
alguna, debe ser puroy simple. Todo plazo, condición y modo se consideran no puestos, salvo
el plazo para su presentación a la aceptación de la letra de cambio. El endoso parcial se tiene
por no hechoy no surte efectos jurídicos. El documento constituye una unidad indivisible. Los
derechos emergentes del título valor son inseparables de éste como documento.
Endoso al portador y Endoso en blanco (Art. 36o LTV).- El endoso al portador produce los
efectos del endoso en blanco. En ambos casos el tenedor, para ejercer los derechos cambia-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 709 of 1506 --

Tema 4: Temas de la especialidad comercial
ríos, deberá llenarlo con su nombre, consignando el número de su documento oficial de iden
tidad o con el de un tercero, o trasm itir el título valor por tradición sin llenar el endoso.
Clases de endoso (Art. 37o LTV).- El endoso puede hacerse en propiedad, en fideicomiso, en
procuración o en garantía.
a) Endoso en propiedad (Arts. 38o y 39° LTV).- En virtud del endoso en propiedad el en
dosante pierde la propiedad del título, que es adquirido por el endosatario, pero con la
calidad de crédito originario, ligado a la posesión de la cosa, o sea al título (Montoya Man-
fredi). El endoso en propiedad transfiere la propiedad del título valory todos los derechos
inherentes a él, en forma absoluta. El endoso en propiedad obliga, a quien lo hace, solida
riamente con los obligados anteriores.
b) Endoso en fideicomiso (Art. 40o LTV).- El fideicomiso es un contrato en virtud del cual
se transfieren uno o más bienes a una persona (fiduciario), con el encargo de que los ad
ministre o enajene y que con el producto de su actividad cumpla una finalidad estable
cida por el constituyente (fideicomitente), a favor o en beneficio de éste o de un tercero
(fideicomisario) (Beaumont-Castellares). El endoso en fideicomiso transfiere el dom inio
fiduciario del título valor en favor del fiduciario, a quien corresponde ejercitar todos los
derechos derivados de éste que correspondían al fideicomitente endosante. El obligado
no puede oponer al endosatario en fideicomiso los medios de defensa fundados en sus
relaciones personales con el fideicomitente, a menos que el fiduciario, al recibir el título,
hubiera actuado intencionalmente en daño del obligado. La responsabilidad (solidaria)
del fiduciario endosante que no haya incluido la cláusula “sin responsabilidad” u otra
equivalente, es similar al del endosante en propiedad, con el límite del patrimonio fid ei
cometido que mantenga en fideicomiso.
c) Endoso en procuración o cobranza (Art. 41o LTV).- El endoso que contenga la cláusula
“en procuración”, “en cobranza”, "en canje” u otra equivalente, no transfiere la propiedad del
título valor; pero faculta al endosatario para actuar en nombre de su endosante, estando
autorizado a presentar el título valor a su aceptación, solicitar su reconocimiento, cobrar
lo judicial o extrajudicialmente, endosarlo sólo en procuración y protestarlo u obtener la
constancia de su incumplimiento, de ser el caso. Es el representante del verdadero titular.
d) Endoso en garantía (Art. 42o LTV).- Si el endoso contiene la cláusula "en garantía” u otra
equivalente, el endosatario puede ejercitar todos los derechos inherentes al título valor
y a su calidad de acreedor garantizado; pero el endoso que a su vez hiciere éste sólo vale
como endoso en procuración, aun cuando no se señalara tal condición.
La cláusula no a la orden o no negociable (Art. 43° LTV).- El emisor o cualquier tenedor
puede insertaren el título valora laorden, la cláusula“no negociable”, “intransferible”, “no
a la orden” u otra equivalente, liberándose de la responsabilidad solidaria frente a sucesi
vos tenedores, surtirá efectos desde la fecha de su anotación en el título. El título valor que
contenga la cláusula “no negociable”, “intransferible”, “no a la orden” u otra equivalente,
sólo es transmisible en laform a ycon los efectos de la cesión de derechos.
BALOTAR 10 DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 710 of 1506 --

UBILEX
El Endoso P o s tu m o o E ndoso p o s te rio r a l v e n c im ie n to (Art. 4 4 ° LTV).- Es el endoso pos
terior al vencí miento y antes de su protesto o formalidad sustitutoria. Esta clase de endo
so produce los mismos efectos que un endoso anterior al vencimiento. El endoso hecho
después del protesto o formalidad sustitutoria, o del plazo para hacerlo, produce efectos
de la cesión de derechos, sin perjudicar la acción cambiaría del título valor, si éste reúne
los requisitos para ello.
Continuidad de Endosos o Legitimidad en la tenencia (Art. 4 5 ° LTV).- El poseedor de un títu
lo valortransmisible por endoso es considerado como tenedor legítimo si justifica su derecho
por una serie Ininterrumpida de endosos, o sea, una cadena no interrumpida de endosos. La
cadena ininterrumpida de endosos es aquella que a partir del primer endosante los endosos
se continúan, de manera que cada endosatario sea endosante hasta el últim o endosatario.
Id e n tific a c ió n del último endosatario (Art. 46o LTV).- El que paga el título valor a su ven
cimiento no está obligado a cerciorarse de la autenticidad de las firmas de los endosantes
anteriores a la persona con quien se entiende el pago ni, en su caso, de la suficiencia de las
facultades y poderes con las que intervienen; pero debe verificar el nombre, documento oficial
de ¡dentidady firma de quien le presenta el título como últim o tenedor, así como la continui
dad ininterrumpida de los endosos.
Endoso de título valor que representa g a r a n tía real (Art. 47° LTV).- El endoso de título valor
que represente derechos reales de garantía (Factura Conformada y Título de Crédito Hipote
cario Negociable) transfiere al endosatario dichos derechos realesy los demás derechos repre
sentados por el documento.
6.3. Cláusulas especiales de los títulos valores
Aspectos Generales (Art. 48o LTV).- En los títulos valores, sean al portador, a la orden o nomi
nativos, podrán incluirse las cláusulas especiales sin más impedimento que los expresamente
prohibidos por ley. Estas cláusulas pueden dividirse:
a) Previstas y permitidas.-Cláusulas a la orden, intereses compensatorios, de prórroga, de
pago en moneda extranjera, intereses moratoriosy reajustes, de liberación de protestos,
de pago en cuenta bancaria, de venta extrajudicial, de sometimiento a leyes y tribunales,
etcétera.
b) Previstas y no permitidas.- Las que anulan la letra de cambio como tal, cláusula al por
tador, condicionamiento de la promesa de pago, promesa de pago en especie, pago en
especie.
c) No previstas y permitidas.- Que el importe de lacambial conste en letras y en números.
d) No previstas y no permitidas.- El aval sometido a condición o el aval constara en docu
mento separado.
Principio de literalidad.- Las cláusulas especiales deberán constar expresamente en cual
quier lugar del documento o en hoja adherida a él, para surtir efecto frente a los obligados
respectivos.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 711 of 1506 --

Tema 4: Temas de la especialidad comercial
Formalidades.- Las cláusulas especiales que se incorporen en un título valor, para tener vali
dez, deben estar impresas en el documento o refrendadas (autorizadas) especialmente con
firm a del obligado que las emite, en el caso de haber sido incorporadas en forma manuscrita,
con sellos o cualquier otro medio distinto. El tenedor no requiere firmarlas.
Valores con representación por anotación en cuenta.- En el caso de los valores con repre
sentación por anotación en cuenta, los pactos y cláusulas especiales deberán constar en el
registro respectivo.
Prórroga sin intervención del obligado (Art. 49° LTV).- La ley utiliza el término prorroga y no
el de renovación. Prórroga es el aplazamiento del acto o hecho, para un tiempo ulterior o como
el alargamiento de un plazo. La prórroga, a diferencia de la renovación, no implica la form a
ción de una nueva relación jurídica patrimonial entre las partes, sino más bien la extensión de
la vigencia de las obligaciones adquiridas en virtud de aquella. La renovación es el arreglo o
cambio que deja algo nuevo. Es también sinónimo de sustitución, reemplazo o restitución de
algo. La renovación permite el nacimiento de una nueva relación entre las partes, pues la pri
mera u originaria se extingue, siendo sustituido por otra vinculación de la misma naturaleza.
La ley dice que el plazo de vencimiento de los títulos valores puede prorrogarse en la fecha de
su vencimiento o aun después de él, siempre que el obligado que adm itió tal prórroga haya
otorgado su consentimiento expreso en el mismo título valor; asimismo, que no se haya ex
tinguido el plazo de prescripción para ejercitar la acción derivada del título valor (acción cam
biaría) a la fecha en que se realice la prórroga, y, el título valor no haya sido protestado o no se
haya obtenido la form alidad sustitutoria, de ser el caso. Las prórrogas surtirán plenos efectos
por el solo mérito de la consignación del nuevo plazo de vencimiento que deje el tenedor en
el mismo título, firm ando dicha prórroga o prórrogas que conceda. El cómputo del plazo de
prescripción de la acción cambiaría se reinicia a partir de la fecha de vencimiento de cada una
de las prórrogas.
Cláusula de Pago en Moneda Extranjera (Art. 50o LTV).- La moneda en que debe ser pagada
un título valor es en moneda nacional. Pero es posible que el título valor contenga la obliga
ción de pagar en moneda extranjera. En aplicación a ello, el título valor puede ser pagado a
elección del deudor, en moneda nacional según su valor el día de vencimiento, en lugar de
pagarse en moneda extranjera, siempre que el deudor no esté en mora. Si se ha pactado de
modo expreso, los títulos valores expresados en moneda extranjera serán pagados en la mis
ma moneda.
Cláusula de intereses compensatorios y moratorios y reajustes (Art. 51o LTV).- Cualquiera
que sea la naturaleza del título valor que contenga una obligación de pago dinerario, podrá
acordarse las tasas de interés compensatorio y m oratorioy/o reajustes y comisiones perm iti
das por la ley, que regirán durante el período de mora. En su defecto, durante dicho período de
mora será aplicable el interés legal. El Interés es la ganancia del capital. El interés convencional
compensatorio proporciona al acreedor un lucro, un beneficio o ganancia y una compensa
ción por el uso del capital. El interés moratorio, en cambio, repara los daños y perjuicios por el
retraso culpable o doloso en el pago pudiese causar. Los intereses moratorios son, entonces,
aquellos que cumplen la función económica de reparar el retardo en la ejecución de una obli
gación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 711

-- 712 of 1506 --

UBILEX
jjj Cláusula de Liberación del Protesto (Art. 52o LTV).» En los títulos valores sujetos a protesto
podrá incluirse la cláusula “sin protesto” u otra equivalente en el acto de su emisión o acep
tación, lo que libera al tenedor de dicha formalidad para ejercitar las acciones derivadas del
título valor. En estos casos la acción cambiaría se ejercitará por el solo mérito de haber vencido
el plazo señalado en el título valor. No rige para el protesto por falta de aceptación en la letra
de cambio. El librador, el endosante o el avalista pueden, por medio de la cláusula “sin pro
testo” dispensar al portador de formalizar el protesto por falta de pago para ejercer la acción
de regreso. Cuando la cláusula integre el texto impreso de la letra de cambio, será suficiente
la firma de ésta por el librador; cuando se inserte manuscrita o por otro medio, se requerirá
que la cláusula sea especialmente firmada, sin perjuicio de la firm a de creación de la letra de
cambio (Gómez Leo).
Cláusula de Pago con Cargo en Cuenta Bancaria (Art. 53° LTV).- En los títulos valores que
contengan obligaciones de pago dinerario, podrá acordarse que dicho pago se cumplirá me
diante cargo en cuenta (corriente, de ahorro, a plazo) mantenida en una empresa del Sistema
Financiero Nacional, señalando el nombre de la empresay, en su caso, el número o código de
la cuenta. Si se trata de letra de cambio, en lugar de domicilio del girado se debe anotar el nú
mero de la cuenta bancariay el nombre del banco; asimismo, si este título es rechazado por no
tener la cuenta corriente provisión de fondos, dicho rechazo produce los efectos del protesto,
porque viene a ser la formalidad que lo sustituye. La empresa del Sistema Financiero Nacional
designada deberá contar con autorización previa del titular de la cuenta para atender el pago,
sea con fondos constituidos previamente o con créditos que conceda al titu lar de la cuenta
designada.
Cláusula de Venta Extrajudicial (Art. 54° LTV).- En los títulos valores afectados en garantía,
salvo disposición distinta de la ley, puede acordarse prescindir de su ejecución judicial y que
su venta se realice en forma directa o extrajudicial, conforme a los acuerdos adoptados al efec
to, según las disposiciones aplicables a la ejecución extrajudicial de la garantía prendaria. El
artículo 1069 del Código Civil precisa que sí vence el plazo de la obligación y ésta no se cumple,
el acreedor puede proceder a la venta del bien en la forma pactada al constituirse la obliga
ción. A falta de pacto, se tram ita como proceso de Ejecución de Garantía.
Cláusula de Sometimiento a Leyes y Tribunales (Art. 55°).- Para el ejercicio de las acciones
derivadas del título valor podrá estipularse el sometimiento a la competencia (voluntaria) de
determinado distrito judicial del país, así como a la jurisdicción arbitral; o a leyes y/o tribuna
les de otro país, si es que existe un elemento extranjero en la relación jurídica cambiaría.
6.4. Garantías de los títulos valores
Formas de Garantizar Títulos Valores (Art. 56o LTV): Las Garantías son los medios de reforzar
el derecho del acreedor en la hipótesis que el deudor no cumpla con la prestación debida;
tienen por objeto conceder seguridad al acreedor de que su crédito será cancelado o pagado.
Utilizando la clasificación tradicional, estas son las siguientes:
Garantías Personales, que son aquellos medios jurídicos por los cuales una persona (con su
patrimonio) se obliga a pagar la obligación que representa un título valor de su garantizado en
caso de incumplimiento de la misma (Fianzay el Aval); y Garantías Reales, que son aquellos
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 713 of 1506 --

Tema 4: Temas de la especialidad comercial
instrumentos jurídicos por los cuales se asegura una obligación que representa un título valor
afectando un bien determinado a su cumplimiento. Los requisitos de validez de las garantías
de obligaciones cambiarías son las siguientes:
a) Para que las garantías surtan efecto en favor de cualquier tenedor, debe dejarse constan
cia de ello en el mismo título. (Principio de Incorporación)
b) Se debe señalar a la persona garantizada, en caso de no hacerlo se presume que la garan
tía opera en respaldo del obligado principal (Principio de Literalidad).
c) Se debe colocar la mención expresa del monto o límite de la garantía, a falta de tal men
ción se entiende que garantiza todas las obligaciones y el importe total que representa el
título valor (Principio de Literalidad).
6.5. Garantías personales
El Aval: Concepto y naturaleza jurídica (Art.S7° LTV).- El Aval es una declaración cambiaría car-
tular por el que importa la constitución de una garantía objetiva, autónoma, típica y abstracta.
Primero, es objetiva porque con ella se pretende asegurar el pago de la obligación cambiaría,
vinculando a una persona para brindar confianza a los adquirentes en la circulación del título.
Asegura el pago frente a cualquier tenedor, incluso si resulta nula la obligación de la persona
avalada. Segundo, es autónoma porque la obligación del avalista es principal, pues el tenedor de
un título avalado puede dirigirse indistintamente contra cualquiera de los signatarios. Tercero,
es típica porque solo se puede concebir el aval en relación a los títulos valores, sea que se trate
de títulos de contenido crediticio, de tradición o representativos de mercaderías. Por último, es
abstracta porque se independiza de la causa que le dio origen o sea la relación jurídica subyacen
te, básica o fundamental. Con excepción del obligado principal, el aval puede ser otorgado por
cualquiera de los que intervienen en el título valoro por un tercero.
La Fianza (Art. 6i ° LTV).- Es una garantía personal accesoria, en virtud de la cual una o más
personas responden de una obligación ajena, comprometiéndose para con el acreedor a cum
plir en todo o en parte, si el deudor principal no cumple. La fianza que conste en el mismo
título valor o en el respectivo registro tiene carácter de solidaria y el fiador no goza del bene
ficio de excusión, aun cuando no se haya dejado constancia de ello en el título, Salvo que en
modo expreso se haya señalado lo contrario. El fiador queda sujeto a la acción cambiaría, del
mismo modo, durante el mismo plazo y en los mismos términos que contra su afianzado. La
responsabilidad no es objetiva ni autónoma, es subjetiva y accesoria, es por ello que la nulidad
de la obligación afianzada afecta la fianza haciéndola nulaoanulable. El fiador puede oponer
al tenedor del título valor los medios de defensa personales de su afianzado. Su obligación es
dependiente por ser accesoria.
Garantías reales (Art. 63o LTV).- Además de las formalidades y requisitos que establezca, por
ejemplo el Código Civil, para la constitución de garantías reales que respalden títulos valores,
como en el caso de la hipoteca, debe consignarse en la Escritura Pública el número y valor de los
títulos valores que se emitan y garanticen con la hipoteca; la serie o series que correspondan, la
fecha o fechas de emisión, en el plazoy forma en que deben amortizarloy designación del fid u
ciario. Dichas garantías (que aseguren el cumplimiento de las obligaciones frente a cualquier
