UBILEX
tenedor) deben señalarse en el mismo título (Principio de literalidad). En ese caso, las transferen
cias del título no requieren del asentimiento del obligado ni, de ser el caso, del constituyente de
la garantía, para que ésta tenga plena eficacia frente a cualquier tenedor del título valor.
El proceso judicial de ejecución de garantía permite afectar el bien determinado al cumpli
miento de la obligación. Al respecto, el artículo iz o del Código Procesal Civil establece que,
además de cumplir las formalidades que la ley prescribe, la obligación garantizada debe estar
contenida en el mismo documento o en cualquier otro título ejecutivo. En tal sentido, si el
documento que contiene la garantía no contiene la obligación referida, el ejecutante deberá
presentar otro título con mérito ejecutivo que contenga la obligación, el cual deberá estar in
tegrado porel documento que contiene la hipoteca, la liquidación del estado de saldo deudor
y porel título valor debidamente protestado. Cabe recalcar que existirán supuestos donde no
será necesario realizar el protesto, por lo que, en su defecto, deberá presentarse la constancia
que exima al ejecutante de dicha formalidad (Considerando 14oCas. N °3056-2017 Lima).
6.6. Del pago y protesto de los títulos valores
a. El pago
Aspectos Generales.- El pago es la realización de la prestación que le proporciona al acreedor
el objeto debido para la satisfacción de su interés, al tiempo que extingue el vínculo y libera
al deudor.
Fecha de pago (Art. 64o LTV).- Las prestaciones contenidas en un título valor deben ser cum
plidas el día señalado para ese efecto. El tenedor no puede ser compelido a recibir en fecha
anterior. Quien cumple la prestación que le corresponde antes de la fecha establecida en el
título, lo hace por su cuenta y riesgo, y responde por la validez del pago. Se coloca en el su
puesto de que se presente situaciones anormales o peligrosas como quiebras fraudulentas, o
sea, puede ser calificada como sospechosa. Quien paga a su vencimiento o en la fecha prevista
para ese efecto, queda liberado válidamente, a menos que haya procedido con dolo o culpa
inexcusable. El obligado contra el cual se ejercite o pueda ejercitarse las acciones derivadas
del título valor está facultado para exigir, contra el pago que realice, la entrega del título valor
cancelado; y, de ser el caso, la constancia del protesto o de la formalidad sustitutoria, más la
cuenta de gastos cancelada.
Pago parcial (Art. 65o LTV).- El tenedor no puede rehusar un pago parcial. Las obligaciones
cambiarías son de ejecución rigurosay es interés del comercio que se facilite en la mayor me
dida posible la liberación de tales obligaciones. El rechazo del pago parcial perjudica a los
demás obligados cambiarios que habrían sido liberados hasta la concurrencia de la suma pa
gada. El tenedor tiene derecho a protestar el título valor por la cantidad impaga y ejercitar
las acciones cambiarías. De verificarse pago parcial, quien paga puede exigir que el tenedor
del título le otorgue el recibo correspondiente, además de la anotación que deberá hacerse
en el mismo título valor. En el registro del protesto deberá hacerse la anotación del pago par
cial si tal pago se efectúa en el acto del protesto o durante el lapso que el título se encuentre
en poder del fedatario. En los casos de cumplimiento parcial, el tenedor debe además hacer
entrega a quien hizo tal pago parcial la copia certificada notarial o judicial del título valor con
la constancia de haber sido parcialmente pagado; en cuyo mérito podrá, quien hizo tal pago
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

