Tema 4: Temas de la especialidad comercial
parcial, ejercitar las acciones cambiarías correspondientes. La copia certificada antes indicada
tiene mérito ejecutivo. De esta forma el que efectúa el pago parcial y quiere subrogarse a la
brevedad para iniciar una acción judicial y recuperar lo pagado por él, puede efectuarlo.
Lugar de pago (Art. 66° LTV).- Es aquel donde el deudor ejecuta la prestación, o sea, el lugar
en donde el acreedor obtiene la satisfacción de su crédito. El título valor debe ser presentado
para su pago en el lugar designado al efecto en el documento, aun cuando el obligado hubiere
cambiado de domicilio, salvo que éste haya comunicado notarialmente al últim o tenedor su
variación, antes del vencimiento o fecha prevista para su pago y siempre dentro de la misma
ciudad o lugar de pago. Si se hubiere señalado que el pago se hará mediante cargo en una
cuenta mantenida en una empresa del Sistema Financiero Nacional conforme a cláusula es
pecial, el título debe presentarse ante la respectiva empresa señalada en el documento, la que
rechazará o atenderá su pago con los fondos que hubiere en la cuenta designada en el título
valor, hasta donde alcancen, o, con las concesiones crediticias que pueda conferir al titu la r de
dicha cuenta. A falta de indicación expresa del lugar de pago, el título valor se entiende paga
dero en el dom icilio que figure junto al nombre de quien resulte ser el obligado principal del
título; o, en su defecto, en el domicilio real del obligado principal; y el dom icilio del indicado
para el pago por intervención.
b. El protesto ( A r t . 70° y ss. LTV)
Definición.- Es una institución propia de los títulos valores cuya finalidad es acreditar la falta
de aceptación o el incumplimiento en el pago por parte del obligado cambiario. La finalidad del
protesto es dejar constancia fehaciente e indubitable de la falta de aceptación o pago del título
valory dejar expedita la acción cambiaría contra los obligados. La responsabilidad de los obliga
dos indirectos en “vía regreso” está subordinada a la falta total o parcial de aceptación o de pago
de la letra, porque requiere la existencia de una prueba de tal eficacia jurídica que demuestre
de manera auténtica dicho incumplimiento. Así, en caso de incumplimiento de las obligaciones
que representa el título valor, debe dejarse constancia de ello mediante el protesto.
Formalidad sustitutoria del protesto.- En los títulos valores sujetos a protesto, cuyo pago
deba verificarse con cargo en una cuenta.
De los títulos valores no sujetos a protesto.- Tratándose de títulos valores sujetos a protesto,
es válida la cláusula “Sin Protesto” u otra equivalente que se incluya en el texto del título valor.
En estos casos, la acción cambiaría se ejercitará por el solo mérito de haber vencido el plazo
señalado en el título valor. Dicha cláusula no impide que el tenedor opte por su protesto, en
cuyo caso los gastos respectivos serán de su cuenta. Esta excepción no aplica para el protesto
por falta de aceptación de la Letra de Cambio, el que debe llevarse a cabo aun cuando se haya
liberado del protesto.
Facultad de realizarel acto del protesto.- El protesto podrá realizarse desde el día siguiente de
su emisión, toda vez que la presentación del título determina su vencimiento, durante el lapso
de presentación al pago, que corresponde al plazo de prescripción de las acciones cambiarías.
En contraste, también será posible presentar el título el mismo día de vencimiento, toda vez
que la ley permite realizarel acto de protesto dentro de los ocho días posteriores al vencimien
to del plazo legal (Cas. N °2308-2016 Lima).
