banco giradoy a la Cámara de Comercio Provincial respectiva, el inicioy culminación del pro
ceso penal por libramiento indebido de Cheques rechazados por falta de fondos. La misma
obligación le corresponde al Juez Civil en los procesos de cobro de los Cheques señalados en
el párrafo anterior.
6.7. Acciones cambiarías derivadas de los títulos valores
Concepto.- Como toda acción procesal, es el derecho subjetivo público que corresponde al
titu lar de un derecho material y que tiene contenido la obligación de la tutela jurídica del
Estado.
Diferencia de Acción y Proceso.- La acción es el derechoy el proceso es el vehículo a través del
cual se hace valer ese derecho.
Características.- Tiene su fundamento en la tenencia legítima del título y no en la relación
causal; no se le puede oponer todas las excepciones que se deducen en la relación extracam-
biaria; el título está revestido de mérito ejecutivo; es una condición esencial la presentación
del título y constituye la única legitimación que requiere la ley.
Finalidad.- Es obtener la ejecución de los bienes del deudor, para conseguir el pago del docu
mento, amparado en el mérito ejecutivo que presta el mismo título.
Acción Cambiaría directa.- Es el derecho que confiere al tenedor del título valor de accionar
contra el obligado principal y/o sus garantes (aceptante y avalista en la letra de cambio, gira-
d ory emitente en los demás títulos valores)
Acción Cambiaría de regreso.- Es el derecho que confiere al tenedor del título valor de accio
nar, conjunta o sucesivamente a la acción directa, contra los endosantes, garantes de éstos y
demás obligados del título, distintos al obligado principal y/o garantes de éste (endosantes,
avalistas de estos).
Acción Cambiaría de ulterior regreso o de reembolso.- Es el derecho que confiere a q uien ha
cumplido con el pago de un título valor en vía de regreso para repetir dicho pago contra los
demás obligados que hayan intervenido en el título valorantes que él, ejercitando la acción de
ulterior regreso. La misma acción corresponde a quien pague en esta vía, contra los obligados
anteriores a él.
Requisitos para ejercitar las acciones cambiarías.- Para ejercitar las acciones cambiarías
constituye requisito obligatorio: En los títulos valores sujetos a protesto, haberse verificado el
