Tema 4: Temas de la especialidad comercial
mismo; En los títulos valores que sean objeto de formalidad que sustituya al protesto, haber
logrado la constancia de la falta de cumplimiento de la obligación consignada poruña institu
ción del Sistema Financiero Nacional o que opten por el protesto voluntario; En los títulos va
lores no sujetos a protesto, o los sujetos a protesto cláusula “sin protesto”, la tenencia del título
cuyo plazo esté vencido o resulte exigióle la obligación según texto del documento o, en su
caso, de la constancia de la Institución de Compensación y Liquidación de Valores, además, se
requiere haber cursado información a la Cámara de Comercio respectiva del incumplimiento.
a. Prescripción y caducidad de las acciones derivadas de los títulos valores
Prescripción de las acciones cambiarías
Concepto.- La prescripción extintiva es una institución jurídica según la cual, el transcurso de
un determinado lapso extingue la acción que tiene el sujeto para exigir un derecho ante los
Tribunales.
Características
a) Extingue la acción dejando subsistente el derecho al que ella se refiere.
b) La prescripción opera a invocación de parte como excepción.
c) Sin perjuicio del inicio del proceso, arbitral y judicial, los plazos de prescripción de la ac
ción cambiaría son perentorios y no admiten interrupción, ni suspensión.
d) El reconocimiento judicial del título valor vencido no interrumpe los plazos de prescrip
ción señalados en el presente Artículo para el ejercicio de las acciones cambiarías deriva
das de él.
e) Para el ejercicio de las acciones cambiarías derivadas además de los requisitos y form ali
dades de ley, deben ser exigidos dentro de los plazos de prescripción.
Plazos de prescripción de las acciones cambiarías.- Las acciones cambiarías prescriben:
a) A los tres años a partir de la fecha de su respectivo vencimiento, la acción directa contra el
obligado principal y/o sus garantes; en el caso de los cheques, los plazos de prescripción
se computan a partir del últim o día del plazo de presentación a cobro señalado en esta
Ley (30 días); en el caso de los demás títulos valores con vencimiento a la vista, el cómputo
se hará a partir del día de su presentación a cobro o, de no haberse dejado constancia de
ello, a partirdel día desu respectivo protesto o de la formalidad sustitutoria; y, de no estar
sujeto a ello, a partir del últim o día para su presentación al pago conforme a ley o del
señalado para ello en el mismo título.
b) Al año, a partir de la fecha de su vencimiento, la acción de regreso contra los obligados
solidarios y/o garantes de éstos; en el caso de los cheques, los plazos de prescripción se
computan a partir del últim o día del plazo de presentación a cobro señalado en esta Ley
(30 días); en el caso de los demás títulos valores con vencimiento a la vista, el cómputo
se hará a partir del día de su presentación a cobro o, de no haberse dejado constancia de
ello, a partirdel día desu respectivo protesto o de la formalidad sustitutoria; y, de no estar
sujeto a ello, a partir del últim o día para su presentación al pago conforme a ley o del
señalado para ello en el mismo título.
