c) A los seis meses, a partir de la fecha de pago en vía de regreso, la acción de ulterior regreso
contra los obligados y/o garantes de éstos, anteriores a quien lo ejercita. Dentro de este
mismo plazo debe ejercitarse la acción de repetición que corresponda al garante del obli
gado principal contra éste.
Prescripción de accio n es c a m b ia ría s d e títu lo s p ro rrogados y renovados
a) La prórroga es la prolongación en el tiempo de los derechos preexistentes que contiene
el Titulo Valor. En este caso, el plazo de prescripción de las acciones cambiarías derivadas
de títulos valores que tengan la cláusula de prórroga, se computará desde la fecha de su
últim o vencimiento, surtiendo efecto respecto a todas las personas que intervengan en el
título valor.
b) La renovación es el nacimiento de una nueva relación jurídica diferente a la originaria,
la cual se ha extinguido. En este caso de las renovaciones acordadas en el título valor, los
plazos de prescripción volverán a ser computados desde la fecha del nuevo vencimiento.
Sin embargo, en este caso, la prescripción de las acciones cambiarías tendrá efecto desde
la misma fecha de la renovación, respecto a las personas que no hubieren intervenido
expresamente en dicha renovación.
c) Caducidad del derecho de suspensión de pago.- En los casos de la suspensión del derecho
de pago por extravío, sustracción o deterioro del título valor, si el obligado no es notifi
cado del inicio del proceso de ineficacia del respectivo título valor o el peticionario no le
hace entrega de la copia de la respectiva demanda presentada ante la autoridad judicial,
dentro de los siguientes quince días de su petición extrajudicial de suspender el pago, ca
duca tal derecho de suspensión, quedando el obligado liberado de toda responsabilidad
por el pago que realice transcurrido dicho plazo de suspensión.
Prescripción de la acció n de e n riq u e cim ie n to sin c a u sa .- Cuando se han extinguido las ac
ciones derivadas de los títulos valores, la acción de enriquecimiento sin causa prescribe a los
dos años de extinguida la correspondiente acción cambiaría derivada del título valor.
C a d u c id a d y prescripción de la acció n c a u s a l.- La caducidad y prescripción de las acciones
causales correspondientes a los actos jurídicos que dieron lugar a la emisión, aceptación, ga
rantía o transferencia de los títulos valores, operan en los plazos que establece el Código Civil.
6.8. Deterioro, destrucción, extravío y sustracción de los títu lo s valores
La entrega de títulos valores que constituyen órdenes o promesas de pago, sólo extinguirá la
obligación prim itiva cuando hubiesen sido pagados o cuando porculpa del acreedorse hubie
sen perjudicado, salvo pacto en contrario.
Entre tanto la acción derivada de la obligación primitiva quedará en suspenso.
II. DERECHO CAMBIARIO
1. La letra de cam bio y su em isión
N o cio n es p re v ia s.- La letra de cambio constituye a la vez un instrumento de pago e instru
mento de crédito, originalmente utilizado en la compraventa que se realiza entre distintas
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 719 of 1506 --

Tema 4: Temas de la especialidad com ercial
plazas. Toda vez que se emite una letra de cambio, existe una relación fundamental previa
entre quien libra la orden (librador) y la persona a quien se le imparte (girado), en razón de la
cual el girado es deudor de quien da la orden. También existe una relación previa entre quien
libra la orden (librador) y quien recibe el documento (beneficiario). Tales relaciones no se ex
tinguen por la creación de la letra.
Tenemos como ejemplo: el comerciante A domiciliado en Lima vende a B radicado en Chim
bóte. Paralelamente A solicita un préstamo del banco C, por un importe aproximado al precio
de venta. A recibe una cantidad de dinero del bancoy se convierte en deudor del banco. Luego
crea la letra de cambio contra By a favor del banco C. Cuando B pague la letra cancela a la vez
su deuda por el precio de venta que deba a A y extingue el préstamo debido por A al banco C.
En el caso la creación de la letra estuvo precedida de dos relaciones fundamentales: entre A
y B un contrato de compraventa; entre A y el banco C, una operación bancaria de préstamo.
Para completar los conocimientos elementales sobre la letra de cambio, es necesario explicar
el instituto de la aceptación. Se mencionó que la letra de cambio es una orden que una per
sona da a otra. Pues bien, en el mecanismo de la letra de cambio es necesario que ésta sea
aceptada por quien reciba la orden. La aceptación se formula, mediante la firm a de la letra
de cambio. El tercero, que se ha de beneficiar con el pago y que es tenedor de la letra, debe
presentarla al girado para que la acepte, firmando esa letra. Si el girado no la acepta no queda
obligado y no puede ser compelido para el pago. Si la acepta queda convertido, en lo que se
llama obligado cambiario, en el principal obligado cambiario. Al crearse la letra, contiene en
su texto sólo una orden de pago.
De la redacción de la letra no surge obligación a cargo de nadie; pero es la Ley la que establece
que el librador de la letra es responsable de la aceptación y del pago de la letra por el girado.
Con ello, desde el nacimiento, el beneficiario tiene frente así la eventualidad de la aceptación
por el girado y la responsabilidad del librador para el caso de que el girado no acepte o para el
caso de que, habiendo aceptado, no pague.
Como se aprecia existen tres sujetos:
a) El girador: es quien emite el documento dando orden de pago, cuyo cumplim iento ga
rantiza.
b) El girad o: es la persona es la persona que se obliga a pagar, a quien se le da la orden de
hacer el pago, el girado también puede ser el girador.
c) El te n e d o r o b e n e ficia rio de la letra: es la persona a la que se ha de hacer el pago de la
suma de dinero indicada en la letra.
Concepto d e la letra de ca m b io .- Es un Título Valor que contiene una orden incondicional
por escrito, suscrita y dirigida por una persona a otra, ordenando a ésta que pague a su pre
sentación, o en un plazo fijo o en un futuro determinable, una cierta cantidad de dinero a una
determinada persona, o a su orden.
C aracterísticas:
a) D o cu m e n to q u e C o n tie n e ord en in co n d ic io n a l.- No acepta condiciones para el pago.
b) D o cu m ento Su scrito .- Para que los participantes sean obligados la letra debe ser firmada.
