c) La orden para ei pago debe estar dirigida por una persona a otra.- Del girador al girado.
d) Contiene el momento de e xig ibilid a d o vencimiento de la letra.- A la vista, a fecha fija,
a cierto plazo desde la aceptación, o a cierto plazo desde su giro.
e) Tiene como Beneficiario a determinada persona o a su orden.- Puede ser Tercera Perso
na o el mismo Girador.
Formalidades de la Letra de Cambio (Art. 119 LTV):
a) La d e n o m in a ció n d e Letra d e C a m b io .- Tiene por objeto brindar al que suscribe la certe
za de la clase de obligaciones que asume.
b) La in d ica ció n del lu g a r de giro.- Es la localidad donde se crea el Título, a falta de mención
expresa, se considera girada la Letra de Cambio en el dom icilio del girador.
c) La in d ica ció n de la fech a d e giro .- Es importante en tanto determinará la ley aplicabley
los plazos de caducidad para el ejercicio de las acciones cambiarías, o conocer el venci
miento de las letras a días o a meses de la fecha de giro. De no existir este dato dejaría sin
la calidad de título valor.
d) El nombre y el n ú m ero del d o cu m e n to o ficial de id e n tid a d de la perso na a cuyo cargo
se gira: El nombre de la persona a cuyo cargo se gira la letra (girado o librado) Si acepta,
se convierte en el obligado principal cambiarlo denominado aceptante.
e) El no m b re d e la p erso na a q u ie n o a la o rden d e q u ie n d e b e hacerse el pago (tom ador):
La persona sea natural o jurídica debe estar indicada con precisión. En este caso la ley no
exige la incorporación del documento de identidad. En la Casación N° 4156-2018 Lima, se
precisa que el tomador será el primer beneficiario de la letra de cambio, en cuyo favor se
gira la misma. Este primer beneficiario puede ser la misma persona que gira la cambial,
en cuyo caso puede optar por señalar que se consigne su nombre, o la cláusula “mi mis
mo” o nosotros mismos”, sin que sea necesario consignar el nombre del beneficiario en
modo expreso.
f) El nom bre, el n ú m e ro del d o cu m e n to o ficial d e id e n tid a d y la firm a d e la p erso n a que
gira la Letra d e C a m b io lib rad o r o girad or; el nombre permitirá identificar a la persona
natural o jurídica. La identificación del representante de la persona jurídica, que tratán
dose de personas jurídicas, además se consignará el nom brey documento oficial de iden
tidad de sus representantes que intervienen en el título. La firm a del girador, es también
un requisito insustituible, pues el girador es quien asume la obligación de hacer pagar o
pagar la prestación contenida en la letra. En tanto la letra no es aceptada es el obligado
principal para el pago de la misma.
g) La orden in co n d icio n a l de p a g a r u n a c a n tid a d determ inada d e d in ero o u na ca n tid a d
d e te rm in a b le de éste, co nfo rm e a los siste m a s de a ctu a liza c ió n o reajuste d e capital
le g a lm e n te a d m itid o s .- La orden incondicional de pagar determinada cantidad de dine
ro significa que la obligación es puray sim pley no subordinada a alguna condición si el
girado no paga la suma ordenada, el libradorestá asumiendo laobligación de pagarla. La
cantidad debe ser determinada o determinable de acuerdo a los índices de ajuste aproba
dos por la ley.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 721 of 1506 --

Tema 4; Temas de la especialidad comercial
h) La indicación del vencimiento.- La indicación del vencimiento es el requisito que confie
re certeza en cuanto a la exigibilidad de la obligación, asegurando su circulación.
i) La in d ica ció n del lu g a r d e p a g o .- Es el lugar donde debe efectuarse el pago. A falta de in
dicación especial, el lugar designado junto al nombre del girado se considera como lugar
de pago y al mismo tiempo como domicilio del girado; y, si no hubiera lugar designado
junto al nombre del girado, será pagadera en el dom icilio real del obligado principal. En
los casos de Letras de Cambio pagaderas conforme a la cláusula de pago con cargo en
cuenta bancaria, no será necesario señalar lugar especial de pago; la letra de cambio po
drá pagarse mediante cargo en cuenta mantenida en una empresa del Sistema Financiero
Nacional.
Form as de g ira r la letra d e cam b io (A r t.12 7 LTV)
La Letra de Cambio puede ser girada:
a) A la o rden del propio g irad o r.- Existe una doble calidad librador y tomador. Bajo esta
modalidad, quien gira la letra, ordena que se pague a su misma orden. Cuando se gire
a la orden del propio girador, se podrá referir a éste con la cláusula de “Mí mismo” u otra
equivalente.
b) A la o rden d e un tercero.- Inviste a éste como titu lar del derecho contenido en el título.
El librador se obliga a pagar o a hacer pagar, al tomador o a quién éste transmita la letra, la
cantidad mencionada en ella.
c) A cargo de tercera p e rso n a .- Es decir que el girador y el girado son personas distintas
entre sí, es la forma propia de este título. Para que girado quede obligado debe aceptar la
letra. En el caso de negarse el girado, el girador es responsable del pago vía acción cam
biaría de regreso.
d) A cargo d el propio g irad o r.- En esta clase de letras, el girador reúne la doble condición de
libradory librado. En este caso no es necesario que vuelva a firm arla como aceptante. Si el
librador acepta la letra, responde frente al tenedor por un doble concepto: como girador
y como aceptante.
e) Por cu en ta de un tercero.- Supone que no es el librador el presunto acreedor del girado,
sino que lo es el tercero por cuya cuenta es girada la letra. Pero el girador responde por la
aceptación y el pago (mandatario sin representación). Toda cláusula liberatoria de dichas
responsabilidades se considera no puesta.
El en d o so ( A r t s .i2 5 y i2 6 LTV)
a) Toda Letra de Cambio, aunque no esté expresamente girada a la orden, es transmisible
por endoso. La letra de cambio es un título a la orden, aunque no haya sido girado expre
samente a la orden, en cuyo caso basta que lleve la denominación de la letra de cambio.
b) El endoso es la forma típica de la circulación de la letra de cambio. El Endoso es una cláu
sula accesoria e inseparable de la letra, por virtud de la cual el acreedor cambiario pone a
otro acreedor en su lugar dentro de la letra de cambio.
In te rv ie n e n en el en do so : El endosante, que transmite la letra de cambio; y el endosatario,
a quien se le transmite la letra. El endosatario, cuando recibe el documento, se convierte en
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 722 of 1506 --

UBILEX
l su nuevo tenedor legítimo y, en consecuencia, adquiere, todos los derechos resultantes de la
letra de cambio. El endosante responde en vía de regreso frente a los tenedores posteriores de
la letra de la aceptación y del pago.
La aceptación
Concepto (Art 127 LTV).- Por la aceptación, el girado (o librado) se obliga a pagar la Letra de
Cambio al vencimiento, asumiendo la calidad de obligado principal, transformándose en acep
tante. La aceptación es un negocio jurídico unilateral, no recepticio, en virtud del cual el girado
se obliga a pagar la letra de cambio al vencimiento, asumiendo la calidad de obligado principal.
Características
a) El girado que acepta la Letra de Cambio queda obligado, aunque ignore el estado de in
solvencia, quiebra, liquidación, disolución o muerte del girador.
b) A falta de pago, el tenedor, aun cuando sea el girador, tiene contra el aceptante acción
cambiaría directa por todo lo que puede exigirse.
c) La aceptación es puray simple; pero a aceptación puede ser parcial, esto es, por una parte
del importe de la letra. El aceptante queda obligado por esta parte y el tenedor puede
iniciar vía de regreso por la parte no aceptada.
d) Cualquier modificación o condición en la aceptación equivale a su negativay da lugar al
respectivo protesto y a la acción cambiaría que corresponda.
Form alidad de la aceptación (Art. 128 LTV)
a) La aceptación debe constaren el anverso de la Letra de Cambio, expresada con la cláusula
“aceptada”, y la firm a del girado.
b) Pero la sola firma de éste importa su aceptación.
c) Cuando la Letra de Cambio sea pagadera a cierto plazo desde la aceptación o cuando, en
virtud de cláusulas especiales deba presentarse a la aceptación en un plazo determinado, la
aceptación debe llevar la fecha del acto; y, si el aceptante la omite, puede insertarla el tenedor.
Reaceptación de la Letra de Cam bio
a) C o ncep to .- La reaceptación importa la renovación de la obligación en los términos de la
aceptación precedente, en cuanto al monto, plazo y lugar de pago, salvo cláusula en con
trario. (139.1)
b) Efectos.- Por el hecho de la reaceptación quedan cambiariamente liberados los anterio
res firmantes de la Letra de Cambio, salvo que vuelvan a intervenir. (Art. 139.3 LTV)
c) F o rm a lid a d d e la re a ce p ta ció n .- La reaceptación constará en el anverso del título o en
hoja adherida a él (Art. 139.2 LTV). La reaceptación no será necesaria si el obligado otorgó
su consentimiento escrito por anticipado para su prórroga (Art. 139-4 LTV)
d) P ro ce d e n cia .- La reaceptación procederá sólo antes de la prescripción de la acción cam
biaría directa, siempre que el título no hubiere sido protestado u obtenido la form alidad
sustitutoria. (Art. 140 LTV)
m2 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 723 of 1506 --

Tema 4: Temas de la especialidad comercial
Presentación a ia aceptación (Art. 130 LTV)
a) Cuando la Letra de Cambio deba ser aceptada, la presentación para su aceptación se hará
en el lugar señalado en el título y, si no se indica, en el lugar que corresponde a su pago.
b) El girador puede estipularen la Letra de Cambio que ésta se presente para su aceptación,
fijando un plazo o sin esta modalidad. Puede, asimismo, estipular que la presentación a
la aceptación no se efectúe antes de determinada fecha.
c) Todo endosante puede estipular que la Letra de Cambio se presente a la aceptación, fijan
do o no un plazo para ello.
d) La inobservancia del plazo para la presentación a la aceptación puede ser invocada sólo
por el girador o endosante que la consignó o personas que hayan intervenido después de
quien lo consignó.
e) Si no se consignó plazo para su presentación a la aceptación, será obl igatoria su presenta
ción para ese efecto, antes de su vencimiento.
Aceptación de la Letra de Cambio con Vencimiento a cierto plazo desde la aceptación (Artículo
134 LTV)
Para que la Letra de Cambio a cierto plazo desde la aceptación sea exigióle, debe ser presenta
da al girado para su aceptación, dentro del plazo de un año desde que fue girada.
Aceptación de Letra de Cam bio a fecha fija o a la vista o a cierto plazo desde su giro (A rt 135 LTV)
La Letra de Cambio con vencimiento a fecha fija, o a la vista, o a cierto plazo desde su giro
puede ser presentada por el tenedor para la aceptación, aunque el girador no haya insertado
estipulación al respecto. La presentación para la aceptación podrá ser hecha antes del venci
miento si la Letra de Cambio es a fecha fija o acierto plazo desde su giro,y dentro del plazo de
un año desde su giro si es a la vista, salvo que en su caso se haya fijado fecha distinta para su
aceptación.
Obligación del Girado (Art. 136 LTV)
El girado a quien se le presente la Letra de Cambio para su aceptación está obligado a aceptar
o rechazar su aceptación. Toda demora faculta al tenedor a solicitar su protesto.
Efectos de la fa lta d e a cep ta ció n (Art. 13 1 LTV)
a) El tenedor pierde la acción cambiaría contra todos los obligados cuando, siendo necesario
presentar la Letra de Cambio para su aceptación, no lo hiciere en el plazo legal o en el
señalado en el título por el girador.
b) También pierde el tenedor la acción cambiaría contra el endosante o garante que hizo la
indicación del plazo para su presentación a la aceptación y contra los que posteriormente
suscribieron la Letra de Cambio, si ésta no es presentada en el plazo señalado por cual
quiera de los endosantes o garantes.
La intervención en la aceptación (Art. 132 LTV)
a) Cuando sean varios los girados, el tenedor presentará la Letra de Cambio en el orden que
considere conveniente. En el caso de indicación alternativa, la presentará a quien dicho
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 724 of 1506 --

UBILEX
tenedor elija, y en el caso de indicación sucesiva, la presentará en el orden enunciado en
la Letra de Cambio.
b) Si la Letra de Cambio fuese aceptada por montos parciales por más de un girado, cada
cual responderá porsu pago porel monto parcial aceptado, debiendo anotarse en el mis
mo título los pagos que realicen, sin perjuicio de la obligación del tenedor de expedirles
las constancias de pago correspondientes.
El ve n cim ie n to
Concepto de v e n cim ie n to : Es el momento en el cual la obligación comienza a ser exigióle.
Cuando se cumple el plazo, establecido para el goce del crédito incorporado a la letra, surge
el derechoy la obligación del portador de presentar la letra, para recibir el dinero equivalente
o para que se extinga la obligación, en algunas de las formas que establecen las leyes perti
nentes.
Form as de se ñ a la r el v e n cim ie n to (A r t.12 1 LTV)
La Letra de Cambio, para tener validez como tal, puede ser girada solamente:
a) A fecha fija; Vence el día señalado. La letra a fecha fija indica que la fecha de vencimiento
está expresada en la propia letra.
b) A la vista; Vence el día de la presentación al girado para su pago. La letra a la vista vence
el día que es presentada al indicado para su pago; el girado sabe que el título vence el
día que se le presenta. Si fuere aceptada, el vencimiento se produce el mismo día de su
aceptación. La Letra de Cambio a la vista vence el día de su presentación al girado para su
pago. La Letra de Cambio pagadera a la vista, antes de su presentación al pago, puede o no
estar aceptada. Si no cuenta con aceptación, la aceptación y el pagóse harán simultánea
mente o exigirse su aceptación antes de su presentación al pago. De no estar aceptada, en
su caso, procederá su protesto por falta de aceptación total o parcial. La Letra de Cambio
a la vista aceptada en oportunidad de su giro o en fecha posterior, que no fuese atendida
en su pago el día de su presentación para ese fin, será protestada por falta de pago, salvo
disposición distinta de la Ley. La presentación al pago de la Letra de Cambio a la vista po
drá hacerse en cualquier momento, a libre decisión de su tenedor, desde el día mismo de
su giro inclusive,y durante el plazo que al efecto se hubiere señalado en el documento. A
falta de dicha indicación, la presentación para su pago deberá hacerse dentro de un plazo
no mayor a un año, desde la fecha de su giro (Artículo 141).
c) Acierto plazo desde la aceptación; Comienza a correr desde que la letra se pone a la vista
del girado y éste lo acepta, o lo rechaza (se acredita con el protesto). A falta de este, la
aceptación sin fecha se considera otorgada el últim o día del plazo establecido para pre
sentarla a la aceptación. La letra a cierto plazo desde la vista, es aquella cuyo vencimiento
depende de la fecha en que la letra se presenta a la aceptación. El artículo 134 de la LTV
señala que en la aceptación a cierto plazo desde la vista, para que la Letra de Cambio a
cierto plazo desde la vista sea exigióle, debe ser presentada al girado para su aceptación,
dentro del plazo de un año desde que fue girada. El girador puede reducir este plazo o fi
jar uno mayor, debiendo en ese caso dejarse constancia en el mismo título. Esta forma de
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 725 of 1506 --

Tema 4: Temas de la especialidad comercial
señalar el vencimiento podrá constar con la cláusula “a cierto plazo desde la aceptación” u
otras equivalentes como la cláusula “a cierto plazo vista”.
d) A cierto plazo desde su giro. Vence al cumplirse el plazo señalado computado desde la
fecha de emisión.
V e n c im ie n to no tipificado.- La Letra de Cambio girada y pagadera dentro de la República que
indique vencimiento distinto a los señalados en el párrafo anterior o vencimientos sucesivos
no produce efectos cambiados. En algunas legislaciones se admite el vencimiento sucesivo de
la letra de cambio; en otras como la legislación califica el documento como nulo cuando se
ha fijado vencimientos sucesivos. La LTV señala con precisión en su artículo 121.2, que la Letra
de Cambio giraday pagadera dentro de la República que indique vencimientos sucesivos, no
produce efectos cambiarios.
V e n cim ie n to s m ú ltip le s .- En caso de designarse el vencimiento utilizando más de una de las
formas indicadas en la ley, siendo una de ellas fecha fija, y hubiera diferencia entre ellas, pre
valece la fecha fija que se haya consignado. La indicación de la fecha de vencimiento puede
constarya sea en recuadros, en forma completa o abreviada. La indicación de cláusulas como
“a la fecha antes indicada”, “al vencimiento” u otras equivalentes, que se limiten a reiterar la
fecha de vencimiento consignada en el título valor, no lo invalida. A falta de indicación del
vencimiento, se considera pagadera a la vista.
C o m p u to d el p lazo d e V e n c im ie n to (Art. 14 4 LTV)
a) El cómputo de los plazos de vencimiento fijados en meses, años u otras formas perm iti
das por la ley se determinará según las normas del derecho común.
b) Las expresiones “ocho días” o "quince días” equivalen al plazo de ocho o de quince días y
no de una semana o dos semanas. La expresión “medio mes” indica un plazo d e is (quin
ce) días. Si al indicarse el día del vencimiento se ha om itido el año, se entiende que es el
mismo año de la emisión de la Letra de Cambio o, de corresponderle, el año siguiente. Si
se indica como fecha de vencimiento una que no existe en el calendario, se entiende que
la fecha vence el últim o día correspondiente al mes de vencimiento.
c) En los plazos legales o convencionales, no se comprenderá el día que les sirva de punto de
partida, salvo expresa disposición en contrario de la ley.
d) En el cómputo de los días no se excluyen los días inhábiles, pero si el día del vencimiento
para su aceptación o pago lo fuera, se entenderá que dicho plazo venceel prim erdía hábil
siguiente. Sin embargo, el plazo para su protesto se computa a partir del día de venci
miento señalado en el documento o en el que según su texto resulte exigible.
El Pago
El pago es el modo normal de extinguir la obligación mediante el cumplim iento de la pres
tación objeto de la misma. La letra de cambio debe ser pagada el día de su vencimiento. El
que paga una letra antes del vencimiento lo hace por su cuenta y riesgo. El tenedor no puede
rehusar un pago parcial; debe otorgar recibo y anotarlo en el Título. Por lo no pagado, debe
protestar la letra.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 726 of 1506 --

UBILEX
Reglas para el pago de la letra de cambio (Art. 14 5 LTV)
a) Toda Letra de Cambio es pagadera en el domicilio señalado en ella o con cargo en la cuen
ta señalada.
b) Cualquier endosante u obligado distinto al principal que pague la Letra de Cambio puede
testar su endoso o firm a y los posteriores.
c) Cuando el girador hubiere indicado en la Letra de Cambio un lugar para el pago diferente
del domicilio del girado, éste puede señalar ese domicilio u otro distinto en el momento de
la aceptación y/o consignar la cláusula con cargo en cuenta corriente bancaria (artículo 138)
d) A falta de esta indicación, se entiende que el aceptante se ha obligado a pagarla en el
lugar designado para el pago, según el documento (artículo 138).
Pacto d e in te reses en Letras d e C a m b io (Art. 146 LTV)
En la Letra de Cambio no procede acordar intereses para el período anterior al de su venci
miento. Sólo a falta de pago y a partir del día siguiente a su vencimiento, generará los intereses
compensatoriosy moratorios o, en su defecto, el interés legal, hasta el día de su pago.
El Protesto por Falta d e A cep tació n (Art. 14 7 LTV)
El protesto es un acto auténtico por medio del cual se prueba el cumplim iento o del aceptante
y, al mismo tiempo, la diligente presentación de la letra por el portador, lo que produce la
preservación de la acción contra los obligados de regreso, esto es, la no caducidad de la acción
cambiaría del regreso de la que trataremos más adelante. Las características más importantes
son:
a) El protesto por falta de aceptación procede cuando se ha presentado infructuosamente la
Letra de Cambio para la aceptación.
b) El protesto por falta de aceptación total dispensa de la presentación para el pago y del
protesto por falta de pago, asumiendo el girador la calidad de obligado principal, contra
quien y demás obligados procede ejercitar la acción cambiaría derivada de la Letra de
Cambio por el solo mérito del protesto por falta de aceptación. La falta de pago de estas
Letras de Cambio se comunicará a la Cámara de Comercio.
c) La obligación de información y registro de que trata el artículo 85o deberá ser cumplida en
los protestos porfaltade aceptación de Letra de Cambio, consignando el nombre del gira-
d ory registrándose en forma independiente del registro de protestos por falta de pago.
d) La cláusula sin protesto a la que se refiere el artículo 81o no resulta aplicable al protesto
por falta de aceptación de la Letra de Cambio. El protesto por falta de aceptación deberá
llevarse a cabo aun en la Letra de Cambio que contenga dicha cláusula.
Las acciones cam biarías (Art. 148 LTV)
La acción cambiaría se ejerce cuando el título valor reúne los requisitos legales exigidos para
su validez. Se puede ejercer de dos formas:
Directa: Cuando se deduce contra el aceptante o sus avalistas.
De regreso: Cuando se ejercita contra cualquier otro obligado.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 727 of 1506 --

Tema 4: Temas de la especialidad comercial
a) Antes del vencimiento de la Letra de Cambio, el tenedor puede ejercitar las acciones
cambiarías que correspondan si ha habido negativa, total o parcial de la aceptación,
por la parte no aceptada; o, el girado aceptante o no hubiese sido declarado insol
vente o resultado ineficaz una medida cautelar u orden de embargo sobre sus bie
nes. Esta últim a regla será aplicable al girador de una Letra de Cambio a su propio
cargo.
b) En caso de ejercitarse la acción cambiaría después de la aceptación parcial, el que
paga la cantidad por la cual la Letra de Cambio no fue aceptada puede exigir que
se deje constancia de dicho pago en el mismo título y además que se le expida el
respectivo recibo.
c) El tenedor, a costo del interesado, está obligado a entregarle copias legalizadas de
la Letra de Cambio con la constancia del protesto por falta de aceptación respectiva,
para permitirle el ejercicio de las acciones cambiarías que le correspondan.
La acción c a m b ia ría d irecta: La acción cambial directa es aquella pretensión del acreedor
cambiarlo de hacer exigible el cobro del monto consignado en el título a su deudor principal
o avalista, quienes responderán de manera solidaria, esto quiere decir que el tenedor podrá
exigir el pago a cualquiera de ellos, de manera indistinta.
Hay dos formas de ejercitar la acción directa: por el portadory el obligado de regreso. La pri
mera es realizada por el ultim o endosatario contra el aceptante y/o avalista, lo que podrá re
clamares el monto de la letra no pagada con los intereses respectivos; los intereses a partirdel
vencimiento, según la tasa indicada en el título, en caso no se haya estipulado, se aplicará el
interés legal, entre otros.
La acción de regreso c a m b ia rlo : La acción cambiaría de regreso, es aquella que corresponde
al tenedor legítimo del título valory además a cada uno de los obligados que haya tenido que
efectuar el pago a un tenedor posterior. La acción de regreso se ejercita contra cualquier obli
gado que puede ser el aceptante o sus avalistas. La responsabilidad del endosante deriva del
hecho de que por el endoso asume la posición de un girador.
La acción de regreso faculta al tenedor del título valor a dirigirse contras los endosantes, ga
rantes de éstosy demás obligados del título, distintos al obligado principal y/o garante de éste.
Generalmente el obligado principal es el aceptante o girado, pero existen algunas situaciones
en lasque deja de serlo, pasando a obtenertal calidad el girador. Tal es el caso del protesto por
falta de aceptación de una letra de cambio, la cual al no ser aceptada convierte a su girador
en sujeto pasivo de la acción cambiaría de regreso, ello sin perjuicio de que el tenedor pueda
dirigirse contra los demás obligados del título valor.
La acción de regreso se podrá accionar en forma conjunta o sucesiva a la acción directa. Sin
embargo, tratándose de la Letra de Cambio parcialmente aceptada, el art. 148 LTV estable
ce que el tenedor podrá ejercitar las acciones cambiarías que correspondan, antes del venci
miento del título valor. Esta norma concuerda con los arts. 122 c) y 153-1 b).
La acció n d e u lte rio r regreso: Acción también denominada de reem bolsóla que quien paga la
obligación podrá ejercitar repetición contra los obligados que lo preceden en el nexo cambia
rlo, los cuales no quedan liberados. También debemos señalar que la acción de ulterior regre-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 728 of 1506 --

UBILEX
so es dependientey se da en consecuencia de la acción de regreso, esto quiere decir que para
que exista la presente acción, se configurará primero el derecho de regreso. Además, que se
podrá repetir con cualquiera de los intervinientes del título valor, incluso el deudory/o acree
dor principal, siemprey cuando se encuentren en la cadena cambiaría.
2. Especialidades del pagaré o del vale a la orden
EL PA G A R É
C o ncep to .- Es el documento o título valor que específica una promesa de pago hecha por es
crito y firmada por el deudor, quién se obliga a pagar una suma fija de dinero a una fecha
determinada. Es el Título valor que se distingue porque el emitente es el obligado principal y
el acreedorel titu la ro beneficiario, cuyo nómbrese indica en el título.
A n a lo g ía s y d ife re n cia s con la letra d e ca m b io .- La ley regula el pagaré como un título que
tiene un régimen extraordinariamente parecido al de la letra. Tanto es así, que en varios países
es considerado como una modalidad de letra. La nota diferencial radica, mientras que la letra
contiene una orden incondicionada del librador al librado de pagar una determinada suma, el
pagaré contiene una promesa incondicionada de un sujeto a otro de pagar una suma determ i
nada. Desde un punto de vista formal, las menciones se asemejan, con la diferencia de que en
el pagaré se simplifican las personas que figuran normalmente en el momento de la emisión,
ya que, en el lugar de aparecer el librador, el librado y el tenedor, sólo figuran quien lo emite
(denominado "emitente") y la persona a la que se ha de hacer el pago (el tenedor).
R eq u isito s fo rm a le s (Art. 158 LTV)
a) La denominación de Pagaré;
b) La indicación del lugary fecha de su emisión;
c) La promesa incondicional de pagar una cantidad determinada de dinero o una cantidad
determinable de éste, conforme a los sistemas de actualización o reajuste de capital legal
mente admitidos. El pago podrá señalarse ya sea como pago único, o en armadas o cuotas.
En este últim o caso, la falta de pago de una o más de el las faculta al tenedor a dar por venci
dos todos los plazos y a exigir el pago del monto total del título; o, alternativamente, exigir
las prestaciones pendientes en las fechas de vencimiento de cualquiera de las siguientes
armadas o cuotas o, inclusive, en la fecha de la última armada o cuota, según decida libre
mente el tenedor. Para ese efecto, será necesario que se logre el correspondiente protesto o
formalidad sustitutoria en oportunidad del incumplimiento de una cualquiera de dichas ar
madas o cuotas, sin que el hecho de no haber obtenido tal protesto o formalidad sustituto
ria correspondiente a las anteriores o a cada una de las armadas o cuotas afecte su derecho
cambiario ni el ejercicio de las acciones derivadas del título. La “cláusula sin protesto” (Art. 52
LTV) surtirá efecto sólo respecto a la última armada o cuota;
d) El nombre de la persona a quien o a la orden de quien debe hacerse el pago;
e) La indicación de su vencimiento único o de los vencimientos parciales en los casos seña
lados en el siguiente párrafo. El vencimiento del Pagaré puede indicarse solamente de las
siguientes formas: A fecha o fechas fijas de vencimiento, según se trata de pago único de
