3. El cheque
C o ncep to .- Es un título valorque contiene una orden incondicional de pago de cierta cantidad
de dinero dada por una persona a una institución bancaria para que pague, a la vista, a favor
de un tercero determinado o al portador, en virtud de un convenio previo (contrato de cuenta
corriente) que la autoriza para expedir tal documento.
F o rm a lid a d e s del C h e q u e (A r t 17 2 LTV): Los cheques serán girados sólo a cargo de bancos,
incluyéndose en este término a otras empresas del Sistema Financiero Nacional; serán gira
dos en formularios impresos, desglosables de talonarios numerados en serie o con claves o
signos de identificación (medios electrónicos), proporcionados por los bancos, bajo recibo, a
sus clientes. Se puede disponer la impresión particular de cheques que deberán ser objeto
de acuerdo entre banco y cliente. El banco sólo verifica que el que sirve de modelo guarde o
incluya los requisitos de ley, así como las otras formalidades de lugarde cada dato, para que la
computadora los pueda leer satisfactoriamente, sin obstáculos; cheques de gerencia, cheques
giro y cheques de viajeros no es obligatorio el talonario; el BCR o Convenio entre Bancos, po
drán establecer características de formularios.
R eq u isito s In trín seco s del C h e q u e (Art. 17 3 LTV) - El librador debe, como condición previa
para su giro, mantener fondos disponibles suficientes en la cuenta corriente del banco girado,
constituido por: Depósito hechos en él; o tener autorización para sobregirar la indicada cuen
ta. Su inobservancia no afecta la validez del Título como cheque.
R eq u isito s E xtrínseco s (Art. 17 4 LTV).- El cheque expresará:
a) El número o código de identificación que le corresponde.
b) Lugary la fecha de emisión.
c) La orden puray simple de pagar una cantidad determinada de dinero (expresada en nú
meros o letras o de ambos modos).
d) Nombre del beneficiario del cheque o de personas a cuya orden se emite, o indicación
que se emite al portador.
e) El nom brey dom icilio (no dato esencial) del banco girado.
f) El Lugar del pago debe ser señalado en forma expresa en su defecto en cualquier oficina
del lugar de emisión, sino lo hubiera, en cualquier oficina del país. Facultativamente, el
banco tendrá la potestad de pagar o dejar constancia de su rechazo a través de cualquiera
de sus oficinas, en cualquiera de los casos antes señalados (artículo 175 LTV).
