LOS CHEQUES ESPECIALES
Cheque Cruzado.- Es aquel que lleva en su anverso dos líneas paralelas, ya sean diagona
les, verticales u horizontales, a fin de que solamente pueda ser cobrado mediante abono
en una cuenta corriente bancaria. No Puede Ser Cobrado En Ventanilla. Cuando un che
que se haya girado sin cruzar, su tenedor puede cruzarlos de modo general o especial (Si
entre líneas contiene el nombre de un banco determinado; este cheque sólo puede ser
pagado por el girado al banco designado; y si éste es el girado, a su cliente) (artículos 184
y 186). Es negociable bajo condición de que su presentación al pago se haga a través de
cualquier banco si es general o del banco designado si es cruzamiento especial (187.2)
• Cheque para abono en cuenta (Art.189 LTV).- El librador o cualquier tenedor puede in
sertar en el anverso del documento la mención “para abonar en cuenta corriente” u otra
equivalente, lo que importar la prohibición de pagarlo en efectivo,y a la vez, la obligación
de abonado en la cuenta corriente del tenedor. El banco no puede pagar el cheque en
efectivo, debe abonar su valor en la cuenta corriente del tenedor.
• Cheque intransferible (Art. 190 LTV).- Es el que tiene la cláusula “No Transferí ble"; “No
Negociable”; “No A La Orden". Sólo puede ser satisfecho en las siguientes formas: a) Pa
gándolo en el banco solo a la persona en cuyo favor se giró; b) Acreditándolo en el banco,
a pedido del tenedor, en la cuenta corriente éste; c) Endosándolo el tenedor a un banco
para el efecto del cobro. La cláusula puede ser puesta por el endosantey surte efecto para
el endosatario.
• Cheque Certificado.- Es un cheque en el que el banco girado, a petición del girador o de
cualquier tenedor, inserta en el dorso una constancia de que existen en su poder fondos su
ficientes a disposición del librador, los que quedan afectados al pago del cheque durante el
término de vigencia de la certificación, cargándose al mismo tiempo en la respectiva cuenta
corriente girada, la suma necesaria para su pago. Tendrá la calidad legal de patrimonio de
afectación y estará destinado exclusivamente al pago del cheque certificado. Se deberá ex
cluir de la masa concursada del emitente. Asimismo, debe separarse de la masa del banco
girado en caso de insolvencia o de liquidación, declarada antes del pago del cheque.
Cheque de Gerencia (Art. 193 LTV).- Es el cheque que, previo pago de su valor, un banco
gira a cargo de ella misma, pagaderas en cualquiera de sus oficinas del país, a la orden de
un tercero indicado por quien lo solicita o, también, a la orden de este último. Existe la po
sibilidad de que sean pagados en sus oficinas del exterior cuando haya indicación expresa
de dicho pago. Para el inicio de acciones cambiarías no requiere protesto.
