• Cheque Giro (Art. 19 4 LTV).- Los bancos emiten a su propio cargo, a la orden de determi
nada persona, con la cláusula “cheque giro" o “giro bancario” en un lugar destacado del
título. Este cheque es intransferible (No Negociable), tiene lim itado su poder de circula
ción, si se paga a otra persona o en otra forma, el banco girado es quien responderá por
el pago efectuado. Es pagadero en las plazasy oficinas propias de la empresa emisoray/o
corresponsales.
• Cheque Garantizado (Art.195 LTV).-Son cheques girados a cargo de un banco, con provi
sión de fondos garantizados por dicho banco girado. Contiene: la denominación “Cheque
Garantizado; la cantidad máxima por la que puede ser emitido; el nombre del benefi
ciario (no puede ser al portador). Son los llamados “¡rrebotables". Se emiten en formato
especial y en papel de seguridad.
• Cheque de viajero Traveler''s Checks (Arts.i9 6 y 197 LTV).-Cheque emitido porel Banco
a su propio cargo, para ser pagado por ella o por los corresponsales en el país o el ex
tranjero. Se emite previo pago del valor monetario que representan. El endosatario debe
verificar del prim ertom adorsu identidad personal, cerciorándose que la firm a del endo
so estampada en su presencia sea conforme con la que aparezca del título mismo y que
hubiera sido puesta al tiempo de su emisión.
• Cheque De Pago Diferido (Arts. 199,200,201,202y 203 LTV).- El Cheque de Pago Diferido
es una orden de pago, emitido a cargo de un banco, cuya condición de pago, es el transcurso
del plazo señalado en el mismo título. La fecha desde laque procede ser presentado para su
pago no podrá ser mayor a treinta días desde su emisión, fecha en la que el emitentedebe
tener fondos suficientes. En el título se deberá consignar la denominación de "Cheque de
Pago Diferido”, en forma destacada; así como la fecha desde la que procede ser “presentado
a cobro" con la cláusula“Páguese desde e l...”; fecha desde la que se computa el plazo aplica
ble a estos cheques de todas las disposiciones que contiene la Ley para los cheques. El plazo
de presentación (30 días) para su pago comenzará a computarse desde la que procede a ser
“presentado a cobro”. Puede ser negociado desde la fecha de su emisión, pero sólo debe pre
sentarse a cobro, desde la fecha que al efecto señalada en el mismo título. El banco girado
rechazará el pago antes de esa fecha, sin que tal rechazo origine su protesto o formalidad
sustitutoria, ni dé lugar a responsabilidad alguna para el emitente.
Endoso.- Si no tiene cláusula a la orden, pero se emite a favor de persona determinada,
se presume a la orden, transferible por endoso (Artículo 201 LTV). El endoso en cheque al
portador, hace responsable solidario al endosatario. La constancia de pago en cheque al
portador no tiene calidad de endoso (Artículo 205 LTV).
Pago del cheque
Oportunidad de Pago (Art. 206 LTV).- El cheque es pagadero a la vista el día de su presenta
ción, aunque tuviere fecha adelantada. Debe ser pagada a su valor facial (visible) en la misma
unidad monetaria que expresa su importe, o sea, en moneda extranjera.
Plazo de presentación (Art. 207 LTV).- El plazo de presentación de un cheque es de 30 días,
emitido en el país o en el extranjero, contados a partir la fecha de la emisión. Salvo que se trate
de un Cheque de Pago Diferido.
