Tema 4: Temas de la especialidad comercial
Irrevocabilidad del Cheque ( A rt 208.1 LTV).- La orden de pago contenida en el cheque no
puede ser revocada por el girador, ni por cualquier otra persona, dentro del plazo de presen
tación (30 días).
Revocación del Pago (Art. 208.1 LTV).- La orden de pago contenida en el cheque solo puede
ser revocada por el emitente, cuando haya vencido el plazo de presentación (30 días).
Suspensión del Pago (Art 208.2 LTV).-Antes de realizado el pago, el emitente, el beneficiario
o últim o endosatario, puede solicitar por escrito la suspensión de su pago al banco girado
(carácter de declaración jurada) en caso de extravío, sustracción o deterioro total del cheque,
bajo condición de interponer demanda judicial de ineficacia del título por las causales men
cionadas.
Constancia de Pago (Art. 210 LTV).- El Banco puede exigiral tenedor del cheque la constancia
de haberse cancelado. El endoso puesto en el documento equivale a la cancelación del mismo.
Si es cheque al portador, el banco está obligado a consignar la constancia del pago. El últim o
endoso colocado, no produce los efectos del endoso. Si el tenedor del cheque no se identifica
el banco no se encuentra obligado a pagar.
Pago Parcial (Art. 211 LTV).- El Banco girado, a pedido del tenedor, pagará hasta donde al
cancen los fondos disponibles del emitente, al momento de su presentación a cobro. En este
caso, debe dejarse constancia, en el título, de los pagos parciales. El tenedor debe otorgar el
correspondiente recibo al banco girado que efectúe tales pagos. Por otro lado, en los casos
que tenedor exija que se deje constancia de la causa de la falta de pago, el banco girado estará
obligado a realizaren forma previa el pago parcial con fondos que hubieray el tenedor estará
obligado a recibirla. Luego de la constancia de falta de pago, el tenedor del título, solo podrá
efectuar el ejercicio de las acciones cambiarías hasta por el saldo no cancelado.
Exoneración de Obligación de Pago del Cheque (Art. 212 LTV).- Los bancos no están obliga
dos a pagar los cheques:
a) Cuando no existan fondos disponibles, salvo decida sobregirar la cuenta.
b) Cuando el documento esté dañado o falsificado en algún dato esencial (numeración, fe
cha, cantidad, beneficiario, firma, etc.)
c) Cuando se presente fuera del plazo de presentación y el girador hubiere notificado la re
vocatoria del mandato de pago.
d) Cuando solicite el tenedor la suspensión de pago por extravío, sustracción o deterioro to
tal del cheque.
e) Cheque a la orden y el derecho del tenedor no estuviera legitimado, con una serie regular
de endosos.
f) Cuando contiene lacláusula“NoTransferible”y no lo cobrase el beneficiario o un banco al
que fue transferido para su pago.
g) Si es al Portadory quien exige su pago no se identifica y firm a la constancia de su cance
lación parcial o total.
h) Cuando es un Cheque cruzado, de Pago Diferido u otro especial y no se observan los re
quisitos para su cobranza.
