1 UBILEX
Formalidad sustitutoria del Protesto (Art. 213 LTV).- Si el banco se niega a pagar dentro del
plazo de presentación, debe hacerlo constar en el mismo Título, con mención del motivo de
su negativa y de la fecha de su presentación, con firm a del funcionario autorizado del Banco.
Igual mención deberá efectuar el banco girado cuando el cheque que rehúsa pagar fuere pre
sentado a través de la cámara de compensación. La comprobación puede ser puesta el día de
presentación, a pedido del tenedor del título. Esta comprobación surte todos los efectos del
protesto, quedando expeditas las acciones cambiarías emergentes del cheque.
Pacto de Truncamiento (Art. 215 LTV).- Es el acuerdo adoptado por los bancos respecto a la
compensación electrónica de cheques mediante procedimientos especiales o sustitutorios
de endosos en procuración (endoso electrónico), así como acordar delegaciones o mandatos
cuya finalidad es dejar constancia respecto al rechazo del pago de cheques (protesto electró
nico), que tendrá los mismos efectos del protesto.
ACCIONES CAMBIARIAS DERIVADAS DEL CHEQUE
Requisito.- La falta de pago se acredita mediante el protesto o con la constancia de falta de
pago consignada por el banco. El tenedor debe presentar el cheque dentro del plazo de pre
sentación (30 días) bajo castigo de perder las acciones cambiarías.
Acción Directa,- Se debe dirigir contra el girador en su calidad de obligado principal y sus
avalistas (Art. 90).
Acción de Regreso.- Se debe dirigircontra los endosantes y sus avalistas.
Título de Crédito Hipotecario Negociable (Arts. 240 al 245 LTV).- es un Título Valor que re
presenta el derecho real de hipoteca sobre un bien inmueble determinado. El Título puede ser
endosado libremente a cualquier persona sólo en respaldo de un crédito dinerario. En estos
casos, el Título representará también el crédito garantizado con la hipoteca señalada en el
mismo documento, en favor de su últim o tenedor. Sólo podrán ser gravados bajo este sistema,
los predios inscritos en el Registro de la Propiedad Inmueble de las Oficinas Regístrales que
integran el Sistema Nacional de los Registros Públicos, así como los inscritos en el Registro
Predial. Una vez inscrita la hipoteca en el respectivo Registro Público, éste emitirá el Título
de Crédito Hipotecario Negociable, según el form ulario que para el efecto dicho organismo
determinará. El primer beneficiario del Título queda facultado a realizar su primer endoso y
consignar en el mismo documento el monto determinado o determinable del crédito dinera
rio que se garantizará con la hipoteca, así como las demás condiciones del mismo. Este primer
endoso podrá hacerse también en garantía de créditos dinerarios indirectos.
4. Títulos de tradición
Son títulos valores que incorporan un derecho real sobre la mercancía (Derecho de Propiedad
o de Garantía) y el derecho de exigir la entrega de una mercancía. Ejemplo: Certificados de
depósitos; Warrants; Vales de prenda; Conocimientos de embarque (Transporte Marítimo);
Cartas de Porte (Transporte Terrestre). Estos títulos confieren a su poseedor legítimo el dere
cho exclusivo a disponer de los bienes que en ellos se mencionan. La tradición del documento
implica la tradición de los bienes. Sin embargo, el artículo 903 del Código Civil establece la
