preferencia del poseedor de buena fe de los bienes sobre el tenedor de los documentos repre
sentativos.
5. Valores mobiliarios
Aspectos Económicos: De acuerdo al empleo financiero que se efectúa, los títulos valores se
pueden clasificar en Efectos de Comercio (Letra, Cheque, Pagaré: Operaciones Aisladas para
facilitar Giro del Negocio) y Valores Mobiliarios (Títulos Seriales para Fínanciamiento de Pro
yectos de Inversión).
Definición.- El art. 3 del D.S. N° 020-2023-EF- TUO de la Ley del Mercado de Valores (LMV),
establece que son valores mobiliarios aquellos emitidos en forma masivay libremente nego
ciables que confieren a sus titulares derechos crediticios, dominiales o patrimoniales, o los de
participación en el capital, el patrimonio o las utilidades del emisor. Asimismo, el art. 85 de la
misma norma establece que los valores pueden ser representados por anotaciones en cuenta
o por medio de títulos, independientemente que se trate de valores objeto de oferta pública
o privada.
Características: Estas dos disposiciones contienen los siguientes elementos configurativos:
a) Se trata de valores libremente negociables;
b) Se trata de valores emitidos en forma masiva;
e) Se trata de valores que confieren a sus titulares derechos crediticios, dominiales o patri
moniales, o los de participación en el capital, el patrimonio o las utilidades del emisor; y,
d) Atendiendo a su aspecto formal, pueden representarse tanto mediante títulos como por
anotaciones en cuenta.
De las características antes expuestas conviene resaltar dos: la negociabilidady la emisión masiva.
Derechos Patrimoniales que contiene: Derechos crediticios (Cambiarios); derechos d om i
niales o patrimoniales (Representativos); derechos de participación en el capital, patrimonio
o utilidades del emisor; derechos de participación de patrimonios autónomos o fideicom i
sos; fideicomitente, fiduciario, fideicomisario (titular del Derecho); derechos referidos a otros
valores mobiliarios e instrumentos financieros; derechos referidos a índices de otros valores
mobiliarios e instrumentos financieros.
Forma de Representación de los Valores Mobiliarios: Representación de los Valores en Tí
tulos: incorporación de los derechos al título; debe observar los requisitos establecidos en la
LMV.
Representación por Anotación en Cuenta: La constitución de derechos se efectúa mediante
anotación en cuenta contable; la transferencia será contable; tendrá igual efecto que la tra
dición de títulos; la inscripción hace oponible a terceros; una vez anotado es irreivindicable
Modo de Agruparlos: Pueden estar agrupados en clases, que tienen identidad del contenido
de derechos; cada clase puede subdividirse en series, éstos tienen identidad del contenido
de derechos, pero diferente valor nominal, o diferente fecha de emisión (por intereses que
devengan)
