Clasificación Segal de los valores mobiliarios
Valores Representativos de Derechos de Participación
a) Acciones: Es alícuota parte del capital social, se crea mediante acto constitutivo o
acuerdo de junta; y su emisión es mediante su suscripción (Arts. 83 y 84 LCS); la co
locación de Acciones puede efectuarse a la par, con prima o bajo la par (Art. 85 LCS);
los derechos que contiene son la de participar en el reparto de utilidades, votar en las
juntas generales, entre otros (Arts. 95 y 96 LCS); son títulos valores nominativos (Arts.
92y 93 LCS); pueden estar representados en Certificado de Accionesy/o anotaciones en
cuentas (Art. 100 LCS) y se suelen clasificaren acciones Ordinariasy Privilegiadas (Arts.
94 al 97 LCS).
b) Certificados Provisionales y otros Valores permitidos por LCS.- Certificados Provisio
nales (art. 100); Partes del fundador (Artículo 72); Títulos que incorpora retribución por
prestaciones Accesorias (artículo 75); Títulos de Participación (artículo 104).
c) Acciones de Inversión (Ley 27028).
d) Certificados de Suscripción Preferente: Contiene el derecho de suscripción de acciones
y bonos convertibles en igual condición de accionistas, que tienen derecho a mantener
su participación en el capital social. Los titulares son los Accionistas; y titulares de bonos
convertibles (LMV); la emisión es obligatoria en aumentos de Capital de inscritos en Bol
sa, 15 días después de acuerdo. El plazo para el ejercicio del derecho según la LCS es no
menor a io días después del Aviso; la LMV señala el plazo no menor a is ni mayor a 60 días
a partir del acuerdo.
e) Certificados de Participación en Fondos Mutuos de Inversión en Valores: Fondo Mu
tuo: Patrimonio autónomo integrado por aportes. Adm inistrado por Administradoras
de Fondos, su patrim onio dividido en cuotas iguales. La participación representada en
Certificados: El rescate de Participaciones se efectúa cuando solicite el titu lar; el bene
ficio del Participe es el Incremento proporcional del Fondo; la emisión de Certificado
es nominativo representado en títulos o mediante anotación; la calidad de Partícipe,
puede ser originario (suscripción) o derivado (adquisición) y la transferencia se debe
comunicar a la administradora.
f) Certificados de Participación en Fondos de Inversión: Características similares a fondos
mutuos, solo que no es posible el rescate de las cuotas, solo pueden ser transferidas.
g) Valores Emitidos en procesos de Titulización: En principio, la titulización es la emisión
de valores respaldado en flujos dinerarios que brinda un grupo de activos transferidos a
patrimonio fideicometido. Por consiguiente, el proceso de titulización inicia cuando el
originador transfiere el activo al Patrimonio Fideicometido. Posteriormente, la adminis
tradora del Patrimonio emite Valores Mobiliarios (Certificados, etc.) y coloca al público.
Finalmente, la suma colocada se destina al originador y los flujos dinerarios originados
por el activo se usan en pago de obligaciones nacidas de la emisión (alícuota de recurso
provenientes del patrimonio autónomo o amortizar principal e intereses).
