Tema 4: Temas de la especialidad com ercial
III. CONTRATOS EMPRESARIALES
CONTRATO DE ARRENDAMIENTO FINANCIERO O LEASING (Decreto Legislativo N° 299)
Es un contrato que tiene por objeto brindar financiamiento a mediano y largo plazo permi
tiendo que el cliente adquiera un bien de capital que ha seleccionado y le facilita su utilización
por un período de tiempo, a cambio de sumas por alquilery gastos de mantenimiento.
La entidad financiera reconoce al vencimiento el pleno derecho de ejercer la opción de com
pra, abonándole una suma de dinero pactada que constituye el valor residual.
Si el cliente no hace uso de tal opción, debe restituir el bien objeto del negocio o celebrar uno
nuevo.
Deriva de la locución totease, alquiler. Alquiler con opción a comprar, para adquirir el bien que
le indique el cliente, para alquilárselo luego o alquilárselo directamente al fabricante.
A continuación, enumeraremos alguna de las modalidades de este contrato:
Leasing financiero: El banco o financiera compran bienes de equlpoy los pone a disposi
ción de los clientes en arrendamiento.
Leasingoperacional: El fabricante o importador de los bienes dados en alquiler, efectúan
una locación revocable dentro de un cierto período de alquiler, mediando un preaviso.
Lease back: Es una operación de leasing inversa, donde el propietario vende un inmueble
a una financieray luego esta en el mismo acto celebra un contrato de arrendamiento con
dicho propietario garantizando de esa manera la liquidez de dicha operación.
Lease and purchase: Alquilar y comprar. Ejemplo: el fabricante concede material que se
alquila a una empresa.
Se distingue del alquiler tradicional porque en el Leasing se da en locación algo que ya
pertenece al propietario y no se compra a pedido del usuario para luego alquilárselo. En
el arrendamiento el locador está obligado a entregar el bien en buen estado y asumir su
reparación en caso de deterioro. En el leasing no existe esta obligación.
El leasing propicia la adquisición de bienes de capital y la colocación de bienes muebles o
inmuebles.
Con relación a las operaciones de arrendamiento financiero de bienes inmuebles consti
tuyen una buena alternativa; sin embargo, para su correcta aplicación debe establecerse,
un marco legal más específico.
Existe una legislación sobre el tema, como por ejemplo, el Decreto Legislativo 299y su corres
pondiente reglamento. Lo que falta es que se brinde más características, más requerimientos.
Todo lo anterior, junto a una estrecha colaboración de las empresas de intermediación finan
ciera, permitiría a un sector de la población realizar mayores operaciones de leasing.
Remitiéndonos al derecho comparado, podemos apreciar que el leasing Inmobiliario ha
permitido en muchos países desarrollados el despegue de la actividad Industrial, finan
ciando sus programas de construcción. Es decir, un banco o una financiera adquieren un
inmueble a solicitud del cliente, con el objetivo de construir un edificio destinado a la
actividad industrial o comercial.
