UBILEX
Leasing inm obiliario Es un contrato a largo plazo y se gestiona a través de una entidad
del sistema financiero. Esta es propietaria del inm uebley cede su uso al inquilino por un
tiempo determinado entre ambosy además le cede el derecho de concretar la compra al
final del contrato pagando un precio mucho menor. Este precio final dependerá del mon
to de las cuotasy del tiempo en que se financie.
Esta modalidad de leasing es nueva en nuestro país, a través del Decreto Legislativo N°
1177 publicado en el diario El Peruano con fe ch a i8 de julio de 2015 se establece el Régimen
de Promoción del Arrendamiento para Vivienda, éste genera tres modalidades nuevas
para el mercado inmobiliario: 1. Contrato de arrendamiento de inmueble destinado a vi
vienda. 2. Contrato de arrendamiento de inmueble destinado a vivienda con opción de
compra. 3. Contrato de arrendamiento - financiero (leasing) de inmueble destinado a vi
vienda.
CONTRATO DE FRANQUICIA
Denominado también Contrato de Franchising, cuyas características son que una de las par
tes llamado franquiciante, propietario de una marca, tecnología, nombre comercial, lema o
invento, permite que la otra parte denominada franquiciado pueda usar, explotar o comercia
lizarlo, contra el pago de una franquicia o regalía. Generalmente, este modelo de contratación
se utiliza para acceder al mercado con clientela asegurada, en virtud de la legitimación comer
cial del franquiciante.
Clases:
La clasificación fundamental es la que atiende a la naturaleza del objeto de la franquicia, dis
tinguiéndose cuatro grupos:
a. Franquicia de producción.- Se denomina así a aquella en la que el franquiciador es el
fabricante de los productos vendidos a través de la red de franquiciay distribuidor de los
mismos.
b. Franquicia de distribución.- Llamada así a aquel sistema de franquicia en el que el fran
quiciador no es el productor, sino que hace las veces de control de compras, solucionando
o comprando los productos a los proveedores y revendiéndolos a sus franquiciados. En
realidad, el franquiciador asume el papel de difusor introduciendo un producto en el cir
cuito de distribución sin ser su productor.
c. Franquicia de servicios.- Es aquel sistema de franquicia en el que el franquiciador trans
mite a sus franquiciados los métodos técnicos o procedimientos por él utilizados para la
gestión del negocio así como el uso de la marca que simboliza una fórm ula novedosa y
original, diferenciada en la prestación del servicio. Se considera a esta franquicia como
la más pura aplicación de la técnica comercial, así como la más vulnerable por ser la más
fácil de imitar.
d. Franquicia industrial.- El franquiciador transmite al franquiciado su tecnología y saber
hacer para que éste fabrique los productos que luego comercializará bajo la norma del
franquiciador.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
