-- 739 of 1506 --

T e » 4: Temas de la especialidad comercial
Elementos del contrato:
a. Elementos personales.- La franquicia es un contrato de colaboración entre empresarios,
franquiciadory franquiciado, independientes y jurídicamente iguales.
Podrán ser franquiciadores y franquiciados las personas jurídicas legalmente constitui
das y las personas físicas con capacidad para ejercer el comercio.
El franquiciadores una persona clave en el contrato, ya que la garantía de la franquicia es
suimagen, laoriginalidaddesús productosyel éxitodesutécnica.
b. Elementos reales.- Se considera los siguientes:
• Transmisión del Know-how al franquiciado, entendiendo éste como un conjunto de
conocimientos de carácter comercial, técnico, administrativo o financiero.
• La cesión de una marca, nombre comercial y otros signos distintivos.
• La asistencia técnicay/o comercial al franquiciado.
c. Elementos formales.- La franquicia es un contrato consensual que no requiere forma es
pecial para producir efectos jurídicos, pero es usual que conste por escrito en términos
clarosyen el idioma del franquiciado, especialmente porque contiene acuerdos y estipu
laciones que regirá la relación jurídicamente las partes, siendo importante a la hora de re
solver los conflictos que se susciten entre ellos. En muchos casos el contrato de franquicia
va precedido de un precontrato en el que se establecen las primeras obligaciones de las
partes.
Son derechos de las partes:
Son derechos del franquiciante o franquiciador:
a. Exigir el pago de la remuneración convenida.
b. Vigilar que no se perjudique la imagen del producto, marca o nombre objeto de la fran
quicia.
c. Hacer que se respeten los derechos de propiedad industrial.
d. Tener acceso a la documentación e información necesaria para un adecuado control.
e. Exigir que el franquiciado cumpla con las disposiciones sobre producción, políticas de
ventas, precios y manuales operativos.
Son derechos del franquiciado:
a. Que el franquiciante le proporcione oportunamente los productos que va a comercializar
y que éstos sean de la calidady demás condiciones establecidas en el contrato.
b. De convenirse en la exclusividad, asegurarse que el franquiciante no opere en el mismo
mercado directamente o a través de una filial o vendedores.
Obligaciones de las partes:
El franquiciador está obligado a:
a. Poner a disposición del franquiciado los productos, marca o signo distintivo y garantizar
su uso pacífico.
