-- 740 of 1506 --

UBILEX
b. Transmitir al franquiciado una técnica, sistema o procedimiento, fruto de la experiencia
del franquiciadory que constituye su buen hacer en la gestión de un negocio.
c. Suministrar al franquiciado los productos para su reventa cuando las mercancías sean
vendidas exclusivamente por el franquiciador.
d. Respetar el franquiciado la información y asistencia comercial y/o técnica adecuaday ac
tualizada para el buen desarrollo de la franquicia.
f. No interferir en el manejo de la empresa del franquiciado.
g. Mantener una política de precios que le permita asegurar al franquiciado una adecuada
operatividad.
El franquiciado por su lado está obligado a-,
a. Pagar el precio de la franquicia, royalties o porcentajes sobre el volumen de las ventas.
b. Obligación de aprovisionarse del franquiciador o de los proveedores concertados.
c. Observar las instruccionesy directivas del franquiciador, en especial de las relativas al pre
cio de venta, promoción, política comercial, entre otros.
d. Suministrar la información que el franquiciador requiera sobre la situación del mercado y
explotación de la franquicia.
e. Respetar los pactos de exclusividady standar de calidad en la presentación, ventay precio
de los productos y servicios, tal como han sido establecidos en el contrato.
f. Guardar secreto sobre los conocimientos y técnicas transmitidas como parte del Know-
how.
g. Participaren los costes de la publicidad.
h. Corre con el riesgo de la empresay con los gastos de personal y diversos.
i. No hacer uso indebido de las marcas y nombres a los que tiene acceso por el contrato.
Extinción del contrato:
El contrato de franquicia de extingue por las siguientes causas:
a. Vencimiento del plazo fijado en el contrato.
b. Muerte del franquiciado si fuera persona natural o disolución si es persona jurídica.
c. La venta a un tercero.
d. Cambios del accionario o del Directorio.
e. Cesión de los derechos a un tercero sin consentimiento del franquiciador.
f. Incumplimiento de las obligaciones de las partes, que dé lugar a la resolución del contra
to.
