Tema 4: Temas de la especialidad comercial
respectivo en común y disfrutar de sus beneficios, por un tiempo determinado, sin la necesi
dad de constituir una sociedad o persona jurídica.
La esencia de este contrato es el objetivo común de las partes, donde la acción es determinada
por dos o más emprendedores, sin el ánimo de formar una sociedad.
Para Arias Schreiber, el contrato de riesgo compartido es un instrumento contractual que res
ponde a la necesidad de movilizar capitales en busca de alta rentabilidady correlativa reduc
ción de riesgo, en el que las partes se juntan con un criterio de coparticipación que asume las
más diferentes formas y matices.
Las partes aportan para lograr el objeto del contrato, activos tangibles o intangibles que debe
rán ser explotados únicamente en miras al fin específico propuesto.
Ventajas
La ventaja que se reconoce a estos contratos es de ser utilizados para una cantidad ilim itada
de proyectos e inversiones, en las distintas áreas de la minería, hidrocarburos, pesquera, nave
gación, industriasy empresas comerciales en general.
En los contratos bancarios, el riesgo compartido se da especialmente en las operaciones con
templadas en los incisos 8) y z6) del Art. 221o de la Ley General del Sistema Financiero (LGSF).
"8).- Actuar en sindicación con otras empresas para otorgar créditos y garantías, bajo ias responsabi
lidades que se contemplen en el convenio respectivo",
*26),- Celebrar contratos de compra o de venta de cartera."
En el primer caso, los Bancos pueden compartir el riesgo del crédito, actuando en sindicación
con otros Bancos, quienes previo convenio pueden otorgar un crédito importante a uno de sus
clientes comunes. Al aprobarse el crédito, los Bancos asumen un porcentaje de participación,
conforme al cual aportarán el capital prestado, porcentaje que servirá también para determ i
nar su participación en las recuperaciones y beneficios.
En el segundo caso, los Bancos pueden celebrar contratos de participación en la venta de car
tera pesada, estableciéndose en los contratos la forma de asumir el riesgo compartido, en los
casos de cartera no recuperada.
CONTRATO DE FA CTO R IN C
Es un contrato de ejecución continua, consensual, bilateral, oneroso, conmutativo, por adhe
sión, por el cual la entidad financiera se obliga frente a una empresa a adquirirle todos los
créditos que se originen normalmentey de una manera constante en su negocio por venta de
mercaderías durante un período de tiempo expresamente convenido, pero pudiendo reservar
se la facultad de seleccionar esos créditos y abonar por los mismos un precio fijado mediante
una proporción establecida sobre su importe y a prestar determinados servicios como infor
mación, asesoría legal y contabilidad.
Permite al cliente obtener recursos líquidos, inmediatos y servicios complementarios a la fi
nanciación propiamente dicha, que pueden ser necesarios para racionalizar a la empresa o
modernizarla.
