UBILEX
El intermediario financiero tiene por función efectuar a favor del fabricante o comerciante la
tarea de gestión y cobro de sus créditos comercialesy la prestación de un conjunto de servicios
especializados.
El comerciante debe transferir la totalidad de las facturas que tenga para cobrara plazo al fac
tor, quien si está de acuerdo en aceptar la lista de clientes cuyas facturas fueron transferidas,
se encarga de cobrarle.
Garantiza incluso, ante la mora del deudor, el buen resultado de la operación a cambio de una
comisión que cobra por riesgo que él asume y los servicios que presta. El Banco se encargará
de la cobranza de los créditos, permitiendo la descongestión administrativa y asumiendo el
riesgo de la insolvencia del deudor.
La adquisición por el factor de créditos por cobrar, es en propiedad y no en garantía, consti
tuyendo una fuente de financiamiento para capital de trabajo, con anticipación del valor de
cuentas pendientes. Permite la asunción de los riesgos de insolvencia de los deudores de los
créditos cedidos, previa selección por parte del factor y también se ofrecen servicios adminis
trativos, contables y comerciales.
CONTRATO DE U N D E R W R I T I N C
Es el contrato consensual, bilateral, oneroso, no formal, innominado, celebrado entre una
entidad o intermediario financiero denominado underw ritery una entidad, institución o so
ciedad emisora de valores mobiliarios, por el cual la primera se obliga a prefinanciar a la se
gunda, parcial o totalmente, los recursos que se obtendrían como resultado de su colocación,
comprometiéndose a procurar la colocación de tales valores en el mercado, garantizando su
total o parcial suscripción por parte de los inversionistas dentro de un plazo predeterminado,
bajo el compromiso de adquirir a firme el saldo de los valores no colocados en caso que a!
término del plazo del contrato quedaran valores sin suscribir.
Constituye una nueva técnica bancada cuyo vínculo unificante consiste en la financiación y
servicios complementarios de asesoramiento que obtiene una de las partes.
Se celebra con todos los títulos del mercado de capitales (principalmente acciones y bonos),
permitiendo la obtención de capital sin esperar la colocación paulatina de los valores y la u ti
lidad para el tomador de las emisiones, generándose un diferencial entre la suma pactada
con la sociedad emisora y el precio de colocación de los valores y la comisión pactada por la
misma.
CONTRATO DE K N O W H O W
Es un contrato atípico en el sentido de que no existe legislación específica. Según Angel Soria
"El Contrato de Know How es el acuerdo de voluntades mediante el cual una parte se obliga
a transmitir, de manera temporal o definitiva, conocimientos, procedimientos o experiencias
de orden técnico o comercial, generalmente, a cambio de una retribución, llamada también
regalía. En el ámbito comercial, lo usual será que el Contrato de Know How sea a título one
roso y por ende, se pacte el pago de una retribución a cambio de los conocimientos que se
confieren. Sin embargo, en opinión que compartimos, autores como Cabanellas, expresan
que “La obligación de pagar regalías, como contraprestación por la licencia recibida, puede
ser eliminada, sin que se altere la esencia del contrato”. Es decir, el pago de una retribución o
