Tema 4: Temas de la especialidad comercial
Iregalía no constituye un elemento esencial del contrato de Know How, dado que éste podría
celebrarse a título gratuito.”5
E le m e n to s esen ciales del K n o w H o w 6: El único elemento esencial del Contrato de Know How
es la cesión del conocimiento que debe cumplir con lo siguiente:
a) Cesión o transmisión del conocimiento: El conocimiento, la técnica, el procedimiento, la fór
mula o la experiencia, podrá ser objeto de una cesión definitiva o temporal, dependiendo
de la voluntad de las partes. No es necesario que la cesión del conocimiento sea en exclu
siva, dado que el titu la r del conocimiento podría celebrar contratos similares con.otras
personas o empresas.
b) Conocimiento no patentado.- El conocimiento objeto del Contrato de Know How debe ser
no patentado. En consecuencia, dicho conocimiento podría ser: (i) patentable siempre
que no se haya patentado o (ii) no patentable (porque no reúne los requisitos para dichos
efectos).
c) Conocimiento debe ser secreto-. El conocimiento debe mantenerse en reserva, es por ello que
el titu la r de él deberá llevar a cabo una serie de actos tendentes a conservar fuera del
alcance de terceros o personas no autorizadas, tal información. El conocimiento y/o in
formación materia del contrato, debe permanecer en secreto en el sentido que sólo es
de conocimiento de ciertas personas, quienes en principio son las partes del contrato y
sus colaboradores (trabajadores o contratistas autorizados). Como consecuencia de esta
característica, es usual que los contratos de Know How incorporen una cláusula de confi
dencialidad que resulte exigible incluso después de culminada la relación contractual.
d) Conocimiento debe ser substancial. Se refiere, como lo expresa Chervin de Katz, a conoci mien
to “que incluye información importante para la venta de mercaderías o el suministro de
servicios a consumidores finales y, en particular para el procesamiento y presentación de
mercadería”. Es decir, información relevante que puede estarvinculada a nuevos procesos,
procedimientos, técnicas y estrategias. El transmitente del Know How desea que su pro-
piedady sus conocimientos guarden ciertos esquemas de producción y distribución en lo
que respecta a la utilización y explotación de él, es entonces así que debe acompañar la
transmisión del Know How con una serie de recomendaciones brindadas en información
para que pueda lograrse un adecuado manejo.
e) Conocimiento debe ser útil: El Know How tendrá valoreconómico en el mercado sólosi apor
ta un mejoramiento para el desarrollo de la actividad comercial o industrial, ya que de
otro modo no tendría ningún atractivo para su obtención por parte de los agentes econó
micos.
f) Conocimiento debe ser identificado: Como lo sostiene Calegari, el conocimiento es identifi
cado “por el hecho que el Know How deba estar descrito de una manera suficientemente
completa para perm itir verificar que cumple las condiciones de secreto y substancial idad.
