UBILEX
Diferencia entre el Contrato «Know How»y el contrato de prestación de servicios:
La nota distintiva entre el contrato de «know how »y el contrato de prestación de servicios
radica en que en este últim o el locador presta los servicios, esto es, despliega una actividad en
favor del prestatario o comitente, que puede requerir que haga uso de conocimientos exper
tos, habilidades y conocimientos especiales, pero que no los transmite (cede) a la otra parte;
mientras que el «know how» encierra la trasmisión de conocimientos especializados a través
de instrucciones, fórmulas, planos, modelos, diseños, dibujos, etcétera, en el que el cedente
no realiza nada más que no sea suministrar información especializada. RTF 01826-10-2023
del 03.03.2023.
CONTRATO DE SEGUROS
El artículo 1 de la Ley N° 2 9 9 4 6 - Ley del Contrato de Seguro (LCS) define el contrato de seguro
como aquel por el que el asegurador se obliga, mediante el cobro de una prim ay para el caso
de que se produzca el evento cuyo riesgo es objeto de cobertura, a indemnizar dentro de los
límites pactados el daño producido al asegurado o a satisfacer un capital, una renta u otras
prestaciones convenidas.
Así la aseguradora asume el riesgoy se compromete a indemnizar al contratante, asegurado o
beneficiario en caso suceda un siniestro (evento que afecte sus bienes, saludo vida) que es cu
bierto por el seguro contratado (enfermedades, robo, accidentes, daño sobre una propiedad,
etc) hasta el monto que se haya pactado.
El pago por el seguro se denomina prima y puede realizarse en una sola cuota o en pagos
fraccionados.
El contrato de seguro cubre cualquier riesgo siempre que al tiempo de su celebración exista un
interés asegurable actual o contingente.
Principios que regulan el contrato de seguro;
El contrato de seguro se rige por los siguientes principios-,
a) Máxima buena fe. Las partes del contrato deben actuar con la máxima transparencia y ve
racidad posible en el cumplimiento de sus obligaciones.
b) Indemnización. No debe exceder el monto del daño sufrido o el valor asignado por las par
tes al interés asegurado, evitando que el seguro se utilice como medio de lucro.
c) Mutualidad. Los riesgos se compensan en virtud de la ley de los grandes números, pero se
conservan individualmente desde el punto de vista jurídico.
d) Interés asegurable. Objeto del contrato y se basa en una relación lícita de carácter econó
mico entre el objeto cubierto y el asegurado. El interés es un factor determinante para la
existenciay validez del contrato de seguro.
e) Causa adecuada. Causa directa e inmediata de la pérdida o daño sufrido por el asegurado
(llamada también causa próxima).
Las estipulaciones insertas en la póliza se interpretan, en caso de duda, a favor del asegurado.
