Tema 4: Temas de la especialidad comercial
C aracterísticas:
Es un contrato consensúa!.-El contrato de seguro queda celebrado por el consentimiento de
las partes aunque no se haya emitido la póliza ni efectuado el pago de la prima. No afecta
el carácter consensual del contrato posponer el inicio de la cobertura del seguro. (Art. 4
LCS)
Es un contrato por adhesión - El contrato de seguro se celebra por adhesión, excepto en las
cláusulas que se hayan negociado entre las partes y que difieran sustancialmente con las
preredactadas (Artículo III). La intermediación a cargo del corredor de seguros no afecta
la naturaleza del seguro como contrato por adhesión (Artículo IV.3ero LCS).
Clases:
Seguros patrimoniales o dedaños-Su final idad es repararuna pérdida sufrida en el patrim o
nio del contratante, como: los seguros de incendio, automóviles, entre otros.
Seguros de vida.-Su objeto es la protección de la vida del asegurado, pudiendo pactarse
el pago de la indemnización a la muerte o la sobrevivencia del asegurado en una fecha
determinada, como los seguros de vida y de accidentes personales.
Partes:
El asegurado. La persona cuya vida, salud o bienes se están asegurando.
La aseguradora. La empresa de seguros autorizada por la SBS.
El contratante. La persona que firm a el contrato de seguros.
El beneficiario. La persona designada en la póliza por el asegurado o contratante para recibir
la indemnización.
En algunos seguros, el asegurado, contratantey beneficiario suelen ser la misma persona.
Obligaciones de las partes:
La aseguradora está obligada
Obligación de indemnizar la pérdida que sufra el contratantey/o asegurado en la even
tualidad de un siniestro, hasta el monto de la suma asegurada pactada en el contrato.
Entregar la póliza o certificado de seguro al contratante y/o asegurado en el plazo de 15
días de presentada la solicitud de seguro, siempre que sea aceptada.
Realizare! pago de la indemnización del siniestro en los plazos previstos en Ley del Con
trato de Seguro (Ley 2 9 9 4 6 ).
El asegurado está obligado
Completar los cuestionarios o declaraciones que requiera el asegurador, así como a pro
porcionar información completa. La inexactitud u omisión dolosa puede determinar la
nulidad del contrato, entendiéndose que este no se contrató.
Comunicara la aseguradora sobre los cambios con respecto del riesgo asegurado.
Pagar la prima convenida dentro de los plazos pactados.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 745

-- 746 of 1506 --

UBILEX
Comunicaren e! plazo más breve posible la ocurrencia de un siniestro, dentro de los 3 días
de ocurrido en el caso de seguros patrimoniales, y si se trata de un seguro personal, en un
plazo no mayor de 7 días desde la fecha de ocurrencia del siniestro o desde la fecha en que
se toma conocimiento de la existencia del seguro, según sea el caso.
Tomar las medidas necesarias para evitar la ocurrencia del siniestro o dism inuir sus con
secuencias.
Elementos esenciales:
a) La prima, que consiste en el desembolso que tiene que realizar el tomador del seguro,
para recibir el pago de la indemnización en caso de que ocurra el siniestro.
b) La indemnización, que es el desembolso que debe realizarse al beneficiario por la ocu
rrencia del siniestro. Sobre este punto en la doctrina no existe un acuerdo único para de
fin ir la naturaleza indemnizatoria o previsional del contrato de seguros, sin embargo, la
Ley se adelanta al señalar que ésta, es de naturaleza indemnizatoria.
c) La póliza, que es el documento que prueba la existencia de la celebración del contrato
de seguro, el cual va a contener los derechosy obligaciones a las que se comprometen las
partes. Está compuesto por:
Condiciones generales: Cláusulas establecidas por la aseguradora para cada tipo de
seguro que son iguales para todos los contratantes.
Condiciones particulares: Contienen información específica sobre el contratantey el
riesgo asegurado, como: identificación de las partes, designación del asegurado y el
beneficiario, descripción de la materia asegurada, la suma asegurada o el alcance de
la coberturay monto.
Condiciones especiales: Disposiciones adicionales que amplían, reducen, aclaran y
en general, modifican el contenido o efectos de las condiciones generales o particu
lares.
Anexos de la Póliza: Por ejemplo, declaraciones de salud, entre otras.
Endosos de la póliza: Modificaciones o nuevas declaraciones del contratante efec
tuadas luego de la emisión de la póliza.
Riesgos inasegurables y riesgos excluidos
El contrato de seguro cubre cualquier riesgo siempre que al tiempo de su celebración exista un
interés asegurable actual o contingente (Art. 2 LCS).
La póliza debe contener los riesgos cubiertosy exclusiones (Art. 26c LCS).
Puede serobjeto de los seguros de daños patrimoniales, cualquier riesgo, si existe interés ase
gurable (Art. 82 LCS).
El asegurador se obliga a resarcir, conforme al contrato, el daño patrimonial causado por el
siniestro, sin incluir el lucro cesante, salvo cuando es expresamente convenido. La obligación
tiene como límite el monto de la suma asegurada, salvo que la ley o el contrato establezcan
algo distinto (Art. 83 LCS).
BALOTAR 10 DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

