Tema 4: Temas de la especialidad comercia''
El asegurador queda liberado si el contratante o, en su caso, el asegurado, o el tercero bene
ficiario, provoca el siniestro dolosamente o por culpa grave, salvo pacto en contrario con re
lación a esta última. Son cubiertos los actos realizados para evitar el siniestro o atenuar sus
consecuencias, por un deber de humanidad generalmente aceptado, por legítima defensa,
estado de necesidad o cumplimiento de un deber legal (Art. 91 LCS).
Cuando no exista interés asegurable al tiempo del perfeccionamiento del contrato o al inicio
desús efectos, el contrato es nulo. En ese caso, el aseguradortienederecho al reembolso de los
gastos (Art. 101 LCS).
Bajo sanción de nulidad, no puede ampararse bajo el seguro de responsabilidad civil la res
ponsabilidad proveniente de actos u omisiones dolosas del asegurado (Art. 108 LCS).
En el seguro de accidentes, está excluido de cobertura el accidente provocado dolosamente
por el contratante, asegurado o el beneficiario (Art. 134 LCS).
CONTRATO DE FIDEICOMISO
El fideicomiso es una relación jurídica por la cual una persona, denominada fideicomitente,
transfiere bienes a otra persona, denominada fiduciario, para la constitución de un patrim o
nio fideicometido, sujeto al dominio fiduciario de este últim o y afecto al cumplimiento de un
fin o fines específicos a favor de un tercero o del propio fideicomitente, a quienes se denomina
fideicomisarios.
Sujetos:
a. FIDEICOMITENTE, que es el propietario de un bien, sobre el que constituye portestamen-
to uotro acto jurídico, un patrimonio fideicometido, para el cumplim iento de un fin espe
cífico.
b. FIDUCIARIO, que es la persona a favor de quien se transfieren los bienes.
c. FIDEICOMISARIO, que es la persona a favor de quien se realizan los fines del fideicomiso,
es el beneficiario directo del contrato, el cual puede ser el mismo fideicomitente.
Los Bancos pueden desempeñarse como fiduciarios, de acuerdo con lo dispuesto en el Art.
242o de la Ley CSF.
Características:
El contrato de fideicomiso consta de una relación jurídica patrimonial constituida por
elementos tanto reales como obligacionales, teniendo sus efectos un mismo fundam en
to causal. De esta manera, la causa o motivo generador del fideicomiso establece un solo
vínculo entre las partes contratantes, se crea así el efecto práctico querido por las partes-,
en lugar de la existencia de dos tipos de contratos, uno de efectos reales y otro de efectos
obligacionales, vinculados entre sí y que determina la constitución de un contrato com
plejo.
Es un contrato de confianza, puesto que el fideicomiso es un contrato ¡ntuitu persemae.
Patrimonio fideicometido.- El patrimonio fideicometido está constituido por los bienes
transferidos en fideicom isoy por los frutos que éstos generen. El patrimonio fideicometido es
distinto al patrimonio del fideicomitente, del fiduciario, del fideicomisario, de cualquier otro
