UBILEX
patrimonio fideicometido administrado por el fiduciario y, de ser el caso, del destinatario del
remanente.
Dominio fiduciario.- El dominio fiduciario es el derecho de carácter temporal que otorga al
fiduciario las facultades necesarias sobre el patrimonio fideicometido, para el cumplim iento
del fin o fines del fideicomiso, con las limitaciones establecidas en el acto constitutivo, según
lo señalado en el Art. 252° de la LCSF. El dominio fiduciario se ejerce desde la transferencia de
los bienes objeto del fideicomiso, salvo disposición contraria establecida en el acto constituti
vo, hasta el término del fideicomiso.
IV. M E R C A D O D E V A L O R E S
Concepto: El Mercado de Valores es un conjunto de instituciones y agentes financieros los
cuales negocian los distintos tipos de activos (acciones, fondos, obligaciones, etc.) a través de
los instrumentos creados específicamente para ello.
Son los lugares en donde los agentes a través de los intermediariosy usando los instrumentos
específicamente desarrollados intercambian activos entre sí, facilitando la transparencia y li
bertad de cualquier ciudadano a realizar compras o ventas de valores.
El objetivo fundamental de los mercados de valores es ayudaren cierta medida al movimiento
de capitales contribuyendo así a la estabilidad monetariay sobre todo a la financiera.
