En el marco jurídico del Mercado de Valores se da una característica muy propia, pues la nor
ma reglamentaria no emana del ejercicio de la potestad de reglamentar las leyes que el inciso
8 del artículo 118 de la Constitución Política confiere al Presidente de la República, sino de la
delegación otorgada a CONASEV (hoy SMV) para dictar las normas reglamentarias mediante
resoluciones que, obviamente, tienen una jerarquía inferiora la de los decretos supremos con
los cuales se reglamentan las leyes. Es, pues, mediante las resoluciones de la CONASEV (hoy
SMV) y las que la Bolsa puede dictar, también por delegación, como se regula el Mercado de
Valores en nuestro país.
A estas normas escritas regulatorias deben adicionarse los usos y prácticas que, como normas
consuetudinariassecundum legen o praeter legen, regulan también las operaciones del mercado.
M ercado p rim a rio .- En el mercado primario, las empresas que requieren financiamiento acu
den al público a presentarles proyectos de inversión para el cual requieren recursos. Depen
diendo del caso, solicitan que le presten dinero, es decir que se asocien con ellas para llevar a
cabo el negocio.
M ercado se c u n d a rio .- El tenedor de un activo (siempre que este activo pueda ser calificado
como valor mobiliario) desea deshacerse de él a cambio de un precio. El ejemplo típico es el
de las transacciones en una bolsa de valores.
Ambos mercados son importantísimos. En el mercado primario, las empresas consiguen re
cursos para llevar a cabo sus actividades, pero esto no sería posible si no existiera un mercado
secundario. En el mercado secundario, los inversionistas liquidan su posición y obtienen nue
vamente sus recursos
O p e ra cio n e s b u rsá tile s
N a tu ra le z a : Las operaciones en el mercado de valores constituyen actos de carácter jurídico,
cuyo objeto es la traslación de dominio de un título valor, con la finalidad de obtener una u tili
dad en función del incremento de precios de los valores mobiliarios que se espera que ocurra,
o una renta representada por intereses en el caso de tratarse de valores de renta fija.
N o ció n: En su noción más lata las operaciones de Bolsa de Valores vienen a ser aquellas que
se realizan en la rueda de bolsa y en los demás mecanismos de negociación organizados por
la bolsa y que funcionen en su recinto y, si bien tienen el carácter de mercantiles, tienen un
ámbito privativo determinado por la propia Bolsay la presencia de intermediarios bursátiles.
P rin cip a le s o p eracio n es b u rsá tile s
Las operaciones bursátiles pueden ser clasificadas atendiendo al momento dentro del cual
pueden ser liquidadas las operaciones;
Al momento dentro del cual pueden ser liquidadas las operaciones.
Las operaciones “al contado”, en las cuales se busca que la ejecución se haga de forma
inmediata, aunque por razones prácticas se liquida dentro de un plazo establecido regla
mentariamente para tal efecto.
Las operaciones “a plazo”, en las que se difiere el cumplim iento a un término. Estas pue
den ser:
