• a “plazo fijo” (cuando el plazo deba necesariamente transcurrir).
• a “voluntad” (cuando las partes deciden el momento para liquidar la operación).
• “diferenciales" (cuando al vencimiento las partes no ejecutan la operación sino entre
gan y reciben, el diferencial entre el precio de la concertación y el precio del venci
miento).
• “con prim a” o “sin prim a” si existe o no un acuerdo mediante el cual se faculta a una
de las partes a pagar una “prima” o un “premio” y liberarse del cumplim iento de la
obligación asumida.
Según si el mercado donde se celebra garantiza o no su cumplimiento: se clasificación en
operaciones “al contado”y operaciones de “reporte”
Según sea que (se compongan o no de dos operaciones distintas), puede considerarse a la
operación “al contado”y operación de “reporte”.
Según si el mercado donde se celebra garantiza o no su cumplimiento, puede considerar
se a las operaciones “con garantía del mercado” y operaciones “sin garantía”.
Superintendencia del mercado de valores (SMV)
Antes llamada CONASEV, es un organismo técnico especializado adscrito al Ministerio de Eco
nomía y Finanzas que tiene por finalidad velar por la protección de los inversionistas, la efi-
cienciay transparencia de los mercados bajosusupervisión, la correcta formación de preciosy
ladifusión de toda la información necesaria para tales propósitos. Tiene personeríajurídica de
derecho público internoy goza de autonomía funcional, administrativa, económica, técnicay
presupuestal.
Son funciones de la SMV las siguientes:
a. Dictar las normas legales que regulen materias del mercado de valores, mercado de pro
ductos y sistema de fondos colectivos.
b. Supervisar el cumplimiento de la legislación del mercado de valores, mercado de pro
ductos y sistemas de fondos colectivos por parte de las personas naturales y jurídicas que
participan en dichos mercados.
Las personas naturales o jurídicas sujetas a la supervisión de la Superintendencia de Ban
ca, Seguros y Administradoras Privadas de Fondos de Pensiones (SBS) lo están también a
laSMVen los aspectos que signifiquen una participación en el mercado de valores bajo la
supervisión de esta última.
c. Promover y estudiar el mercado de valores, el mercado de productos y el sistema de fon
dos colectivos.
Asimismo, corresponde a la SMV supervisar el cumplimiento de las normas internacionales de
auditoría por parte de las sociedades auditoras habilitadas por un colegio de contadores públi
cos del Perú y contratadas por las personas naturales o jurídicas sometidas a la supervisión de la
SMV en cumplimiento de las normas bajo su competencia, para lo cual puede impartir disposi
ciones de carácter general concordantes con las referidas normas internacionales de auditoría y
requerirles cualquier información o documentación para verificar tal cumplimiento.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 751 of 1506 --

Tema 4: Temas de la especialidad comercial
Régimen sancionador
El Reglamento de Sanciones- RESOLUCION SMV N° 035-2018-SMV-01 (Pub. el 18/12/2018) re
gula el ejercicio de la facultad sancionadora atribuida a la Superintendencia del Mercado de
Valores - SMV mediante el TUO de su Ley Orgánica, Decreto Ley N° 26126; la Ley del Mercado
de Valores, Decreto Legislativo N °8 6 i; el Decreto Ley N° 21907 sobre Empresas Adm inistrado
ras de Fondos Colectivos; la Ley sobre Bolsa de Productos, Ley N° 26361; la Ley General de So
ciedades, Ley N° 26887; la Ley que promueve el canje o redención de las acciones de inversión,
Ley N° 2873 9; y demás normas que otorguen facultades sancionadoras a la SMV.
La resolución mencionada regula el procedimiento sancionador a cargo de los órganos com
petentes señalados en el Reglamento de Organización y Funciones de la SMV y establece las
sanciones por las infracciones a las normas bajo competencia de SMV.
Están sujetos al presente Reglamento las personas naturales y jurídicas que realicen activi
dades autorizadas por la SMV, así como cualquier otra persona natural o jurídica que deba
cumplir las normas bajo competencia de esta Superintendencia.
Infracciones:
Constituye infracción toda acción u omisión contraria a las leyes, reglamentos y otras dispo
siciones generales o específicas referidas al mercado de valores, mercado de productos y sis
tema de fondos colectivos, así como a las demás disposiciones legales o reglamentarias cuyo
cumplimiento corresponda controlar o supervisar a la SMV; y, que se encuentren tipificadas
como infracción administrativa en los anexos del presente Reglamento.
Las infracciones están clasificadas en muy graves, graves y leves.
Fases del procedimiento sancionador:
Fase instructora (Art.16 Reg).-
a) La fase instructora se inicia con la imputación de cargos por parte de las Intendencias Ge
nerales de Cumplimiento, dándose inicio al procedimiento administrativo sancionador.
La imputación de cargos es irrecurrible.
Las Intendencias Generales de Cumplimiento otorgan a los administrados un plazo de
cinco (5) a quince (15) días para la presentación de descargos, contado a partir del día
siguiente de la notificación de la imputación. El plazo otorgado puede ser prorrogado por
las Intendencias Generales de Cumplimiento por un plazo máximo igual al inicialmente
otorgado, dependiendo de la complejidad del caso.
El administrado puede solicitar el uso de la palabra ante el Intendente General de Cum
plimiento.
Si una vez iniciado el procedimiento sancionador, se identifican actos o hechos que
constituyan otras posibles infracciones, las Intendencias Generales de C um plim iento
deben im putar los cargos correspondientes, de acuerdo con lo establecido en el párrafo
anterior.
Como consecuencia de los descargos o nuevos elementos probatorios, por excepción, las
