cautelares, correctivas y/o provisionales de oficio o a petición de parte en los casos some
tidos a su conocimiento.
e) La resolución final debe pronunciarse respecto de la comisión de la infracción, la aplica
ción de una sanción o la decisión de archivar el procedimiento. Asimismo, puede imponer
medidas cautelares, provisionales o correctivas. El Superintendente Adjunto puede dis
