DERECHOS LABORALES CONSTITUCIONALIZADOS
La constitucionalización del Derecho Laboral tiene especial importancia por las razones si
guientes:
La Constitución es la norma de mayor jerarquía entre las fuentes nacionales y por lo tanto,
incluir en su texto normas de Derecho Laboral significa que se les otorga la máxima impor
tancia.
En segundo término, la constitucionalización del Derecho del Trabajo ha sido, simultánea
mente causa y efecto del reconocimiento de los principales derechos laborales como dere
chos fundamentales.
En tercery últim o término la constitucionalización es importante en relación con la eficacia de
los derechos por ella reconocidos.
Los derechos laborales constitucionalizados en la Carta Magna de 1993 son los siguientes:
Toda persona tiene derecho a trabajar libremente, con sujeción a ley. (Art. z inciso 15)
El trabajo como derecho y deber. (Art. 22).
El trabajo, en sus diversas modalidades, es objeto de atención prioritaria del Estado, el
cual protege especialmente a la madre, al menor de edady al impedido que trabajan.
El Estado promueve condiciones para el progreso social y económico, en especial median
te políticas de fomento del empleo productivo y de educación para el trabajo.
Ninguna relación laboral puede lim itar el ejercicio de los derechos constitucionales, ni
desconocer o rebajar la dignidad del trabajador.
