El trabajador tiene derecho a una remuneración equitativay suficiente, que procure, para
él y su familia, el bienestar material y espiritual. (Art. 24).
La jornada ordinaria de trabajo es de ocho horas diarias y cuarenta y ocho horas sema
nales como máximo. En caso de jornadas acumulativas o atípicas, el promedio de horas
trabajadas en el período correspondiente no puede superar dicho máximo. (Art. 25).
Los trabajadores tienen derecho a descanso semanal y anual remunerados. Su disfrute y
su compensación se regulan por ley o por convenio.
En la relación laboral se respetan los siguientes principios (Art. 26):
1. Igualdad de oportunidades sin discriminación.
2. Carácter irrenunciable de los derechos reconocidos por la Constitución y la ley.
3. Interpretación favorable al trabajador en caso de duda insalvable sobre el sentido de una
norma.
La ley otorga al trabajador adecuada protección contra el despido arbitrario. (Art. 27).
El Estado reconoce los derechos de sindicación, negociación colectivay huelga. (Art. 28).
El Estado reconoce el derecho de los trabajadores a participar en las utilidades de la
empresay promueve otras formas de participación. (Art. 29).
II. PRINCIPIOS DEL DERECHO LABORAL
Son las líneas que orientan de manera directa, la formulación de algunas normas y una serie
de soluciones para los diferentes conflictos laborales.
Son principios del Derecho de Trabajo:
Principio de igualdad de trato: En este sentido, si el empleador otorga a un trabajador un
derecho debería otorgárselo a todos los demás, exceptuando que dicho beneficio esté ampa
rado por alguna situación particular del trabajador.
Principio de irrenunciabilidad de derechos: Es el principio por el cual los trabajadores no
pueden renunciar a las normas que le o torga n o reconocen derechos o beneficios. Este princi
pio nace del carácter protector del derecho laboral.
Principio de estabilidad laboral: Otorga el carácter permanente a la relación de trabajo ha
ciendo depender su disolución únicamente de la voluntad del trabajador, y solo excepcional
mente de la del empleador.
Principio de primacía de la realidad: Es la preferencia de los hechos, de lo que se da en la
realidad, que a los documentos. En caso de discordancia entre lo que ocurre en la práctica y
lo que establecen las formas (pactos, documentos), debe prevalecer la práctica (los hechos).
