Principio de continuidad de la relación laboral: Este principio expresa la tendencia actual
del Derecho Laboral de atribuirle la más larga duración a la relación laboral desde todos los
puntos de vista y en todos los aspectos. La continuidad es una característica que surge de la
naturaleza del contrato de trabajo que es de tracto sucesivo pues no se agota con la realización
instantánea de ciertos actos sino que continúa con el tiempo.
Principio de inmediatez: A través de este principio tanto el empleador como el trabajador
deben comunicarse, sin mediar mayor lapso de tiempo, los actos que signifiquen violación de
obligaciones o derechos laboralesy devengan en actos de hostilidad o causas justas de despi
do. Realizar dicha comunicación de forma extemporánea o no hacerla supondrá el olvido de
los hechos acontecidos y, por ende, tardía cualquier imputación posterior, no siendo factible
reclamar o sancionar los actos olvidados.
Principio de razonabilidad: Se entiende porrazonabilidadal criterio a partir del cual se deter
mina la remuneración de un trabajador en los casos que no pudiera establecer plenamente a
pesar de haber quedado claro la existencia de una relación laboral. En este caso, los tribunales
presumen una remuneración a partir de ciertas circunstancias, tales como: la naturaleza de la
labor efectuada y la remuneración percibida por un trabajador que cumpla una labor seme
jante, etc.
Principio protector: Ante la sobreexplotación del trabajador que es la parte débil de la rela
ción laboral se crea el Derecho del Trabajo con la finalidad de crear condiciones que superen
la desigualdad mediante la intervención del Estado que crea dispositivos legales que protejan
al trabajador. Es por eso que el principio protector es fundamental, de donde se desprenden
otros principios que también apuntan a proteger al trabajador. Según señala Américo Plá, “el
principio protector constituye el núcleo central y básico del sistema”. De no existir este proble
ma de desigualdad, es posible que el Derecho del Trabajo no hubiera aparecido.
Este principio se expresa, según Plá, a través de los principios operativos indubio pro operario, la
aplicación de la norma más favorabley la condición más beneficiosa.
P r in c ip io d e in d u b io pro o p e ra r io : El principio indubio pro operario será aplicable cuando
exista un problema de asignación de significado de los alcances y contenido de una nor
ma. Ergo, nace de un conflicto de interpretación, mas no de integración normativa. La
noción de “norma” abarca a la misma Constitución, los tratados, leyes, los reglamentos,
los convenios colectivos de trabajo, los contratos de trabajo, etc. Pasco Cosmopolis pre
cisa que la aplicación de este principio debe ajustarse a los siguientes dos requisitos: i)
Existencia de una duda insalvable o inexpugnable; ii) Respeto a la ra tio ju ris de la norma
objeto de interpretación (para tal efecto, el aplicador del derecho deberá asignarle un
sentido concordantey compatible con la razón de ésta). El TC considera que la aplicación
del referido principio está sujeta a las cuatro consideraciones siguientes: i) Existencia de
una norma jurídica que, como consecuencia del proceso de interpretación, ofrece varios
sentidos; ii) Imposibilidad lógico-axiológica de dirim ir esta duda mediante la utilización
de cualquier método de interpretación adm itido como válido por el ordenamiento na
cional; iii) Obligación de adoptar como sentido normativo a aquél que ofrece mayores
beneficios al trabajador; iv) Imposibilidad del operador de integrar la norma, ya que el
