consideración de que los derechos y obligaciones concernientes a la relación laboral se
regulan por la voluntad de las partes, manifestada en el contrato de trabajo, sin que en
ningún caso puedan establecerse en perjuicio del trabajador condiciones menos favora
bles o contrarias a las disposiciones legales y convenios colectivos.
ili. DERECHO INDIVIDUAL Y DERECHO COLECTIVO. MARCO NORMATIVO
Derecho Individual: Es el conjunto de normas que regulan el nacimiento, la vida y laextinción
de las relaciones individuales de trabajo. Determinan las condiciones generales de la presta
ción de trabajo, fijan los derechos y obligaciones de los trabajadores y empleadores y señala
regímenes particulares a algunas formas de prestación del trabajo.
Las relaciones individuales de trabajo se encuentran reguladas por el TUO del Decreto Legisla
tivo 728 - Ley de Productividad y Competitividad Laboral (D. S. N° 003-97-TR),y su reglamento,
D. S. N° o o i-9 6 -TR.
Derecho Colectivo: Es el conjunto de normas que regulan la formación y fundaciones de las
organizaciones de trabajadores y empleadores, así como las relaciones entre éstas.
Las relaciones colectivas de trabajo se encuentran reguladas por el TUO de la Ley de Relacio
nes Colectivas de Trabajo- D. S. N°oio-2003-TR,y su reglamento D.S. N° 011-92-TR.
IV. CONTRATO DE TRABAJO
El contrato de trabajo es un acuerdo de voluntades destinado a producir efectos jurídicos en
tre dos partes, trabajadory empleador, vínculo que tiene como características el suministro de
la fuerza de trabajo por parte del trabajador, mientras que el pago de una remuneración y las
facultades de dirigir, fiscal izar y sancionar corresponden al empleador1.
El Contrato de trabajo da inicio a la relación laboral, generando un conjunto de derechos y
obligaciones para el trabajadory el empleador.
Nuestra legislación no da un concepto del contrato de trabajo, sin embargo, menciona los ele
mentos esenciales de éste, conforme lo tenemos en el Art. 4 del D.S. N° 003-97-TR TUO del D.
Leg. N° 728, Ley de Productividad y Competitividad Laboral: “En toda prestación personal de
