Para la existencia del contrato de trabajo es necesario que concurran los tres elementos esen
ciales:
a. P re sta c ió n p e rso n a l d e se rv icio s. Elemento esencial del contrato de trabajo que se tra
duce en el hecho de que el servicio será brindado en forma personal y directa solo por el
trabajador como persona natural2.
