Diferencias con el contrato de locación de servicios:
El Tribunal Constitucional a través de la STC Exp. N° 04840-2007-PA/TC- Huánuco precisa la
naturaleza jurídica de los contratos de trabajo en relación con los contratos civiles de locación
de servicios.
A criterio del Tribunal Constitucional, toda relación laboral se caracteriza por la existencia de
tres elementos esenciales que la definen como tal: (i) Prestación personal de servicios; (ii)
Subordinación; y, (iii) Remuneración.
En contraposición a ello, el contrato de locación de servicios es definido por el artículo 1764o
del Código Civil como un acuerdo de voluntades por el cual “el locador se obliga, sin estar su
bordinado al comitente, a prestarle sus servicios por cierto tiempo o para un trabajo determ i
nado, a cambio de una retribución”, de lo que se sigue que el elemento esencial del contrato
de locación de servicios es la independencia del locador frente al comitente en la prestación
de sus servicios.
