Clases:
CONTRATO DE TRABAJO A PLAZO INDETERMINADO
El contrato de trabajo a plazo indeterminado o indefinido es aquella en donde la prestación
de servicios no tiene un alcance limitado en el tiempo.
El Legislador peruano ha considerado (Art. 4 o D.S. N° 003-97-TR) la presunción de que toda
relación laboral es a plazo indeterminado, admitiendo prueba en contrario.
A este tipo de contrato de trabajo se le denomina contrato típico, además de plazo indetermi
nado, jornada a tiempo completo o a tiempo parcial (mínimo 4 horas diarias) o en promedio,
para un solo em pleadory en la misma cantidad, y al de duración temporal, o modales se le
conoce como contrato atípico. El contrato de trabajo a plazo indeterminado podrá celebrarse
en forma verbal o escrita.
El trabajador alcanza a la protección contra el despido arbitrario, una vez superado el período
de prueba.
Presunción: En toda prestación personal de servicios remunerados y subordinados se presu
me la existencia de un contrato a plazo indeterminado. El contrato individual de trabajo pue
de celebrarse libremente por tiempo indeterminado o sujeto a modalidad. El primero podrá
celebrarse en forma verbal o escrita y el segundo en forma escrita y con los requisitos que la
Ley establece. También puede celebrarse por escrito contratos a tiempo parcial, sin limitación
alguna. Los servicios para ser de naturaleza laboral, deben ser prestados en forma personal y
directa sólo porel trabajadorcomo persona natural. No invalida esta condición queel trabaja
dor pueda ser ayudado por familiares directos que dependan de él, siempre que ello sea usual
dada la naturaleza de las labores.
Período de Prueba: De acuerdo al a rticu ló lo del D.S. N° 003-97-TR, el período de prueba es de
tres (3) meses, a cuyo térm ino el trabajador alcanza derecho a la protección contra el despido
arbitrario. Las partes pueden pactar un término mayor en caso las labores requieran de un
período de capacitación o de adaptación, o, por su naturaleza, o, grado de responsabilidad tal
prolongación pueda resultar justificada. La ampliación del período de prueba debe constar
por escrito y no podrá exceder, en conjunto con el período inicial, de seis meses, en el caso de
trabajadores calificados, o, de confianza; y, de un año en el caso de personal de dirección.
CONTRATO DE TRABAJO A PLAZO FIJO
El Contrato de Trabajo a Plazo Fijo o determinado, es aquella en donde la prestación de servi
cios si tiene una limitación en el tiempo.
Nuestra legislación laboral mantiene como regla general la celebración de contratos de traba
jo a plazo indeterminado, sin embargo, permite que se pacte contratos a plazo fijo a los que se
denomina “Sujeto a Modalidad”.
CONTRATOS DE TRABAJO SUJ ETOS A MODALI DAD
Los contratos de trabajo sujetos a modalidad pueden celebrarse cuando así lo requieran las
necesidades del mercado o mayor producción de la empresa, así como cuando lo exija la natu
raleza temporal o accidental del servicio que se va a prestar o de la obra que se ha de ejecutar,
