en el inciso d) del artículo 77° del Decreto Supremo N.° 003-97-TFI; siendo así, cualquier determinación del
empleador para la culminación de la relación laboral sólo podía sustentarse en una causa justa establecida por
la ley relacionada con la conducta o capacidad laboral del trabajador; de lo contrario se trataría de un despido
arbitrario, cuya proscripción garantiza el contenido esencial del derecho al trabajo, reconocido por el artículo
22° de la Constitución Política",
Las modalidades que contemplan la legislación peruana son (Arts. 5 4 - 7 3 D.S. N° 003--97-TR):
Contratos temporales:
Son contratos de naturaleza temporal y comprende: contrato por inicio o lanzamiento
de una nueva actividad; contrato por necesidad del mercado; contrato por reconversión
empresarial.
• Contrato temporal por inicio o incremento de actividad: El contrato temporal por
Inicio de una nueva actividades aquel celebrado entre un empleadory un trabajador
originados por el Inicio de una nueva actividad empresarial. Su duración máxima es
de tres años.
Se entiende como nueva actividad, tanto el inicio de la actividad productiva, como la
posterior instalación o apertura de nuevos establecimientos o mercados, así como el
inicio de nuevas actividades o el Incremento de las ya existentes dentro de la misma
empresa.
• Contrato temporal por necesidad del mercado: El Contrato temporal por necesi
dades del mercado es aquel que se celebra entre un empleadory un trabajador con
el objeto de atender incrementos coyunturales de la producción originados por va
riaciones sustanciales de la demanda en el merado aun cuando se trate de labores
ordinarias que formen parte de la actividad normal de la empresa y que no pueden
