ser satisfechas con personal permanente. Este puede ser renovado sucesivamente
hasta el término máximo establecido por ley.
• Contrato temporal por reconversión empresarial: Es contrato temporal por recon
versión empresarial el celebrado en virtud a la sustitución, ampliación o modifica
ción de las actividades desarrolladas en la empresa, y en general toda variación de
carácter tecnológico en las maquinarias, equipos, instalaciones, medios de produc
ción, sistemas, métodos y procedimientos productivos.
Contratos accidentales:
Son contratos de naturaleza accidental y comprende: contrato ocasional; contrato de su
plencia; contrato de emergencia.
• Contrato accidental ocasional: El Contrato accidental ocasional es aquel celebrado entre
un empleadory un trabajador para atender necesidades transitorias distintas a la activi
dad habitual del centro de trabajo. Su duración máxima es de seis meses al año.
• Contrato accidental de suplencia: El contrato accidental de suplencia es aquel ce
lebrado entre un em pleadory un trabajador con el objeto que éste sustituya a un
trabajador estable de la empresa, cuyo vínculo laboral se encuentre suspendido por
alguna causa justificada prevista en la legislación vigente, o por efecto de disposicio
nes convencionales aplicables en el centro de trabajo. Su duración será la que resulte
necesaria según las circunstancias.
• Contrato de emergencia: El contrato de emergencia es aquel que se celebra para
cubrir las necesidades promovidas por caso fortuito o fuerza mayor coincidiendo su
duración con la de la emergencia.
Contratos de obra o servicio:
Son contratos de obra o servicioy comprende: contrato específico; contrato intermitente;
contrato de temporada.
• Contrato para obra o servicio específico: Los contratos para hora determinada o servi
cio específico, son aquellos celebrados entre un empleadory un trabajador, con objeto
previamente establecido y de duración determinada. Su duración será la que resulte
necesaria.
• Contrato de servicio intermitente: Los contratos de servicio intermitente son aque
llos celebrados entre un empleadory un trabajador, para cubrir las necesidades de
las actividades de la empresa que por su naturaleza son permanente pero disconti
nuas.
• Contrato de temporada: El contrato de temporada es aquel celebrado entre un em
presario y un trabajador con el objeto de atender necesidades propias del gi ro de la
empresa o establecimiento, que se cumplen sólo en determinadas épocas del año y
que están sujetas a repetirse en periodos equivalentes en cada ciclo en función a la
naturaleza de la actividad productiva. En los contratos de trabajo bajo modalidad
deberán constar por escritoy portriplicado, debiendo consignarse en forma expresa
su duración, y las causas objetivas determinadas de la contratación.
