V. DERECHOS Y OBLIGACIONES DEL EMPLEADOR Y DEL EMPLEADO
Los sujetos en una relación laboral producto de celebrar un contrato de trabajo son: El traba-
jad ory el empresario.
La palabra TRABAJADOR es definida como “una persona que con la edad legal suficiente, y
de forma vol untaría presta sus servicios retri buidos." Los servicios prestados pueden real izarse
dentro del ámbito de una organización bajo la dirección de otra persona física (empleador o
empresario), o bien de un trabajador independiente siendo su propio jefe.
La legislación laboral peruana otorga al TRABAJADOR una variedad de derechos, los cuales
se derivan del contrato de trabajo; estos derechos son: derecho al pago de beneficios tales
como la compensación por tiempo de servicio, vacaciones, gratificaciones, etc. Y así como se
establecen derechos también se establecen obligaciones para el trabajador, teniendo como
principal obligación: obediencia a las órdenes del empleador referidas al objeto del contrato
de trabajo. Además, el trabajador debe actuar de buena fe al realizarla prestación deservicios.
EL EMPLEADOR es la persona física o jurídica que contrata al trabajador por cuenta ajena
para que preste sus servicios a cambio de un salario.
EL EMPLEADOR cuenta con derechos y obligaciones propias de una relación laboral, siendo
el principal derecho el poder de dirección, el cual se compone de la facultad de dirección re
glamentaria (potestad de dictar las órdenes necesarias para la ejecución del trabajo), facultad
de control (potestad de supervisar que las órdenes dictadas sean cumplidas), y la facultad de
sanción donde el empleador puede sancionar disciplinariamente cualquier incumplimiento del
trabajador. Además del poder de dirección el empleador puede hacer uso de ius vam ndi, es decir
tiene la facultad de introducir cambios o puede modificar turnos, días horas de trabajo, así como
la forma y modalidad de la prestación laboral, siempre que se encuentre dentro de los criterios
de razonabilidad, y además teniendo en cuenta las necesidades del centro de trabajo.
