VI. ESTABILIDAD LABORAL
La estabilidad es la protección legal contra las posibilidades de term inar la relación laboral,
busca la permanencia del contrato del trabajo y que el mismo no se extinga por cualquier
causal.
Es en sí el derecho que garantiza el trabajador la conservación de su empleo.
Tipos de estabilidad laboral: Existen dos tipos de estabilidad laboral.
Estabilidad de entrada.- Preferencia por la contratación de duración permanente sobre la tem
poral.
Estabilidad de salida - Protección frente al térm ino de la relación laboral, que sea sólo por cau
sales taxativas prohibiciones del despido injustificado.
La estabilidad de salida puede ser:
a. Estabilidad absoluta: Cuando la violación del derecho a conservar el empleo. Niega efi
cacia al despido y admite la reincorporación forzosa. En el Perú solo cabe en el Despido
nulo por causales señaladas en la ley. O sea que el empleador no puede, en ningún caso,
negar ese reingreso.
b. Estabilidad Relativa. Se configura cuando violado el derecho a conservar el empleo, no
se garantiza la reincorporación efectiva del trabajador. La estabilidad relativa admite una
división pudiendo ser propia e impropia.
b.i Estabilidad relativa propia.- El despido sigue siendo nulo, pero no se persigue di
rectamente la reinstalación efectiva, de hecho, por considerarse que la obligación
del empleador de reincorporar en cuanto obligación personal de hacer, no podría
ser objeto de ejecución forzada en natura y por entenderse, también que en muchos
casos en los que existe un contacto personal más o menos frecuente o intenso entre
empleador y trabajador la reinstalación efectiva resultaría poco razonable y difícil
mente aplicable en la práctica.
b.2 Estabilidad relativa impropia.-Tiende a dificultar o a sancionar pecuniariamente el
acto del despido, pero sin anularlo. El trabajador tiene derecho a una indemnización
especial. En el Perú predomina este tipo de estabilidad.
El Art. 48 de la Constitución de 1979 señala:
“El Estado reconoce el derecho de estabilidad en el trabajo. El trabajador solo puede ser despe
dido porcausa justa, señalada en la ley y debidamente comprobada”, como se advierte de la
norma referida, la Constitución de 1979 recoge las dos modalidades de estabilidad
laboral (de entrada y de salida), hecho que no ocurre con la Constitución de 1993,
