tanto, considerar que la Constitución de 1979 otorga mayor protección al trabajador
al otorgar estabilidad laboral absoluta, es un despropósito, toda vezque, actualmen
te bajo lo dispuesto por la Constitución de 1993, a la luz de las sentencias del Tribu
nal Constitucional, un trabajador goza de estabilidad laboral absoluta, hecho que se
demuestra con la posibilidad de impugnar su despido y solicitar su reposición por
supuestos distintos a los señalados en el despido nulo6.
VI!. CAUSAS DE EXTINCIÓN DE LA RELACIÓN LABORAL
Las causas de extinción del contrato de trabajo son los siguientes:
a) El fallecimiento del trabajador o del empleador si éste últim o es persona natural.
b) La renuncia o retiro voluntario del trabajador.
c) La terminación de la obra o de servicio, el cumplimiento de la condición resolutoria, y el
vencimiento del plazo en los contratos legalmente celebrados bajo modalidad.
d) El mutuo disenso entre el trabajadory empleador.
e) La invalidez absoluta permanente.
f) Lajubilación.
g) El despido, en los casos y formas permitidos por la Ley.
h) La terminación de la relación laboral por causa objetiva en los casos y formas permitidos
por la presente ley (D.S. No0 0 3 -97-TR).
1. DESPIDO
Desde el punto de vista estrictamente conceptual se define o concibe al despido bajo los al
cances del derecho laboral o del derecho del trabajo como la terminación, culminación o ex
tinción de la relación laboral promovida unilateralmente porel empleador, en tal sentido es la
voluntad de la parte empleadora la que origina la ruptura o rompimiento del vínculo laboral
que trae como consecuencia la finalización de la contratación laboral y por ende del contrato
de trabajo cualquiera fuera su naturaleza, sea se trate de un contrato de trabajo a plazo inde
terminado o indefinido; de contratos sujetos a modalidad (también conocidos como contra
