tos a plazo fijo, temporales o determinados) o de un contrato en régimen de tiempo parcial.
Cabe resaltar que el acto que origina el despido, sea de forma justificada o injustificada, es la
propia decisión o voluntad del empleador.
En el Perú, existen dos regímenes de protección frente al despido arbitrario, uno legal y otro
constitucional. El primero encuentra sustento, en lo dispuesto por el TUO del D. Leg. 728- D.S.
N°003-97-TRy el D.S.N0 001-96-TR-Reglamento de la Ley de Fomento al Empleo; paraacceder
al segundo ha de invocarse la vulneración de un derecho fundamental y acudir a la jurisdic
ción constitucional vía un proceso de amparo.
En el caso de la acción de amparo, la protección que se dispensa al trabajador no está referida
a la arbitrariedad del despido, que dependerá de la prueba de la existencia de la causa justa
imputada, sino al carácter lesivo de los derechos constitucionales presente en dicho despido.
1.1. Tipos de Despido en el ordenamiento jurídico peruano
Desde la perspectiva de nuestro marco legal en materia laboral y los pronunciamientos del
Tribunal Constitucional, en algunos casos precedentes vinculantes, sobre el despido se puede
apreciar la presencia de los siguientes tipos de despido:
