1. - Despido Justificado: El despido justificado implica que para el despido de un trabajador
sujeto al régimen laboral de la actividad privada que labora cuatro o más horas diarias (es
por ello que el trabajador con contrato en régimen de tiempo parcial que labora menos de
cuatro horas diarias no tiene derecho a indemnización por despido arbitrario) para un mismo
empleadores indispensable la existencia de causajusta contemplada en la ley y debidamente
comprobada. La causajusta puede estar relacionada con la capacidad o rendimiento del tra
bajador o en todo caso con su conducta o comportamiento, la demostración de la causa justa
corresponde al empleador dentro del proceso judicial que el trabajador pudiera interponer
para impugnar el despido, el despido del trabajador fundado en causas relacionadas con su
conducta o su capacidad no da lugar a indemnización, en caso de presentarse esta clase de
despido lo único que le corresponde al trabajador es el pago o abono de sus beneficios socia
les.
2. - Despido A rb itra rio : El despido arbitrario se configura en dos escenarios: El primero, cuan
do se despide al trabajador por no haberse expresado causa o sin causa (INCAUSADO) o el
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 767 of 1506 --

Tema 5: Temas de la especialidad laboral
segundo, cuando se despide al trabajador sin poderse demostrar la causa invocada en el juicio
o proceso judicial (INJUSTIFICADO). En el casodel despido arbitrario el trabajador tiene dere
cho al pago de una indemnización por despido arbitrario como única reparación por el daño
sufrido, precisamente la citada indemnización es equivalente a una remuneración y media
ordinaria mensual porcada año completo de servicios con un máximo d e iz remuneraciones,
las fracciones se abonan por dozavos y treintavos, según corresponda, su abono procede supe
rado el período de prueba, asimismo el trabajador podrá demandarsimultáneamente el pago
de cualquier otro derecho o beneficio social pendiente. La normatividad establece un plazo de
caducidad de 30 días naturales de producido el hecho para accionar judicialmente la indem
nización por despido arbitrario, sin embargo, los plenos jurisdiccionales y la jurisprudencia es
que se consideren días hábiles. Desde el punto de vista procesal el trabajador debe impugnar
ante la justicia laboral ordinaria el despido bajo la figura o pretensión de indemnización por
despido arbitrario, por lo tanto, el único efecto es resarcitorio, no cabe la reposición en el em
pleo.
2.1. Despido Incausado: Es el despido que se produce cuando el trabajador es cesado o des
vinculado sin expresión de causa o motivación, Este tipo de despido fue reconocido en el
proceso de amparo por despido arbitrario en el caso Telefónica (Sindicato unitario de tra
bajadores de Telefónica del Perú S.A. y FETRATEL) recaído en el Exp. N° 1124-2002-AA/TC,
de fecha 11 de julio de 2002. Sobre este caso, los magistrados sostuvieron que el remedio
establecido en la ley era insuficiente para reparar el despido arbitrario incausado, pues va
cía de contenido la protección constitucional del contenido esencial del derecho al trabajo.
Así, enunció lo siguiente: “Ahora bien, el segundo párrafo del artículo 34° del Texto Único Ordenado
del Decreto Legislativo N °7Z8, Ley de Productividad y C om petitivldad Laboral, Decreto Supremo N.°
003''97-TR , establece que frente a un despido a rb itra rio corresponde una indemnización «como única
reparación». No prevé la posibilidad de reincorporación. El denominado despido ad nutum impone
sólo una tutela indem nizatoria. Dicha disposición es incompatible con la Constitución, a juicio de este
Tribunal, por las siguientes razones:
a. El artículo 3 4 o, segundo párrafo, es incompatible con el derecho al trabajo porque vacía de contenido
este derecho constitucional. En efecto, si, como quedó dicho, uno de los aspectos del contenido esencial del
derecho al trabajo es la proscripción del despido salvo por causa justa, el artículo 34°, segundo párrafo, al
habilitar el despido incausado o arbitrario al empleador, vacía totalm ente el contenido de este derecho
constitucional".
El Tribunal señaló en su resolución aclaratoria que solo el despido incausado es inconstitucio
nal. Luego, el injustificado es ilegal, por lo que permitió que por medio de la vía de amparo
pudiesen proceder las demandas de despido incausado.
Estas precisiones cambiaron luego de que el Tribunal Constitucional estableciera un prece
dente vinculante sobre la procedencia del amparo en caso de despido. Mediante la sentencia
recaída en el Exp. N.° 206-2005''AA (caso «Baylón Flores») señaló que solo procederán las de
mandas de amparo en materia laboral que se sustenten en despidos nulos, incausados o frau
dulentos, en caso que en la víajudicial ordinaria no sea posible obtenervías procedimentales
específicas, igualmente satisfactorias, para la protección del derecho constitucional amena
zado o vulnerado.
