Luego, esto se precisaría en el I Pleno Jurisdiccional Supremo en Materia Laboral, de fechas
4 y i4 d e mayo de 2012, en el cual se señaló que la vía judicial era suficiente para evaluar la re
posición incluso en los casos de despido incausado e injustificado”7. El Pleno acordó: “ Losjueces
de trabajo en los procesos laborales ordinarios regulados por la Ley Procesal del Trabajo, Ley 26636, están
facultados para conocer los procesos de impugnación o nulidad de despido incausado o despido fraudu
lento, que de ser fundado tengan como consecuencia la reposición del trabajador al centro de trabajo.”
2.2. Despido Injustificado: El despido injustificado es cuando la causa del despido de un tra
bajador no puede ser probada. Esta puede existir o no, pero es imposible de demostrarse ante
un tribunal. En tal caso, se considera que la causa no existey el despido no tiene lugar.
3. - Despido Nulo o Nulidad de Despido: Aparece esta modalidad de conformidad con lo esta
blecido en el artículo 29o del Decreto Legislativo N° 728 y como consecuencia de la necesidad
de proteger, entre otros, derechos tales como los previstos en el inciso 2) del artículo 2; inciso
1) del artículo 26o e inciso 1) del artículo 28o de la Constitución.
Se produce el denominado despido nulo, cuando:
Se despide al trabajador porsu mera condición de afiliado a un sindicato o porsu partici
pación en actividades sindicales.
Se despide al trabajador por su mera condición de representante o candidato de los tra
bajadores (o por haber actuado en esa condición)
Se despide al trabajador por razones de discriminación derivados de su sexo, raza, reli
gión, opción política, etc.
Se despide a la trabajadora porsu estado de embarazo (siempre que se produzca en cual
quier momento del periodo de gestación o dentro de los 90 días posteriores al parto).
Se despide al trabajador por razones de ser portador de Sida (Cfr. Ley N° 26626).
Se despide al trabajador por razones de discapacidad (Cfr. Ley 27050).
Por la naturaleza de la vulneración de un derecho fundamental, el trabajador al plantear su
acción judicial de despido nulo o nulidad de despido tiene derecho a la reposición laboral, es
decir, tiene un efecto restitutorio, siendo la única clase de despido en nuestra legislación en
que está permitido el reingreso al centro laboral, inclusive en ejecución de sentencia el traba
jador puede variar el beneficio de la reposición por el de la indemnización similar al monto
indemnizatorio propuesto para el despido arbitrario.
En el caso del despido nulo, si el Juez ordena la reposición el trabajador deberá ser reincorpo
rado en el empleo sin afectar su categoría anterior.
4. - Despido Indirecto: El despido que se produce como consecuencia de un acto de hostilidad
que no ha sido materia de enmienda por parte del empleador a pesar del requerimiento por
escrito del trabajador.
En el artículo 30 del T.U.O del D.L del 728 se establece que son actos «equiparables» al despido
los siguientes supuestos:
