Tema 5: Temas de la especialidad laboral
La falta de pago de la remuneración en la oportunidad correspondiente, salvo razones de
fuerza mayor o caso fortuito debidamente comprobados por el empleador;
La reducción de la categoría y de la remuneración. Asimismo, el incumplimiento de requi
sitos objetivos para el ascenso del trabajador.
El traslado del trabajadora lugar distinto de aquel en el que preste habitualmente servi
cios, con el propósito de ocasionarle perjuicio;
La inobservancia de medidas de higieney seguridad que pueda afectar o poner en riesgo
la viday la salud del trabajador;
El acto de violencia o el faltamiento grave de palabra en agravio del trabajador o de su
familia;
Los actos de discriminación por razón de sexo, raza, religión, opinión, idioma, discapaci
dad o de cualquier otra índole;
Los actos contra la moral y todos aquellos que afecten la dignidad del trabajador.
La negativa injustificada de realizar ajustes razonables en el lugar de trabajo para los tra
bajadores con discapacidad.
Cuando el trabajador sea perjudicado por alguno de estos actos, podrá emplazar por escrito
a su empleador imputándole el acto de hostilidad correspondiente, debiendo darle un plazo
razonable (no menor de seis días naturales) para que se presenten sus descargos o enmiende
su conducta.
Caso contrario, el trabajador podrá darse por despedido y podrá pedir la indemnización, bajo
los alcances de la indemnización por despido arbitrario.
5. Despido Fraudulento: Aparece esta modalidad de conformidad con lo establecido im plíci
tamente en la sentencia del Tribunal Constitucional recaída en el Exp. N.° 0628-2001-AAITC,
de fecha 10 de julio de 2002. En aquel caso se pretendió presentar un supuesto de renuncia
voluntaria cuando en realidad no lo era.
Se produce el denominado despido fraudulento, cuando:
"Se despide al trabajador con ánimo perverso y auspiciado por el engaño, por ende, de manera
contraria a la verdad y la rectitud de las relaciones laborales; aun cuando semumpíe con Im,
imputación de una causal y los cánones procedimentales, como sucede cuando se<ímputa:al¡
trabajador hechos notoriamente inexistentes, falsos o Imaginarios o, asimismo/sejerntribuye5
una falta no prevista legalmente, vulnerando el principio de tipicidad, como lo haiseñalado, enr
este último caso, la jurisprudencia de este Tribunal (Exp. N. 0 415-987-AA/TC, 555-99-AA/TC y
150-2000-AA/TC); o se produce la extinción de la relación laboral con vicio de voluntad (Exp.
N.° 628-2001 -AA/TC) o mediante la "fabricación de pruebas".
m
En estos supuestos, al no existir realmente causa justa de despido ni, al menos, hechos respecto de cuya tras
cendencia o gravedad corresponda dilucidar al juzgador o por tratarse de hechos no constitutivos de causa
justa conforma a la ley, la situación es equiparable al despido sin invocación de causa, razón por la cual este
acto deviene lesivo del derecho constitucional al trabajo.
El Tribunal Constitucional estima que la protección adecuada contra el despido arbitrario previsto en el artículo
27° de la Constitución ofrece dualmente una opción reparadora (readmisión en el empleo) o indemnizato-
ria (resarcimiento por el daño causado), según sea el caso." (STC Exp. N° 976-2001-AA/TC. Caso Eusebia Llanos
Huasco).
