2 Suspensión del contrato de trabajo
Durante el desarrollo de la relación laboral puede haber lapsos en los que el trabajador no
presta labor efectiva. Estos períodos de inactividad producen una suspensión del contrato de
trabajo, en el cual hay un cese temporal a la obligación del trabajador de prestar el servicio y
la del empleadorde pagar la remuneración respectiva, sin que desaparezca el vínculo laboral.
Son causales de suspensión del contrato de trabajo:
La invalidez temporal.
La enfermedad y el accidente comprobados.
La maternidad durante el descanso prey postnatal.
El descanso vacacional.
La licencia para desempeñar cargo cívico y para cumplir con el servicio militar.
El permisoy la licencia para el desempeño de cargos sindicales.
Lasanción disciplinaria.
El ejercicio del derecho de huelga.
La detención del trabajador, salvo caso de condena privativa de la libertad.
La inhabilitación administrativa o judicial por período no superior a tres meses.
El permiso o licencia concedidos por el empleador.
El caso fortuito y la fuerza mayor.
Otros establecidos por norma expresa.
La suspensión del contrato de trabajo puede ser perfecta o imperfecta.
2.1. Suspensión perfecta: Es perfecta la suspensión del contrato de trabajo cuando cesa tem
poralmente la obligación del trabajador de prestar el servicio y la del empleador de pagar la
remuneración respectiva. Ejemplo: El caso fortuito o fuerza mayor, licencias sin goce de haber,
las sanciones disciplinarias, etc.
En el contexto de la emergencia sanitaria decretada por el gobierno ante la pandemia del
COVI19 se emitió el Decreto de Urgencia N° 038-2020 contemplando una excepción según la
cual se puede aplicar la suspensión perfecta de labores cuando el empleador no pueda man-
