tener los vínculos laborales, mediante Decreto de Urgencia N° 087-2021, se amplió la vigencia
de la suspensión perfecta de labores hasta el 02 de octubre de 2021.
2.2. Suspensión imperfecta: Se suspende de modo imperfecto, cuando el empleador debe
abonar remuneración sin contraprestación efectiva de labores. Ejemplo: Los permisos remu
nerados, las vacaciones, la hora de permiso por lactancia materna, etc.
V I I I . R E G ÍM E N E S E S P E C ÍA L E S
1. Régimen laboral de la microempresa
El régimen laboral especial para la microempresa está regulado por el TUO de la Ley
de Promoción de la Competitividad, Formalización y Desarrollo de la Micro y Pequeña
Empresa y del Acceso al Empleo Decente, D.S. N° 013-2013-PRODUCE TUO de la Ley de
Impulso al Desarrollo Productivo y al Crecimiento Empresarial (28.12.2013) y por su Re
glamento, D.S. N° 008-2008-TR (30.09.2008), establece que los trabajadores contratados
bajo dicho régimen no tendrán derecho al pago de las gratificaciones por Fiestas Patrias
y Navidad, tampoco el pago de la CTS ni asignación familiar.
2. Régimen laboral de la pequeña empresa
El régimen laboral especial para la pequeña empresa, se encuentra regulado, al igual
que el régimen de la microempresa, por el D.S. N° 013-2013-PRODUCE TUO de la Ley de
Impulso al Desarrollo Productivo y al Crecimiento Empresarial y por su Reglamento, D.S.
N° 008-2008-TR. No obstante, este régimen otorga a sus trabajadores mayores benefi
cios laborales, dentro de los cuales se encuentran las gratificaciones. Dicha normativa
dispone que los trabajadores de las pequeñas empresas tendrán derecho a percibir dos
gratificaciones en el año, con ocasión de las Fiestas Patrias y Navidad, las cuales serán
equivalentes a media remuneración mensual cada una.
3. Régimen laboral agrario y agrícola
Para el caso del régimen agrario, las normas de la materia, Ley del Régimen laboral agra
rio y de incentivos para el sector agrario y riego, agroexportadory agroindustrial, Ley N°
31110 (31.12.2020) y su Reglamento, D.S. N° N° 005-2021-MIDAGRI, disponen que la tra
bajadora o trabajador agrario cuya jornada laboral es más 04 o más horas diarias en pro
medio a la semana, tiene derecho a percibir una Remuneración Básica mensual no menor
a la Remuneración Mínima Vital de los/las trabajadores/as sujetos al régimen laboral de
la actividad privada. En este aspecto, el empleador debe poner en conocimiento del/la
trabajador/a, al inicio de la relación laboral, la periodicidad y la forma de pago de la re
muneración.
Asimismo, los trabajadores agrarios tienen derecho a participar de las utilidades de sus
respectivas empresas desde el primer día de labores. A tal efecto, se incluye al personal
de las áreas administrativas y de soporte técnico de las empresas. Se les reconoce el pago
semestral o prorrateado de las gratificaciones legales y CTS, a elección del trabajador, el
pago de la asignación familiar, la bonificación extraordinaria por inafectación de las gra-
tificacionesy el seguro de vida, sin perjuicio de los demás derechos aplicables a los traba
jadores del régimen laboral de la actividad privada.
