I 4. Régimen de construcción civil
El régimen de construcción civil contiene características especiales tanto en lo referente a
las condiciones de trabajo, como en su regulación legal.
En la actualidad, el régimen de construcción civil se encuentra normado por el Decreto
Legislativo N° 7Z7 y los convenios colectivos firmados por rama de actividad, el decreto le
gislativo mencionado establece que a aquellos que laboran para Empresas Constructoras
de Inversión Limitada (aquellas que ejecuten obras cuyos costos individuales no excedan
las 50 UIT), y los que laboran para personas naturales que construyan directamente sus
propias viviendas, siempre que la obra no supere el límite de 50 UIT, les serán aplicables
las normas que regulan el régimen laboral común.
Características: Conforme lo ha señalado el Tribunal Constitucional en la Sentencia re
caída en el Exp. N° 0261-2003-AA/TC, en el régimen laboral especial de los trabajadores
de construcción civil, podemos encontrar oz cualidades particulares: a) La eventualidad.
Dado que la relación laboral no es permanente, esta relación dura mientras se ejecute la
labor para la cual los trabajadores han sido contratados o mientras dure la ejecución de la
obra, b) La ubicación relativa. No existe un lugar fijo y permanente donde se realicen las
labores de construcción, desenvolviéndose en diversos sitios, sin fijeza absoluta.
Categorías: Existen 3 tipos de categorías: a) Operarios: En esta categoría están incluidos
los albañiles, carpinteros, tierreros, pintores, electricistas, gasfiteros, plomeros, almace
neros, chóferes, mecánicos, operadores de mezcladoras de winchasy demás trabajadores
calificados, b ) Ayudantes u oficiales: En esta categoría están incluidos los trabajadores
que laboran como auxiliares del operarioy que no han alcanzado la calificación plena en
la especialidad. A tal efecto, se considera como oficiales a los guardianes, tanto si prestan
sus servicios a propietarios como a contratistas o subcontratistas de construcción civil, c)
Peones: Son los trabajadores no calificados, que son ocupados indistinta mente en diver
sas tareas de la industria, prestando sus labores con un nivel menor de responsabilidad
en las tareas realizadas por carecer de calificación.
Remuneración: En el régimen de construcción civil los trabajadores son remunerados
por jornales, aunque dependerá de la categoría en la que se encuentren. Este monto se
asignay se acuerda mediante el convenio colectivo negociado en la rama de construcción
civil. La remuneración básica para los trabajadores de construcción civil se creó mediante
Decreto Supremo del 0 2 .0 3 .T945 la cual estableció el jornal básico para cada una de las
categorías de trabajadores de este régimen, estas fueron incrementadas, posteriormente,
mediante una serie de resoluciones y/o actas.
Asignaciones: a) Por escolaridad, esta asignación es equivalente atreinta (30) jornales bási
cos al año, porcada hijo menor de 18 años que curse estudios de nivel inicial, primarios o
secundarios; b) Por fallecimiento, se abona a los familiares del trabajador fallecido durante
el contrato de trabajo es de una (1) UIT, siempre y cuando el costo de la obra presupuesta
da sea igual o mayor a 350 UIT.
Gratificaciones: De conformidad con la Resolución Directoral N° 777-87-DR-LIM, los tra
bajadores de construcción civil tienen derecho a gratificaciones: a) Por Fiestas Patrias, a
