Tema 5: Temas de la especialidad laboral
40 jornales básicos, si es que el trabajador laboró en una misma obra los 07 meses ante
riores, y se abona a razón de 1/7 por mes calendario completo de labor, contando desde
enero a julio, b) Por Navidad, a 40 jornales básicos, siempre y cuando el trabajador haya
laborado 05 meses anteriores a las fiestas de navidad, y se paga a razón de 1/5 por mes
calendario completo laborado en la obra, contando desde agosto a diciembre.
Bonificaciones: En el régimen laboral de construcción civil, podemos encontrar las si
guientes bonificaciones: la bonificación unificada de construcción (BUC) y la bonificación
por alta especialización (BAE), entre otras bonificaciones.
OPERARIO 32%
OFICIAL 30%
PEÓN 30%
Vacaciones: Los trabajadores de construcción civil tienen derecho a 30 días calendario
de descanso vacacional, por cada año de trabajo para un mismo empleador, siempre y
cuando cumplan con los requisitos que menciona el Decreto Legislativo N°713, como son
cumplir con el récord de 260 días efectivos de labor si la jornada es de 06 días a la semana
(si la jornada fuese de 5 días a la semana, se deberá cumpli r el récord de 21 o días efectivos
de labor).
Compensación por Tiempo de Servicios: La CTS para los trabajadores de construcción
civil es equivalente al 15% de las remuneraciones básicas percibidas por el trabajador du
rante el tiempo de servicios que laboró para un mismo empleador. A dicho cálculo tam
bién se le incluyen las horas extras, las cuales son computadas como horas simples y no
como sobretasa.
Extinción del contrato de trabajo: En cuanto al despido o el cese del contrato se aplicarán
las reglas establecidas en el T.U.O del Decreto Legislativo 728, en específico los artículos 23
referidos al despidoy el artículo 16 sobre la extinción del contrato.5
5. Régimen laboral de trabajadores del hogar
El régimen de trabajadores del hogar, está regulado por la Ley de las Trabajadoras y los
Trabajadores del Hogar, Ley N° 31047 (01.10.2020) y su reglamento Decreto Supremo N°
009-2021-TR. El ámbito de aplicación de esta norma está referido a aquellas personas que
realicen labores propias del desenvolvimiento de la vida de un hogar y conservación de
una casa habitación, siempre que no importen negocio o lucro económico directo para
la persona empleadora o sus familiares. Dichas labores incluyen tareas domésticas, ta
les como la limpieza, cocina, ayudante de cocina, lavado, planchado, asistencia, mante
nimiento, cuidado de niñas, niños y adolescentes, personas adultas mayores, personas
enfermas, personas con discapacidad u otras personas dependientes del hogar, cuidado
de mascotas domésticas, cuidado del hogar, entre otras. El monto de la remuneración de
la persona trabajadora del hogar será establecido por acuerdo libre de las partes, pero
no podrá ser inferiora la remuneración mínima vital (RMV) por jornada completa de 08
