derecho a gratificación por Fiestas Patrias y por Navidad, siendo cada ana equivalente al
monto total de la remuneración mensual.
6. Régimen laboral de los trabajadores extranjeros
La Ley para la Contratación de Trabajadores Extranjeros, D. Leg. N° 6 8 9 (05.11.91), dispone
que la contratación de trabajadores extranjeros está sujeta al régimen laboral de la acti
vidad privaday a los límites que establece dicha norma, así como su Reglamento, D.S. N°
014-92-TR (23.12.92). En razón a lo mencionado, las remuneraciones, beneficios labora
les y, en general, todo beneficio a que tenga derecho un trabajador peruano, deberán ser
igualmente otorgados a los trabajadores extranjeros.
7. Régimen laboral de trabajadores artistas
El régimen laboral de los trabajadores artistas, regulado por la Ley del Artista e Intér
prete Ejecutante, Ley N° 28131 (19.12.2003) y su Reglamento, D.S. N° 058-2004-PCM
(29.07.2004), dispone como obligación el pago mensual de las gratificaciones al Fondo
por Fiestas Patrias y Navidad, el cual se efectuará a razón de un sexto de la remuneración
del trabajador.
8. Régimen laboral de trabajadores a tiempo parcial
Los trabajadores contratados a tiempo parcial tienen derecho a los beneficios laborales
para cuya percepción no se exija el cumplimiento del requisito mínimo de 4 horas diarias
de labor. En razón a lo mencionado, los trabajadores a tiempo parcial tienen derecho al
pago de las gratificaciones legales por Fiestas Patrias y Navidad.
9. Régimen laboral de los trabajadores portuarios
Conforme con lo dispuesto por la Ley del Trabajo Portuario, Ley N° 27866 (16.11.2002), y
el TUO de su reglamento, D.S. N° 013-2004-TR (27.10.2004), el trabajador portuario se
encuentra comprendido dentro del régimen laboral de la actividad privada. En tal sen
tido, a estos trabajadores les corresponderá percibir todos los derechos y beneficios que
perciban los trabajadores sujetos a dicho régimen, con las particularidades de su propio
régimen.
10. Régimen laboral de trabajadores pescadores y de la industria pesquera
Este régimen corresponde a aquellos trabajadores pescadores que aporten a la Caja de
Beneficios y Seguridad Social del Pescador (CBSSP), siéndoles aplicable lo dispuesto por
el D.S. N° 014-2004-TR (15.12.2004), siendo de aplicación supletoria el régimen laboral de
la actividad privada en cuanto no contradiga lo regulado por la legislación mencionada.
Dicha norma dispone que los trabajadores pescadoresy de la industria pesquera tendrán
derecho a percibir por gratificaciones una suma equivalente al 16,66% de la remunera
ción que perci ba el trabajador por el tiempo efectivamente laborado. Es de precisar que el
trabajador sujeto a este régimen podrá retirar libremente lo depositado por concepto de
gratificaciones.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 775 of 1506 --

Tema 5: Temas de la especialidad laboral
IX. REMUNERACIONES, SUELDOS Y SALARIOS
1. Remuneraciones
La remuneración es la contraprestación que percibe el trabajador por haber puesto su capaci
dad de trabajo a disposición del empleador. Constituye remuneración el íntegro de lo que el
trabajador percibe por sus servicios, siempre que sean de su libre disposición. No se conside
ran remuneración los conceptos previstos en el artículo 19o del TUO del D.Leg. N° 650 (D.S. N°
001-97-TR).
Formas de pago:
a) En dinero.
b) En especie.
Condiciones de Pago
En forma directa al trabajador o a través de terceros si el trabajador puede disponer de la
remuneración en forma oportuna.
Se abona luego de prestados los servicios.
El incumplimiento genera interés legal laboral.
El incumplimiento constituye acto de hostilidad.
Forma de determinación
Portiempo.
Por rendimiento o resultado en el trabajo.
Remuneración por hora.
Remuneración integral.
2. Sueldos y salarios
Los sueldosy salarios incluyen el ingreso bruto de los trabajadores o el pago registrado por los
establecimientos en las planillas sin considerar ingresos por pago en especie. La definición de
ingreso incluye todos los pagos hechos sobre la base de los conceptos recibidos en el período
de referencia, incluyendo pagos por horas extras y comisiones; además, los datos son proce
sados antes de deducciones como: impuesto a la renta, pensiones y préstamos. Los sueldos
y salarios corresponden a todos los trabajadores asalariados sujetos al régimen laboral de la
actividad privada registrados en las planillas de los establecimientos de 10 y más trabajado
res. Cabe indicar que la información no incluye aprendices, trabajadores no remunerados, tra
bajadores contratados mediante empresas de servicios y aquellos trabajadores que trabajan
menos de 48 horas a la semana.
La remuneración m ínim a vital
Es el monto remunerativo mínimo que debe percibir un trabajador sujeto al régimen laboral
de la actividad privada que labore por lo menos 04 horas diarias. A partir del 01 de enero del
2025 la RMV es de S/. 1130.00 mensuales (D. S. N° 006-2024-TR).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 775

-- 776 of 1506 --

UBILEX
X. ASIGNACIÓN FAMILIAR
La Asignación Familiar se encuentra normada en la Ley N° 25129 (Pub. 06.12.1989) y su regla
mento D.S. N° 035-90-TR, esta norma establece que todo trabajador que tenga a su cargo uno
o más hijos menores de 18 años percibirá esta asignación familiar. En el caso de que el hijo al
cumplir la mayoría de edad se encuentre efectuando estudios superiores o universitarios, este
beneficio se extenderá hasta que termine dichos estudios, hasta un máximo de 6 años poste
riores al cumplimiento de dicha mayoría de edad.
Para calcular el pago de la Asignación Familiar se tomará en cuenta el 10% de la remuneración
mínima vital vigente a la fecha de otorga reste derecho, este monto se sumará a la remunera
ción que perciba el trabajador.
Ejemplo: Si un trabajador perci be normal mente 1,000 nuevos solesy si éste acredita tener uno
o más hijos, menores de 18 años o en estudios superiores, percibirá adicional mente a su remu
neración el 10% de la remuneración mínima vital vigente en la fecha del pago.
XI. COMPENSACIÓN POR TIEMPO DE SERVICIOS
La compensación por tiempo de servicios tiene la calidad de beneficio social de previsión de
las contingencias que origina el cese en el trab ajo yde promoción del trabajadory su familia.
La compensación portiem po de servicios se devenga desde el primer mes de iniciado el víncu
lo laboral; cumplido este requisito toda fracción se computa por treintavos.
La compensación por tiempo de servicios se deposita semestralmente en la institución elegi
da por el trabajador. Efectuado el depósito queda cumplida y pagada la obligación, sin per
juicio de los reintegros que deban efectuarse en caso de depósito insuficiente o que resultare
diminuto.
La Compensación por Tiempo de Servicios se encuentra regulada por el D. Leg. N° 650 y
su TUO el D.S. N° o o i- 97-TR, conjuntamente con su reglamento el D. S. N° 0 0 4 - 97-TR; sin
embargo, estas normas no agotan todo lo relativo al tema, anotar que para algunos regíme
nes especiales como los trabajadores de construcción civil, trabajadores mineros, artistas,
trabajadores del hogar, trabajadores a domicilio, trabajadores portuarios, pesqueros, los
cuales se regirán por sus propias reglas, pues en algunos casos no corresponderá efectuar
un depósito semestral, y en lo que no esté regulado se aplicará supletoriamente el D. Leg.
650 y su reglamento.
Trabajadores comprendidos: Sólo están comprendidos en el beneficio de la compensación
por tiempo de servicios los trabajadores sujetos al régimen laboral común de la actividad pri
vada que cumplan, cuando menos en promedio, una jornada mínima diaria de cuatro horas.
El derecho a percibir la CTS se configura una vez transcurrido un mes de prestación efectiva de
labores, cumplido este requisito toda fracción se computará por treintavos.
Trabajadores excluidos: No están comprendidos en el régimen de Compensación por Tiem
po de Servicios los trabajadores que perciben el 30% o más del importe de las tarifas que paga
el público por los servicios. No se considera tarifa las remuneraciones de naturaleza imprecisa
tales como la comisión y el destajo.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

