Tema 5: Temas de la especialidad laboral
Los trabajadores sujetos a regímenes especiales de Compensación por Tiempo de Servicios,
tales como construcción civil, pescadores, artistas, trabajadores del hogar y casos análogos,
continúan regidos por sus propias normas.
TRABAJADORES CON DERECHO A CTS
Trabajadores con jomada mayor o igual a 4 horas diarias:
Empleados
Obreros
Trabajadores con contrato a plazo fijo y a plazo indeter
minado
Trabajadores y socios trabajadores de cooperativas
Trabajadores de pequeña empresa
Trabajadores de sociedades civiles
Trabajadores de empresas autogestionarias
Trabajadores extranjeros
Trabajadores en periodo de prueba
Trabajadores dirección y de confianza
Trabajadores del hogar
Trabajadores que perciben una remuneración integral
TRABAJADORES SIN DERECHO A CTS
Trabajadores con jornada menor a 4 horas diarias
Jóvenes comprendidos en modalidad formativa
Trabajadores que perciben 30% o más de la tarifa
Trabajadores de micro empresa
Servidores CAS
Del tiempo de servicios computables:
Sólo se toma en cuenta el tiempo de servicios efectivamente prestado en el Perú, o en el ex
tranjero cuando el trabajador haya sido contratado en el Perú.
Son computables los días de trabajo efectivo. En consecuencia, los días de Inasistencia injus
tificada, así como los días no computables se deducirán del tiempo de servicios a razón de un
treintavo por cada uno de estos días.
Por excepción también son computables:
a) Las inasistencias motivadas por accidente de trabajo o enfermedad profesional o por en
fermedades debidamente comprobadas, en todos los casos hasta por 6 o días al año. Se
computan en cada periodo anual comprendido entre el i de noviembre de un año y el 31
de octubre del año siguiente.
b) Los días de descanso prey post natal;
c) Los días de suspensión de la relación laboral con pago de remuneración por el emplea
dor;
d) Los días de huelga, siempre que no haya sido declarada Improcedente o ilegal; y,
e) Los días que devenguen remuneraciones en un procedimiento de calificación de despido.
Remuneración Computable: Son remuneración computable la remuneración básica y todas
las cantidades que regularmente perciba el trabajador, en dinero o en especie como contra
prestación de su labor, cualquiera sea la denominación que se les dé, siempre que sean de su
