UBILEX
libre disposición. Se incluye en este concepto el valor de la alimentación principal cuando es
'''' proporcionada en especie por el empleadory se excluyen los conceptos contemplados en los
Artículos 19 y 20 (Ley de la Compensación porTiempo de Servicios).
La remuneración computable para establecer la compensación por tiempo de servicios de los
trabajadores empleados y obreros, se determina en base al sueldo o 30 jornales que percibe
el trabajador según el caso, en los meses de abril y octubre de cada año, respectivamente y
comprende los conceptos remunerativos señalados en el artículo precedente.
Las remuneraciones diarias se multiplicarán por 30 para efectos de establecer la remunera
ción computable. La equivalencia diaria se obtiene dividiendo entre 30 el modo mensual co
rrespondiente.
A lim e n ta c ió n .- La alimentación principal otorgada en especie se valorizará de común acuer
do y su importe se consignará en el libro de plan i lias y boletas de pago. Si las partes no se pu
sieran deacuerdo, regirá laque establezca el Instituto Nacional de Alim entacióny Nutrición u
organismos que lo sustituya.
Tratándose de la alimentación otorgada en especie o a través de concesionarios, u otras for
mas que no impliquen pago en efectivo, se considerará el valor que tenga en el últim o día
laborable del mes anteriora aquél en que se efectúe el depósito correspondiente.
El valor mensual se establecerá en base al mes del respectivo semestre en que el trabajador
acumuló mayor número de días de goce de este beneficio consignándose en el libro de plani
llas y boletas de pago.
R em u n eració n en e sp e cie .- Cuando se pacte el pago de la remuneración en especie, enten
diéndose por tal los bienes que recibe el trabajador como contraprestación del servicio, se
valorizará de común acuerdo o, a falta de éste, por el valor de mercado y su importe se consig
nará en el libro de planillasy boletas de pago.
R e g u la rid a d d e la re m u n e ra ció n .- Se considera remuneración regular aquella percibida ha
bitualmente por el trabajador, aun cuando sus montos puedan variaren razón de incrementos
u otros motivos. Por excepción, tratándose de remuneraciones complementarias, de natura
leza variable o imprecisa, se considera cumplido el requisito de regularidad si el trabajador las
ha percibido cuando menos tres meses en cada periodo de seis.
C o m isio n ista s, d e s ta je ro s y tra b a ja d o re s q u e p erciban re m u n e ració n p rin cip al im p re c isa .-
En el caso de comisionistas, destajeros y en general de trabajadores que perciban remunera
ción principal imprecisa, la remuneración computable se establece en base al promedio de
las comisiones, destajo o remuneración principal imprecisa percibidas por el trabajador en el
semestre respectivo.
Si el período a liquidarse fuere inferior a seis meses la remuneración computable se establece
rá en base al promedio diario de lo percibido durante dicho periodo.
R em u n e racio n e s p e rió d ica s.- Las remuneraciones de periodicidad semestral se incorporan a
la remuneración computable a razón de un sexto de lo percibido en el semestre respectivo. Se
incluye en este concepto las gratificaciones de Fiestas Patrias y Navidad.
