Tema 5: Temas de la especialidad laboral
¿Cuál es la c o n d ic ió n le g a l d e los d e p ó s ito s d e la CTS?
Los depósitos de la CTS, incluidos sus intereses, son intangibles e inembargables, salvo por
alimentos y el 50%, su abono solo procede al cese del trabajador. (Art. 37TUO D. Leg. 650).
¿C u á n to es el m o n to m á x im o p o sib le qu e po d rá retirar un t r a b a ja d o r d e su s d ep ó sito s de
C T S ?
Conforme al artículo 41 TUO D. Leg. 650 el monto máximo posible que podrá retirar un traba
jador de sus depósitos de CTS no podrá exceder en su conjunto del 50% del total de la com
pensación por tiempo de servicios depositadas y sus intereses, computada desde el inicio de
los depósitos. Sin embargo, a través de la Ley N° 32027 (Pub. 17.05.2024) y su reglamento D.S.
N° 003-2024-TR, ante la actual crisis económica se autoriza, por única vezy hasta el 31.12.2024,
a los trabajadores comprendidos dentro de los alcances del TUO del Decreto Legislativo 650,
Ley de Compensación por Tiempo de Servicios, a disponer libremente del 100 % de los depó
sitos por CTS efectuados en las entidades financieras y que tengan acumulados a la fecha de
disposición.
¿C ó m o se pro du ce el pago de la C TS al p ro du cirse el cese del tra b a ja d o r?
Con excepción de los retiros parciales autorizados, laCTSysus intereses sólo podrá ser pagado
al trabajador y/o derechohabientes, según corresponda, al producirse el cese. Para el retiro
correspondiente el trabajador deberá acompañar a su solicitud la certificación del empleador
que acredite el cese. (Art. 45 TUO D.Leg.650).
R e m u n e racio n e s no C o m p u ta b le s:
No se consideran remuneraciones computables las siguientes:
a) Gratificaciones extraordinarias u otros pagos que perciba el trabajador ocasionalmente,
a título de liberalidad del empleador o que hayan sido materia de convención colectiva,
o aceptadas en los procedimientos de conciliación o mediación, o establecidas por reso
lución de la Autoridad Administrativa de Trabajo, o por laudo arbitral. Se incluye en este
concepto a la bonificación por cierre de pliego;
b) Cualquier forma de participación en las utilidades de la empresa;
c) El costo o valor de las condiciones de trabajo;
d) La canasta de Navidad o similares;
e) El valor del transporte, siempre que esté supeditado a la asistencia al centro de trabajo y
que razonablemente cubra el respectivo traslado. Se incluye en este concepto el monto
fijo que el empleador otorgue por pacto individual o convención colectiva, siempre que
cumpla con los requisitos antes mencionados;
f) La asignación o bonificación por educación, siempre que sea por un monto razonable y se
encuentre debidamente sustentada;
g) Las asignaciones o bonificaciones por cumpleaños, matrimonio, nacimiento de hijos,
fallecimiento y aquéllas de semejante naturaleza. Igualmente, las asignaciones que se
abonen con motivo de determinadas festividades siempre que sean consecuencia de una
negociación colectiva.
