h) Los bienes que la empresa otorgue a sus trabajadores, de su propia producción, en canti
dad razonable para su consumo directivo y de su familia;
i) Todos aquellos montos que se otorgan al trabajador para el cabal desempeño de su labor
o con ocasión de sus funciones, tales como movilidad, viáticos, gastos de representación,
vestuario y en general todo lo que razonablemente cumpla tal objeto y no constituya be
neficio o ventaja patrimonial para el trabajador;
j) El refrigerio que no constituya alimentación principal, conforme al Artículo 12o de la pre
sente Ley.
Tampoco se incluirá en la remuneración computable la alimentación proporcionada directa
mente por el empleador que tenga la calidad de condición de trabajo por ser indispensable
para la prestación de los servicios, o cuando se derive de mandato legal.
XII. INDEMNIZACIÓN
En el Perú, por ley únicamente se reconoce la indemnización por despido arbitrario, mientras
que son las cortes laborales aquellas que evalúan los casos de indemnizaciones por daños y
perjuicios, así como sus derivados.
1. In d e m n iza c ió n por d e sp id o a rb itra rio
Dentro de los requisitos que el trabajador debe cum plir para acceder a una indemniza
ción por despido arbitrario, están los siguientes:
Haber superado el periodo de prueba (3 meses).
Tener una jornada de al menos 4 horas diarias: por este requisito se entiende que los
trabajadores a tiempo parcial, no tienen derecho a la indemnización porque laboran
menos de 4 horas.
Saber que el motivo del despido no se encuentra tipificado en la norma y por tanto
es injustificado. (Art. 25 del D.S. N° 003-97-TR).
La indemnización que se da en el despido arbitrario es equivalente a una remuneración y me
dia ordinaria mensual porcada año completo de servicio con un máximo de 12 remuneracio
nes. Las fracciones de año se abonan por dozavos y treintavos, según corresponda. Su abono
procede superado el periodo prueba.
En los casos de despido nulo, si se declara fundada ¡a demanda el trabajador será repuesto en
su empleo, salvo que en ejecución de sentencia, opte por la indemnización establecida en el
artículo 38o del D.S. N° 003-97-TR.
También procede la indemnización cuando el trabajador que se considere hostilizado opte
excluyentemente por la terminación del contrato de trabajo, el monto será el que se señale
para el despido arbitrario independiente de la m ulta y beneficios sociales que puedan corres
ponderá.
En el caso de los trabajadores contratado a plazo fijo o sujetos a modalidad, la indemnización
se determina en función a los meses que restan para el térm ino del contrato, con el mismo
tope de doce remuneraciones mensuales.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

