Tema 5: Tem as de la especialidad laboral
¿Se puede despedir a un trabajador y otorgarle la indem nización por despido arb itrario ?
El empleador que decide despedir a un trabajador aun cuando le abone el monto de indem
nización por despido arbitrario corre el riesgo que el trabajador inicie una acción judicial (a
través de un proceso de amparo) donde solicite su reposición.
