2 . In d e m n iz a c ió n por d a ñ o s y p e rju ic io s9: En casos de despidos fraudulentos o incausados,
los precedentes judiciales han adm itido el pago de indemnizaciones por daños y perjuicios,
que incluyen diversos derivados.
2 .1. In d e m n iz a c ió n por d a ñ o m o ral: Para que esta indemnización proceda, se debe acredi
tar de manera fehaciente que el despido, le causó al trabajador gran aflicción o sufrimiento
y posible deterioro de imagen (Cas. Labo ral N ° i 3 9 -2 0 14 -L a L ib e r ta d /C a s . L abo ral No. 699-
2 0 15 -L im a ).
2.2. In d e m n iz a c ió n por lucro cesante: Incluye el pago de los beneficios que el trabajador
dejó de percibir por habersido despedido, aunque puede disminuirse en caso se verifique que
realizó otras actividades remuneradas. Procede solo en caso el trabajador no haya cobrado la
indemnización por despido arbitrario.
