2.4. D añ o s p u nitivo s: El V Pleno jurisdiccional Supremo en Materia Laboral y Previsional tam
bién destacó que en caso de que a los trabajadores se le reconozca una indemnización por
dañosy perjuicios derivados de despidos incausadosy fraudulentos, el juez ordenará además
el pago de daños punitivos, afín deque se pueda evitar que los empleadores vuelvan a incurrir
en dicha conducta ilícita.
El importe de los daños punitivos será equivalente a lo que hubiera aportado el trabajador
a la ONP o AFP durante el periodo de despido y no será indispensable que el trabajador los
demande, pudiendo otorgarlo el juez de oficio.
3. In d e m n iza c ió n por d a ñ o s y p e rju icio s d e riv a d o s de e n fe rm e d a d e s pro fesio n a les y a cci
d en tes de tra b a jo :
La indemnización por daños y perjuicios causados por accidente de trabajo y enfermedades
profesionales tiene como punto de partida el contrato de trabajo. Es decir, estas contingencias
sólo se presentan en el caso de los trabajadores subordinados a un empleador. No sucede
así, por ejemplo, en la locación de servicios, por no existir la misma relación que se da en el
contrato laboral. Consecuentemente, el accidente de trabajoy la enfermedad profesional son
contingencias inherentes al contrato de trabajo.
Respecto a las enfermedades profesionales en el I Plen o ju risd ic c io n a l Su p re m o en m a te ria
lab o ral, celebrado los días 04 y 14 de mayo de 2012 del T e m a N ° 02: In d e m n iz a c ió n por D a
ñ o s y P e rju icio s d e riv ad o s de E n fe rm e d a d e s P ro fe sio n ales, su b te m a c) Sobre la n e ce sid a d
de qu e el d e m a n d a n te a credite los e le m e n to s d e la re sp o n sa b ilid a d civil, se acordó lo si
guiente:
Que el trabajador debe cumplir con probar la existencia de la enfermedad profesional, y el
empleador, el cumplimiento de sus obligaciones legales, laboralesy convencionales.
En el caso de los accidentes de trabajo hay pronunciamientos que difieren entre ellos tenemos
a la Cas. N° 2725-2012 -Apurimac, establece que laobligación de seguridady salud en el traba
jo del empleador importa una protección íntegra del trabajador, siendo suficiente que el daño
se produzca a consecuencia del trabajo prestado. Los términos específicos de la sentencia ca-
satoria son los siguientes: “[...] Con la actual configuración de ¡a obligación general de prevención la
deuda del empleador se extiende a la protección íntegra del trabajador, de su salud y seguridad, siendo
suficiente entonces con que el daño se produzca como causa o consecuencia de la prestación laboral para
que se proceda al análisis de los demás elementos tipificantes de la responsabilidad contractual Sin
embargo, y con un criterio distinto, en la Cas. N ° 2 2 9 3 -2 0 12-C u sco , establece que la responsa-
