Tema 5: Temas de la especialidad laboral
bilidad laboral por accidentes de trabajo se rige en función al incumplimiento del empleador
de su deber de seguridad, en los términos siguientes: “[U]no de los deberes del empleador que se
derivan de la relación laboral es el deber de g a rantizar la seguridad y salud del personal que se encuentra
en relación de subordinación frente a él [...] [por lo que] se debe exam inar si en el actuar de la emplazada
buho culpa o no, si om itió adoptar las medidas exigidas a su parte, si cumplió o no con la obligación de
dar o hacer cuya inejecución sustente la pretensión indem nizatoria.y si demostró una conducta a n ti
jurídica que causó daño al trabajador se determinará la obligación al pago de una indemnización que
repare de alguna manera la pérdida de una vida humana como consecuencia de un accidente de trabajo".
En términos similares, la Corte Suprema de Justicia de la República estableció en la C as. N °
1819''2010-Lima lo siguiente: “[S]e ha establecido en la jurisprudencia nacional y extranjera que la
responsabilidad contractual im puta al empleador el pago resarcitorio por el incum plim iento de normas
de seguridad e higiene ocupacional, originado en la cláusula implícita de todo contrato de trabajo que
obliga a velar por la seguridad de sus obreros".
Finalmente, en cuanto a los conceptos indemnizables10 el I P le n o J u ris d icc io n al S u p re m o en
M ate ria Laboral, en el T E M A N ° 02: su b te m a a) Sobre la co m p eten cia del órg ano ju r is d ic
cio n a l lab o ral p ara conocer de las d e m a n d a s de d a ñ o s y p e rju icio s por e n fe rm e d a d pro
fe sio n al, ta n to por d a ñ o p a trim o n ia l com o por d a ñ o m oral, el Pleno acordó: “Los jueces que
ejercen competencia en el marco de la Ley Procesal del Trabajo N° 26636y en la Nueva Ley Procesal
del Trabajo número 29497, conocerán de las demandas de daños y perjuicios por responsabilidad con
tractual tanto por daño patrim onial, que abarca el lucro cesante y daño emergente, como por daño
moral, especialmente en los casos de enfermedad profesional"
En esa misma línea de análisis, en el V I P len o Ju risd iccio n al S u p re m o en M a te ria Laboral
y P re v isio n a l llevado a cabo los días dieciocho de septiembre y dos de octubre de dos mil
