del a rtícu lo 5 3 o de la Ley N° 29783» Ley d e S e g u rid a d y S a lu d en el Trab ajo , el Pleno acordó:
El empleador, como garante de la seguridad y salud en el centro laboral, siempre será responsable por
cualquier evento dañoso para la vida o salud del trabajador. Asimismo, puede utilizarse la transacción
como un mecanismo para la extinción de obligaciones por responsabilidad por accidentes de trabajoy/o
enfermedades profesionales, en cuyo caso el monto otorgado deberá ser valorado tomando en cuenta el
artículo i° de la Constitución Política del Perú.
En caso se reconozca al trabajador un monto indemnizatorio por daños y perjuicios, el juez de oficio orde
nará pagar una suma de dinero por daños punitivos, cuyo monto m áximo será fijado con criterio pruden
cial por el juez, sin exceder el total del monto indemnizatorio ordenado pagar pordaño emergente, lucro
cesante o daño moraly atendiendo a la conducta del empleador frente al caso concreto.
Los Plenos anteriormente citados guardan congruencia con la doctrina jurisprudencial emi
tido por la Sala Suprema establecido en la C asació n Laboral N . 0 4 4 13 -2 0 14 C a lla o , de fecha
