XIII. VACACIONES
Tiene derecho a descanso vacacional el trabajador que cumpla una jornada ordinaria mínima
de 04 horas, siempre que haya cumplido dentro del año de servicios, el récord vacacional res
pectivo.
R eq u isito s p a ra G o za r d el D escan so : Para que el trabajador adquiera el derecho al descanso
vacacional, tiene que cumplir los dos requisitos indispensables que deben darse de manera
conjunta:
Contar con un año de labor.
Haber cumplido con un determinado número de días efectivos de labor durante dicho
año (hay excepciones).
En el caso de trabajadores con jornada ordinaria de seis días a la semana, éstos para gozar del
descanso vacacional deberán haber prestado labor efectiva por lo menos, durante doscientos
sesenta días dentro del año de servicios.
Có m p u to de los d ía s Efectivos d e Trabajo: Para efectos del cómputo del record vacacional
antes mencionado se considerarán como días efectivos de trabajo los siguientes.-
La jornada ordinaria mínima de cuatro horas.
La jornada cumplida en días de descanso, cualquiera sea el número de horas laboradas.
Las horas de sobre tiempo en número de cuatro o más en un día.
Las inasistencias por enfermedad común, por accidente de trabajo y enfermedad profe
sional, en todos los casos solamente los primeros sesenta días dentro de cada año de ser
vicios. v El descanso prey post natal.
El permiso sindical.
Las faltas o inasistencias autorizadas por Ley, convenio individual o colectivo o decisión
del empleador.
El período vacacional correspondiente al año anterior.
Los días de huelga, salvo que haya sido declamada improcedente o ilegal.
D u ra ció n : La duración del descanso vacacional es de 30 días continuos, sin embargo, se per
mite fraccionar su goce.
De este modo existen casos en las que el trabajador no disfruta de 30 de descanso, sino de más
o menos días, dependiendo de que se pacte acumular o reducir las vacaciones.
Fraccio n am ien to : A solicitud escrita del trabajador el empleador podrá autorizar el goce va
cacional en períodos que no podrá ser menor a siete días naturales.
A cu m u la ció n : El trabajador puede convenir por escrito con su empleador (sin necesidad de
poner en conocimiento de la AAT el acuerdo y que éste sea aprobado por dicha autoridad)
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 785 of 1506 --

Tema 5: Temas de la especialidad laboral
en acumular hasta 02 descansos consecutivos, siempre que después de un año de servicios
continuo disfrute por lo menos de un descanso de 07 días naturales, los cuales son deducibles
del total de días de descanso vacacional acumulados. El descanso vacacional puede reducirse
de 30 a 15 días, con la respectiva compensación de quince días de remuneración, la cual deberá
abonarse independientemente de la remuneración vacacional correspondiente. El acuerdo de
reducción debe constar por escrito.
O p o rtu n id a d d el D escan so : Las vacaciones serán otorgadas al trabajador en el período anual
sucesivo a aquél en que alcanzó el derecho al goce de dicho descanso. La oportunidad del des
canso vacacional será fijada de común acuerdo entre el empleador y el trabajador, teniendo
en cuenta las necesidades de funcionamiento de la empresay los intereses propios del traba
jador. A falta de acuerdo decidirá el empleador en función de su facultad directriz.
R e m u n e ració n V a ca cio n a l: La remuneración vacacional es equivalente a la que el trabajador
hubiera percibido habitual y regularmente en caso de continuar laborando. Para este efecto,
se considera remuneración la computable para la compensación por tiempo deservicios; con
excepción por su propia naturaleza de las remuneraciones. La remuneración vacacional de
los comisionistas se establece sobre la base del promedio de las comisiones percibidas por
el trabajador en el semestre. En los casos de trabajo discontinuo o de temporada, por su pro
pia naturaleza, no procede el descanso físico, sino, el pago al trabajador de un doceavo de la
remuneración vacacional por cada mes completo de labor efectiva y de toda fracción de mes
por treintavos. El trabajador a domicilio tiene derecho a percibir por vacaciones el equivalente
al 8.33% del total de las remuneraciones percibidas durante el año cronológico anterior de
servicios prestados al empleador. Este beneficio se paga conjuntamente con la remuneración
del mes en el que se cumple el año cronológico.
O p o rtu n id a d de Pago: La remuneración vacacional será abonada al trabajador antes del ini
cio del descanso, sin embargo ésta debe registrarse en la planilla en el mes al que corresponde
dicho descanso, de tal modo que el pago adelantado de la remuneración vacacional no tendrá
incidencia alguna. El trabajador tiene derecho a percibir a la conclusión de su descanso los in
crementos de remuneración que se pudieran producir durante el goce desús vacaciones. Si el
trabajador acordó la reducción del descanso, percibirá antes de que se inicie éste, además del
monto correspondiente a los días de descanso, el monto de la compensación extraordinaria.
El empleador está obligado a hacer constar expresamente en el libro de planillas la fecha del
descanso vacacional y el pago de las remuneraciones correspondientes.
S itu a ció n d e los T ra b a ja d o re s qu e no G o za n del D escanso: Puede ocurrir que el trabajador
cumpla con el record vacacional, pero no disfrute del descanso físico, dentro del año siguiente
a la fecha en que le correspondía hacer use de ésta. En ese caso percibirá una triple remunera
ción que se computará de la forma siguiente:
Una por el trabajo realizado.
Una por el descanso vacacional adquirido y no gozado, y
Una indemnización por no haber disfrutado del descanso (la últim a no está sujeto a pago,
de retención de ninguna aportación, contribución o tributo).
