UBILEX
Indemnización vacacíonal- Cas. Lab. N° 2039-2013-La Libertad. 2 2 /1 1 /2 0 1 3 .
"(...) anótese que la estructura de la indemnización vacacíonal prevista en el artículo 23 del De- ''
■ « J B S L r creto Legislativo N° 713, ante el no disfrute del descanso vacacíonal dentro del año siguiente a
aquél en el que adquiere el derecho, está compuesta de tres conceptos: i) una remuneración por
¡ ¡ I el trabajo realizado; ¡i) una remuneración por el descanso vacacíonal adquirido y no gozado;y, iii)
una indemnización equivalente a una remuneración por no haber disfrutado del descanso vaca-
clonal (en rigor, indemnización en sentido estricto). Vigésimo: En este particular escenario, este
Supremo Tribunal precisa que atendiendo a los previsto en el inciso b) del artículo 15 de la Ley del Profesorado :
N° 24029 como se tiene señalado le corresponde al demandante durante el término que ha laborado como
profesor, sesenta días de vacaciones, sobre los cuales le corresponde el pago de una remuneración por el
descanso vacacíonal adquirido y no gozado (porcada mes), en razón que solo le fue pagada una remuneración
por las labores realizadas, asimismo sólo le corresponde la indemnización equivalente a una remuneración
por no haber disfrutado del descanso, principalmente porque si bien existe norma que regulé los sesenta días
de goce vacacíonal para el caso de los docentes universitarios ordinarios de universidades privadas, no existe
disposición expresa que sancione al empleador con el pago de una indemnización p o m o disfrutar del goce de
los treinta días adicionales al supuesto normativo previsto en el D. Legislativo N ° 713."
XIV. DESCANSOS REMUNERADOS
Como regla general, el trabajador tiene derecho a que se le pague los días efectivamente
trabajados; sin embargo, para algunos casos, la norma ha establecido la obligación del em
pleador de pagar al trabajador aun cuando éste no realice trabajo efectivo. Es el caso de las
vacaciones anuales, descanso semanal obligatorio y días feriados, temas que trataremos a
continuación.
Las vacaciones son el derecho que tiene el trabajador, luego de cumplir con ciertos requisitos,
a suspender la prestación desús servicios durante un cierto número de días al año, sin pérdida
de la remuneración habitual, a fin de restaurar sus fuerzas y entregarse a ocupaciones perso
nales o a la distracción.
Tiene derecho a descanso vacacíonal el trabajado que cumpla una jornada ordinaria mí
nima de cuatro horas, siempre que haya cumplido dentro del año de servicios, el récord
vacacíonal.
Este derecho se encuentra regulado por el D. Leg. N° 713 (08.11.91) y su Reglamento D.S. N°
012-92-TR (03.12.92)
Con respecto al descanso semanal obligatorio, de acuerdo al D. Leg. N°713 el trabajador tiene
derecho a gozar como mínimo de 24 horas consecutivas de descanso en cada semana.
Con respecto al descanso en día feriado, la ley establece que el trabajadortiene derecho a des
canso remunerado en los días feriados señalados por el D. Leg. N °713-
