XV. JORNADA DE TRABAJO
Es el tiempo durante el cual en forma diaria, semanal o mensual el trabajador se encuentra a
disposición de su empleador, con el fin de cumplir la prestación laboral que éste le exija.
La jornada de trabajo no es un elemento esencial del contrato de trabajo; sin embargo, su
estipulación es de suma importancia,ya que de éste depende la determinación de la remune
ración del trabajador, así como el acceso de diversos beneficios sociales como es el caso de la
compensación por tiempo de servicio.
1. Jornada ordinaria
La jornada legal es de 8 horas diarias o 48 horas semanales, como máximo. Puede reducirse
por ley, convenio o decisión del empleador. En caso de jornadas de trabajo y descanso alterna
tivas, acumulativas o atípicas, el promedio de horas trabajadas en el período correspondiente
no puede superarel máximo de la jornada legal.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 788 of 1506 --

La jornada de los adolescentes entre 15 y 17 años no excederá de seis horas diarias o treinta y
seis horas semanales y la de los adolescentes entre 12 y 14 años de cuatro horas diarias o vein
ticuatro horas semanales.
Están excluidos de la jornada máxima los trabajadores de dirección, los que no se encuentran
sujetos a fiscalización inm ediatay los que prestan servicios intermitentes de espera, vigilancia
o custodia.
De existir jornada inferior a la máxima legal, el empleador puede extenderlas unilateralmente
hasta dicho límite incrementando la remuneración en función del tiempo adicional.
I Plano Jurisdiccional Supremo en Materia Laboral, Tama 3, Lima. Pufe. 17/G 7/2ST2.
(Sí) "Los trabajadores de espera, vigilancia o custodia, no están comprendidos en la jornada máxima
sólo si es que su prestación de servicios se realiza de manera intermitente".
2. Jomada extraordinaria
Es la jornada de Trabajo extraordinario conocida también como horas extras, siendo aquella
realizado más allá de la jornada ordinaria, diaria o semanal, o de la jornada de trabajo inferior
a la ordinaria, diaria o semanal establecido en el centro de trabajo.
El trabajo en sobretiempo es voluntarioy debe ser remunerado extraordinariamente en la for
ma que por convenio, pacto o contrato se establezca, siendo su monto mínimo un 25% más
del valor de la hora ordinaria.
sj I Pleno Jurisdiccional Supremo en Materia Laboral. Tema 3. Lima. Pub. 17/07/2012.
- Ü L © “Las limitaciones presupuéstales no privan a los trabajadores del Sector Público de gozar del
| ■ H E pago de horas extras si se ha realizado trabajo en sobretiempo".
© "Existe la posibilidad que las entidades del Sector Público compensen el pago de horas extras con
períodos de descanso sustitutorio. Sin embargo, para ello tal como Sector Privado, es necesaria la
aceptación del trabajador y su manifestación de conformidad consignada en un acuerdo (convenio)."
3. Jornada atípica
“Tratándose de jornadas atíplcas, en cualquier tipo de actividades laborales, no pueden supe
rar el promedio de ocho horas diarias ni decuarentay ocho por semana, ya sea que se trate de
un período de tres semanas, o de un período más corto, como lo dispone la Constitución y el
Convenio N °i de laOlT. Considerando que el artículo 25o de la Constitución impone la jornada
máxima de trabajo de cuarentlocho horas semanales, ésta prevalecerá sobre cualquier dispo
sición internacional o interna que imponga una jornada semanal mayor, puesto que se trata
de una norma más protectora” (Exp. N° 4635-2004-AA/TC-Tacna. Caso Sindicato de Trabaja
dores Toquepala y anexos)- Precedente vinculante.
XVI. HORARIO DE TRABAJO
El horario de trabajo es la medida de la jornada, es decir, determina con exactitud la hora de
ingreso y de salida en cada día de trabajo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 789 of 1506 --

Tema 5: Temas de la especialidad laboral
Por horario de trabajo, se entiende al establecimiento o adecuación de la jornada de trabajo a
los requerimientos del empleadory constituye el señalamiento del inicio y el térm ino de dicha
jornada. El Convenio N .°i,en su artículo 8o, num erali literal a) señalaquecon el objetode faci
litar la aplicación de la jornada de trabajo, se debe dar a conocer el horario de trabajo, median
te carteles colocados en lugares visibles del centro de trabajo, en éste mismo cartel, se deberá
señalar el horario de refrigerio o los descansos que no se consideran como horas de trabajo.
¿Qué es el trabajo en sobretiempo u horas extras?
Es el trabajo realizado más allá de la jornada ordinaria diaria o semanal y puede realizarse
antes de la hora de ingreso o después de la hora de salida establecida. El trabajo en sobre-
tiempo es voluntario tanto en su otorgamiento como en su realización, sólo es obligatorio en
casos justificados por hecho fortuito o de fuerza mayor, que pongan en peligro las personas,
los bienes del centro de trabajo o la continuidad de la actividad productiva. La hora extra se
entenderá otorgada tácitamente, cuando el trabajador acredite haber laborado en sobretiem
po, aún sin autorización expresa del empleador. Cuando el sobretiempo es anterior o posterior
a la jornada de trabajo en horario nocturno, la hora extra se calcula en base al valor de la remu
neración ordinaria para la jornada nocturna. Art. 9 del D.S. N°007-2002-TR.
¿En qué oportunidad el empleador debe pagar las horas extras?
Las horas extras deben ser remuneradas en la misma oportunidad de pago de las remune
raciones y su monto debe ser también registrado en las planillas electrónicas, así como en la
boleta de pago.
¿Cómo se calculan las horas extras?
Las horas extras se pagan con un recargo a convenir del 25% adicional del valor hora para las
dos primeras horas y un 35% adicional del valor hora a partir de la tercera hora en adelante.
Por ejemplo:
Remuneración mensual: 1,000 nuevos soles
Días: 30 días mes laboral (tenga el mes 31 días o 28 días, siempre el mes laboral es de 30 días)
jornada de trabajo: 8 horas
Para saber cuánto gano por hora se divide: S/. 1,000 (remuneración) / 30 (mes laboral) /8
(horas de trabajo) = S/. 4.16 valor hora.
S/.4.16 (valor hora) +1.04 (25% adicional primera hora extra) = S/. 5.20.
S/. 4.16 (valor hora) +1.04 (25% adicional segunda hora extra) = S/. 5.20.
S/. 4-16 (valor hora) +1.45 (35% adicional tercera hora extra) = S/. 5.61.
Es decir, si mi horario de trabajo es de 08.00 ama 5.00 p.m. (con una hora de refrigerio de 01 a
02 p.m.)y laboro hasta las 08.00 p.m. (03 horas extras) percibiré ese día por cada hora extra:
Remuneración por la primera hora extra: S/.4.16 (remuneración por hora) más S/. 1.04
(25% del valor hora adicional) = TOTAL: S/.5.20 nuevos soles por la primera hora extra.
(2) Remuneración por la segunda hora extra: S/.4.16 (remuneración por hora) más S/. 1.04
(25% del valor hora adicional) = TOTAL: S/.5.20 nuevos soles por la segunda hora extra.
