(3) Remuneración por la tercera hora extra: S/.4.16 (remuneración por hora) más S/. i .45
(35% del valor hora adicional) = TOTAL: S/.5.61 nuevos soles, por la segunda hora extra.
TOTAL: (1) + (2) + (3) = S/. 16.01 solo por horas extras + mi día de trabajo.
XVII. GRATIFICACIONES
Las gratificaciones forman parte de los beneficios sociales que corresponden a los trabajado''
res como parte del vínculo laboral.
Clases.- Las gratificaciones pueden ser legales o a título de liberalidad. Serán gratificaciones
legales aquellas otorgadas en forma obligatoria por mandato legal (ejemplo: gratificaciones
por fiestas patrias y navidad), convenio colectivo o contrato de trabajo entre los trabajadores
y el empleador.
También encontramos a las gratificaciones extraordinarias, las cuales son otorgadas de mane-
ra excepcional o de forma esporádica, y, por tanto no tiene carácter remunerativo, de confor
midad con el artículo 19 del TUO de la Ley de CTS, D. S. N °o o i-97-TR.
Tienen derecho a percibir gratificación por Fiestas patrias y Navidad, los trabajadores sujetos
al Régimen Laboral de la Actividad Privada, sea cual fuere su relación laboral, ya sea el tipo de
contrato de trabajo y el tiempo de prestación de servicios del trabajador.
Quedan excluidos de los alcances de la normatividad que enmarca a las Gratificaciones lega
les, las personas que prestan servicios vía contrato civil de locación de serviciosy los que están
sujetos a convenios de Modalidades Formativas Laborales (Aprendizaje con predominio en la
Empresay con predominio en el Centro de Formación Profesional- Prácticas Pre Profesionales,
Práctica Profesional, Capacitación Laboral Juvenil, pasantía- pasantía en la Empresay Pasantía
de Docentes y Catedráticos, y actualización para la reinserción Laboral).
Para tenerderecho a la gratificación es requisito indispensable habercumplido como mínimo
un mes calendario de trabajo efectivo en la empresa.
Los trabajadores tienen derecho a percibir el íntegro de la gratificación, siempre que hayan
laborado 6 meses en el semestre, (anteriores a la oportunidad del goce de este beneficio).
En caso que el trabajador cuente con menor de 6 meses de servicios percibirá la gratificación
en forma proporcional a los meses laborados.
Gratificación Trunca: Si el trabajador no tiene vínculo laboral vigente en la fecha en que co
rresponda percibir el beneficio, pero hubiera laborado como mínimo un mes en el semestre
respectivo, percibirá la gratificación en forma proporcional a los meses efectivamente trabaja
dos. Para estos efectos se debe tom ar en cuenta lo siguiente:
- El derecho a la gratificación trunca se origina al momento del cese del trabajador, siempre
que tenga cuando menos un mes completo de servicios.
- El monto de la gratificación trunca se determina de manera proporcional a los meses ca
lendarios completos laborados en el período (enero-junio o julio-diciembre) en el que se
produzca el cese.
- La remuneración computable es la vigente al mes inmediato anterior al que se produjo el
cese.
