Terra 5: Temas de la especialidad laboral
- La gratificación trunca se paga conjuntamente con todos los beneficios sociales dentro de
las 48 horas siguientes de producido el cese.
XVIII. UTILIDADES
Cada año las empresas realizan un balance final de pérdidas y ganancias. Si una empresa re
gistra ganancias, quiere decir que la empresa ha tenido una buena actividad económica du
rante el año. En este caso le corresponde hacer una repartición de estas ganancias o utilidades
en la cual debe incluir la participación de los trabajadores, este derecho de los trabajadores
está reconocido en el artículo 29 de la Constitución Política vigente.
La participación de los trabajadores en la distribución de las utilidades se estableció con el fin
de buscar la identificación de éstos con la empresa y que ello repercuta en el aumento de la
producción y productividad de sus centros de trabajo.
De acuerdo al D. Leg. N°892, las empresas que se encuentran obligadas a repartir utilidades a
sus trabajadores, son todas aquellas que generen rentas de tercera categoría, que tengan más
de 20 trabajadores y que hayan generado utilidades durante el ejercicio respectivo.
¿Q ué trabajadores tienen derecho al pago de utilidades?
Tienen derecho a participar en las utilidades todos los trabajadores que laboran en empresas
con más de 20 trabajadores que hayan cumplido las jornadas máximas de trabajo establecido
en la empresa, sea a plazo indefinido o sujetos a cualquiera de las modalidades de contrata
ción laboral.
Los trabajadores con jornada inferior a la máxima establecida, participaran en las utilidades
en forma proporcional a la jornada trabajada.
Estarán excluidos, por tanto, los trabajadores de empresas que tengan 20 o menos trabajado
res, así como los trabajadores y socios trabajadores de las cooperativas.
Las empresas repartirán sus utilidades en diferentes porcentajes, de acuerdo al tipo de activi
dad que realizan, conforme al siguiente cuadro:
DISTRIBUCIÓN DE UTILIDADES SEGÚN TIPO DE EMPRESA
Empresas pesqueras ''] 0%
Empresas de telecomunicaciones 10%
Empresas industriales 10%
Empresas mineras 8%
Empresas de comercio al por mayor yal por menor y restaurantes 8%
Empresas que realizan otras actividades 5%
¿Cuál es el plazo para solicitar el pago de los beneficios sociales?
La Ley 27321 (Ley que establece nuevo plazo de prescripción de las acciones derivadas de la
relación laboral) menciona que el plazo para solicitar el pago de beneficios laborales es de 4
años contados a partir del día siguiente de la extinción del vínculo laboral.
