XIX. RÉGIMEN LABORAL PÚBLICO. DERECHOS ¥ OBLIGACIONES. INICIO Y TÉRMINO DE
LA CARRERA ADMINISTRATIVA.
En la actualidad, existen varios regímenes laborales en las entidades del Estado, entre genera
les y especiales (ver cuadro), lo cual conlleva a un desorden en la administración pública en la
medida que cada régimen implica distintos derechos y deberes para los servidores públicos.
La Carrera Adm inistrativa: La carrera administrativa en el Perú es un conjunto de principios,
normasy procesos que regulan el Ingreso, los derechosy los deberes de los servidores públicos
que, con carácter estable, prestan servicios de naturaleza permanente en la administración
pública. Su objetivo es la incorporación de personal idóneo, garantizando su permanencia y
desarrollo, sobre la base de mérltosy calificaciones en el desempeño de sus funcionesy dentro
de una estructura uniforme de grupos ocupadonales y de niveles.
La carrera administrativa está regulada por la Ley de bases de la carrera administrativa y de
remuneraciones del sector público (D. Leg 276) y su reglamento (D.S. 005-90-PCM). El régi
men laboral público administrativo establecido en esa Ley se caracteriza por ser un sistema
cerrado, en el cual el ingreso a la carrera se realiza por el nivel más bajo del grupo ocupacional
y la promoción de los servidores públicos en los diferentes niveles depende del cumplim iento
de requisitos previamente determinados, que incluyen antigüedad en el puesto, capacitación
y evaluación. La carrera cuenta con tres grupos ocupadonales con distintos niveles cada uno,
en donde la homogeneidad remuneratoria está establecida mediante un sistema único de
remuneraciones. La remuneración está constituida por un salarlo básico, además de bonifica
ciones y beneficios.
