-- 793 of 1506 --

Tema 5: Temas de la especialidad laboral
Según las Constitución y la Ley de Carrera Administrativa los servidores del Estado pueden
ser:
Funcionario Público: Es el ciudadano que es elegido o designado por autoridad competente,
conforme al ordenamiento legal, para desempeñar funciones-cargos del más alto nivel en los
poderes públicos y los organismos con autonomía. Las funciones-cargos políticos y de con
fianza son los determinados por Ley (Art. 4 o D. S. N °0 0 5 -9 0 -PCM).
Servidor Público: Es el ciudadano en ejercicio que presta servicio en entidades de la Adminis
tración Pública con nombramiento o contrato de autoridad competente, con las formalidades
de Ley, en jornada legal y sujeto a retribución remunerativa permanente en períodos regula
res.
Hace carrera el servidor nombrado y por tanto tiene derecho a estabilidad laboral indetermi
nada de acuerdo a ley.
Deberes jurídicos y m orales del servidor público:
Son obligaciones de los servidores:
a) Cumplir personal y diligentemente los deberes que impone el servido público;
b) Salvaguardarlos Intereses del estadoy emplear austeramente los recursos públicos;
c) Concurrir puntualm entey observar los horarios establecidos;
d) Conocer exhaustivamente las labores del cargo y capacitarse para un mejor desempeño;
e) Observar un buen trato y lealtad hada el público en general, hacia los superiores y com
pañeros de trabajo:
f) Guardar absoluta reserva en los asuntos que revistan tal carácter, aún después de haber
cesado en el cargo;
g) Inform ara la superioridad de los actos delictivos o de inmoralidad cometidos en el ejerci
cio de la fundón pública; y
h) Las demás que le señalen las leyes o el reglamento.
No basta con la técnica, con los conocimientos y la experiencia, para cum plir a cabalidad los
deberes y responsabilidades de un servidor público. Es preciso completarlo con los principios
y con la praxis de la moral.
La norma excluye de la carrera administrativa a las Fuerzas Armadas, Fuerzas Policiales y los
trabajadores de las empresas del Estado o de sociedades de economía mixta, así como a los
funcionarios que desempeñan cargos políticos o de confianza.
La carrera administrativa solamente es compatible con el ejercicio de la docencia universita
ria, que puede ser ejercida por un máximo de seis horas semanales.
Derechos y obligaciones
Son derechos del servidor público:
a) Hacer carrera pública base mérito, sin discriminación de ninguna índole.
b) Gozar de estabilidad. No cese ni destitución sino porcausay procedimiento previsto en Ley.
c) Percibir remuneración y beneficios que corresponde a su nivel.
